window.DATA_B2_V=[{"id":"V1","q":"Los sábados voy al ____ de mi barrio y compro un montón de cosas por poco dinero.","o":["estadio","mercadillo","polideportivo","ayuntamiento"],"a":1,"k":"장소 어휘","t":"토요일마다 나는 우리 동네 벼룩시장에 가서 적은 돈으로 많은 물건을 산다.","e":"mercadillo는 mercado(시장)에 작은 것을 뜻하는 어미 -illo가 붙은 말로, 주로 야외에 정기적으로 서는 노천 시장·벼룩시장을 뜻합니다. 싸게 이것저것 살 수 있다는 문맥에 딱 맞습니다. 예: El mercadillo se pone los domingos.(벼룩시장은 일요일마다 선다.)","x":["estadio: 경기장, 스타디움이라 물건을 사는 곳이 아닙니다 ✗","mercadillo: 노천 시장, 벼룩시장 → 정답 ✓","polideportivo: 종합 체육관(실내 스포츠 시설)이라 쇼핑과 무관합니다 ✗","ayuntamiento: 시청, 구청이라 물건을 사는 곳이 아닙니다 ✗"]},{"id":"V2","q":"Hay que llamar a un fontanero inmediatamente, se ha roto la ____ del baño.","o":["lámpara","cortina","cisterna","alfombrilla"],"a":2,"k":"집안 물건 어휘","t":"당장 배관공을 불러야 해, 화장실 변기 물탱크가 고장 났어.","e":"cisterna는 변기 뒤쪽의 물탱크(물을 내리는 장치)를 뜻합니다. 배관공(fontanero)을 불러야 하는 고장이므로 물과 관련된 설비가 와야 자연스럽습니다. 참고로 '물을 내리다'는 tirar de la cadena라고 합니다.","x":["lámpara: 전등, 램프라 고칠 사람은 전기 기사(electricista)입니다 ✗","cortina: 커튼, 샤워 커튼이라 배관공이 필요 없습니다 ✗","cisterna: 변기 물탱크 → 배관공이 고치는 설비라 정답 ✓","alfombrilla: 작은 깔개, 욕실 매트라 '고장'이 날 수 없습니다 ✗"]},{"id":"V3","q":"Ana y su madre son ____. Es increíble cómo se parecen.","o":["clavadas","opuestas","desiguales","dispares"],"a":0,"k":"외모 닮음 표현","t":"아나와 그녀의 엄마는 판박이다. 어쩜 그렇게 닮았는지 놀라울 정도다.","e":"clavado/a는 구어에서 '꼭 닮은, 판박이인'이라는 뜻으로 씁니다. 'ser clavado a alguien(누구와 똑 닮다)' 형태로 자주 쓰며, 여기서는 두 여성이 주어라 clavadas가 됩니다. 예: Es clavado a su padre.(그는 아버지를 쏙 빼닮았다.)","x":["clavadas: 판박이인, 꼭 닮은 → 정답 ✓","opuestas: 정반대인이라 '닮았다'는 뒷문장과 모순됩니다 ✗","desiguales: 고르지 않은, 불평등한이라 의미가 맞지 않습니다 ✗","dispares: 서로 다른, 이질적인이라 닮았다는 내용과 반대입니다 ✗"]},{"id":"V4","q":"Tras horas de interrogatorio, el sospechoso ____ que había cometido el crimen.","o":["difundió","confesó","descubrió","propagó"],"a":1,"k":"범죄·수사 어휘","t":"몇 시간의 심문 끝에 용의자는 자신이 범죄를 저질렀다고 자백했다.","e":"confesar는 '(죄나 비밀을) 고백하다, 자백하다'라는 뜻입니다. 심문(interrogatorio) 뒤에 용의자가 범행을 인정하는 상황이므로 confesó가 자연스럽습니다. 명사형은 confesión(자백, 고백)입니다.","x":["difundió: difundir(퍼뜨리다, 유포하다)로, 소식을 널리 알리는 것이라 맞지 않습니다 ✗","confesó: confesar(자백하다) → 정답 ✓","descubrió: descubrir(발견하다, 밝혀내다)로, 자기 범행을 '발견'하는 것은 어색합니다 ✗","propagó: propagar(전파하다, 퍼뜨리다)로 의미가 맞지 않습니다 ✗"]},{"id":"V5","q":"Si trabajas de cara al público, debes tener ____ con los clientes.","o":["tacto","arrogancia","malicia","desconsideración"],"a":0,"k":"성격·태도 어휘","t":"고객을 직접 상대하는 일을 한다면 고객에게 요령 있게(세심하게) 대해야 한다.","e":"tacto는 원래 '촉각'이지만, 'tener tacto'는 '남의 기분을 상하게 하지 않도록 눈치 있고 세심하게 대하다'라는 뜻입니다. de cara al público는 '대중(고객)을 직접 상대하는'이라는 표현입니다.","x":["tacto: 눈치, 세심한 배려 → 고객 응대에 필요한 자질이라 정답 ✓","arrogancia: 오만함이라 고객에게 가져야 할 태도가 아닙니다 ✗","malicia: 악의, 짓궂음이라 문맥과 반대입니다 ✗","desconsideración: 무례함, 배려 없음이라 문맥과 반대입니다 ✗"]},{"id":"V6","q":"¡Vaya ____! Nos felicitaron aunque no se alegrasen de nuestra victoria.","o":["explotación","intolerancia","hipocresía","discriminación"],"a":2,"k":"부정적 태도 어휘","t":"정말 위선이야! 우리의 승리를 기뻐하지도 않으면서 우리를 축하해 줬어.","e":"hipocresía는 '위선(속마음과 다르게 겉으로 꾸미는 것)'입니다. 기쁘지 않은데 축하하는 행동이 바로 위선이죠. '¡Vaya + 명사!'는 '정말 대단한 ~이군!'이라는 감탄 표현입니다. 형용사·사람은 hipócrita(위선적인, 위선자)입니다.","x":["explotación: 착취, 개발이라 문맥과 무관합니다 ✗","intolerancia: 불관용, 편협함이라 축하하는 행동과 맞지 않습니다 ✗","hipocresía: 위선 → 정답 ✓","discriminación: 차별이라 이 상황과 맞지 않습니다 ✗"]},{"id":"V7","q":"Admiro la ____ de José María. Su hermano, en cambio, es un hombre frágil.","o":["delicadeza","fortaleza","debilidad","franqueza"],"a":1,"k":"성격 반의어","t":"나는 호세 마리아의 강인함을 존경한다. 반면에 그의 형(동생)은 나약한 사람이다.","e":"en cambio(반면에)가 대조를 만들므로, frágil(연약한)과 반대되는 말이 필요합니다. fortaleza는 '(정신적·육체적) 강인함, 굳셈'이라는 뜻으로 정답입니다. 참고로 fortaleza에는 '요새'라는 뜻도 있습니다.","x":["delicadeza: 섬세함, 연약함, 상냥함으로 frágil과 대조가 되지 않습니다 ✗","fortaleza: 강인함 → frágil(연약한)과 대조되어 정답 ✓","debilidad: 약함, 나약함으로 frágil과 같은 쪽이라 대조가 안 됩니다 ✗","franqueza: 솔직함으로 강함/약함의 대조와 관계없습니다 ✗"]},{"id":"V8","q":"El asesino resultó ser un tipo frío y ____.","o":["calculador","pasional","sentimental","conmovedor"],"a":0,"k":"성격 형용사","t":"그 살인범은 냉정하고 계산적인 사람으로 밝혀졌다.","e":"calculador/a는 '계산적인, 치밀하게 이익을 따지는'이라는 뜻으로 frío(냉정한)와 함께 자주 쓰입니다. 'frío y calculador'는 굳어진 짝꿍 표현처럼 쓰입니다. resultar ser는 '~인 것으로 드러나다'라는 뜻입니다.","x":["calculador: 계산적인 → frío와 잘 어울려 정답 ✓","pasional: 열정적인, 격정적인이라 frío(냉정한)와 모순됩니다 ✗","sentimental: 감상적인, 감정이 풍부한이라 frío와 반대입니다 ✗","conmovedor: 감동적인(사물·이야기에 주로 씀)이라 살인범 묘사에 맞지 않습니다 ✗"]},{"id":"V9","q":"Mariana se enfada por cualquier cosa, es muy ____.","o":["meticulosa","vergonzosa","quisquillosa","desvergonzada"],"a":2,"k":"성격 형용사","t":"마리아나는 아무것도 아닌 일에도 화를 낸다, 아주 까다롭다.","e":"quisquilloso/a는 '사소한 일에 쉽게 기분 상하고 트집 잡는, 까다로운'이라는 뜻입니다. 'se enfada por cualquier cosa(아무 일에나 화낸다)'와 의미가 딱 맞습니다.","x":["meticulosa: 꼼꼼한, 세심한이라 화를 잘 내는 것과 다릅니다 ✗","vergonzosa: 수줍음 많은, 부끄러워하는이라 문맥과 무관합니다 ✗","quisquillosa: 사소한 일에 쉽게 발끈하는, 까다로운 → 정답 ✓","desvergonzada: 뻔뻔한, 염치없는이라 의미가 맞지 않습니다 ✗"]},{"id":"V10","q":"Los hijos de Aurora tienen buenos ____, los ha educado muy bien.","o":["modos","tonos","estilos","modales"],"a":3,"k":"예절 어휘","t":"아우로라의 아이들은 예의가 바르다, 그녀가 아이들을 아주 잘 가르쳤다.","e":"modales(복수형)는 '예의범절, 행동거지'를 뜻하며 'tener buenos modales(예의가 바르다)'는 자주 쓰는 표현입니다. 반대는 'tener malos modales(버릇이 없다)'입니다. 교육(educar)을 잘 받았다는 내용과 잘 맞습니다.","x":["modos: 방식, 방법이라 '예의'의 뜻으로는 주로 modales를 씁니다 ✗","tonos: 어조, 톤이라 문맥과 맞지 않습니다 ✗","estilos: 스타일, 양식이라 예절의 뜻이 아닙니다 ✗","modales: 예의범절 → 'tener buenos modales'라는 고정 표현으로 정답 ✓"]},{"id":"V11","q":"Es una noticia ____, por eso nos quedamos mudos cuando nos enteramos.","o":["estallido","bomba","explosión","bala"],"a":1,"k":"관용 표현","t":"그건 폭탄 같은 뉴스였고, 그래서 우리는 소식을 들었을 때 말을 잃었다.","e":"'noticia bomba'는 '충격적인 뉴스, 폭탄 뉴스'라는 뜻의 관용 표현입니다. 여기서 bomba는 명사 뒤에서 형용사처럼 쓰여 성·수 변화를 하지 않습니다. quedarse mudo는 '(놀라서) 말문이 막히다'입니다.","x":["estallido: 폭발, 터짐이라 noticia 뒤에 붙여 쓰지 않습니다 ✗","bomba: 폭탄 → 'noticia bomba(충격 뉴스)' 고정 표현이라 정답 ✓","explosión: 폭발이라 명사 뒤 수식 표현으로 쓰지 않습니다 ✗","bala: 총알이라 이런 관용 표현이 없습니다 ✗"]},{"id":"V12","q":"Este niño es un ____. Sin duda es muy espabilado.","o":["burro","lelo","pícaro","bobo"],"a":2,"k":"성격 어휘","t":"이 아이는 꾀돌이다. 확실히 아주 영리하다.","e":"pícaro/a는 '꾀바른, 약삭빠른, 장난기 있는 영리한 사람'을 뜻합니다. 뒷문장의 espabilado(눈치 빠르고 영리한)와 의미가 통합니다. 나머지 보기는 모두 '바보'라는 뜻이라 반대입니다.","x":["burro: 당나귀, 비유적으로 멍청이라 espabilado와 반대입니다 ✗","lelo: 멍한 사람, 바보라 문맥과 반대입니다 ✗","pícaro: 꾀바른 아이, 영리한 장난꾸러기 → 정답 ✓","bobo: 바보, 얼간이라 문맥과 반대입니다 ✗"]},{"id":"V13","q":"Confía en mí, yo nunca te ____.","o":["soportaré","aplaudiré","defraudaré","aguantaré"],"a":2,"k":"동사 어휘","t":"나를 믿어, 나는 절대 너를 실망시키지 않을 거야.","e":"defraudar는 '(기대·신뢰를) 저버리다, 실망시키다'라는 뜻입니다. 'Confía en mí(나를 믿어)'와 짝을 이루어 신뢰를 배신하지 않겠다는 의미가 됩니다. 예: No quiero defraudar a mis padres.(부모님을 실망시키고 싶지 않다.)","x":["soportaré: soportar(참다, 견디다)로 신뢰와 연결되지 않습니다 ✗","aplaudiré: aplaudir(박수 치다)로 문맥과 맞지 않습니다 ✗","defraudaré: defraudar(실망시키다, 배신하다) → 정답 ✓","aguantaré: aguantar(참다, 버티다)로 의미가 맞지 않습니다 ✗"]},{"id":"V14","q":"Esta semana tengo ____ de tarde en el restaurante.","o":["turno","jornada","orden","hora"],"a":0,"k":"직장 어휘","t":"이번 주에 나는 식당에서 오후 근무조다.","e":"turno는 '(교대) 근무 시간, 차례'를 뜻합니다. 'turno de mañana/tarde/noche'는 오전·오후·야간 근무조라는 표현입니다. 'Te toca a ti, es tu turno.(네 차례야.)'처럼 '순번'의 뜻도 있습니다.","x":["turno: 교대 근무 시간 → 'turno de tarde(오후조)'로 정답 ✓","jornada: 하루 근무 시간 전체(jornada completa 전일제)라 'de tarde'와 쓰기 어색합니다 ✗","orden: 순서, 명령이라 근무 시간 뜻이 아닙니다 ✗","hora: 시간, 시각이라 'tener hora'는 '예약이 있다'는 뜻이 됩니다 ✗"]},{"id":"V15","q":"Greta Thunberg es una conocida ____ medioambiental.","o":["activista","abolicionista","medallista","documentalista"],"a":0,"k":"직업·인물 어휘","t":"그레타 툰베리는 유명한 환경 운동가이다.","e":"activista는 '(사회·정치) 운동가, 활동가'를 뜻합니다. -ista로 끝나는 명사는 남녀 형태가 같아 관사로 성을 구분합니다(el/la activista). 'activista medioambiental'은 환경 운동가입니다.","x":["activista: 운동가, 활동가 → 정답 ✓","abolicionista: (노예제·사형제 등) 폐지론자라 환경과 관계없습니다 ✗","medallista: 메달리스트(메달 수상자)라 맞지 않습니다 ✗","documentalista: 다큐멘터리 제작자 또는 문헌 정리 전문가라 맞지 않습니다 ✗"]},{"id":"V16","q":"María ha descubierto que su marido tiene una ____, aunque todos sabían de sus infidelidades.","o":["socia","amante","colega","compañera"],"a":1,"k":"인간관계 어휘","t":"마리아는 남편에게 내연녀가 있다는 걸 알게 되었다, 모두가 그의 외도를 알고 있었지만.","e":"amante는 '애인, 정부(불륜 상대)'를 뜻합니다. infidelidades(외도, 불륜)라는 단어가 결정적인 힌트입니다. amante는 남녀 형태가 같으며 '애호가'라는 뜻도 있습니다(amante de la música 음악 애호가).","x":["socia: (사업) 동업자, 회원이라 불륜과 무관합니다 ✗","amante: 불륜 상대, 정부 → 정답 ✓","colega: 동료라 외도 문맥과 맞지 않습니다 ✗","compañera: 동료, 동반자(때로 배우자)라 외도 상대 뜻은 아닙니다 ✗"]},{"id":"V17","q":"Le dimos un ____ al paciente porque le estaba dando un ataque de ansiedad.","o":["calmante","antiinflamatorio","antipirético","analgésico"],"a":0,"k":"약 어휘","t":"그 환자에게 불안 발작이 오고 있어서 우리는 진정제를 주었다.","e":"calmante는 calmar(진정시키다)에서 나온 말로 '진정제'입니다. 불안 발작(ataque de ansiedad)에는 마음을 가라앉히는 약이 필요하므로 정답입니다. 다른 보기는 염증·열·통증을 다스리는 약입니다.","x":["calmante: 진정제 → 불안 발작에 쓰는 약이라 정답 ✓","antiinflamatorio: 소염제(염증을 줄이는 약)라 맞지 않습니다 ✗","antipirético: 해열제라 불안 증세와 무관합니다 ✗","analgésico: 진통제라 불안을 가라앉히는 약이 아닙니다 ✗"]},{"id":"V18","q":"¿Dónde compraste los ____ del sofá? ¡Son preciosos!","o":["cojines","roperos","colchones","estantes"],"a":0,"k":"가구·소품 어휘","t":"소파 쿠션들 어디서 샀어? 정말 예쁘다!","e":"cojín(복수 cojines)은 '쿠션'입니다. 소파 위에 올려놓는 소품이므로 'cojines del sofá'가 자연스럽습니다. 복수형이 되면 강세 표시가 사라지는 점(cojín → cojines)도 기억하세요.","x":["cojines: 쿠션들 → 소파의 소품이라 정답 ✓","roperos: 옷장들이라 소파에 딸린 물건이 아닙니다 ✗","colchones: 매트리스들이라 침대에 쓰는 것입니다 ✗","estantes: 선반들이라 소파와 관계없습니다 ✗"]},{"id":"V19","q":"Los niños están ____, diles que se callen.","o":["alborotados","serenos","sosegados","embobados"],"a":0,"k":"상태 형용사","t":"아이들이 떠들썩하게 난리야, 조용히 하라고 해.","e":"alborotado/a는 '소란스러운, 들떠서 떠드는'이라는 뜻입니다. 조용히 시키라는(diles que se callen) 뒷문장과 맞아떨어집니다. 동사 alborotar는 '소란을 피우다', 명사 alboroto는 '소동'입니다.","x":["alborotados: 소란스러운, 떠들썩한 → 정답 ✓","serenos: 차분한, 평온한이라 조용히 시킬 필요가 없습니다 ✗","sosegados: 침착한, 조용한이라 문맥과 반대입니다 ✗","embobados: 멍하니 넋을 잃은이라 떠드는 상태가 아닙니다 ✗"]},{"id":"V20","q":"La ____ es consecuencia del tiempo seco y la falta de lluvia durante un largo periodo.","o":["contaminación","radiación","inundación","sequía"],"a":3,"k":"환경·기후 어휘","t":"가뭄은 오랜 기간 건조한 날씨와 비 부족의 결과이다.","e":"sequía는 seco(건조한)와 관련된 말로 '가뭄'을 뜻합니다. 건조한 날씨와 비가 오지 않는 상황이 원인이라는 설명에 딱 맞습니다. 반대 현상은 inundación(홍수)입니다.","x":["contaminación: 오염이라 비 부족의 결과가 아닙니다 ✗","radiación: 방사선, 복사라 기후 설명과 맞지 않습니다 ✗","inundación: 홍수, 침수라 비가 많이 올 때 생깁니다 ✗","sequía: 가뭄 → 정답 ✓"]},{"id":"V21","q":"Para que su paquete llegue antes, puede usar el envío ____.","o":["ordinario","normal","urgente","extraordinario"],"a":2,"k":"우편 어휘","t":"소포가 더 빨리 도착하도록 빠른우편(특급 배송)을 이용하실 수 있습니다.","e":"'envío urgente'는 '빠른우편, 특급 배송'을 뜻합니다. urgente는 '긴급한'이라는 뜻으로, 더 빨리 도착하게 하려면 이 서비스를 고르는 것이 맞습니다. 일반 배송은 envío ordinario라고 합니다.","x":["ordinario: 일반의, 보통의 → 일반 배송이라 더 빠르지 않습니다 ✗","normal: 보통의라 빨리 도착하게 하는 방법이 아닙니다 ✗","urgente: 긴급한 → 'envío urgente(빠른우편)'로 정답 ✓","extraordinario: 특별한, 비범한이라 배송 종류로 쓰지 않습니다 ✗"]},{"id":"V22","q":"Antes de tomar una mala decisión, debes ____ sobre el asunto.","o":["reflexionar","filosofar","fingir","especular"],"a":0,"k":"사고 동사","t":"잘못된 결정을 내리기 전에 그 문제에 대해 곰곰이 생각해야 한다.","e":"reflexionar sobre algo는 '~에 대해 숙고하다, 깊이 생각하다'라는 뜻입니다. 결정을 내리기 전에 신중히 생각하라는 조언이므로 가장 자연스럽습니다. 명사는 reflexión(숙고, 성찰)입니다.","x":["reflexionar: 숙고하다 → 정답 ✓","filosofar: 철학적으로 사색하다(종종 장황하게 따지다)라 조언으로 어색합니다 ✗","fingir: ~인 척하다라 의미가 맞지 않습니다 ✗","especular: 추측하다, 투기하다라 신중한 숙고의 뜻이 아닙니다 ✗"]},{"id":"V23","q":"Estamos hartos de tus ____, eres demasiado estricta con nosotros.","o":["alabanzas","piropos","exigencias","cumplidos"],"a":2,"k":"요구·칭찬 어휘","t":"우리는 너의 요구에 질렸어, 너는 우리에게 너무 엄격해.","e":"exigencia는 exigir(요구하다)의 명사로 '(까다로운) 요구'를 뜻합니다. '너무 엄격하다'는 뒷문장과 연결되므로 exigencias가 정답입니다. estar harto de는 '~에 진절머리가 나다'입니다.","x":["alabanzas: 칭찬, 찬사라 엄격함과 맞지 않습니다 ✗","piropos: (주로 이성에게 하는) 칭찬의 말, 작업 멘트라 맞지 않습니다 ✗","exigencias: 요구 사항, 까다로운 요구 → 정답 ✓","cumplidos: 칭찬, 인사치레라 엄격함과 반대입니다 ✗"]},{"id":"V24","q":"Marta siempre ha sido una persona ____ y prudente.","o":["irresponsable","irreflexiva","alocada","sensata"],"a":3,"k":"성격 형용사","t":"마르타는 항상 분별 있고 신중한 사람이었다.","e":"sensato/a는 '분별 있는, 사리에 맞게 판단하는'이라는 뜻으로 prudente(신중한)와 잘 어울립니다. 주의: sensible은 '예민한, 감수성이 풍부한'이라는 다른 뜻이니 헷갈리지 마세요.","x":["irresponsable: 무책임한이라 prudente와 어울리지 않습니다 ✗","irreflexiva: 경솔한, 생각 없이 행동하는이라 prudente와 반대입니다 ✗","alocada: 경박한, 무모한이라 문맥과 반대입니다 ✗","sensata: 분별 있는 → prudente와 짝을 이뤄 정답 ✓"]},{"id":"V25","q":"La bollería industrial no está permitida en las dietas de ____.","o":["adelgazamiento","aumento","estrechamiento","encogimiento"],"a":0,"k":"식생활 어휘","t":"공장에서 만든 빵·과자류는 다이어트(체중 감량) 식단에서 허용되지 않는다.","e":"adelgazamiento는 adelgazar(살을 빼다)의 명사로 '체중 감량'입니다. 'dieta de adelgazamiento'는 '체중 감량 식단'이라는 자주 쓰는 표현입니다. bollería industrial은 공장에서 대량 생산한 빵·케이크류를 말합니다.","x":["adelgazamiento: 체중 감량 → 정답 ✓","aumento: 증가라 'dieta de aumento'는 쓰지 않습니다(체중 증가는 aumento de peso) ✗","estrechamiento: 좁아짐, 협착이라 식단과 무관합니다 ✗","encogimiento: 줄어듦, 수축이라 식단과 무관합니다 ✗"]},{"id":"V26","q":"Si ____ bien la comida, nuestra digestión será más fácil.","o":["sorbemos","chupamos","escupimos","masticamos"],"a":3,"k":"먹기 동작 동사","t":"음식을 잘 씹으면 소화가 더 쉬워질 것이다.","e":"masticar는 '(음식을) 씹다'라는 뜻입니다. 잘 씹어야 소화(digestión)가 쉬워지므로 정답입니다. 껌은 'chicle'이며 '껌을 씹다'는 mascar chicle라고도 합니다.","x":["sorbemos: sorber(홀짝이다, 빨아 마시다)로 소화와 직접 관련이 약합니다 ✗","chupamos: chupar(빨다, 핥다)로 음식을 잘 소화시키는 동작이 아닙니다 ✗","escupimos: escupir(뱉다)로 먹지 않으면 소화할 것도 없습니다 ✗","masticamos: masticar(씹다) → 정답 ✓"]},{"id":"V27","q":"Voy a pasar unos meses en Londres para ____ mi nivel de inglés.","o":["fomentar","comparar","empeorar","mejorar"],"a":3,"k":"동사 어휘","t":"나는 영어 실력을 향상시키기 위해 런던에서 몇 달을 보낼 것이다.","e":"mejorar는 '개선하다, 향상시키다'라는 뜻입니다. 'mejorar el nivel de un idioma(언어 실력을 늘리다)'는 아주 자주 쓰는 표현입니다. 반대말은 empeorar(악화시키다)입니다.","x":["fomentar: 장려하다, 촉진하다로, 실력에는 잘 쓰지 않습니다 ✗","comparar: 비교하다라 목적에 맞지 않습니다 ✗","empeorar: 악화시키다라 일부러 할 리 없습니다 ✗","mejorar: 향상시키다 → 정답 ✓"]},{"id":"V28","q":"Voy a lavar estas camisas, están llenas de ____.","o":["agujeros","restos","manchas","desperfectos"],"a":2,"k":"의류 상태 어휘","t":"이 셔츠들 빨래할게, 얼룩투성이야.","e":"mancha는 '얼룩, 때'입니다. 빨래(lavar)를 하는 이유가 얼룩이므로 정답입니다. 'estar lleno de ~'는 '~로 가득하다'이며, 동사 manchar는 '더럽히다, 얼룩지게 하다'입니다.","x":["agujeros: 구멍들이라 빨아도 해결되지 않습니다 ✗","restos: 잔해, 나머지라 셔츠에 대해 쓰기 어색합니다 ✗","manchas: 얼룩들 → 빨래하는 이유라 정답 ✓","desperfectos: 손상, 흠집이라 세탁보다 수선이 필요합니다 ✗"]},{"id":"V29","q":"No hay vuelo directo al destino que hemos elegido, así que tendremos que hacer ____.","o":["retención","alto","escala","estación"],"a":2,"k":"여행 어휘","t":"우리가 고른 목적지로 가는 직항편이 없어서 경유해야 할 것이다.","e":"'hacer escala'는 '(비행기·배가) 경유하다, 중간 기착하다'라는 고정 표현입니다. 직항(vuelo directo)이 없다는 앞 문장과 자연스럽게 이어집니다. 예: Hicimos escala en Madrid.(마드리드를 경유했다.)","x":["retención: 정체, 억류라 비행 경유의 뜻이 아닙니다 ✗","alto: 'hacer un alto'는 잠시 멈추다는 뜻이고 관사 없이 쓰지 않으며 비행 경유 표현도 아닙니다 ✗","escala: 경유, 기착 → 'hacer escala'로 정답 ✓","estación: 역, 계절이라 hacer와 함께 경유 뜻이 되지 않습니다 ✗"]},{"id":"V30","q":"Me casaré con mi ____ el año que viene.","o":["marido","prometido","cónyuge","comprometido"],"a":1,"k":"가족·관계 어휘","t":"나는 내년에 약혼자와 결혼할 것이다.","e":"prometido/a는 '약혼자'입니다(prometer 약속하다에서 나옴). 아직 결혼 전이므로 '남편(marido)'이나 '배우자(cónyuge)'는 맞지 않습니다. comprometido는 '약혼한(형용사)'이나 '헌신적인'의 뜻으로 주로 써서 명사 '약혼자'로는 prometido가 자연스럽습니다.","x":["marido: 남편이라 이미 결혼한 사람에게 씁니다 ✗","prometido: 약혼자 → 정답 ✓","cónyuge: 배우자(법률 용어)라 결혼 전에는 쓸 수 없습니다 ✗","comprometido: 'estar comprometido(약혼한 상태다)'처럼 형용사로 주로 써서 여기선 어색합니다 ✗"]},{"id":"V31","q":"Pocos están a favor de la ____ de estas becas porque ayudan a muchos estudiantes.","o":["omisión","exclusión","adición","supresión"],"a":3,"k":"사회·교육 어휘","t":"이 장학금들은 많은 학생을 돕기 때문에 그 폐지에 찬성하는 사람은 거의 없다.","e":"supresión은 suprimir(폐지하다, 없애다)의 명사로 '(제도·혜택의) 폐지'를 뜻합니다. 장학금이 학생들을 돕기 때문에 '폐지'에 찬성하는 사람이 적다는 논리가 맞습니다. 예: la supresión de un impuesto(세금 폐지)","x":["omisión: 생략, 누락이라 제도를 없애는 뜻이 아닙니다 ✗","exclusión: 배제, 제외라 장학금 '제도'에는 잘 쓰지 않습니다 ✗","adición: 추가, 덧셈이라 돕는 제도를 늘리는 데 반대할 이유가 없습니다 ✗","supresión: 폐지 → 정답 ✓"]},{"id":"V32","q":"El hijo de Marina es una preciosidad. ¡Qué bebé tan ____!","o":["lindo","llorón","regordete","pequeño"],"a":0,"k":"외모 형용사","t":"마리나의 아들은 정말 귀여워. 어쩜 이렇게 예쁜 아기일까!","e":"lindo/a는 '예쁜, 귀여운'이라는 뜻으로 앞 문장의 preciosidad(아주 예쁜 것)와 의미가 이어집니다. 중남미에서는 lindo가 bonito보다 훨씬 자주 쓰이는 일상어입니다. '¡Qué + 명사 + tan + 형용사!'는 감탄문 구조입니다.","x":["lindo: 예쁜, 귀여운 → preciosidad와 어울려 정답 ✓","llorón: 잘 우는, 울보라 칭찬의 맥락과 맞지 않습니다 ✗","regordete: 통통한이라 '예쁘다'는 앞 문장을 직접 받지 않습니다 ✗","pequeño: 작은이라 감탄의 이유로 부족합니다 ✗"]},{"id":"V33","q":"La ____ de expresión es fundamental en un estado democrático.","o":["ausencia","voluntad","restricción","libertad"],"a":3,"k":"사회·정치 어휘","t":"표현의 자유는 민주 국가에서 필수적이다.","e":"'libertad de expresión'은 '표현의 자유'라는 고정 표현입니다. 민주 국가의 기본 가치라는 문맥과 딱 맞습니다. 비슷하게 libertad de prensa(언론의 자유), libertad de culto(종교의 자유)도 있습니다.","x":["ausencia: 부재, 없음이라 민주 국가의 필수 요소가 될 수 없습니다 ✗","voluntad: 의지라 'voluntad de expresión'은 쓰지 않습니다 ✗","restricción: 제한이라 민주주의 가치와 반대입니다 ✗","libertad: 자유 → 'libertad de expresión(표현의 자유)'으로 정답 ✓"]},{"id":"V34","q":"Olga ____ en viajar por la noche y no hay manera de que cambie de idea.","o":["se ha obstinado","ha quedado","se ha interesado","ha influido"],"a":0,"k":"대명동사 어휘","t":"올가는 밤에 여행하겠다고 고집을 부렸고 그녀의 생각을 바꿀 방법이 없다.","e":"obstinarse en + 동사원형은 '~하겠다고 고집하다'라는 뜻입니다. 뒤의 'no hay manera de que cambie de idea(생각을 바꿀 방법이 없다)'가 고집을 보여 주는 힌트입니다. 비슷한 표현으로 empeñarse en, insistir en이 있습니다.","x":["se ha obstinado: obstinarse en(~을 고집하다) → 정답 ✓","ha quedado: quedar en은 '~하기로 약속하다'라 고집의 뜻이 없습니다 ✗","se ha interesado: interesarse por/en(~에 관심을 갖다)로 생각을 안 바꾼다는 내용과 맞지 않습니다 ✗","ha influido: influir en(~에 영향을 주다)로 의미가 맞지 않습니다 ✗"]},{"id":"V35","q":"____ porque había comido algo en mal estado.","o":["Me resfrié","Temblé","Me constipé","Vomité"],"a":3,"k":"건강·증상 어휘","t":"상한 음식을 먹어서 나는 토했다.","e":"vomitar는 '토하다, 구토하다'입니다. 'comer algo en mal estado(상한 음식을 먹다)'의 결과로 가장 자연스럽습니다. 감기 걸리다(resfriarse, constiparse)는 상한 음식과 관계없습니다.","x":["Me resfrié: resfriarse(감기에 걸리다)로 상한 음식과 무관합니다 ✗","Temblé: temblar(떨다)로 원인과 결과가 맞지 않습니다 ✗","Me constipé: constiparse(감기에 걸리다, 스페인 구어)로 원인이 맞지 않습니다 ✗","Vomité: vomitar(토하다) → 정답 ✓"]},{"id":"V36","q":"Las consecuencias del calentamiento global pueden ser ____ para el planeta.","o":["favorables","provechosas","prácticas","devastadoras"],"a":3,"k":"환경 어휘","t":"지구 온난화의 결과는 지구에 파괴적일 수 있다.","e":"devastador/a는 devastar(황폐하게 하다)에서 나온 형용사로 '파괴적인, 참혹한'입니다. 지구 온난화(calentamiento global)의 부정적 결과를 설명하므로 정답입니다.","x":["favorables: 유리한, 호의적인이라 문맥과 반대입니다 ✗","provechosas: 이로운, 유익한이라 문맥과 반대입니다 ✗","prácticas: 실용적인이라 의미가 맞지 않습니다 ✗","devastadoras: 파괴적인 → 정답 ✓"]},{"id":"V37","q":"¡Qué salón tan ____! Es muy agradable estar aquí.","o":["horroroso","sucio","espantoso","acogedor"],"a":3,"k":"집 묘사 형용사","t":"정말 아늑한 거실이야! 여기 있으니 아주 기분 좋아.","e":"acogedor/a는 acoger(맞아들이다)에서 나온 형용사로 '아늑한, 포근한, 친근한'입니다. 뒷문장 'Es muy agradable estar aquí'와 의미가 이어집니다.","x":["horroroso: 끔찍한이라 기분 좋다는 말과 모순됩니다 ✗","sucio: 더러운이라 문맥과 반대입니다 ✗","espantoso: 끔찍한, 무시무시한이라 문맥과 반대입니다 ✗","acogedor: 아늑한 → 정답 ✓"]},{"id":"V38","q":"Ponte el ____ si no quieres mojarte.","o":["jersey","chándal","chubasquero","pijama"],"a":2,"k":"의류 어휘","t":"젖고 싶지 않으면 비옷을 입어.","e":"chubasquero는 chubasco(소나기)에서 나온 말로 얇은 '비옷, 방수 재킷'입니다. 젖지 않으려면(si no quieres mojarte) 입는 옷이라 정답입니다. impermeable도 같은 뜻으로 많이 씁니다.","x":["jersey: 스웨터라 비를 막지 못합니다 ✗","chándal: 운동복(트레이닝복, 스페인어)이라 방수가 되지 않습니다 ✗","chubasquero: 비옷, 방수 재킷 → 정답 ✓","pijama: 잠옷이라 문맥과 맞지 않습니다 ✗"]},{"id":"V39","q":"Vivimos en una ____ rústica lejos de la ciudad.","o":["botica","confitería","droguería","finca"],"a":3,"k":"주거 어휘","t":"우리는 도시에서 멀리 떨어진 시골 농장 주택에 산다.","e":"finca는 '(시골의) 농장, 토지가 딸린 집'을 뜻합니다. 'finca rústica'는 시골 땅·농가를 가리키는 표현입니다. 중남미에서는 finca가 커피 농장 등 '농장'의 뜻으로 특히 자주 쓰입니다.","x":["botica: 약국(옛말)이라 사는 곳이 아닙니다 ✗","confitería: 과자점, 제과점이라 주거지가 아닙니다 ✗","droguería: 생활용품점(스페인), 약재상이라 주거지가 아닙니다 ✗","finca: 시골 농장, 토지 딸린 집 → 정답 ✓"]},{"id":"V40","q":"Las redes sociales tienen millones de ____ en todo el mundo.","o":["emprendedores","compradores","usuarios","clientes"],"a":2,"k":"인터넷 어휘","t":"소셜 네트워크는 전 세계에 수백만 명의 사용자가 있다.","e":"usuario/a는 '사용자, 이용자'로, 앱·인터넷 서비스·대중교통 등을 이용하는 사람을 말합니다. 소셜 미디어(redes sociales)는 물건을 사는 곳이 아니라 '이용'하는 서비스이므로 usuarios가 정답입니다.","x":["emprendedores: 창업가들이라 SNS 이용자를 뜻하지 않습니다 ✗","compradores: 구매자들이라 SNS와 맞지 않습니다 ✗","usuarios: 사용자들 → 정답 ✓","clientes: 고객들이라 무료 SNS 이용자에게는 잘 쓰지 않습니다 ✗"]},{"id":"V41","q":"Hoy en clase de biología hablaremos de la teoría de la ____ de Darwin.","o":["evolución","renovación","progresión","transformación"],"a":0,"k":"과학 어휘","t":"오늘 생물 시간에는 다윈의 진화론에 대해 이야기할 것이다.","e":"'teoría de la evolución'은 '진화론'이라는 고정 표현입니다. 다윈의 이론이라는 점이 결정적 힌트입니다. 동사 evolucionar는 '진화하다, 발전하다'입니다.","x":["evolución: 진화 → '진화론'으로 정답 ✓","renovación: 갱신, 쇄신이라 다윈의 이론과 무관합니다 ✗","progresión: 진행, 수열이라 맞지 않습니다 ✗","transformación: 변형, 변화라 다윈 이론의 정식 명칭이 아닙니다 ✗"]},{"id":"V42","q":"Por desgracia, Luisa tuvo un ____ espontáneo en el segundo mes de su embarazo.","o":["alumbramiento","parto","aborto","nacimiento"],"a":2,"k":"의료 어휘","t":"안타깝게도 루이사는 임신 두 달째에 자연 유산을 겪었다.","e":"aborto는 '유산, 낙태'를 뜻하며 'aborto espontáneo'는 '자연 유산'입니다(인공 임신 중절은 aborto provocado/inducido). por desgracia(안타깝게도)와 임신 2개월이라는 정보가 힌트입니다.","x":["alumbramiento: 출산, 분만(격식어)이라 임신 2개월에는 맞지 않습니다 ✗","parto: 출산, 분만이라 문맥과 맞지 않습니다 ✗","aborto: 유산 → 'aborto espontáneo(자연 유산)'로 정답 ✓","nacimiento: 탄생이라 '불행히도'라는 표현과 맞지 않습니다 ✗"]},{"id":"V43","q":"Como me dio un mareo, la enfermera me dijo que ____ en la camilla.","o":["me tumbara","me durmiera","me desplomara","me cayera"],"a":0,"k":"동작 동사·접속법","t":"내가 어지러워서 간호사가 진료 침대에 누우라고 했다.","e":"tumbarse는 '눕다, 드러눕다'입니다. 'decir que + 접속법(바람·명령을 나타낼 때 쓰는 동사 형태)'은 '~하라고 말하다'라는 지시를 뜻하며, 과거라서 접속법 과거 me tumbara가 쓰였습니다. camilla는 '진료용 간이침대, 들것'입니다.","x":["me tumbara: tumbarse(눕다) → 어지러울 때 하는 행동이라 정답 ✓","me durmiera: dormirse(잠들다)로 간호사가 지시할 내용이 아닙니다 ✗","me desplomara: desplomarse(털썩 쓰러지다)로 지시할 동작이 아닙니다 ✗","me cayera: caerse(넘어지다)로 지시할 수 없는 동작입니다 ✗"]},{"id":"V44","q":"Apenas duerme tres horas cada noche, por eso está ____.","o":["serena","animada","sosegada","agotada"],"a":3,"k":"상태 형용사","t":"그녀는 매일 밤 겨우 세 시간 자서 기진맥진하다.","e":"agotado/a는 agotar(고갈시키다)에서 나온 말로 '기진맥진한, 녹초가 된'입니다. 잠을 거의 못 잔(apenas duerme) 결과로 자연스럽습니다. 물건에 쓰면 '품절된'이라는 뜻도 있습니다(Está agotado. 품절이다).","x":["serena: 차분한이라 수면 부족의 결과로 맞지 않습니다 ✗","animada: 활기찬이라 문맥과 반대입니다 ✗","sosegada: 평온한이라 문맥과 맞지 않습니다 ✗","agotada: 기진맥진한 → 정답 ✓"]},{"id":"V45","q":"La impactante noticia causó un gran ____ mediático.","o":["trueno","vuelo","revuelo","zumbido"],"a":2,"k":"언론 어휘","t":"그 충격적인 뉴스는 언론에 큰 파장(소동)을 일으켰다.","e":"revuelo는 '소동, 술렁임, 파문'입니다. 'causar revuelo'는 '파문을 일으키다', 'revuelo mediático'는 '언론의 떠들썩한 반응'이라는 자주 쓰는 표현입니다. vuelo(비행)와 헷갈리지 마세요.","x":["trueno: 천둥이라 비유로 쓰지 않습니다 ✗","vuelo: 비행, 항공편이라 의미가 맞지 않습니다 ✗","revuelo: 소동, 파문 → 'revuelo mediático'로 정답 ✓","zumbido: 윙윙거리는 소리라 맞지 않습니다 ✗"]},{"id":"V46","q":"Cada vez que vamos a una fiesta, José ____ con alguna chica. Siempre ha sido mujeriego.","o":["pelea","compite","discute","liga"],"a":3,"k":"구어 동사","t":"우리가 파티에 갈 때마다 호세는 어떤 여자에게 작업을 건다. 그는 늘 바람둥이였다.","e":"ligar con alguien은 스페인 구어로 '~에게 작업을 걸다, 이성과 사귀다(꼬시다)'라는 뜻입니다. mujeriego(여자를 밝히는 남자, 바람둥이)가 결정적 힌트입니다. 중남미에서는 지역에 따라 levantar, ligar 등 다양한 표현을 씁니다.","x":["pelea: pelear(싸우다)로 mujeriego와 연결되지 않습니다 ✗","compite: competir(경쟁하다)로 맞지 않습니다 ✗","discute: discutir(말다툼하다)로 맞지 않습니다 ✗","liga: ligar(작업 걸다) → 정답 ✓"]},{"id":"V47","q":"Mi tío es un vago que vive del ____.","o":["mito","relato","cuento","poema"],"a":2,"k":"관용 표현","t":"우리 삼촌은 거짓말로 먹고사는 게으름뱅이다.","e":"'vivir del cuento'는 '일하지 않고 남을 속이거나 요령으로 먹고살다'라는 관용 표현입니다. vago(게으름뱅이)와 의미가 이어집니다. cuento는 원래 '이야기, 동화'인데 '거짓말, 꾸며낸 말'의 뜻도 있습니다.","x":["mito: 신화라 이런 관용 표현이 없습니다 ✗","relato: 이야기, 서술이라 관용 표현에 쓰지 않습니다 ✗","cuento: 이야기, 꾸며낸 말 → 'vivir del cuento'로 정답 ✓","poema: 시라 관용 표현에 쓰지 않습니다 ✗"]},{"id":"V48","q":"En países donde llueve mucho es común tener una ____.","o":["aspiradora","cosechadora","lavadora","secadora"],"a":3,"k":"가전제품 어휘","t":"비가 많이 오는 나라에서는 건조기가 있는 것이 흔하다.","e":"secadora는 secar(말리다)에서 나온 말로 '(빨래) 건조기'입니다. 비가 많이 와서 빨래를 밖에 말리기 어려운 나라라는 문맥과 맞습니다. 헤어드라이어는 secador라고 합니다.","x":["aspiradora: 진공청소기라 비와 관계없습니다 ✗","cosechadora: 수확기(농기계)라 맞지 않습니다 ✗","lavadora: 세탁기라 비가 많은 것과 특별한 관계가 없습니다 ✗","secadora: 빨래 건조기 → 정답 ✓"]},{"id":"V49","q":"Me gusta muchísimo comer ____, sobre todo los mejillones.","o":["legumbres","verdura","embutidos","marisco"],"a":3,"k":"음식 어휘","t":"나는 해산물 먹는 것을 정말 좋아하는데, 특히 홍합을 좋아한다.","e":"marisco는 '해산물(갑각류·조개류)'입니다. 홍합(mejillones)은 조개류이므로 marisco에 속합니다. 스페인 요리에서는 새우(gambas), 오징어(calamares) 등이 대표적인 marisco 재료입니다.","x":["legumbres: 콩류(렌즈콩, 병아리콩 등)라 홍합과 관계없습니다 ✗","verdura: 채소라 홍합과 관계없습니다 ✗","embutidos: 소시지·햄 같은 가공육이라 맞지 않습니다 ✗","marisco: 해산물 → 정답 ✓"]},{"id":"V50","q":"Ernesto no tiene un ____ de tonto. Al contrario, es más listo que el hambre.","o":["mechón","cabello","pelo","flequillo"],"a":2,"k":"관용 표현","t":"에르네스토는 바보 같은 구석이 하나도 없다. 오히려 아주 영리하다.","e":"'no tener (ni) un pelo de tonto'는 '바보 같은 데가 털끝만큼도 없다, 아주 영리하다'는 관용 표현입니다. 'más listo que el hambre(배고픔보다 영리하다)'도 '매우 똑똑하다'는 관용 표현입니다.","x":["mechón: 머리카락 한 움큼(타래)이라 관용 표현에 쓰지 않습니다 ✗","cabello: 머리카락(격식어)이라 관용 표현에 쓰지 않습니다 ✗","pelo: 털, 머리카락 → 'no tener un pelo de tonto'로 정답 ✓","flequillo: 앞머리라 관용 표현에 쓰지 않습니다 ✗"]},{"id":"V51","q":"No puedo echar la basura en este ____ porque está lleno.","o":["barril","contenedor","envase","recipiente"],"a":1,"k":"생활 어휘","t":"이 수거함은 꽉 차서 쓰레기를 버릴 수가 없다.","e":"contenedor는 길가에 놓인 대형 '쓰레기 수거함, 컨테이너'입니다. 'echar la basura en el contenedor(수거함에 쓰레기를 버리다)'는 스페인에서 일상적인 표현입니다. 재활용 수거함도 contenedor de reciclaje라고 합니다.","x":["barril: 통, 배럴(술·기름 통)이라 쓰레기통이 아닙니다 ✗","contenedor: 쓰레기 수거함 → 정답 ✓","envase: (음료·식품) 용기, 포장 용기라 쓰레기를 버리는 곳이 아닙니다 ✗","recipiente: 그릇, 용기 일반이라 쓰레기 수거함으로 쓰지 않습니다 ✗"]},{"id":"V52","q":"El ____ es una representación gráfica de nuestro planeta.","o":["itinerario","plano","mapamundi","callejero"],"a":2,"k":"지도 어휘","t":"세계지도는 우리 행성을 그림으로 나타낸 것이다.","e":"mapamundi는 '세계지도'입니다. 'representación gráfica de nuestro planeta(지구를 그림으로 나타낸 것)'라는 정의에 맞습니다. el mapamundi는 남성 명사입니다.","x":["itinerario: 여행 일정, 경로라 지도가 아닙니다 ✗","plano: (도시·건물) 평면도, 시가지도라 지구 전체가 아닙니다 ✗","mapamundi: 세계지도 → 정답 ✓","callejero: (도시의) 거리 지도책이라 지구 전체가 아닙니다 ✗"]},{"id":"V53","q":"Si no tienes el ____ de circulación en regla, no puedes usar tu auto.","o":["informe","visado","formulario","permiso"],"a":3,"k":"자동차·행정 어휘","t":"자동차 등록증(운행 허가증)이 제대로 갖춰져 있지 않으면 차를 쓸 수 없다.","e":"'permiso de circulación'은 스페인에서 차량 운행 허가증, 즉 자동차 등록증을 말합니다(운전면허는 permiso/carné de conducir). en regla는 '(서류가) 제대로 갖춰진, 규정에 맞는'이라는 뜻입니다. auto는 중남미에서 많이 쓰는 '자동차'입니다(스페인은 주로 coche).","x":["informe: 보고서라 차량 운행 서류가 아닙니다 ✗","visado: 비자라 차와 관계없습니다 ✗","formulario: 서식, 신청서라 허가증이 아닙니다 ✗","permiso: 허가(증) → 'permiso de circulación'으로 정답 ✓"]},{"id":"V54","q":"Comimos tanto en el ____ que acabamos con dolor de barriga.","o":["banco","banquillo","banquito","banquete"],"a":3,"k":"음식·행사 어휘","t":"연회에서 너무 많이 먹어서 우리는 결국 배가 아팠다.","e":"banquete는 '연회, 성대한 잔치'입니다. 많이 먹었다는 문맥과 맞습니다. 비슷한 형태의 banco(은행, 벤치), banquillo(벤치, 피고석) 등과 헷갈리지 마세요. barriga는 '배'의 구어입니다.","x":["banco: 은행, 벤치라 먹는 곳이 아닙니다 ✗","banquillo: (경기장) 벤치, 피고석이라 맞지 않습니다 ✗","banquito: 작은 걸상이라 맞지 않습니다 ✗","banquete: 연회, 잔치 → 정답 ✓"]},{"id":"V55","q":"Los vegetales son alimentos con gran cantidad de ____.","o":["fibra","manteca","azúcar","grasa"],"a":0,"k":"영양 어휘","t":"채소는 섬유질이 많은 식품이다.","e":"fibra는 '섬유질, 식이섬유'입니다. 채소(vegetales)의 대표적인 영양 성분이므로 정답입니다. 'alimentos ricos en fibra(섬유질이 풍부한 식품)'처럼 자주 씁니다.","x":["fibra: 섬유질 → 정답 ✓","manteca: (돼지)기름, 라드(중남미 일부에서는 버터)라 채소에 많지 않습니다 ✗","azúcar: 설탕, 당이라 채소의 대표 성분이 아닙니다 ✗","grasa: 지방이라 채소에는 적습니다 ✗"]},{"id":"V56","q":"Algunos perros están considerados ____ peligrosas.","o":["razas","clases","categorías","etnias"],"a":0,"k":"동물 어휘","t":"일부 개들은 위험한 견종으로 여겨진다.","e":"raza는 동물의 '품종, 견종'입니다. 'razas de perros peligrosas(위험 견종)'는 법률상 쓰이는 표현입니다. etnia는 사람의 '민족'에만 쓰므로 개에게는 쓰지 않습니다.","x":["razas: 품종, 견종 → 정답 ✓","clases: 종류, 수업이라 견종을 말할 때 쓰지 않습니다 ✗","categorías: 범주, 등급이라 개의 품종에 쓰지 않습니다 ✗","etnias: 민족(사람에게만 씀)이라 ✗"]},{"id":"V57","q":"¡Qué irresponsable! Se pasa el día entero ____.","o":["vagueando","faenando","laborando","aplicándose"],"a":0,"k":"구어 동사","t":"정말 무책임해! 하루 종일 빈둥거리며 지내.","e":"vaguear는 vago(게으른)에서 나온 동사로 '빈둥거리다, 게으름 피우다'입니다. 'pasarse el día + 현재분사'는 '~하며 하루를 보내다'라는 구조입니다. 무책임하다는 비난과 잘 맞습니다.","x":["vagueando: vaguear(빈둥거리다) → 정답 ✓","faenando: faenar(고기잡이 등 일을 하다)로 비난할 이유가 없습니다 ✗","laborando: laborar(일하다, 격식어)로 무책임과 반대입니다 ✗","aplicándose: aplicarse(열심히 하다)로 문맥과 반대입니다 ✗"]},{"id":"V58","q":"Voy a merendar un bocadillo con una ____ de queso y otra de jamón.","o":["rebanada","tajada","rodaja","loncha"],"a":3,"k":"음식 단위 어휘","t":"나는 치즈 한 장과 햄 한 장을 넣은 샌드위치로 간식을 먹을 것이다.","e":"loncha는 햄·치즈를 얇게 썬 '한 장(슬라이스)'입니다. 빵 한 조각은 rebanada, 레몬·소시지처럼 둥글게 썬 것은 rodaja, 고기·수박 조각은 tajada로 구분합니다. merendar는 '간식(오후 새참)을 먹다'입니다.","x":["rebanada: 빵을 썬 한 조각이라 치즈·햄에는 쓰지 않습니다 ✗","tajada: 고기·과일 등 덩어리를 자른 조각이라 얇은 햄에는 어색합니다 ✗","rodaja: 둥글게 썬 조각(레몬, 토마토 등)이라 맞지 않습니다 ✗","loncha: 얇게 썬 한 장(햄, 치즈) → 정답 ✓"]},{"id":"V59","q":"No puedo comprar esa moto, cuesta un ____ de la cara.","o":["ojo","labio","diente","pelo"],"a":0,"k":"관용 표현","t":"그 오토바이는 살 수 없어, 엄청나게 비싸.","e":"'costar un ojo de la cara'는 '눈알 하나 값이 든다', 즉 '엄청나게 비싸다'는 관용 표현입니다. 비슷한 표현으로 'costar un riñón(콩팥 하나 값)'도 있습니다.","x":["ojo: 눈 → 'costar un ojo de la cara(엄청 비싸다)'로 정답 ✓","labio: 입술이라 이런 관용 표현이 없습니다 ✗","diente: 이빨이라 이런 관용 표현이 없습니다 ✗","pelo: 털이라 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"V60","q":"Aunque son ____ en política, son amigos en su vida personal.","o":["afines","cercanos","rivales","inseparables"],"a":2,"k":"인간관계 어휘","t":"그들은 정치에서는 경쟁자이지만 개인적인 삶에서는 친구다.","e":"rival은 '경쟁자, 라이벌'입니다. aunque(~이지만)가 대조를 만들므로 '친구'와 반대되는 관계가 필요합니다. rival은 남녀 형태가 같고, 복수는 rivales입니다.","x":["afines: 생각이 비슷한이라 '친구'와 대조가 되지 않습니다 ✗","cercanos: 가까운이라 대조가 되지 않습니다 ✗","rivales: 경쟁자들 → aunque의 대조를 살려 정답 ✓","inseparables: 떼려야 뗄 수 없는이라 대조가 되지 않습니다 ✗"]},{"id":"V61","q":"Aunque tarde un poco más, prefiero ____ el café en vez de comprarlo ya listo.","o":["colar","batir","moler","exprimir"],"a":2,"k":"요리 동사","t":"시간이 좀 더 걸리더라도 나는 이미 만들어진 커피를 사는 대신 커피콩을 가는 것을 더 좋아한다.","e":"moler는 '(곡물·커피콩을) 갈다, 빻다'입니다. 'moler el café'는 커피콩을 가는 것을 말하며, 갈아 놓은 커피는 café molido라고 합니다. 불규칙 동사로 muelo, mueles…처럼 o가 ue로 바뀝니다.","x":["colar: 거르다(필터로 내리다)라 '이미 만든 것 대신'과 대비가 약합니다. 중남미에서는 커피를 내리다로 쓰기도 합니다 ✗","batir: 휘젓다, 거품 내다라 커피 준비 과정에 맞지 않습니다 ✗","moler: 갈다, 빻다 → 정답 ✓","exprimir: (과일을) 짜다라 커피에는 쓰지 않습니다 ✗"]},{"id":"V62","q":"Este partido es una ____ de otro menos radical.","o":["escisión","desvinculación","amputación","separación"],"a":0,"k":"정치 어휘","t":"이 정당은 덜 급진적인 다른 정당에서 분리되어 나온 분파이다.","e":"escisión은 '(조직·정당의) 분열, 분파'를 뜻하며 'ser una escisión de ~'는 '~에서 갈라져 나온 분파다'라는 표현입니다. 정당처럼 하나의 조직이 쪼개질 때 쓰는 정확한 용어입니다.","x":["escisión: 분열, 분파 → 정당에 쓰는 정확한 용어라 정답 ✓","desvinculación: 관계 단절이라 'ser una desvinculación de'처럼 쓰지 않습니다 ✗","amputación: (신체) 절단이라 맞지 않습니다 ✗","separación: 분리, 별거로 의미는 비슷하나 정당 분파를 가리키는 말로는 쓰지 않습니다 ✗"]},{"id":"V63","q":"Me encantaría ____ la vuelta al mundo. ¿A ti no?","o":["hacer","realizar","dar","efectuar"],"a":2,"k":"동사 결합 표현","t":"세계 일주를 하고 싶어. 너는 안 그래?","e":"'dar la vuelta al mundo'는 '세계 일주를 하다'라는 고정 표현으로 동사 dar와 결합합니다. 'dar una vuelta(산책하다, 한 바퀴 돌다)'도 같은 짝꿍 표현입니다.","x":["hacer: 일반적인 '하다'이지만 이 표현에서는 dar를 씁니다 ✗","realizar: 실행하다(격식)라 이 고정 표현에 쓰지 않습니다 ✗","dar: 'dar la vuelta al mundo(세계 일주하다)' → 정답 ✓","efectuar: 실시하다(격식)라 이 고정 표현에 쓰지 않습니다 ✗"]},{"id":"V64","q":"____ mi familia a mi trabajo es esencial para mí, mis hijos son lo primero.","o":["Interponer","Poner","Proponer","Anteponer"],"a":3,"k":"동사 어휘","t":"가족을 일보다 우선시하는 것은 나에게 아주 중요하다, 내 아이들이 최우선이다.","e":"anteponer A a B는 'A를 B보다 앞에 두다, 우선시하다'입니다(ante=앞 + poner=두다). 'mis hijos son lo primero(아이들이 최우선)'가 결정적 힌트입니다. poner처럼 불규칙 변화합니다(antepongo, antepuse).","x":["Interponer: 사이에 끼워 넣다, (소송을) 제기하다라 맞지 않습니다 ✗","Poner: 두다라 'A a B' 구조로 우선시의 뜻이 되지 않습니다 ✗","Proponer: 제안하다라 의미가 맞지 않습니다 ✗","Anteponer: ~보다 우선시하다 → 정답 ✓"]},{"id":"V65","q":"Los ____ de la Capilla Sixtina fueron realizados en el siglo XVI.","o":["trazos","dibujos","reportajes","frescos"],"a":3,"k":"미술 어휘","t":"시스티나 성당의 프레스코화들은 16세기에 그려졌다.","e":"fresco는 '프레스코화(덜 마른 회반죽 벽에 그린 벽화)'입니다. 미켈란젤로가 그린 시스티나 성당 천장화가 대표적인 fresco입니다. fresco는 형용사로 '시원한, 신선한'이라는 뜻도 있습니다.","x":["trazos: 선, 획이라 작품을 가리키지 않습니다 ✗","dibujos: 소묘, 그림이라 벽화 작품을 정확히 말하지 못합니다 ✗","reportajes: 르포, 취재 기사라 맞지 않습니다 ✗","frescos: 프레스코 벽화 → 정답 ✓"]},{"id":"V66","q":"¡Qué ilusión! Mañana nos ____ las llaves de nuestra nueva vivienda.","o":["adjudican","entregan","atribuyen","presentan"],"a":1,"k":"주거·거래 동사","t":"정말 설레! 내일 우리 새 집 열쇠를 넘겨받아(그들이 우리에게 건네준다).","e":"entregar는 '건네주다, 인도하다'이며 'entregar las llaves'는 새 집이나 차를 인도할 때 쓰는 표현입니다. ¡Qué ilusión!은 '정말 기대돼, 설레!'라는 감탄 표현입니다.","x":["adjudican: adjudicar(낙찰하다, 배정하다)로 '열쇠'와 함께 쓰지 않습니다 ✗","entregan: entregar(건네주다) → 정답 ✓","atribuyen: atribuir(~의 탓/덕으로 돌리다)로 맞지 않습니다 ✗","presentan: presentar(소개하다, 제출하다)로 열쇠 인도의 뜻이 아닙니다 ✗"]},{"id":"V67","q":"Este niño está muy ____, hoy no dice ni mu.","o":["charlatán","hablador","callado","parlanchín"],"a":2,"k":"성격·상태 형용사","t":"이 아이는 아주 조용하다, 오늘은 한마디도 하지 않는다.","e":"callado/a는 callarse(입을 다물다)에서 나온 말로 '말이 없는, 조용한'입니다. 'no decir ni mu'는 '한마디도 안 하다'라는 관용 표현입니다. 나머지 보기는 모두 '수다스러운'이라는 뜻입니다.","x":["charlatán: 수다쟁이, 말이 많은이라 반대입니다 ✗","hablador: 말이 많은이라 반대입니다 ✗","callado: 말이 없는 → 정답 ✓","parlanchín: 수다스러운이라 반대입니다 ✗"]},{"id":"V68","q":"Afortunadamente, nuestro negocio ____ sin problemas.","o":["camina","marcha","corre","anda"],"a":1,"k":"동사 의미 확장","t":"다행히 우리 사업은 문제없이 잘 돌아가고 있다.","e":"marchar는 '행진하다, 떠나다' 외에 '(일·기계가) 잘 진행되다, 돌아가다'라는 뜻이 있습니다. 'El negocio marcha bien(사업이 잘된다)'처럼 씁니다. andar도 비슷하게 쓸 수 있지만 사업에는 marchar가 가장 자연스럽습니다.","x":["camina: caminar(걷다)로 사업 진행에는 쓰지 않습니다 ✗","marcha: marchar(잘 진행되다) → 정답 ✓","corre: correr(달리다)로 사업 진행의 뜻이 아닙니다 ✗","anda: andar도 '돌아가다'로 쓰일 수 있지만 사업 문맥의 표준 표현은 marchar입니다 ✗"]},{"id":"V69","q":"Siempre desayuno porque no me gusta ir a trabajar con el estómago ____.","o":["vacío","lleno","repleto","saciado"],"a":0,"k":"신체 상태 표현","t":"나는 빈속으로 출근하는 것을 싫어해서 항상 아침을 먹는다.","e":"'con el estómago vacío'는 '빈속으로, 공복으로'라는 고정 표현입니다. 아침을 먹는 이유가 빈속을 피하려는 것이므로 vacío가 정답입니다. 약 설명서에서 'en ayunas(공복에)'라는 표현도 자주 봅니다.","x":["vacío: 빈 → 'estómago vacío(빈속)'로 정답 ✓","lleno: 가득 찬이라 아침을 먹는 이유가 되지 않습니다 ✗","repleto: 꽉 찬이라 문맥과 반대입니다 ✗","saciado: 배부른이라 문맥과 반대입니다 ✗"]},{"id":"V70","q":"Tengo la ____ de que va a lograr sus propósitos, es muy tenaz.","o":["certeza","duda","incredulidad","incertidumbre"],"a":0,"k":"확신·의심 어휘","t":"나는 그가 목표를 이룰 거라고 확신한다, 그는 아주 끈질기다.","e":"certeza는 '확신, 확실성'이며 'tener la certeza de que ~'는 '~라고 확신하다'입니다. 확신을 나타내므로 que 뒤에 직설법(va a lograr)이 옵니다. tenaz(끈질긴)가 확신의 근거입니다.","x":["certeza: 확신 → 정답 ✓","duda: 의심이라 tenaz라는 근거와 맞지 않습니다 ✗","incredulidad: 믿지 않음, 불신이라 문맥과 반대입니다 ✗","incertidumbre: 불확실성이라 문맥과 반대입니다 ✗"]},{"id":"V71","q":"Quienes se dejan llevar por la ____ no son personas reflexivas.","o":["flema","ira","calma","quietud"],"a":1,"k":"감정 어휘","t":"분노에 휩쓸리는 사람들은 사려 깊은 사람이 아니다.","e":"ira는 '분노, 격노'입니다. 'dejarse llevar por ~'는 '~에 휩쓸리다'라는 표현으로 감정과 함께 자주 씁니다. 분노에 휩쓸리는 사람은 reflexivo(사려 깊은)하지 않다는 논리가 성립합니다.","x":["flema: 침착함, 냉정함(또는 가래)이라 사려 깊음과 모순되지 않습니다 ✗","ira: 분노 → 정답 ✓","calma: 평온, 침착이라 문맥과 반대입니다 ✗","quietud: 고요함이라 문맥과 반대입니다 ✗"]},{"id":"V72","q":"¿Quieres dejar de ____ a tu hermano de una vez?","o":["animar","contentar","fastidiar","alabar"],"a":2,"k":"동사 어휘","t":"이제 그만 좀 네 동생을 괴롭힐래?","e":"fastidiar는 '귀찮게 하다, 짜증 나게 하다, 괴롭히다'입니다. 'dejar de + 동사원형(~하는 것을 그만두다)'과 'de una vez(이제 그만, 단번에)'가 그만두라는 짜증 섞인 요청을 만듭니다.","x":["animar: 격려하다, 기운 나게 하다라 그만두라고 할 행동이 아닙니다 ✗","contentar: 기쁘게 하다, 달래다라 맞지 않습니다 ✗","fastidiar: 괴롭히다, 귀찮게 하다 → 정답 ✓","alabar: 칭찬하다라 그만두라고 할 행동이 아닙니다 ✗"]},{"id":"V73","q":"Inés es profesora de ____ en la piscina municipal.","o":["cerámica","natación","pintura","manualidades"],"a":1,"k":"운동·취미 어휘","t":"이네스는 시립 수영장에서 수영 강사로 일한다.","e":"natación은 nadar(수영하다)의 명사로 '수영(종목)'입니다. 수영장(piscina)이 결정적인 힌트입니다. 'profesor/a de + 과목'은 '~ 선생님'이라는 표현입니다. 중남미에서는 수영장을 alberca(멕시코), pileta(아르헨티나)라고도 합니다.","x":["cerámica: 도예라 수영장과 관계없습니다 ✗","natación: 수영 → 정답 ✓","pintura: 그림, 회화라 수영장과 관계없습니다 ✗","manualidades: 공예, 만들기라 수영장과 관계없습니다 ✗"]},{"id":"V74","q":"Detuvieron a la banda criminal gracias a nuestros agentes ____.","o":["infiltrados","colados","entrometidos","introducidos"],"a":0,"k":"범죄·수사 어휘","t":"우리 잠입 요원들 덕분에 범죄 조직을 체포했다.","e":"infiltrado/a는 infiltrarse(잠입하다)에서 나온 말로 '잠입한'입니다. 'agente infiltrado'는 범죄 조직에 숨어 들어간 '잠입 수사관'을 뜻하는 고정 표현입니다.","x":["infiltrados: 잠입한 → 'agentes infiltrados(잠입 요원)'로 정답 ✓","colados: 새치기한, 몰래 끼어든(구어)이라 수사 요원에 쓰지 않습니다 ✗","entrometidos: 참견하기 좋아하는이라 맞지 않습니다 ✗","introducidos: 도입된, 들여온이라 요원 수식에 쓰지 않습니다 ✗"]},{"id":"V75","q":"Me encanta la ____ sonora de esta película.","o":["lista","cinta","banda","serie"],"a":2,"k":"영화 어휘","t":"나는 이 영화의 사운드트랙(OST)이 정말 좋다.","e":"'banda sonora'는 '영화 음악, 사운드트랙'이라는 고정 표현입니다. banda에는 '밴드(악단), 띠, 무리' 등 여러 뜻이 있습니다.","x":["lista: 목록이라 'lista sonora'는 쓰지 않습니다 ✗","cinta: 테이프, 리본이라 이 표현에 쓰지 않습니다 ✗","banda: → 'banda sonora(사운드트랙)'로 정답 ✓","serie: 시리즈, 연속물이라 맞지 않습니다 ✗"]},{"id":"V76","q":"Amelia se caracteriza por su ____, es una gran persona.","o":["parcialidad","bondad","indignidad","indecencia"],"a":1,"k":"성품 어휘","t":"아멜리아는 착한 마음씨가 특징이다, 정말 훌륭한 사람이다.","e":"bondad는 bueno(착한)의 명사로 '선량함, 친절함'입니다. 'gran persona(훌륭한 사람)'라는 뒷말과 잘 어울립니다. caracterizarse por는 '~이 특징이다'라는 표현입니다.","x":["parcialidad: 편파성, 불공평이라 칭찬이 아닙니다 ✗","bondad: 선량함 → 정답 ✓","indignidad: 비열함, 품위 없음이라 반대입니다 ✗","indecencia: 무례함, 외설이라 반대입니다 ✗"]},{"id":"V77","q":"Alejandra es muy ____ en clase de lengua. Es obvio que es su materia favorita.","o":["subjetiva","impulsiva","objetiva","participativa"],"a":3,"k":"수업 태도 형용사","t":"알레한드라는 국어 시간에 아주 적극적으로 참여한다. 그게 그녀가 가장 좋아하는 과목인 것이 분명하다.","e":"participativo/a는 participar(참여하다)에서 나온 형용사로 '적극적으로 참여하는'입니다. 좋아하는 과목이라서 수업에 적극적이라는 논리가 자연스럽습니다. clase de lengua는 스페인어(국어) 수업을 말합니다.","x":["subjetiva: 주관적인이라 좋아하는 과목과 연결되지 않습니다 ✗","impulsiva: 충동적인이라 맞지 않습니다 ✗","objetiva: 객관적인이라 맞지 않습니다 ✗","participativa: 적극적으로 참여하는 → 정답 ✓"]},{"id":"V78","q":"Hay personas que nacen con ____ y todo les sale bien.","o":["astro","sol","estrella","luna"],"a":2,"k":"관용 표현","t":"운을 타고나서 모든 일이 잘 풀리는 사람들이 있다.","e":"'nacer con estrella'는 '복을 타고나다, 운이 좋다'라는 관용 표현입니다(반대는 nacer estrellado, 불운을 타고나다). 'todo les sale bien(모든 게 잘된다)'이 힌트입니다.","x":["astro: 천체, 스타라 이 관용 표현에 쓰지 않습니다 ✗","sol: 해라 이 관용 표현에 쓰지 않습니다 ✗","estrella: 별 → 'nacer con estrella(운을 타고나다)'로 정답 ✓","luna: 달이라 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"V79","q":"Ana y Juan viven en un chalé ____ a las afueras de Valencia.","o":["pegado","adosado","vinculado","contiguo"],"a":1,"k":"주거 어휘","t":"아나와 후안은 발렌시아 교외의 연립 주택에 산다.","e":"'chalé adosado'는 옆집과 벽을 공유하며 나란히 붙어 있는 '연립 단독주택(타운하우스)'입니다. adosar는 '(벽에) 붙이다'라는 뜻입니다. 독립된 단독주택은 chalé independiente라고 합니다.","x":["pegado: 붙은(일반어)이라 주택 종류 명칭으로 쓰지 않습니다 ✗","adosado: 벽을 맞댄 → 'chalé adosado(타운하우스)'로 정답 ✓","vinculado: 연결된, 관련된이라 건물에 쓰지 않습니다 ✗","contiguo: 인접한이라 주택 종류 명칭이 아닙니다 ✗"]},{"id":"V80","q":"El ____ es la cría del caballo.","o":["cervatillo","potro","ternero","pichón"],"a":1,"k":"동물 새끼 어휘","t":"망아지는 말의 새끼이다.","e":"potro는 '망아지(말의 새끼)'입니다. 동물 새끼 이름은 따로 외워야 합니다: cervatillo(새끼 사슴), ternero(송아지), pichón(새끼 비둘기). potro에는 체조의 '안마'라는 뜻도 있습니다.","x":["cervatillo: 새끼 사슴이라 ✗","potro: 망아지 → 정답 ✓","ternero: 송아지(소의 새끼)라 ✗","pichón: 새끼 비둘기라 ✗"]},{"id":"V81","q":"Estoy a dos ____. Hasta que cobre no puedo comprar nada.","o":["lámparas","luces","farolas","velas"],"a":3,"k":"관용 표현","t":"나는 빈털터리야. 월급 받기 전까지는 아무것도 살 수 없어.","e":"'estar a dos velas'는 '돈이 한 푼도 없다, 빈털터리다'라는 스페인 관용 표현입니다. 뒷문장 'Hasta que cobre(월급 받을 때까지)'가 돈이 없다는 의미를 확인해 줍니다. hasta que 뒤 미래의 일은 접속법(cobre)을 씁니다.","x":["lámparas: 램프라 이 관용 표현에 쓰지 않습니다 ✗","luces: 빛, 불이라 이 관용 표현에 쓰지 않습니다 ✗","farolas: 가로등이라 이 관용 표현에 쓰지 않습니다 ✗","velas: 양초 → 'estar a dos velas(빈털터리다)'로 정답 ✓"]},{"id":"V82","q":"Si no pago el ____ del coche, no podré usarlo.","o":["convenio","acuerdo","seguro","compromiso"],"a":2,"k":"자동차·보험 어휘","t":"자동차 보험료를 내지 않으면 차를 쓸 수 없을 것이다.","e":"seguro는 명사로 '보험'입니다. 'pagar el seguro del coche(자동차 보험료를 내다)'는 자주 쓰는 표현으로, 보험 없이는 차를 몰 수 없다는 문맥에 맞습니다. 형용사로는 '안전한, 확실한'이라는 뜻입니다.","x":["convenio: 협약, 협정이라 차량 비용이 아닙니다 ✗","acuerdo: 합의라 지불할 대상이 아닙니다 ✗","seguro: 보험 → 정답 ✓","compromiso: 약속, 책임이라 지불할 대상이 아닙니다 ✗"]},{"id":"V83","q":"Estamos encantados con el ____ de nuestro partido en las elecciones generales.","o":["triunfo","fracaso","hundimiento","revés"],"a":0,"k":"선거 어휘","t":"우리는 총선에서 우리 당의 승리에 무척 기쁘다.","e":"triunfo는 '승리, 성공'입니다. estar encantado(아주 기쁘다)라는 감정과 어울리는 결과는 승리입니다. 나머지 보기는 모두 '실패, 패배'의 뜻입니다.","x":["triunfo: 승리 → 정답 ✓","fracaso: 실패라 기뻐할 일이 아닙니다 ✗","hundimiento: 침몰, 몰락이라 기뻐할 일이 아닙니다 ✗","revés: 좌절, 역경이라 기뻐할 일이 아닙니다 ✗"]},{"id":"V84","q":"Esta ____ de jabón es de las mejores que he usado.","o":["pastilla","tableta","barra","cápsula"],"a":0,"k":"물건 단위 어휘","t":"이 비누는 내가 써 본 것 중 최고 중 하나다.","e":"'pastilla de jabón'은 '비누 한 개(고형 비누)'를 세는 표현입니다. pastilla는 '알약, 정제'라는 뜻도 있습니다. 초콜릿 판은 tableta de chocolate, 막대 모양은 barra(barra de pan 바게트)를 씁니다.","x":["pastilla: 고형 비누 한 개 → 'pastilla de jabón'으로 정답 ✓","tableta: 판(초콜릿 판), 태블릿이라 비누에는 쓰지 않습니다 ✗","barra: 막대, 바(빵·립스틱 등)라 비누 단위로는 일반적이지 않습니다 ✗","cápsula: 캡슐이라 비누에 쓰지 않습니다 ✗"]},{"id":"V85","q":"Tu redacción es ____, deberías repetirla.","o":["pésima","excelente","inmejorable","estupenda"],"a":0,"k":"평가 형용사","t":"네 작문은 형편없어, 다시 써야 해.","e":"pésimo/a는 '최악의, 형편없는'입니다. 다시 써야 한다(deberías repetirla)는 결론이 부정적 평가를 요구합니다. 반대 의미의 óptimo(최적의), excelente(훌륭한)와 함께 기억하세요.","x":["pésima: 형편없는 → 정답 ✓","excelente: 훌륭한이라 다시 쓸 필요가 없습니다 ✗","inmejorable: 더할 나위 없는이라 문맥과 반대입니다 ✗","estupenda: 아주 멋진이라 문맥과 반대입니다 ✗"]},{"id":"V86","q":"Todos los ____ de los hechos señalaron al mismo acusado.","o":["asistentes","observadores","espectadores","testigos"],"a":3,"k":"법률 어휘","t":"사건의 목격자들은 모두 같은 피고인을 지목했다.","e":"testigo는 '목격자, 증인'입니다. 'testigo de los hechos(사건 목격자)'와 '피고인을 지목하다'는 법정 상황에 딱 맞습니다. testigo는 남녀 형태가 같습니다(el/la testigo).","x":["asistentes: 참석자들이라 사건 증언과 관계없습니다 ✗","observadores: 관찰자, 참관인이라 법정 증언 용어가 아닙니다 ✗","espectadores: 관객들이라 맞지 않습니다 ✗","testigos: 목격자, 증인 → 정답 ✓"]},{"id":"V87","q":"Es normal que esté ____ tras su divorcio, es algo difícil para cualquier persona.","o":["dichoso","satisfecho","radiante","apenado"],"a":3,"k":"감정 형용사","t":"이혼 후에 그가 슬퍼하는 건 당연하다, 누구에게나 힘든 일이다.","e":"apenado/a는 pena(슬픔)에서 나온 말로 '슬픈, 마음 아픈'입니다. 이혼 후의 힘든 감정을 표현하므로 정답입니다. 주의: 중남미 일부(멕시코 등)에서는 apenado가 '부끄러운, 창피한'이라는 뜻으로도 쓰입니다.","x":["dichoso: 행복한, 운 좋은이라 문맥과 반대입니다 ✗","satisfecho: 만족한이라 문맥과 반대입니다 ✗","radiante: 빛나는, 기쁨에 찬이라 문맥과 반대입니다 ✗","apenado: 슬픈, 마음 아픈 → 정답 ✓"]},{"id":"V88","q":"En esta isla hay árboles ____ que no se encuentran en ningún otro lugar.","o":["habituales","autóctonos","corrientes","comunes"],"a":1,"k":"자연·생태 어휘","t":"이 섬에는 다른 어느 곳에도 없는 토종 나무들이 있다.","e":"autóctono/a는 '토착의, 그 지역 고유의'입니다. 다른 곳에서 찾아볼 수 없다는 설명과 일치합니다. 비슷한 말로 nativo, endémico(고유종의)가 있습니다.","x":["habituales: 흔한, 평소의라 문맥과 반대입니다 ✗","autóctonos: 토착의, 고유의 → 정답 ✓","corrientes: 흔한, 보통의라 문맥과 반대입니다 ✗","comunes: 흔한라 다른 곳에 없다는 말과 모순됩니다 ✗"]},{"id":"V89","q":"Voy a meter el zumo en el frigorífico para que ____.","o":["se congele","se caliente","se enfríe","se derrita"],"a":2,"k":"온도 변화 동사","t":"주스가 시원해지도록 냉장고에 넣을게.","e":"enfriarse는 '차가워지다, 식다'입니다. 냉장고(frigorífico)에 넣는 목적이므로 정답입니다. 'para que + 접속법'은 '~하도록'이라는 목적 표현입니다. 냉동실(congelador)에 넣으면 congelarse(얼다)가 됩니다.","x":["se congele: congelarse(얼다)로 냉동실에서 일어나는 일입니다 ✗","se caliente: calentarse(데워지다)로 냉장고와 반대입니다 ✗","se enfríe: enfriarse(차가워지다) → 정답 ✓","se derrita: derretirse(녹다)로 냉장고에 넣는 목적이 아닙니다 ✗"]},{"id":"V90","q":"No estoy leyendo el libro, solo lo estoy ____.","o":["memorizando","hojeando","escudriñando","estudiando"],"a":1,"k":"독서 동사","t":"나는 그 책을 읽고 있는 게 아니라 그냥 훑어보고 있을 뿐이다.","e":"hojear는 hoja(페이지)에서 나온 말로 '(책장을) 대충 넘겨 보다, 훑어보다'입니다. 'No estoy leyendo, solo...'라는 대조가 '제대로 읽지 않는' 행동을 요구합니다. 발음이 같은 ojear(힐끗 보다)와 철자를 구별하세요.","x":["memorizando: memorizar(암기하다)로 읽는 것보다 더 깊은 행동입니다 ✗","hojeando: hojear(훑어보다) → 정답 ✓","escudriñando: escudriñar(꼼꼼히 살피다)로 대조와 반대입니다 ✗","estudiando: estudiar(공부하다)로 대조가 성립하지 않습니다 ✗"]},{"id":"V91","q":"Dicen que lo ____ sale caro.","o":["costoso","gratis","barato","rebajado"],"a":2,"k":"속담","t":"싼 게 비지떡이라는 말이 있다.","e":"'Lo barato sale caro'는 '싼 것이 결국 비싸게 먹힌다', 즉 '싼 게 비지떡'이라는 속담입니다. 'lo + 형용사'는 '~한 것'이라는 추상 명사를 만듭니다. salir caro는 '비싸게 치이다'라는 뜻입니다.","x":["costoso: 값비싼이라 'lo costoso sale caro'는 당연한 말이 됩니다 ✗","gratis: 무료의라 이 속담에 쓰지 않습니다 ✗","barato: 싼 → 'Lo barato sale caro'로 정답 ✓","rebajado: 할인된이라 속담의 형태가 아닙니다 ✗"]},{"id":"V92","q":"Me puso ____ en la herida para que no se me infectase.","o":["un adhesivo","una tirita","una pegatina","escayola"],"a":1,"k":"응급처치 어휘","t":"감염되지 않도록 상처에 반창고를 붙여 주었다.","e":"tirita는 스페인에서 쓰는 '반창고, 밴드'(상표명에서 온 말)입니다. 중남미에서는 curita(멕시코 등), bandita 등으로 부릅니다. infectarse는 '감염되다'이며 para que 뒤라 접속법 과거(infectase)가 쓰였습니다.","x":["un adhesivo: 접착제, 스티커라 상처 치료용이 아닙니다 ✗","una tirita: 반창고 → 정답 ✓","una pegatina: 스티커라 상처에 붙이는 것이 아닙니다 ✗","escayola: 깁스(석고)라 골절에 쓰며 상처 감염 방지용이 아닙니다 ✗"]},{"id":"V93","q":"Antes de comer, pon un ____ para que no se manche la mesa.","o":["mantel","paño","pañuelo","trapo"],"a":0,"k":"식탁 어휘","t":"식사 전에 식탁이 더러워지지 않도록 식탁보를 깔아.","e":"mantel은 '식탁보'입니다. 'poner el mantel(식탁보를 깔다)'은 식탁을 차릴 때 쓰는 표현입니다. 1인용 개인 매트는 mantel individual이라고 합니다.","x":["mantel: 식탁보 → 정답 ✓","paño: 천, 행주라 식탁에 까는 것이 아닙니다 ✗","pañuelo: 손수건이라 맞지 않습니다 ✗","trapo: 걸레, 헝겊이라 식탁에 까는 것이 아닙니다 ✗"]},{"id":"V94","q":"Solo somos buenos amigos, no tenemos ninguna relación ____.","o":["personal","cordial","amistosa","amorosa"],"a":3,"k":"인간관계 어휘","t":"우리는 그냥 좋은 친구일 뿐, 어떤 연애 관계도 아니다.","e":"amoroso/a는 amor(사랑)에서 나온 형용사로 '사랑의, 연애의'입니다. 'relación amorosa'는 '연인 관계'입니다. 'solo somos buenos amigos'와 대조되는 관계가 필요하므로 정답입니다.","x":["personal: 개인적인이라 친구 관계도 포함되어 모순됩니다 ✗","cordial: 정중한, 우호적인이라 친구 사이에 오히려 있는 관계입니다 ✗","amistosa: 우정의, 친근한이라 친구라는 말과 모순됩니다 ✗","amorosa: 연애의 → 정답 ✓"]},{"id":"V95","q":"Voy a usar sal y pimienta para ____ la comida.","o":["sazonar","rehogar","endulzar","saltear"],"a":0,"k":"요리 동사","t":"음식에 간을 하려고 소금과 후추를 쓸 것이다.","e":"sazonar는 '(소금·향신료로) 간을 하다, 양념하다'입니다. 소금과 후추를 사용하는 목적에 딱 맞습니다. 비슷한 말로 condimentar, aliñar(샐러드 드레싱하다)가 있습니다.","x":["sazonar: 간하다, 양념하다 → 정답 ✓","rehogar: (기름에) 약불로 볶다라 소금·후추의 용도가 아닙니다 ✗","endulzar: 달게 하다라 소금·후추와 반대입니다 ✗","saltear: 센 불에 볶다라 소금·후추의 용도가 아닙니다 ✗"]},{"id":"V96","q":"Uno de los momentos más señalados de la ____ fue el discurso del ganador del Goya a mejor actor.","o":["gala","velada","proyección","función"],"a":0,"k":"행사 어휘","t":"시상식에서 가장 눈에 띈 순간 중 하나는 고야상 남우주연상 수상자의 연설이었다.","e":"gala는 '(시상식 등의) 성대한 행사, 갈라'입니다. 고야상(Premios Goya, 스페인 영화상) 시상식은 흔히 'la gala de los Goya'라고 부릅니다. 형용사 señalado는 '특별한, 두드러진'이라는 뜻입니다.","x":["gala: 시상식, 갈라 행사 → 정답 ✓","velada: 저녁 모임, 야회라 시상식 명칭으로 쓰지 않습니다 ✗","proyección: (영화) 상영이라 수상 연설과 맞지 않습니다 ✗","función: (연극) 공연, 상영 회차라 시상식이 아닙니다 ✗"]},{"id":"V97","q":"Álvaro es un ____ de quince años que vive con sus padres en Madrid.","o":["cuarentón","treintañero","señor","chaval"],"a":3,"k":"나이·사람 어휘","t":"알바로는 마드리드에서 부모님과 함께 사는 열다섯 살 소년이다.","e":"chaval/a는 스페인 구어로 '소년, 젊은이, 아이'입니다. 15살이라는 나이에 맞는 말은 이것뿐입니다. 중남미에서는 chico, muchacho, 지역에 따라 chamaco(멕시코), pibe(아르헨티나) 등을 씁니다.","x":["cuarentón: 40대 남자라 15살과 맞지 않습니다 ✗","treintañero: 30대 사람이라 맞지 않습니다 ✗","señor: 아저씨, 신사라 15살에게 쓰지 않습니다 ✗","chaval: 소년, 젊은이 → 정답 ✓"]},{"id":"V98","q":"Estoy a dieta, por eso tomo productos ____.","o":["grasos","procesados","hipercalóricos","desnatados"],"a":3,"k":"식품 어휘","t":"나는 다이어트 중이라 저지방 제품을 먹는다.","e":"desnatado/a는 nata(유지방, 크림)를 뺀 것으로 '탈지의, 무지방의'입니다. 'leche desnatada(무지방 우유)', 'yogur desnatado'처럼 씁니다. 반대로 일반 우유는 leche entera라고 합니다.","x":["grasos: 기름진이라 다이어트와 반대입니다 ✗","procesados: 가공된이라 다이어트용 제품의 특징이 아닙니다 ✗","hipercalóricos: 고칼로리의라 다이어트와 반대입니다 ✗","desnatados: 탈지의, 저지방의 → 정답 ✓"]},{"id":"V99","q":"Esta chica es muy ____, nunca se entera de lo que pasa.","o":["maleducada","observadora","atenta","despistada"],"a":3,"k":"성격 형용사","t":"이 아이는 아주 덜렁거린다, 무슨 일이 일어나는지 전혀 눈치채지 못한다.","e":"despistado/a는 '정신이 딴 데 팔린, 덜렁거리는, 둔한'입니다. 'nunca se entera de lo que pasa(무슨 일인지 전혀 모른다)'와 의미가 일치합니다. 동사 despistarse는 '정신을 놓다, 깜빡하다'입니다.","x":["maleducada: 버릇없는이라 눈치 없음과 관계없습니다 ✗","observadora: 관찰력 있는이라 문맥과 반대입니다 ✗","atenta: 주의 깊은, 세심한이라 문맥과 반대입니다 ✗","despistada: 덜렁거리는, 정신 딴 데 팔린 → 정답 ✓"]},{"id":"V100","q":"Me encanta leer ____ de moda.","o":["revistas","gacetas","noticieros","boletines"],"a":0,"k":"출판물 어휘","t":"나는 패션 잡지 읽는 것을 정말 좋아한다.","e":"revista는 '잡지'입니다. 'revista de moda(패션 잡지)'는 자주 쓰는 표현입니다. gaceta는 관보·신문, boletín은 회보·소식지, noticiero는 뉴스 프로그램(주로 중남미)입니다.","x":["revistas: 잡지들 → 정답 ✓","gacetas: 관보, 신문이라 패션과 어울리지 않습니다 ✗","noticieros: 뉴스 프로그램(중남미)이라 '읽는' 것이 아닙니다 ✗","boletines: 회보, 소식지라 패션 잡지를 뜻하지 않습니다 ✗"]},{"id":"V101","q":"La ____ es propia de las personas altruistas.","o":["solidaridad","avaricia","tacañería","codicia"],"a":0,"k":"성품 어휘","t":"연대 의식(나눔)은 이타적인 사람들의 특징이다.","e":"solidaridad는 '연대, 서로 돕는 마음'입니다. altruista(이타적인, 남을 위하는)와 의미가 통합니다. 'ser propio de ~'는 '~의 특징이다'라는 표현입니다.","x":["solidaridad: 연대, 나눔 → 정답 ✓","avaricia: 탐욕이라 이타심과 반대입니다 ✗","tacañería: 인색함이라 이타심과 반대입니다 ✗","codicia: 탐욕, 욕심이라 이타심과 반대입니다 ✗"]},{"id":"V102","q":"Si quieres encontrar un buen piso, te recomiendo que vayas a esta ____ inmobiliaria.","o":["agencia","gerencia","administración","secretaría"],"a":0,"k":"부동산 어휘","t":"좋은 집을 찾고 싶다면 이 부동산 중개소에 가 보라고 추천할게.","e":"'agencia inmobiliaria'는 '부동산 중개소'입니다. agencia는 '대리점, 사무소'로 agencia de viajes(여행사)처럼 씁니다. piso는 스페인에서 '아파트, 집'입니다(중남미는 departamento, apartamento).","x":["agencia: 대리점, 사무소 → 'agencia inmobiliaria'로 정답 ✓","gerencia: 경영진, 관리부라 집을 찾는 곳이 아닙니다 ✗","administración: 관리, 행정이라 'administración de fincas(건물 관리사무소)'는 있지만 집 구할 때 가는 곳이 아닙니다 ✗","secretaría: 사무국, 비서실이라 맞지 않습니다 ✗"]},{"id":"V103","q":"____ profesional de este artista empezó cuando era adolescente.","o":["La gira","La actuación","El itinerario","La trayectoria"],"a":3,"k":"경력 어휘","t":"이 예술가의 직업적 경력은 그가 청소년이었을 때 시작되었다.","e":"trayectoria는 '경력, 행보, 궤적'입니다. 'trayectoria profesional(직업 경력)'은 이력·커리어를 말하는 고정 표현입니다. 청소년 때 시작된 긴 활동을 나타내므로 정답입니다.","x":["La gira: 순회공연, 투어라 '직업적 투어가 시작됐다'는 어색합니다 ✗","La actuación: 공연, 연기라 한 번의 공연을 가리킵니다 ✗","El itinerario: 여행 일정, 경로라 경력의 뜻이 아닙니다 ✗","La trayectoria: 경력 → 'trayectoria profesional'로 정답 ✓"]},{"id":"V104","q":"____ es de color anaranjado.","o":["El pepino","La calabaza","La alcachofa","El rábano"],"a":1,"k":"채소 어휘","t":"호박은 주황색이다.","e":"calabaza는 '호박'으로 주황색입니다. 'dar calabazas a alguien'은 '(고백을) 거절하다, 퇴짜 놓다'라는 재미있는 관용 표현도 있습니다. anaranjado는 naranja(오렌지)에서 나온 '주황색의'입니다.","x":["El pepino: 오이라 초록색입니다 ✗","La calabaza: 호박 → 주황색이라 정답 ✓","La alcachofa: 아티초크라 초록색입니다 ✗","El rábano: 무, 래디시라 흰색이나 빨간색입니다 ✗"]},{"id":"V105","q":"No me fío de sus palabras, su explicación de los hechos no es ____.","o":["extraña","ilógica","creíble","imprecisa"],"a":2,"k":"신뢰 형용사","t":"나는 그의 말을 믿지 않는다, 사건에 대한 그의 설명은 믿을 만하지 않다.","e":"creíble은 creer(믿다)에서 나온 형용사로 '믿을 수 있는'입니다. 'no es creíble(믿기지 않는다)'은 'No me fío(믿지 않는다)'와 논리적으로 이어집니다. 반대말은 increíble(믿을 수 없는, 놀라운)입니다.","x":["extraña: 이상한이라 'no es extraña'면 정상이라는 뜻이 되어 반대입니다 ✗","ilógica: 비논리적인이라 'no es ilógica'면 논리적이라는 뜻이 됩니다 ✗","creíble: 믿을 만한 → 'no es creíble'로 정답 ✓","imprecisa: 부정확한이라 'no es imprecisa'면 정확하다는 뜻이 됩니다 ✗"]},{"id":"V106","q":"Lo siento, señor, está ____ aparcar ahí.","o":["contraindicado","permitido","prohibido","admitido"],"a":2,"k":"규칙·허가 어휘","t":"죄송합니다, 손님, 거기는 주차 금지입니다.","e":"'está prohibido + 동사원형'은 '~하는 것이 금지되어 있다'입니다. 'Lo siento, señor'라는 사과가 허락하지 않는다는 내용을 예고합니다. 표지판에서는 'Prohibido aparcar(주차 금지)'로 씁니다. 중남미는 aparcar 대신 estacionar를 주로 씁니다.","x":["contraindicado: (약 등이) 금기인이라 주차에는 쓰지 않습니다 ✗","permitido: 허용된이라 사과할 이유가 없습니다 ✗","prohibido: 금지된 → 정답 ✓","admitido: 받아들여진, 인정된이라 사과와 맞지 않습니다 ✗"]},{"id":"V107","q":"Me gustaría ir al ____ de la última película de Tarantino.","o":["estreno","comienzo","inicio","principio"],"a":0,"k":"영화 어휘","t":"나는 타란티노의 최신 영화 개봉(시사회)에 가고 싶다.","e":"estreno는 '(영화·공연의) 개봉, 첫 공연, 시사회'입니다. 동사 estrenar는 '처음 선보이다, 처음 사용하다'로 'estrenar zapatos(새 신발을 처음 신다)'처럼도 씁니다.","x":["estreno: 개봉, 첫 상영 → 정답 ✓","comienzo: 시작이라 '영화의 시작 부분'이 되어 '가다'와 맞지 않습니다 ✗","inicio: 시작이라 영화 개봉 행사를 뜻하지 않습니다 ✗","principio: 시작, 원칙이라 맞지 않습니다 ✗"]},{"id":"V108","q":"Odia a su vecino, tanto que no quiere verlo ni en ____.","o":["imagen","cuadro","pintura","foto"],"a":2,"k":"관용 표현","t":"그는 이웃을 너무 싫어해서 얼굴도 보기 싫어한다(그림으로도 보기 싫어한다).","e":"'no querer ver a alguien ni en pintura'는 '그림으로도 보기 싫을 만큼 질색하다'라는 관용 표현입니다. 한국어의 '꼴도 보기 싫다'와 비슷합니다.","x":["imagen: 이미지라 이 관용 표현에 쓰지 않습니다 ✗","cuadro: 그림, 액자라 이 관용 표현에 쓰지 않습니다 ✗","pintura: 그림 → 'ni en pintura'로 정답 ✓","foto: 사진이라 이 관용 표현의 형태가 아닙니다 ✗"]},{"id":"V109","q":"Teníamos tanta hambre que ____ la cena en menos de diez minutos.","o":["degustamos","devoramos","saboreamos","probamos"],"a":1,"k":"먹기 동사","t":"우리는 너무 배가 고파서 10분도 안 되어 저녁을 먹어 치웠다.","e":"devorar는 '게걸스럽게 먹어 치우다, 탐식하다'입니다. 너무 배가 고파서(tanta hambre) 빨리 먹었다는 문맥에 맞습니다. 'devorar un libro(책을 단숨에 읽다)'처럼 비유적으로도 씁니다.","x":["degustamos: degustar(시식하다, 음미하다)로 빨리 먹는 것과 반대입니다 ✗","devoramos: devorar(먹어 치우다) → 정답 ✓","saboreamos: saborear(음미하다)로 빨리 먹는 것과 맞지 않습니다 ✗","probamos: probar(맛보다)로 다 먹어 치우는 뜻이 아닙니다 ✗"]},{"id":"V110","q":"No me cuentes la ____ de la peli, prefiero no saber de qué va.","o":["opinión","trama","crítica","argumentación"],"a":1,"k":"영화·문학 어휘","t":"영화 줄거리를 말하지 마, 무슨 내용인지 알고 싶지 않아.","e":"trama는 '(영화·소설의) 줄거리, 플롯'입니다. 'de qué va(무슨 내용인지)'를 알고 싶지 않다는 말과 연결됩니다. 스포일러는 스페인어로 spoiler 또는 destripe라고도 합니다.","x":["opinión: 의견이라 내용을 알게 되는 것과 직접 관계가 없습니다 ✗","trama: 줄거리 → 정답 ✓","crítica: 비평, 평론이라 줄거리 자체가 아닙니다 ✗","argumentación: 논증, 논거 제시라 영화 줄거리가 아닙니다(줄거리 뜻은 argumento) ✗"]},{"id":"V111","q":"Es tan tímida que ____ por cualquier cosa.","o":["se marea","se sonroja","se desvanece","se desmaya"],"a":1,"k":"감정·신체 반응","t":"그녀는 너무 수줍음이 많아서 아무 일에나 얼굴이 빨개진다.","e":"sonrojarse는 '(부끄러워서) 얼굴이 붉어지다'입니다. tímida(수줍은)라는 성격과 가장 잘 어울리는 반응입니다. 비슷한 말로 ruborizarse, ponerse rojo가 있습니다.","x":["se marea: marearse(어지럽다, 멀미하다)로 수줍음과 관계없습니다 ✗","se sonroja: sonrojarse(얼굴이 붉어지다) → 정답 ✓","se desvanece: desvanecerse(사라지다, 기절하다)로 맞지 않습니다 ✗","se desmaya: desmayarse(기절하다)로 수줍음의 반응이 아닙니다 ✗"]},{"id":"V112","q":"El 8 es un número ____.","o":["similar","impar","equivalente","par"],"a":3,"k":"수학 어휘","t":"8은 짝수이다.","e":"'número par'는 '짝수', 'número impar'는 '홀수'입니다. 8은 2로 나누어떨어지므로 짝수입니다. par는 명사로 '한 쌍'(un par de zapatos 신발 한 켤레)이라는 뜻도 있습니다.","x":["similar: 비슷한이라 수의 종류가 아닙니다 ✗","impar: 홀수의라 8에 맞지 않습니다 ✗","equivalente: 동등한이라 수의 종류가 아닙니다 ✗","par: 짝수의 → 정답 ✓"]},{"id":"V113","q":"La cafetería en la que trabajo está en el ____ histórico de Córdoba.","o":["fondo","foco","meollo","casco"],"a":3,"k":"도시 어휘","t":"내가 일하는 카페는 코르도바의 구시가지(역사 지구)에 있다.","e":"'casco histórico/antiguo'는 도시의 '구시가지, 역사 지구'입니다. casco는 원래 '헬멧'이라는 뜻입니다. 코르도바는 스페인 안달루시아의 도시로 구시가지가 유네스코 세계유산입니다.","x":["fondo: 바닥, 깊은 곳이라 도시 구역을 뜻하지 않습니다 ✗","foco: 초점, 중심지라 이 표현에 쓰지 않습니다 ✗","meollo: 핵심, 골자라 장소에 쓰지 않습니다 ✗","casco: → 'casco histórico(구시가지)'로 정답 ✓"]},{"id":"V114","q":"Me encantan los juegos de ____, sobre todo el bingo.","o":["construcción","naipes","rol","azar"],"a":3,"k":"놀이 어휘","t":"나는 운에 맡기는 게임을 정말 좋아한다, 특히 빙고를.","e":"'juego de azar'는 '운에 좌우되는 게임, 도박성 게임'입니다. azar는 '우연, 운'이며 'al azar(무작위로)'라는 표현도 자주 씁니다. 빙고는 실력이 아닌 운으로 하는 게임이라 정답입니다.","x":["construcción: 건설 게임(블록 쌓기 등)이라 빙고와 맞지 않습니다 ✗","naipes: 카드(트럼프)라 빙고는 카드 게임이 아닙니다 ✗","rol: 롤플레잉 게임이라 빙고와 맞지 않습니다 ✗","azar: 운, 우연 → 'juegos de azar'로 정답 ✓"]},{"id":"V115","q":"Los asistentes quedaron gratamente impresionados por el modo ____ en el que habló la oradora.","o":["desordenado","irregular","magistral","enrevesado"],"a":2,"k":"평가 형용사","t":"참석자들은 연사가 말하는 탁월한 방식에 기분 좋게 감명받았다.","e":"magistral은 maestro(대가)와 관련된 말로 '대가다운, 탁월한'입니다. gratamente impresionados(기분 좋게 감명받은)라는 긍정적 반응과 맞습니다. 'clase magistral'은 '대가의 특강, 마스터클래스'입니다.","x":["desordenado: 무질서한이라 긍정적 감명과 맞지 않습니다 ✗","irregular: 불규칙한, 들쭉날쭉한이라 맞지 않습니다 ✗","magistral: 탁월한, 대가다운 → 정답 ✓","enrevesado: 복잡하게 꼬인이라 감명과 맞지 않습니다 ✗"]},{"id":"V116","q":"Mi coche no ____, tendré que llamar al mecánico para que lo mire.","o":["sale","empieza","arranca","parte"],"a":2,"k":"자동차 동사","t":"내 차가 시동이 안 걸려, 정비사를 불러서 봐 달라고 해야겠어.","e":"arrancar는 '(엔진이) 시동이 걸리다, 출발하다'입니다. 'El coche no arranca(차 시동이 안 걸린다)'는 자주 쓰는 표현입니다. arrancar에는 '뽑다, 뜯어내다'라는 뜻도 있습니다.","x":["sale: salir(나가다)로 차 시동에는 쓰지 않습니다 ✗","empieza: empezar(시작하다)로 차를 주어로 쓰지 않습니다 ✗","arranca: arrancar(시동이 걸리다) → 정답 ✓","parte: partir(출발하다, 쪼개다)로 시동 고장에 쓰지 않습니다 ✗"]},{"id":"V117","q":"Algunos de nosotros notamos un ____ irónico en sus palabras.","o":["indicio","matiz","acento","gusto"],"a":1,"k":"뉘앙스 어휘","t":"우리 중 몇몇은 그의 말에서 아이러니한 뉘앙스를 느꼈다.","e":"matiz는 '뉘앙스, 미묘한 차이, 색조'입니다. 'un matiz irónico(비꼬는 뉘앙스)'처럼 말투의 미묘한 느낌을 말할 때 씁니다. 복수형은 matices입니다(z → c).","x":["indicio: 징후, 단서라 'indicio irónico'는 어색합니다 ✗","matiz: 뉘앙스 → 정답 ✓","acento: 억양, 강세, 사투리라 '아이러니한 억양'은 어색합니다 ✗","gusto: 맛, 취향이라 맞지 않습니다 ✗"]},{"id":"V118","q":"El ____ es una prenda que se usa para dormir.","o":["biquini","camisón","jersey","gorro"],"a":1,"k":"의류 어휘","t":"잠옷 원피스(나이트가운)는 잘 때 입는 옷이다.","e":"camisón은 '(원피스형) 잠옷, 나이트가운'입니다. camisa(셔츠)에 크다는 어미 -ón이 붙은 말입니다. 상하의로 된 잠옷은 pijama라고 합니다. prenda는 '옷 한 벌, 의류'입니다.","x":["biquini: 비키니라 수영복입니다 ✗","camisón: 잠옷 원피스 → 정답 ✓","jersey: 스웨터라 잘 때 입는 옷이 아닙니다 ✗","gorro: 털모자라 잘 때 입는 옷이 아닙니다 ✗"]},{"id":"V119","q":"Al pasar la frontera revisarán nuestra mercancía en la ____.","o":["secretaría","jefatura","aduana","notaría"],"a":2,"k":"여행·행정 어휘","t":"국경을 넘을 때 세관에서 우리 물품을 검사할 것이다.","e":"aduana는 '세관'입니다. 국경(frontera)에서 물건(mercancía)을 검사하는 곳이므로 정답입니다. 세관원은 aduanero/a입니다.","x":["secretaría: 사무국이라 국경 검사와 관계없습니다 ✗","jefatura: 본부, 경찰서라 물품 검사 장소가 아닙니다 ✗","aduana: 세관 → 정답 ✓","notaría: 공증 사무소라 맞지 않습니다 ✗"]},{"id":"V120","q":"Tus calificaciones son bastante ____, enhorabuena.","o":["bajas","mediocres","altas","mejorables"],"a":2,"k":"성적 어휘","t":"네 성적이 꽤 높구나, 축하해.","e":"calificación은 '성적, 점수'이며 'calificaciones altas(높은 성적)'와 축하(enhorabuena)가 잘 어울립니다. 스페인에서는 성적을 notas라고도 많이 씁니다.","x":["bajas: 낮은이라 축하할 일이 아닙니다 ✗","mediocres: 그저 그런이라 축하할 일이 아닙니다 ✗","altas: 높은 → 정답 ✓","mejorables: 개선의 여지가 있는이라 축하와 맞지 않습니다 ✗"]},{"id":"V121","q":"Ernesto está de ____ por enfermedad, por eso no trabaja ahora.","o":["bajada","bajón","baja","bajonazo"],"a":2,"k":"직장 어휘","t":"에르네스토는 병가 중이라 지금은 일하지 않는다.","e":"'estar de baja (por enfermedad)'는 '병가 중이다, 휴직 중이다'라는 표현입니다. baja는 '낮은'이라는 형용사 외에 '휴직, 탈퇴'라는 명사 뜻이 있습니다. 'darse de baja'는 '(회원·서비스에서) 탈퇴하다'입니다.","x":["bajada: 내리막, 하강이라 휴직의 뜻이 아닙니다 ✗","bajón: (기분·건강의) 급격한 저하라 'estar de bajón'은 '기분이 다운되다'입니다 ✗","baja: 휴직 → 'estar de baja'로 정답 ✓","bajonazo: 크게 떨어짐(구어)이라 맞지 않습니다 ✗"]},{"id":"V122","q":"Alquilé este piso a través de una agencia ____.","o":["de viajes","espacial","inmobiliaria","de turismo"],"a":2,"k":"부동산 어휘","t":"나는 부동산 중개소를 통해 이 집을 빌렸다.","e":"'agencia inmobiliaria'는 '부동산 중개소'입니다. 집(piso)을 빌리는(alquilar) 일은 부동산을 통해 하므로 정답입니다. a través de는 '~을 통해서'입니다.","x":["de viajes: 여행사라 집 임대와 관계없습니다 ✗","espacial: 우주의(우주국)라 맞지 않습니다 ✗","inmobiliaria: 부동산의 → 정답 ✓","de turismo: 관광 사무소라 집 임대와 맞지 않습니다 ✗"]},{"id":"V123","q":"No me interesa la ____ deportiva, prefiero conocer la actualidad sociopolítica.","o":["tipografía","prensa","imprenta","redacción"],"a":1,"k":"언론 어휘","t":"나는 스포츠 신문(언론)에는 관심이 없고 사회·정치 시사를 알고 싶다.","e":"prensa는 '언론, 신문(인쇄 매체)'입니다. 'prensa deportiva'는 스포츠 신문·스포츠 언론을 뜻합니다. 'la actualidad(시사, 최신 소식)'와 대조되어 언론 매체가 필요합니다.","x":["tipografía: 활판 인쇄, 서체라 맞지 않습니다 ✗","prensa: 언론, 신문 → 정답 ✓","imprenta: 인쇄소, 인쇄술이라 맞지 않습니다 ✗","redacción: 작문, 편집부라 'redacción deportiva(스포츠 편집부)'는 독자가 관심 갖는 대상이 아닙니다 ✗"]},{"id":"V124","q":"Este alumno tiene una conducta ____, es un placer tenerlo en clase.","o":["anómala","extraña","ejemplar","sorprendente"],"a":2,"k":"평가 형용사","t":"이 학생은 모범적인 행동을 하고 있어서, 수업에 함께하는 것이 즐겁다.","e":"ejemplar는 '모범적인, 본보기가 되는'입니다(명사로는 '(책의) 한 부'). 'es un placer tenerlo en clase'라는 칭찬과 잘 맞습니다. conducta는 '행동, 품행'입니다.","x":["anómala: 비정상적인이라 칭찬과 맞지 않습니다 ✗","extraña: 이상한이라 칭찬과 맞지 않습니다 ✗","ejemplar: 모범적인 → 정답 ✓","sorprendente: 놀라운이라 좋은지 나쁜지 분명하지 않아 칭찬의 이유가 약합니다 ✗"]},{"id":"V125","q":"Me gustó la primera ____ de esta serie televisiva, pero la segunda me decepcionó.","o":["época","estación","temporada","etapa"],"a":2,"k":"방송 어휘","t":"나는 이 TV 시리즈의 첫 번째 시즌은 좋았지만 두 번째 시즌에는 실망했다.","e":"temporada는 '(드라마·스포츠의) 시즌, 철'입니다. 'primera temporada(시즌 1)'처럼 씁니다. 'temporada alta/baja(성수기/비수기)'도 자주 쓰는 표현입니다.","x":["época: 시대, 시기라 드라마 시즌에 쓰지 않습니다 ✗","estación: 계절, 역이라 드라마에 쓰지 않습니다 ✗","temporada: 시즌 → 정답 ✓","etapa: 단계, 구간이라 드라마 시즌 명칭이 아닙니다 ✗"]},{"id":"V126","q":"Dije algo de lo que me arrepiento, fue una metedura de ____.","o":["pie","pierna","rodilla","pata"],"a":3,"k":"관용 표현","t":"내가 후회할 말을 했어, 그건 큰 실언(말실수)이었어.","e":"'meter la pata'는 '실수하다, 말실수하다'라는 관용 표현이고 그 명사형이 'metedura de pata(실수, 헛발질)'입니다. pata는 동물의 '다리'인데 사람에게 쓰면 구어적인 느낌이 납니다.","x":["pie: 발이라 이 관용 표현에 쓰지 않습니다 ✗","pierna: (사람의) 다리라 이 관용 표현에 쓰지 않습니다 ✗","rodilla: 무릎이라 이 관용 표현에 쓰지 않습니다 ✗","pata: 동물의 다리 → 'metedura de pata(실수)'로 정답 ✓"]},{"id":"V127","q":"La policía no pudo detener al sospechoso porque este tenía una ____.","o":["disculpa","excusa","justificación","coartada"],"a":3,"k":"법률 어휘","t":"용의자에게 알리바이가 있어서 경찰은 그를 체포할 수 없었다.","e":"coartada는 '알리바이(범행 시각에 다른 곳에 있었다는 증명)'입니다. 체포를 못 한 이유가 되므로 정답입니다. excusa(변명)나 justificación(정당화)은 일반적인 핑계라 수사 용어로 맞지 않습니다.","x":["disculpa: 사과라 체포를 막지 못합니다 ✗","excusa: 변명, 핑계라 수사 용어가 아닙니다 ✗","justificación: 정당화, 사유라 알리바이의 뜻이 아닙니다 ✗","coartada: 알리바이 → 정답 ✓"]},{"id":"V128","q":"No me preocupa el futuro, vivo el ____.","o":["tiempo","instante","momento","rato"],"a":2,"k":"시간 표현","t":"나는 미래가 걱정되지 않아, 순간(현재)을 살고 있어.","e":"'vivir el momento'는 '지금 이 순간을 살다, 현재를 즐기다'라는 표현입니다. momento는 '순간, 때'로 이 구절에서 가장 자연스럽습니다. 비슷하게 'vivir el presente'도 씁니다.","x":["tiempo: 시간이라 'vivir el tiempo'는 쓰지 않습니다 ✗","instante: 순간(아주 짧은)이라 이 고정 표현으로는 잘 쓰지 않습니다 ✗","momento: 순간 → 'vivir el momento'로 정답 ✓","rato: 잠시 동안이라 이 표현에 쓰지 않습니다 ✗"]},{"id":"V129","q":"Antes de jugar, debes ____ las cartas.","o":["barajar","revolver","agitar","remover"],"a":0,"k":"놀이 동사","t":"게임을 하기 전에 카드를 섞어야 한다.","e":"barajar는 '(카드를) 섞다'입니다. 명사 baraja는 '카드 한 벌'입니다. 비유적으로 'barajar opciones(여러 선택지를 검토하다)'라고도 씁니다.","x":["barajar: 카드를 섞다 → 정답 ✓","revolver: 휘젓다, 뒤지다라 카드에는 쓰지 않습니다 ✗","agitar: 흔들다라 카드에는 쓰지 않습니다 ✗","remover: (액체를) 젓다, 옮기다라 카드에는 쓰지 않습니다 ✗"]},{"id":"V130","q":"Eloy es ____, planea muy bien sus viajes para evitar contratiempos.","o":["madrugador","cumplidor","desorganizado","previsor"],"a":3,"k":"성격 형용사","t":"엘로이는 앞일을 대비하는 사람이라 차질이 없도록 여행 계획을 아주 잘 세운다.","e":"previsor/a는 prever(예견하다)에서 나온 말로 '앞일을 내다보고 대비하는, 준비성 있는'입니다. 차질(contratiempos)을 피하려고 계획을 잘 세운다는 설명과 일치합니다.","x":["madrugador: 일찍 일어나는 사람이라 계획과 직접 관계가 없습니다 ✗","cumplidor: 약속·의무를 잘 지키는이라 미리 대비하는 것과는 다릅니다 ✗","desorganizado: 체계 없는이라 문맥과 반대입니다 ✗","previsor: 준비성 있는 → 정답 ✓"]},{"id":"V131","q":"Este vídeo se ha hecho ____, lo han visto millones de personas.","o":["viral","contagioso","infeccioso","habitual"],"a":0,"k":"인터넷 어휘","t":"이 영상은 입소문이 나서 수백만 명이 봤다.","e":"'hacerse viral'은 '(인터넷에서) 입소문이 나다, 바이럴되다'입니다. hacerse + 형용사는 '~이 되다'라는 변화를 나타냅니다. viral은 원래 '바이러스의'라는 뜻입니다.","x":["viral: 입소문 난, 바이럴 → 정답 ✓","contagioso: 전염성의라 영상에는 쓰지 않습니다 ✗","infeccioso: 감염성의라 영상에 쓰지 않습니다 ✗","habitual: 일상적인이라 수백만 조회와 맞지 않습니다 ✗"]},{"id":"V132","q":"Carmen ha conseguido el trabajo porque tiene ____. ¡Qué injusto!","o":["enchufe","enlace","cable","hilo"],"a":0,"k":"구어 표현","t":"카르멘은 빽(연줄)이 있어서 그 일자리를 얻었다. 정말 불공평해!","e":"enchufe는 원래 '콘센트, 플러그'이지만 스페인 구어에서 '연줄, 빽'이라는 뜻이 있습니다. 'tener enchufe'는 '빽이 있다', enchufado는 '낙하산'입니다. '¡Qué injusto!'가 힌트입니다.","x":["enchufe: 연줄, 빽 → 정답 ✓","enlace: 연결, 링크, 결혼식이라 '빽'의 뜻이 아닙니다 ✗","cable: 전선이라 이런 뜻이 없습니다(echar un cable은 '도와주다') ✗","hilo: 실, 맥락이라 이런 뜻이 없습니다 ✗"]},{"id":"V133","q":"Si no pueden pagar de una vez, les damos la opción de hacerlo ____.","o":["en efectivo","con tarjeta","al contado","a plazos"],"a":3,"k":"결제 표현","t":"한 번에 지불할 수 없으시면 할부로 하실 수 있는 옵션을 드립니다.","e":"'a plazos'는 '할부로'입니다. 'de una vez(한 번에)'와 대조됩니다. 반대로 '일시불로'는 'al contado' 또는 'en un solo pago'입니다.","x":["en efectivo: 현금으로라 할부와 관계없습니다 ✗","con tarjeta: 카드로라 결제 수단이지 분할 방식이 아닙니다 ✗","al contado: 일시불(현금)로라 문맥과 반대입니다 ✗","a plazos: 할부로 → 정답 ✓"]},{"id":"V134","q":"Se ha roto un vaso, así que no andes ____.","o":["calzado","vestido","desnudo","descalzo"],"a":3,"k":"상태 형용사","t":"유리잔이 깨졌으니 맨발로 다니지 마.","e":"descalzo/a는 '맨발의'입니다. 'andar descalzo(맨발로 다니다)'처럼 씁니다. 깨진 유리 때문에 발을 다칠 수 있다는 문맥에 맞습니다. 반대말은 calzado(신을 신은)입니다.","x":["calzado: 신발을 신은이라 금지할 이유가 없습니다 ✗","vestido: 옷을 입은이라 맞지 않습니다 ✗","desnudo: 벌거벗은이라 유리와 관련된 주의가 아닙니다 ✗","descalzo: 맨발의 → 정답 ✓"]},{"id":"V135","q":"Necesito un ____ pequeño para cerrar la taquilla del gimnasio.","o":["pestillo","imperdible","broche","candado"],"a":3,"k":"생활용품 어휘","t":"헬스장 사물함을 잠그려면 작은 자물쇠가 필요하다.","e":"candado는 '자물쇠(맹꽁이자물쇠)'입니다. 사물함(taquilla)을 잠그는 데 쓰는 물건입니다. taquilla는 스페인에서 '사물함'이면서 '매표소'라는 뜻도 있습니다.","x":["pestillo: 빗장, 걸쇠라 문에 붙어 있는 것으로 따로 들고 다니지 않습니다 ✗","imperdible: 안전핀이라 잠그는 용도가 아닙니다 ✗","broche: 브로치, 똑딱단추라 맞지 않습니다 ✗","candado: 자물쇠 → 정답 ✓"]},{"id":"V136","q":"No creas nada de lo que dice, ____ constantemente.","o":["piensa","idea","planea","miente"],"a":3,"k":"동사 어휘","t":"그가 하는 말은 하나도 믿지 마, 그는 늘 거짓말을 해.","e":"mentir는 '거짓말하다'입니다. 'No creas nada de lo que dice(그 말을 믿지 마)'의 이유가 됩니다. e가 ie로 바뀌는 불규칙 동사입니다(miento, mientes, miente). 명사는 mentira(거짓말)입니다.","x":["piensa: pensar(생각하다)로 믿지 말라는 이유가 되지 않습니다 ✗","idea: idear(고안하다)로 이유가 되지 않습니다 ✗","planea: planear(계획하다)로 이유가 되지 않습니다 ✗","miente: mentir(거짓말하다) → 정답 ✓"]},{"id":"V137","q":"No seas ____ y háblales a tus profesores con respeto.","o":["descarada","ilusa","candorosa","ingenua"],"a":0,"k":"성격 형용사","t":"뻔뻔하게 굴지 말고 선생님들께 예의 바르게 말해.","e":"descarado/a는 '뻔뻔한, 무례한, 버릇없는'입니다. '존중하며 말하라(con respeto)'는 요구와 대조되므로 정답입니다. 'No seas + 형용사'는 '~하게 굴지 마'라는 부정 명령입니다.","x":["descarada: 뻔뻔한, 무례한 → 정답 ✓","ilusa: 망상에 빠진, 순진하게 착각하는이라 존중과 대조되지 않습니다 ✗","candorosa: 순진무구한이라 무례함과 관계없습니다 ✗","ingenua: 순진한이라 무례함과 관계없습니다 ✗"]},{"id":"V138","q":"Al tratarse de un pago recurrente, ____ los recibos de la luz y el agua.","o":["he domiciliado","he oficializado","he dictado","he decretado"],"a":0,"k":"은행 어휘","t":"정기적인 지불이라서 전기와 수도 요금 고지서를 자동이체로 해 두었다.","e":"domiciliar는 스페인 은행 용어로 '(요금을) 계좌 자동이체로 설정하다'입니다. 'domiciliar los recibos(고지서를 자동이체하다)'처럼 씁니다. pago recurrente는 '정기 결제'입니다.","x":["he domiciliado: domiciliar(자동이체 설정하다) → 정답 ✓","he oficializado: oficializar(공식화하다)로 요금 납부와 무관합니다 ✗","he dictado: dictar(받아쓰게 하다, 공포하다)로 맞지 않습니다 ✗","he decretado: decretar(법령으로 정하다)로 맞지 않습니다 ✗"]},{"id":"V139","q":"Nuestra discrepancia ____ en el hecho de que somos de ideologías opuestas.","o":["vive","se aloja","radica","habita"],"a":2,"k":"동사 어휘","t":"우리의 의견 차이는 우리가 정반대의 이념을 가지고 있다는 사실에 있다.","e":"radicar en ~은 '(원인·핵심이) ~에 있다'라는 뜻입니다. 'El problema radica en ~(문제는 ~에 있다)'처럼 원인을 설명할 때 자주 씁니다. 다른 보기는 사람이 '살다, 묵다'라는 뜻이라 추상적인 의견 차이에 쓰지 않습니다.","x":["vive: vivir(살다)로 추상적 원인에 쓰지 않습니다 ✗","se aloja: alojarse(묵다, 숙박하다)로 맞지 않습니다 ✗","radica: radicar en(~에 원인이 있다) → 정답 ✓","habita: habitar(거주하다)로 맞지 않습니다 ✗"]},{"id":"V140","q":"Prefiero ducharme con agua ____, ni fría ni caliente.","o":["templada","limpia","clara","congelada"],"a":0,"k":"온도 형용사","t":"나는 차갑지도 뜨겁지도 않은 미지근한 물로 샤워하는 것을 좋아한다.","e":"templado/a는 '미지근한, 온화한'입니다. 'ni fría ni caliente(차갑지도 뜨겁지도 않은)'라는 설명과 정확히 맞습니다. 기후에 쓰면 'clima templado(온화한 기후)'가 됩니다.","x":["templada: 미지근한 → 정답 ✓","limpia: 깨끗한이라 온도와 관계없습니다 ✗","clara: 맑은이라 온도와 관계없습니다 ✗","congelada: 얼어붙은이라 '차갑지 않다'는 말과 모순됩니다 ✗"]},{"id":"V141","q":"Me gustan las casas ____, no quiero vivir en un sitio pequeño.","o":["espaciosas","altas","diminutas","estrechas"],"a":0,"k":"주거 형용사","t":"나는 넓은 집이 좋다, 작은 곳에서 살고 싶지 않다.","e":"espacioso/a는 espacio(공간)에서 나온 말로 '넓은, 공간이 넉넉한'입니다. 'no quiero vivir en un sitio pequeño'와 의미가 일치합니다. 비슷한 말로 amplio가 있습니다.","x":["espaciosas: 넓은 → 정답 ✓","altas: 높은이라 넓이를 말하지 않습니다 ✗","diminutas: 아주 작은이라 문맥과 반대입니다 ✗","estrechas: 좁은이라 문맥과 반대입니다 ✗"]},{"id":"V142","q":"La profesora ____ las palabras que he escrito mal.","o":["ha tachado","alabado","ha elogiado","censurado"],"a":0,"k":"동사 어휘","t":"선생님은 내가 잘못 쓴 단어들에 줄을 그어 지웠다.","e":"tachar는 '(줄을 그어) 지우다, 삭제 표시를 하다'입니다. 틀리게 쓴(he escrito mal) 단어에 하는 행동으로 정답입니다. 보기 B와 D는 조동사 ha가 빠져 있어 문법적으로도 성립하지 않습니다.","x":["ha tachado: tachar(줄을 그어 지우다) → 정답 ✓","alabado: alabar(칭찬하다)의 과거분사로 ha가 없어 문장이 성립하지 않고, 틀린 단어를 칭찬할 리도 없습니다 ✗","ha elogiado: elogiar(칭찬하다)로 틀린 단어에 맞지 않습니다 ✗","censurado: censurar(검열하다, 비난하다)의 과거분사로 ha가 없어 문장이 성립하지 않습니다 ✗"]},{"id":"V143","q":"A diferencia de otros animales, los humanos son seres ____.","o":["salvajes","racionales","indómitos","selváticos"],"a":1,"k":"성질 형용사","t":"다른 동물들과 달리 인간은 이성적인 존재이다.","e":"racional은 razón(이성)에서 나온 말로 '이성적인, 합리적인'입니다. 'a diferencia de(~와 달리)'가 인간과 동물의 차이를 강조하므로, 인간만의 특징인 이성이 정답입니다.","x":["salvajes: 야생의라 동물의 특징에 가깝습니다 ✗","racionales: 이성적인 → 정답 ✓","indómitos: 길들일 수 없는이라 인간의 특징이 아닙니다 ✗","selváticos: 밀림의라 맞지 않습니다 ✗"]},{"id":"V144","q":"Antes ____ cada día, pero ahora no prueba el alcohol.","o":["se fatigaba","se emborrachaba","se agotaba","se atiborraba"],"a":1,"k":"대명동사 어휘","t":"예전에는 매일 술에 취했지만 지금은 술을 입에도 대지 않는다.","e":"emborracharse는 borracho(취한)에서 나온 말로 '술에 취하다'입니다. 'no prueba el alcohol(술을 입에 대지 않는다)'과 대조됩니다. 예전의 반복된 습관이라 불완료 과거(se emborrachaba)를 썼습니다.","x":["se fatigaba: fatigarse(피곤해지다)로 술과 대조되지 않습니다 ✗","se emborrachaba: emborracharse(술에 취하다) → 정답 ✓","se agotaba: agotarse(지치다)로 술과 관계없습니다 ✗","se atiborraba: atiborrarse(배 터지게 먹다)로 술 끊은 것과 직접 대조되지 않습니다 ✗"]},{"id":"V145","q":"Alicia me ____ un guiño en señal de complicidad.","o":["echó","hizo","puso","dio"],"a":1,"k":"동사 결합 표현","t":"알리시아는 공모의 표시로 나에게 윙크를 했다.","e":"'hacer un guiño'는 '윙크하다'라는 짝꿍 표현입니다. 동사 하나로는 guiñar (el ojo)라고 합니다. 'en señal de ~'는 '~의 표시로'입니다. 구어에서 echar un guiño도 들리지만 표준적인 결합은 hacer입니다.","x":["echó: echar(던지다)로 일부 구어에서 쓰이지만 표준 결합이 아닙니다 ✗","hizo: hacer → 'hacer un guiño(윙크하다)'로 정답 ✓","puso: poner(놓다)로 guiño와 결합하지 않습니다 ✗","dio: dar(주다)로 guiño와는 잘 결합하지 않습니다 ✗"]},{"id":"V146","q":"La profesora castigó al alumno por ____ una patada a su compañero.","o":["hacerle","darle","ponerle","echarle"],"a":1,"k":"동사 결합 표현","t":"선생님은 친구를 발로 찼다는 이유로 그 학생에게 벌을 주었다.","e":"'dar una patada a alguien'은 '~를 발로 차다'라는 짝꿍 표현입니다. 타격 동작은 dar와 결합합니다(dar un golpe 때리다, dar un puñetazo 주먹으로 치다). le는 'a su compañero'를 받는 간접목적격 대명사(~에게)입니다.","x":["hacerle: hacer(하다)로 patada와 결합하지 않습니다 ✗","darle: dar → 'dar una patada(발로 차다)'로 정답 ✓","ponerle: poner(놓다)로 patada와 결합하지 않습니다 ✗","echarle: echar(던지다)로 patada와 결합하지 않습니다 ✗"]},{"id":"V147","q":"El pan ____ es más oscuro que el pan blanco.","o":["seco","integral","fresco","duro"],"a":1,"k":"음식 어휘","t":"통밀빵은 흰 빵보다 색이 더 진하다.","e":"'pan integral'은 '통밀빵'입니다. integral은 '전체의, 정제하지 않은'이라는 뜻으로 'arroz integral(현미)'처럼도 씁니다. 겉껍질까지 사용해 색이 진하다는 설명과 맞습니다.","x":["seco: 마른, 딱딱해진이라 색과 관계없습니다 ✗","integral: 통밀의 → 정답 ✓","fresco: 갓 구운, 신선한이라 색과 관계없습니다 ✗","duro: 딱딱한, 오래된이라 색과 관계없습니다 ✗"]},{"id":"V148","q":"No viviría en un lugar con poca ____ ciudadana.","o":["hostilidad","confianza","lealtad","seguridad"],"a":3,"k":"사회 어휘","t":"나는 시민 안전(치안)이 좋지 않은 곳에서는 살지 않겠다.","e":"'seguridad ciudadana'는 '치안, 시민 안전'이라는 고정 표현입니다. 살기 싫은 이유로 치안이 부족한 것이 자연스럽습니다. 조건법 viviría는 '살지 않을 것이다'라는 가정의 뜻을 나타냅니다.","x":["hostilidad: 적대감이라 '적대감이 적은 곳'은 오히려 살기 좋습니다 ✗","confianza: 신뢰라 'confianza ciudadana'는 고정 표현이 아닙니다 ✗","lealtad: 충성, 의리라 맞지 않습니다 ✗","seguridad: 안전 → 'seguridad ciudadana(치안)'로 정답 ✓"]},{"id":"V149","q":"No ____ a hacer ningún deporte de riesgo, temo que me pase algo.","o":["me niego","me opongo","me atrevo","me resisto"],"a":2,"k":"대명동사 어휘","t":"나는 위험한 스포츠는 할 엄두가 나지 않는다, 무슨 일이 생길까 봐 두렵다.","e":"atreverse a + 동사원형은 '감히 ~하다, ~할 용기가 있다'입니다. 'no me atrevo a ~'는 '~할 엄두가 안 난다'로 두려움(temo)과 잘 맞습니다. 다른 보기도 대명동사지만 거부·반대의 뜻이라 두려움과 연결되지 않습니다.","x":["me niego: negarse a(~하기를 거부하다)로 의지적 거부라 두려움과 덜 맞고, 'no me niego'면 뜻이 반대가 됩니다 ✗","me opongo: oponerse a(~에 반대하다)로 뒤에 명사가 오며 맞지 않습니다 ✗","me atrevo: atreverse a(감히 ~하다) → 정답 ✓","me resisto: resistirse a(~하기를 꺼리다)로 'no me resisto'면 의미가 반대가 됩니다 ✗"]},{"id":"V150","q":"Saldremos pronto de casa para ____ el día.","o":["desarrollar","desperdiciar","acortar","aprovechar"],"a":3,"k":"동사 어휘","t":"하루를 알차게 보내려고 우리는 일찍 집을 나설 것이다.","e":"aprovechar는 '(시간·기회를) 활용하다, 알차게 쓰다'입니다. 'aprovechar el día'는 '하루를 알차게 보내다'라는 자주 쓰는 표현입니다. 식사 때 하는 인사 '¡Que aproveche!(맛있게 드세요!)'도 같은 동사입니다.","x":["desarrollar: 발전시키다, 전개하다로 '하루'와 결합하지 않습니다 ✗","desperdiciar: 낭비하다로 일찍 나서는 이유와 반대입니다 ✗","acortar: 줄이다로 맞지 않습니다 ✗","aprovechar: 활용하다 → 정답 ✓"]},{"id":"V151","q":"Corre el ____ de que la famosa pareja ha roto su relación.","o":["dicho","rumor","ruido","murmullo"],"a":1,"k":"rumor 관용 표현","t":"그 유명한 커플이 헤어졌다는 소문이 돌고 있다.","e":"'Corre el rumor de que ~'는 '~라는 소문이 돈다'라는 아주 자주 쓰는 관용 표현입니다. rumor는 '소문'이라는 뜻이고, 동사 correr(달리다)와 함께 쓰여 소문이 퍼져 나가는 모습을 나타냅니다. 예: Corre el rumor de que van a cerrar la fábrica. (공장이 문을 닫는다는 소문이 돈다.)","x":["dicho: '속담, 격언' 또는 '말한 것'이라는 뜻으로 소문이 퍼진다는 표현에는 쓰지 않습니다 ✗","rumor: '소문'으로, 'corre el rumor de que'라는 고정 표현을 이룹니다 → 정답 ✓","ruido: '소음, 시끄러운 소리'라는 뜻이라 문맥에 맞지 않습니다 ✗","murmullo: '웅성거림, 속삭이는 소리'라는 뜻으로 소문 자체를 가리키지 않습니다 ✗"]},{"id":"V152","q":"Es una escritora de ____, de ahí que sus libros sean tan vendidos.","o":["fama","reputación","notoriedad","renombre"],"a":3,"k":"명성 어휘","t":"그녀는 이름난 작가라서 그녀의 책이 그렇게 많이 팔린다.","e":"'de renombre'는 '명성 있는, 이름난'이라는 뜻의 고정 표현으로, 사람 명사 뒤에 붙여 형용사처럼 씁니다. 예: un médico de renombre(이름난 의사). fama, reputación도 '명성'이라는 뜻이지만 보통 'de mucha fama', 'tener buena reputación'처럼 수식어나 다른 동사와 함께 써야 자연스럽습니다.","x":["fama: '명성'이지만 'de fama' 단독보다 'famosa'나 'de mucha fama'가 자연스러워 ✗","reputación: '평판'으로, 좋은지 나쁜지 수식어(buena/mala)가 필요해 단독으로는 어색합니다 ✗","notoriedad: '세상에 널리 알려짐, 악명'에 가까운 뉘앙스로 'de notoriedad'는 잘 쓰지 않습니다 ✗","renombre: '명성'으로, 'de renombre(이름난)'라는 고정 표현을 이룹니다 → 정답 ✓"]},{"id":"V153","q":"El romanticismo es la principal característica de las novelas ____.","o":["rojas","verdes","amarillas","rosas"],"a":3,"k":"novela rosa","t":"로맨스는 연애 소설의 주된 특징이다.","e":"'novela rosa'(직역: 분홍 소설)는 사랑 이야기를 중심으로 한 '로맨스 소설, 연애 소설'을 가리키는 표현입니다. 이처럼 스페인어에는 색깔로 장르를 나타내는 표현이 있습니다. 예: novela negra(범죄·추리 소설), prensa amarilla(황색 언론, 선정적 언론).","x":["rojas: '빨간'이라는 뜻으로 소설 장르를 나타내는 표현이 아닙니다 ✗","verdes: '초록의'라는 뜻이며, 'chiste verde(야한 농담)'처럼 쓰이지만 연애 소설과는 무관합니다 ✗","amarillas: '노란'이라는 뜻으로 'prensa amarilla(선정적 언론)'에 쓰이며 소설 장르가 아닙니다 ✗","rosas: '분홍의'로, 'novela rosa'는 연애 소설을 뜻합니다 → 정답 ✓"]},{"id":"V154","q":"Tuvieron que ____ el brazo para inmovilizarlo.","o":["ajustarme","vendarme","cubrirme","escayolarme"],"a":3,"k":"의료 어휘","t":"그들은 내 팔을 고정하기 위해 깁스를 해야 했다.","e":"escayolar는 '석고 붕대(깁스)를 하다'라는 뜻입니다. 문장에서 'inmovilizar(움직이지 못하게 고정하다)'라고 했으므로, 단순히 붕대를 감는 것보다 깁스를 하는 것이 정확합니다. 참고로 중남미에서는 'enyesar'(yeso: 석고)라는 말을 더 많이 씁니다.","x":["ajustarme: '맞추다, 조이다'라는 뜻으로 팔을 고정하는 치료를 나타내지 않습니다 ✗","vendarme: '붕대를 감다'로, 붕대만으로는 완전히 고정(inmovilizar)하기 어렵습니다 ✗","cubrirme: '덮다, 가리다'라는 일반적인 뜻이라 치료 행위로는 맞지 않습니다 ✗","escayolarme: '깁스를 하다'로, 팔을 움직이지 못하게 고정하는 처치입니다 → 정답 ✓"]},{"id":"V155","q":"La artritis es una enfermedad ____, no es de corta duración.","o":["momentánea","pasajera","leve","crónica"],"a":3,"k":"질병 어휘","t":"관절염은 만성 질환이라 짧게 끝나는 병이 아니다.","e":"crónico/a는 '만성의'라는 뜻으로, 오랫동안 계속되는 병을 말할 때 씁니다. 문장 뒷부분 'no es de corta duración(짧은 기간이 아니다)'이 결정적인 힌트입니다. 반대말은 agudo/a(급성의)입니다. 예: una enfermedad crónica(만성 질환).","x":["momentánea: '순간적인, 일시적인'이라 '오래간다'는 문맥과 반대입니다 ✗","pasajera: '지나가는, 일시적인'이라 짧은 병을 뜻해 문맥과 반대입니다 ✗","leve: '가벼운, 경미한'으로 기간이 아니라 정도를 나타냅니다 ✗","crónica: '만성의'로, 오래 지속되는 병을 뜻합니다 → 정답 ✓"]},{"id":"V156","q":"Me encanta el plan que propones, es de lo más ____.","o":["tedioso","apetecible","aburrido","ambicioso"],"a":1,"k":"형용사 어휘","t":"네가 제안한 계획이 정말 마음에 들어, 아주 끌리는 계획이야.","e":"apetecible는 '하고 싶어지는, 끌리는, 구미가 당기는'이라는 뜻입니다. 동사 apetecer(~하고 싶다)에서 나온 형용사로, 음식뿐 아니라 계획·제안에도 씁니다. 'es de lo más + 형용사'는 '정말 ~하다'라는 강조 표현입니다. 예: ¿Te apetece ir al cine? (영화 보러 갈래?)","x":["tedioso: '지루한, 따분한'이라 '마음에 든다'는 앞 문장과 모순됩니다 ✗","apetecible: '끌리는, 하고 싶어지는'으로 계획이 마음에 든다는 문맥에 맞습니다 → 정답 ✓","aburrido: '지루한'이라 문맥과 반대입니다 ✗","ambicioso: '야심 찬'으로 계획에 쓸 수는 있지만 '마음에 든다'는 이유로는 덜 자연스럽습니다 ✗"]},{"id":"V157","q":"Afortunadamente, el número de ____ en nuestra región es cada vez menor.","o":["empleados","desempleados","asalariados","trabajadores"],"a":1,"k":"노동 어휘","t":"다행히도 우리 지역의 실업자 수는 점점 줄어들고 있다.","e":"desempleado/a는 '실업자, 일자리가 없는 사람'입니다. 'Afortunadamente(다행히)'와 'cada vez menor(점점 줄어드는)'가 함께 쓰였으므로, 줄어들어서 좋은 것은 실업자 수입니다. 비슷한 말로 parado/a(스페인), cesante(칠레 등)도 있습니다.","x":["empleados: '직원, 고용된 사람'으로 이 수가 줄어드는 것은 다행이 아닙니다 ✗","desempleados: '실업자'로, 그 수가 줄어드는 것은 다행스러운 일입니다 → 정답 ✓","asalariados: '월급 받는 근로자'로 줄어드는 것이 다행이라는 문맥과 맞지 않습니다 ✗","trabajadores: '노동자'로 이 수가 줄어드는 것은 좋은 소식이 아닙니다 ✗"]},{"id":"V158","q":"¿Cómo no te van a doler los pies después de la ____?","o":["conferencia","reunión","caminata","velada"],"a":2,"k":"활동 어휘","t":"그렇게 오래 걷고 나서 어떻게 발이 안 아프겠어?","e":"caminata는 '긴 산책, 오래 걷기, 도보 여행'이라는 뜻입니다. 발이 아픈 이유가 되려면 많이 걸은 활동이어야 하므로 caminata가 정답입니다. 예: Hicimos una caminata de diez kilómetros. (우리는 10킬로미터를 걸었다.)","x":["conferencia: '강연, 회의'로 발이 아플 만한 활동이 아닙니다 ✗","reunión: '회의, 모임'으로 발이 아픈 이유가 되지 않습니다 ✗","caminata: '오래 걷기'로 발이 아픈 원인이 됩니다 → 정답 ✓","velada: '저녁 모임, 야회'로 걷는 활동과 관련이 없습니다 ✗"]},{"id":"V159","q":"Tenemos un ____ de un mes para pedir la revisión de nuestro examen.","o":["lapso","curso","plazo","transcurso"],"a":2,"k":"기간 어휘","t":"우리는 시험 재검토를 요청할 수 있는 기한이 한 달 있다.","e":"plazo는 '기한, (정해진) 기간'이라는 뜻으로, 무엇을 해야 하는 마감까지의 기간을 말합니다. 'tener un plazo de ~ para + 동사원형'은 '~할 기한이 …이다'라는 표현입니다. 예: El plazo de inscripción termina mañana. (등록 기한은 내일 끝난다.)","x":["lapso: '(시간의) 경과, 기간'으로 막연한 시간 간격을 말하며 마감 기한의 뜻은 약합니다 ✗","curso: '과정, 학년, 강좌'라는 뜻으로 문맥에 맞지 않습니다 ✗","plazo: '기한'으로 정해진 마감 기간을 뜻합니다 → 정답 ✓","transcurso: '(시간의) 흐름, 경과'로 'en el transcurso de'처럼 쓰여 기한의 뜻이 아닙니다 ✗"]},{"id":"V160","q":"Se para cada día delante de ese ____, pero nunca compra nada.","o":["estante","escaparate","portal","ventanal"],"a":1,"k":"상점 어휘","t":"그는 매일 그 진열장 앞에 멈춰 서지만 아무것도 사지 않는다.","e":"escaparate는 가게 앞에 상품을 진열해 둔 '쇼윈도, 진열창'입니다. '사지 않는다(nunca compra nada)'는 말이 상점과 관련된 단어임을 알려 줍니다. 중남미에서는 'vitrina'라는 말을 더 자주 씁니다. 예: mirar escaparates(윈도쇼핑하다).","x":["estante: '선반, 책장'으로 그 앞에 멈춰 서서 구경하는 대상으로는 부자연스럽습니다 ✗","escaparate: '쇼윈도'로 물건을 구경만 하고 사지 않는 상황에 딱 맞습니다 → 정답 ✓","portal: '현관, 건물 입구'로 물건을 사는 것과 관련이 없습니다 ✗","ventanal: '큰 창문'으로 상품 진열과는 관련이 없습니다 ✗"]},{"id":"V161","q":"Todos nos quedamos ____ al ver llorar a la señora.","o":["cegados","conmovidos","aliviados","decepcionados"],"a":1,"k":"감정 어휘","t":"그 부인이 우는 것을 보고 우리 모두 마음이 뭉클해졌다.","e":"conmovido/a는 '감동한, 마음이 움직인'이라는 뜻으로, 동사 conmover(마음을 움직이다)에서 왔습니다. 누군가 우는 모습을 보고 느끼는 감정으로 가장 자연스럽습니다. 'quedarse + 형용사'는 '~한 상태가 되다'라는 뜻입니다.","x":["cegados: '눈이 먼'이라는 뜻으로 우는 사람을 보고 느끼는 감정이 아닙니다 ✗","conmovidos: '마음이 뭉클한, 감동한'으로 문맥에 맞습니다 → 정답 ✓","aliviados: '안도한'으로 남이 우는 것을 보고 안도하는 것은 부자연스럽습니다 ✗","decepcionados: '실망한'으로 우는 모습을 본 반응으로 맞지 않습니다 ✗"]},{"id":"V162","q":"Me tomé un calmante al ver que me estaba dando un ____ de ansiedad.","o":["golpe","choque","trastorno","ataque"],"a":3,"k":"ataque 콜로케이션","t":"불안 발작이 오고 있다는 걸 알고 진정제를 먹었다.","e":"'ataque de ansiedad'는 '불안 발작'이라는 뜻의 고정된 짝 표현입니다. ataque는 '공격'이라는 뜻 외에 병이나 감정이 갑자기 덮치는 '발작'을 뜻합니다. 'darle a alguien un ataque'는 '~에게 발작이 일어나다'라는 표현입니다. 예: un ataque de risa(웃음보가 터짐), un ataque al corazón(심장마비).","x":["golpe: '타격, 충격'으로 'ansiedad'와 짝을 이루지 않습니다 ✗","choque: '충돌'로 'ansiedad'와 함께 쓰지 않습니다 ✗","trastorno: '장애'로 'trastorno de ansiedad(불안 장애)'는 있지만 'dar un trastorno'처럼 갑자기 일어나는 일에는 쓰지 않습니다 ✗","ataque: '발작'으로 'ataque de ansiedad'가 고정 표현입니다 → 정답 ✓"]},{"id":"V163","q":"Don Fermín es el párroco de nuestra ____.","o":["oficina","galería","tienda","iglesia"],"a":3,"k":"종교 어휘","t":"페르민 신부님은 우리 성당의 주임 신부님이다.","e":"párroco는 가톨릭 교구(parroquia)를 맡은 '주임 신부'입니다. 신부가 있는 곳은 당연히 iglesia(교회, 성당)입니다. 'Don'은 남성 이름 앞에 붙이는 존칭으로 '~님, ~씨'에 해당합니다.","x":["oficina: '사무실'로 신부와 관련이 없습니다 ✗","galería: '화랑, 회랑'으로 신부와 관련이 없습니다 ✗","tienda: '가게'로 신부와 관련이 없습니다 ✗","iglesia: '교회, 성당'으로 주임 신부가 일하는 곳입니다 → 정답 ✓"]},{"id":"V164","q":"El nuevo gobierno pretende atraer ____ de obra extranjera en sectores como la construcción.","o":["cabeza","mano","espalda","pierna"],"a":1,"k":"mano de obra","t":"새 정부는 건설업 같은 분야에 외국인 노동력을 유치하려 한다.","e":"'mano de obra'(직역: 작업의 손)는 '노동력, 일손'이라는 뜻의 고정 표현입니다. 'mano de obra extranjera'는 '외국인 노동력', 'mano de obra barata'는 '값싼 노동력'입니다. 한국어에서도 '일손'이라고 하듯 손(mano)이 노동을 상징합니다.","x":["cabeza: '머리'로 'de obra'와 고정 표현을 이루지 않습니다 ✗","mano: '손'으로 'mano de obra(노동력)'라는 고정 표현을 이룹니다 → 정답 ✓","espalda: '등'으로 노동력을 뜻하는 표현이 없습니다 ✗","pierna: '다리'로 노동력을 뜻하는 표현이 없습니다 ✗"]},{"id":"V165","q":"Ese señor va con un perro guía porque es ____.","o":["sordo","mudo","sordomudo","ciego"],"a":3,"k":"장애 어휘","t":"그 남자는 시각 장애인이라서 안내견과 함께 다닌다.","e":"ciego/a는 '눈이 보이지 않는, 시각 장애인'이라는 뜻입니다. 'perro guía(안내견)'는 앞을 보지 못하는 사람을 돕는 개이므로 ciego가 정답입니다. 요즘은 좀 더 정중하게 'persona con discapacidad visual'이라고도 합니다.","x":["sordo: '귀가 들리지 않는'으로 안내견과 직접 관련이 없습니다 ✗","mudo: '말을 못 하는'으로 안내견과 관련이 없습니다 ✗","sordomudo: '듣지도 말하지도 못하는'으로 안내견이 필요한 이유가 아닙니다 ✗","ciego: '앞을 보지 못하는'으로 안내견이 필요한 이유입니다 → 정답 ✓"]},{"id":"V166","q":"La yarda es una ____ de longitud.","o":["dimensión","medida","superficie","capacidad"],"a":1,"k":"측정 어휘","t":"야드는 길이의 단위이다.","e":"medida는 '치수, 측정, 단위'라는 뜻으로, 'medida de longitud'는 '길이의 단위'입니다. 이 문맥에서는 'unidad de medida(측정 단위)'와 같은 의미로 쓰였습니다. 예: El metro es una medida de longitud. (미터는 길이의 단위다.)","x":["dimensión: '차원, 크기'로 '길이의 단위'라는 뜻이 되지 않습니다 ✗","medida: '측정 단위, 치수'로 야드가 무엇인지 정확히 나타냅니다 → 정답 ✓","superficie: '면적, 표면'으로 길이와 맞지 않습니다 ✗","capacidad: '용량'으로 부피를 재는 개념이라 길이와 맞지 않습니다 ✗"]},{"id":"V167","q":"Álvaro es un ____ de los deportes de riesgo, sobre todo del paracaidismo.","o":["soñador","ilusionado","apasionado","romántico"],"a":2,"k":"성격·취미 어휘","t":"알바로는 익스트림 스포츠, 특히 스카이다이빙의 열렬한 애호가이다.","e":"apasionado/a는 '열정적인 사람, 애호가'라는 뜻으로 'ser un apasionado de + 명사'는 '~를 아주 좋아하는 사람이다'라는 표현입니다. pasión(열정)에서 온 말입니다. 예: Es una apasionada de la música. (그녀는 음악 애호가다.)","x":["soñador: '몽상가'로 특정 취미를 열렬히 좋아한다는 뜻이 아닙니다 ✗","ilusionado: '설레는, 기대에 찬'이라는 형용사로 'un ilusionado de'라는 표현은 쓰지 않습니다 ✗","apasionado: '애호가, 열정적인 사람'으로 'un apasionado de'가 자연스럽습니다 → 정답 ✓","romántico: '낭만주의자, 낭만적인 사람'으로 스포츠와 어울리지 않습니다 ✗"]},{"id":"V168","q":"Estos zapatos me ____, son demasiado pequeños para mí.","o":["comprimen","presionan","aprietan","agobian"],"a":2,"k":"apretar 동사","t":"이 신발은 나한테 꽉 끼어, 나한테 너무 작아.","e":"apretar는 '꽉 죄다, 꽉 끼다'라는 뜻으로, 신발이나 옷이 작아서 몸을 조일 때 씁니다. 사람(나)은 간접목적격 대명사 me로 나타냅니다. 예: Este pantalón me aprieta. (이 바지는 나한테 꽉 낀다.) 현재형에서 e가 ie로 바뀌는 불규칙 동사입니다(aprieto, aprietas…).","x":["comprimen: '압축하다'로 신발이 작다는 일상 표현으로는 쓰지 않습니다 ✗","presionan: '누르다, 압박하다'로 의미는 비슷하지만 작은 신발에는 쓰지 않습니다 ✗","aprietan: '꽉 끼다'로 작은 신발이나 옷에 쓰는 표현입니다 → 정답 ✓","agobian: '숨 막히게 하다, 괴롭히다'로 주로 심리적 압박에 씁니다 ✗"]},{"id":"V169","q":"Debemos ____ el mayor partido a la situación, así nos beneficiaremos todos.","o":["sacarle","extraerle","exprimirle","quitarle"],"a":0,"k":"sacar partido","t":"우리는 이 상황을 최대한 활용해야 해. 그러면 모두가 이득을 볼 거야.","e":"'sacar partido a/de algo'는 '~을 활용하다, ~에서 이득을 얻다'라는 관용 표현입니다. 'sacar el mayor partido'는 '최대한 활용하다'라는 뜻이고, 여기서 le는 'a la situación'을 미리 받는 간접목적격 대명사입니다. 비슷한 표현으로 'sacar provecho de'가 있습니다.","x":["sacarle: 'sacar partido(활용하다)'라는 관용 표현을 이룹니다 → 정답 ✓","extraerle: '추출하다'라는 뜻이지만 'partido'와 짝을 이루지 않습니다 ✗","exprimirle: '짜내다'로 'exprimir al máximo'는 있지만 'partido'와 함께 쓰지 않습니다 ✗","quitarle: '빼앗다, 없애다'로 활용한다는 뜻과 반대입니다 ✗"]},{"id":"V170","q":"Antes tenía una cocina de gas, ahora cocino en una ____.","o":["vitrocerámica","nevera","encimera","despensa"],"a":0,"k":"주방 어휘","t":"예전에는 가스레인지가 있었는데, 지금은 전기레인지(하이라이트)로 요리한다.","e":"vitrocerámica는 유리 세라믹 상판으로 된 '전기레인지(하이라이트/인덕션 유형)'입니다. 'cocina de gas(가스레인지)'와 비교되는 조리 기구이므로 정답입니다. 참고로 'cocina'는 '부엌'뿐 아니라 '레인지, 화구'라는 뜻도 있습니다.","x":["vitrocerámica: '전기레인지'로 가스레인지를 대신하는 조리 기구입니다 → 정답 ✓","nevera: '냉장고'로 요리하는 기구가 아닙니다 ✗","encimera: '조리대 상판'으로 위에서 재료를 손질할 수는 있지만 불을 쓰는 기구는 아닙니다 ✗","despensa: '식료품 저장실'로 요리하는 곳이 아닙니다 ✗"]},{"id":"V171","q":"Vamos a analizar ____ de esta novela.","o":["un fragmento","un pedazo","un trozo","una pieza"],"a":0,"k":"부분 어휘","t":"이 소설의 한 구절을 분석해 봅시다.","e":"fragmento는 '단편, 일부분'이라는 뜻으로, 글·음악·작품의 일부를 말할 때 씁니다. 소설은 텍스트이므로 'un fragmento de la novela(소설의 한 대목)'가 자연스럽습니다. pedazo나 trozo는 주로 물건(빵, 케이크 등)의 '조각'에 씁니다.","x":["un fragmento: '(작품의) 일부, 대목'으로 소설에 쓰기 알맞습니다 → 정답 ✓","un pedazo: '조각'으로 주로 음식이나 물건에 씁니다 ✗","un trozo: '조각, 토막'으로 일상에서 물건에 쓰며 분석 대상인 텍스트에는 덜 적절합니다 ✗","una pieza: '부품, 한 점(작품)'으로 소설의 일부를 뜻하지 않습니다 ✗"]},{"id":"V172","q":"Antonio está en el hospital debido a la paliza que le ____.","o":["proporcionaron","propinaron","pasaron","encargaron"],"a":1,"k":"propinar 콜로케이션","t":"안토니오는 그들이 그에게 가한 폭행 때문에 병원에 있다.","e":"propinar는 '(타격·주먹 등을) 가하다, 먹이다'라는 뜻으로, 'propinar una paliza(흠씬 두들겨 패다)', 'propinar un golpe(한 대 치다)'처럼 짝을 이루어 씁니다. paliza는 '심한 구타, 매질'이라는 뜻입니다. 일상에서는 'darle una paliza'라고도 합니다.","x":["proporcionaron: '제공하다'로 도움·정보를 줄 때 쓰며 폭행에는 쓰지 않습니다 ✗","propinaron: '(구타를) 가하다'로 'paliza'와 짝을 이룹니다 → 정답 ✓","pasaron: '건네다, 지나가다'로 'paliza'와 함께 쓰지 않습니다 ✗","encargaron: '맡기다, 주문하다'로 문맥에 맞지 않습니다 ✗"]},{"id":"V173","q":"Es un ____, no sabe nada de nada.","o":["ignorante","enterado","listo","chulo"],"a":0,"k":"성격 어휘","t":"그는 무식한 사람이라 아무것도 모른다.","e":"ignorante는 '무지한 사람, 무식한 사람'이라는 뜻으로, 동사 ignorar(모르다)와 관련된 말입니다. 'no sabe nada de nada(정말 아무것도 모른다)'는 설명과 정확히 일치합니다. 반대말로는 sabio(현명한 사람), culto(교양 있는 사람)가 있습니다.","x":["ignorante: '무식한 사람'으로 아무것도 모른다는 설명과 맞습니다 → 정답 ✓","enterado: '잘 아는 사람, 소식통'으로 문맥과 반대입니다 ✗","listo: '똑똑한 사람'으로 문맥과 반대입니다 ✗","chulo: '건방진 사람' 또는 스페인 구어로 '멋진'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V174","q":"Tristemente, nuestro abuelo ____ hace un mes a causa de un problema cardíaco.","o":["fracasó","falleció","falló","faltó"],"a":1,"k":"죽음 어휘","t":"슬프게도 우리 할아버지는 심장 문제로 한 달 전에 돌아가셨다.","e":"fallecer는 '돌아가시다, 사망하다'라는 뜻으로 morir보다 공손하고 격식 있는 표현입니다. 'a causa de un problema cardíaco(심장 문제 때문에)'와 'Tristemente(슬프게도)'가 힌트입니다. 비슷하게 생긴 fracasar, fallar, faltar와 헷갈리지 않도록 주의하세요.","x":["fracasó: '실패하다'로 할아버지의 죽음을 나타내지 않습니다 ✗","falleció: '돌아가시다'로 morir의 정중한 표현입니다 → 정답 ✓","falló: '실패하다, 고장 나다'로 사람의 죽음에 쓰지 않습니다 ✗","faltó: '부족하다, 결석하다'라는 뜻이라 문맥에 맞지 않습니다 ✗"]},{"id":"V175","q":"No soporto los dolores ____. Para mí tener la regla es un auténtico problema.","o":["menstruales","lumbares","estomacales","dentales"],"a":0,"k":"신체·통증 어휘","t":"나는 생리통을 견딜 수가 없어. 나에게 생리는 정말 큰 문제야.","e":"menstrual은 '월경의, 생리의'라는 뜻으로 'dolores menstruales'는 '생리통'입니다. 문장의 'tener la regla(생리를 하다)'가 결정적인 힌트입니다. regla는 '자, 규칙' 외에 구어로 '생리'라는 뜻도 있습니다.","x":["menstruales: '생리의'로 'tener la regla'와 바로 연결됩니다 → 정답 ✓","lumbares: '허리의'로 'dolores lumbares(요통)'는 있지만 생리와 직접 연결되지 않습니다 ✗","estomacales: '위의'로 '위통'을 뜻해 생리와 관련이 없습니다 ✗","dentales: '치아의'로 '치통'을 뜻해 생리와 관련이 없습니다 ✗"]},{"id":"V176","q":"Todos los miembros del ____ consideraron que la acusada era culpable.","o":["jurado","clan","coro","equipo"],"a":0,"k":"법률 어휘","t":"배심원단의 모든 구성원은 피고인이 유죄라고 판단했다.","e":"jurado는 '배심원단' 또는 '심사위원단'이라는 뜻입니다. 'acusada(피고인)'와 'culpable(유죄의)'이라는 법정 어휘가 나오므로 재판에서 유무죄를 판단하는 jurado가 정답입니다. 개별 배심원 한 명도 jurado라고 부를 수 있습니다.","x":["jurado: '배심원단'으로 피고인의 유무죄를 판단합니다 → 정답 ✓","clan: '씨족, 패거리'로 재판과 관련이 없습니다 ✗","coro: '합창단'으로 재판과 관련이 없습니다 ✗","equipo: '팀'으로 유무죄를 판단하는 집단이 아닙니다 ✗"]},{"id":"V177","q":"Conozco a esa chica ____, no sé ni cómo se llama.","o":["muy bien","de vista","perfectamente","de cerca"],"a":1,"k":"conocer de vista","t":"그 여자애는 얼굴만 알아, 이름도 몰라.","e":"'conocer a alguien de vista'는 '~를 얼굴만 알다, 오며 가며 본 적만 있다'라는 관용 표현입니다. 뒤 문장 'no sé ni cómo se llama(이름조차 모른다)'가 깊이 아는 사이가 아님을 보여 줍니다. 예: A tu vecino lo conozco solo de vista. (네 이웃은 얼굴만 알아.)","x":["muy bien: '아주 잘'이라 이름도 모른다는 말과 모순됩니다 ✗","de vista: '얼굴만 (아는)'으로 이름도 모르는 상황에 맞습니다 → 정답 ✓","perfectamente: '완벽하게'라 이름도 모른다는 말과 모순됩니다 ✗","de cerca: '가까이서'라는 뜻으로 잘 안다는 뉘앙스라 문맥에 맞지 않습니다 ✗"]},{"id":"V178","q":"Antes de pintar, asegúrate de que el ____ esté limpio.","o":["cepillo","cincel","torno","pincel"],"a":3,"k":"도구 어휘","t":"그림을 그리기 전에 붓이 깨끗한지 확인해.","e":"pincel은 그림을 그릴 때 쓰는 '붓'입니다. 벽 등에 페인트를 칠할 때 쓰는 큰 솔은 brocha라고 합니다. 'asegúrate de que + 접속법(esté)'은 '~인지 확인해'라는 표현으로, 확실히 하려는 내용에 접속법을 씁니다.","x":["cepillo: '솔, 빗, 칫솔'로 그림을 그리는 도구가 아닙니다 ✗","cincel: '끌'로 조각할 때 쓰는 도구입니다 ✗","torno: '선반, 물레'로 그림 도구가 아닙니다 ✗","pincel: '붓'으로 그림 그리기 전에 확인할 도구입니다 → 정답 ✓"]},{"id":"V179","q":"Mis abuelos tuvieron nada menos que ocho hijos, sin duda una familia ____.","o":["anormal","convencional","voluminosa","numerosa"],"a":3,"k":"familia numerosa","t":"우리 조부모님은 무려 여덟 명의 자녀를 두셨으니, 정말 대가족이었다.","e":"'familia numerosa'는 '대가족, 다자녀 가정'이라는 고정 표현입니다. numeroso/a는 '수가 많은'이라는 뜻입니다. 스페인에서는 자녀가 셋 이상인 가정을 공식적으로 'familia numerosa'라고 부르고 혜택을 줍니다. 'nada menos que'는 '무려'라는 강조 표현입니다.","x":["anormal: '비정상적인'으로 가족에 쓰면 부정적이고 어색합니다 ✗","convencional: '전통적인, 평범한'으로 자녀가 많다는 뜻이 아닙니다 ✗","voluminosa: '부피가 큰'으로 물건에 쓰며 가족에는 쓰지 않습니다 ✗","numerosa: '수가 많은'으로 'familia numerosa(대가족)'라는 고정 표현입니다 → 정답 ✓"]},{"id":"V180","q":"Las tortugas se protegen de los ataques gracias a su ____.","o":["corteza","cascarón","concha","caparazón"],"a":3,"k":"동물 어휘","t":"거북은 등딱지 덕분에 공격으로부터 자신을 보호한다.","e":"caparazón은 거북·게 등의 단단한 '등딱지, 갑각'입니다. 거북이 몸을 숨기는 단단한 껍데기를 말할 때 가장 정확한 단어입니다. 'gracias a'는 '~ 덕분에'라는 뜻입니다.","x":["corteza: '나무껍질, 빵 껍질'로 동물에 쓰지 않습니다 ✗","cascarón: '알껍데기'로 거북의 등딱지가 아닙니다 ✗","concha: '조개껍데기, 소라껍데기'로 연체동물의 껍질에 주로 씁니다 ✗","caparazón: '등딱지'로 거북의 단단한 껍질입니다 → 정답 ✓"]},{"id":"V181","q":"Roberto se quedó ____ al ver a su chica con el traje de novia.","o":["alumbrado","encendido","iluminado","deslumbrado"],"a":3,"k":"감정 형용사","t":"로베르토는 웨딩드레스를 입은 그녀를 보고 넋을 잃었다.","e":"deslumbrado/a는 원래 '(강한 빛에) 눈이 부신'이라는 뜻이지만, 비유적으로 '아름다움이나 놀라움에 넋을 잃은, 홀딱 반한'이라는 뜻으로 많이 씁니다. 'quedarse deslumbrado'는 '눈이 휘둥그레지다, 매료되다'입니다. 예: Me quedé deslumbrada con el paisaje. (나는 그 풍경에 넋을 잃었다.)","x":["alumbrado: '불이 밝혀진'으로 사람의 감정 상태를 나타내지 않습니다 ✗","encendido: '(불이) 켜진'으로 사람에게는 '흥분한, 달아오른'이 되어 문맥에 맞지 않습니다 ✗","iluminado: '빛을 받은, 깨달음을 얻은'으로 아름다움에 반한 상태가 아닙니다 ✗","deslumbrado: '넋을 잃은, 매료된'으로 신부를 보고 놀란 상황에 맞습니다 → 정답 ✓"]},{"id":"V182","q":"____ mi sueldo a que no vas a ganar el primer premio de la lotería.","o":["Me apuesto","Pongo","Arriesgo","Me dejo"],"a":0,"k":"apostarse 구문","t":"네가 복권 1등에 당첨되지 못한다는 데 내 월급을 걸겠어.","e":"'apostarse algo a que ~'는 '~라는 데 …을 걸다'라는 표현입니다. apostar(내기하다, 걸다)는 재귀형 apostarse로 쓰면 구어에서 '확신한다'는 뉘앙스가 강해집니다. 예: Me apuesto lo que quieras a que llueve mañana. (내일 비 온다는 데 뭐든 걸게.) 현재형은 o가 ue로 바뀝니다(apuesto).","x":["Me apuesto: '(내기에) 걸다'로 'a que'와 함께 쓰는 고정 구문입니다 → 정답 ✓","Pongo: '놓다, 두다'로 'pongo ~ a que'는 스페인어 내기 표현으로 쓰지 않습니다 ✗","Arriesgo: '위험을 무릅쓰다'로 'a que'와 함께 내기를 나타내지 않습니다 ✗","Me dejo: '놓아두다, 내버려 두다'로 내기의 뜻이 없습니다 ✗"]},{"id":"V183","q":"Antes era muy buen estudiante, en cambio ahora ____ malas notas constantemente.","o":["saca","extrae","revela","pone"],"a":0,"k":"sacar notas","t":"예전에는 아주 좋은 학생이었는데, 지금은 계속 나쁜 성적을 받는다.","e":"'sacar buenas/malas notas'는 '좋은/나쁜 성적을 받다'라는 고정 표현입니다. sacar는 '꺼내다'라는 뜻 외에 '(성적·점수를) 받다, 얻다'라는 뜻으로 자주 쓰입니다. 예: Saqué un diez en el examen. (시험에서 10점(만점)을 받았다.) 'poner notas'는 선생님이 '성적을 매기다'라는 뜻입니다.","x":["saca: '(성적을) 받다'로 'sacar malas notas'라는 고정 표현입니다 → 정답 ✓","extrae: '추출하다'로 성적에는 쓰지 않습니다 ✗","revela: '드러내다, 폭로하다'로 성적과 관련이 없습니다 ✗","pone: 'poner notas'는 선생님이 '점수를 매기다'라는 뜻이라 학생 주어에 맞지 않습니다 ✗"]},{"id":"V184","q":"Muchos adolescentes tienen ____.","o":["acné","artrosis","canas","calvicie"],"a":0,"k":"신체·질환 어휘","t":"많은 청소년들이 여드름이 있다.","e":"acné는 '여드름'으로, 사춘기 청소년(adolescentes)에게 흔한 피부 증상입니다. 나머지 보기는 모두 나이 든 사람에게 흔한 현상입니다. 여드름 하나하나는 구어로 'grano'라고도 합니다. 예: Me ha salido un grano. (뾰루지가 났다.)","x":["acné: '여드름'으로 청소년에게 흔합니다 → 정답 ✓","artrosis: '골관절염'으로 주로 노인에게 생깁니다 ✗","canas: '흰머리'로 주로 나이 든 사람에게 생깁니다 ✗","calvicie: '대머리, 탈모'로 청소년에게 흔하지 않습니다 ✗"]},{"id":"V185","q":"Tengo una colección de ____ de pulsera.","o":["collares","anillos","relojes","pendientes"],"a":2,"k":"액세서리 어휘","t":"나는 손목시계를 모은 컬렉션이 있다.","e":"'reloj de pulsera'는 '손목시계'라는 고정 표현입니다. pulsera는 '팔찌'라는 뜻이며, 'de pulsera'는 '팔목에 차는'이라는 의미가 됩니다. 참고로 벽시계는 'reloj de pared', 자명종은 'despertador'입니다.","x":["collares: '목걸이'로 'de pulsera'와 함께 쓰지 않습니다 ✗","anillos: '반지'로 'de pulsera'와 함께 쓰지 않습니다 ✗","relojes: '시계'로 'reloj de pulsera(손목시계)'라는 고정 표현을 이룹니다 → 정답 ✓","pendientes: '귀걸이'로 'de pulsera'와 함께 쓰지 않습니다 ✗"]},{"id":"V186","q":"La enfermera me dijo que sólo tenía una herida ____. ¡Menos mal!","o":["superficial","trivial","profunda","bestial"],"a":0,"k":"상처 어휘","t":"간호사가 내가 가벼운 찰과상만 입었다고 말했다. 다행이야!","e":"'herida superficial'은 '피부 겉면만 다친 가벼운 상처'라는 뜻입니다. superficial은 '표면의, 얕은'입니다. '¡Menos mal!(다행이다)'과 'sólo(~뿐)'가 심각하지 않은 상처라는 힌트입니다. 반대말은 'herida profunda(깊은 상처)'입니다.","x":["superficial: '얕은, 표면의'로 가벼운 상처를 뜻해 '다행이다'와 맞습니다 → 정답 ✓","trivial: '사소한, 하찮은'으로 일이나 문제에 쓰며 상처에는 잘 쓰지 않습니다 ✗","profunda: '깊은'으로 심각한 상처라 '다행이다'와 맞지 않습니다 ✗","bestial: '끔찍한, 엄청난'으로 문맥과 반대입니다 ✗"]},{"id":"V187","q":"Me encanta ver el ____, esos primeros momentos de la mañana...","o":["anochecer","ocaso","amanecer","atardecer"],"a":2,"k":"하루 시간대 어휘","t":"나는 해 뜨는 것을 보는 게 정말 좋아, 아침의 그 첫 순간들 말이야...","e":"amanecer는 '새벽, 해돋이'라는 명사이자 '날이 밝다'라는 동사입니다. 'esos primeros momentos de la mañana(아침의 첫 순간들)'가 결정적인 힌트입니다. 예: Salimos al amanecer. (우리는 새벽에 출발했다.)","x":["anochecer: '해 질 녘, 밤이 되는 때'로 아침과 반대입니다 ✗","ocaso: '일몰, 해넘이'로 아침과 반대입니다 ✗","amanecer: '해돋이, 새벽'으로 아침의 첫 순간입니다 → 정답 ✓","atardecer: '해 질 녘, 저녁 무렵'으로 아침과 반대입니다 ✗"]},{"id":"V188","q":"Te has pasado de la ____ con tu comentario, deberías disculparte.","o":["raya","línea","franja","serie"],"a":0,"k":"pasarse de la raya","t":"네 말은 선을 넘었어, 사과해야 해.","e":"'pasarse de la raya'(직역: 선을 넘어가다)는 '도를 넘다, 선을 넘다'라는 관용 표현입니다. raya는 '줄, 선'입니다. 한국어의 '선을 넘다'와 비슷하지만 스페인어에서는 línea가 아닌 raya를 씁니다. 예: Esta vez te has pasado de la raya. (이번엔 네가 도를 넘었어.)","x":["raya: '선'으로 'pasarse de la raya(도를 넘다)'라는 관용 표현입니다 → 정답 ✓","línea: '선'이라는 뜻은 같지만 이 관용 표현에는 쓰지 않습니다 ✗","franja: '띠, 줄무늬'로 관용 표현을 이루지 않습니다 ✗","serie: '시리즈, 연속'으로 문맥과 관련이 없습니다 ✗"]},{"id":"V189","q":"Tengo una confianza ____ en ella, es una persona honrada y sincera.","o":["ciega","sorda","pura","muda"],"a":0,"k":"confianza ciega","t":"나는 그녀를 전적으로 믿어. 그녀는 정직하고 진실한 사람이야.","e":"'confianza ciega'(직역: 눈먼 신뢰)는 '맹목적인 신뢰, 전적인 믿음'이라는 고정 표현입니다. 조금도 의심하지 않고 믿는다는 뜻입니다. 'tener una confianza ciega en alguien'은 '~를 철석같이 믿다'입니다.","x":["ciega: '눈먼'으로 'confianza ciega(전적인 신뢰)'라는 고정 표현입니다 → 정답 ✓","sorda: '귀먹은'으로 신뢰와 함께 쓰는 표현이 없습니다 ✗","pura: '순수한'으로 신뢰와 짝을 이루는 관용 표현이 아닙니다 ✗","muda: '말 못 하는'으로 신뢰와 함께 쓰지 않습니다 ✗"]},{"id":"V190","q":"Los alimentos ____ tienen menos grasa.","o":["cremosos","aceitosos","desnatados","azucarados"],"a":2,"k":"식품 어휘","t":"저지방(탈지) 식품은 지방이 더 적다.","e":"desnatado/a는 '지방(크림)을 걷어낸, 탈지한'이라는 뜻으로, nata(크림, 유지방)에서 온 말입니다. 'leche desnatada(탈지유)', 'yogur desnatado(저지방 요거트)'처럼 씁니다. 지방이 조금 남은 것은 'semidesnatado'라고 합니다. 중남미에서는 'descremado'를 더 많이 씁니다.","x":["cremosos: '크림 같은, 부드러운'으로 오히려 지방이 많을 수 있습니다 ✗","aceitosos: '기름진'으로 지방이 많다는 뜻이라 반대입니다 ✗","desnatados: '탈지한'으로 지방을 줄인 식품입니다 → 정답 ✓","azucarados: '설탕이 든'으로 지방 함량과 관련이 없습니다 ✗"]},{"id":"V191","q":"Encontrar ese yacimiento fue un importante ____ arqueológico.","o":["alcance","invento","hallazgo","desenlace"],"a":2,"k":"발견 어휘","t":"그 유적지를 발견한 것은 중요한 고고학적 발견이었다.","e":"hallazgo는 '발견, 찾아낸 것'이라는 뜻으로 동사 hallar(찾다, 발견하다)에서 왔습니다. 땅속에 있던 유적(yacimiento)을 찾아낸 것이므로 hallazgo가 정답입니다. 'hallazgo arqueológico(고고학적 발견)'는 뉴스에서 자주 쓰는 표현입니다.","x":["alcance: '범위, 사정거리'로 발견을 뜻하지 않습니다 ✗","invento: '발명'으로 새로 만들어 낸 것이라 원래 있던 유적을 찾은 것과 다릅니다 ✗","hallazgo: '발견'으로 유적지를 찾아낸 일에 딱 맞습니다 → 정답 ✓","desenlace: '결말'로 이야기나 사건의 끝을 뜻합니다 ✗"]},{"id":"V192","q":"Que tenga un cochazo así siendo pobre es ____.","o":["incuestionable","lo lógico","sensato","un sinsentido"],"a":3,"k":"sinsentido","t":"가난한데 그런 고급차를 가지고 있다는 건 말이 안 된다.","e":"sinsentido는 '말도 안 되는 것, 터무니없는 일'이라는 뜻의 명사입니다(sin + sentido: 의미 없음). 가난한데 cochazo(아주 좋은 차, coche의 확대형)를 가졌다는 것은 모순이므로 sinsentido가 맞습니다. 'ser un sinsentido'처럼 관사 un과 함께 씁니다.","x":["incuestionable: '의심의 여지가 없는'으로 모순된 상황을 표현하지 않습니다 ✗","lo lógico: '당연한 것'으로 가난한데 고급차를 가진 상황과 반대입니다 ✗","sensato: '분별 있는, 합리적인'으로 모순된 상황과 맞지 않습니다 ✗","un sinsentido: '말도 안 되는 일'로 모순을 나타냅니다 → 정답 ✓"]},{"id":"V193","q":"No entiendo cómo puedes comerte eso. ¡Qué ____!","o":["asco","sabor","delicia","placer"],"a":0,"k":"감탄 표현","t":"어떻게 그걸 먹을 수 있는지 모르겠어. 정말 역겨워!","e":"'¡Qué asco!'는 '역겨워!, 더러워!'라는 뜻의 감탄 표현입니다. asco는 '혐오감, 구역질'입니다. 'No entiendo cómo puedes comerte eso(어떻게 그걸 먹니)'라는 앞 문장이 부정적인 반응임을 알려 줍니다. 'dar asco'는 '역겹게 하다'입니다. 예: Me dan asco las cucarachas. (바퀴벌레가 역겹다.)","x":["asco: '역겨움'으로 '¡Qué asco!(역겨워!)'라는 감탄 표현입니다 → 정답 ✓","sabor: '맛'으로 '¡Qué sabor!'는 긍정적이거나 중립적이라 문맥과 맞지 않습니다 ✗","delicia: '아주 맛있는 것, 기쁨'으로 긍정적이라 문맥과 반대입니다 ✗","placer: '즐거움'으로 긍정적이라 문맥과 반대입니다 ✗"]},{"id":"V194","q":"Aunque siempre hace papeles ____, adoro a esta actriz.","o":["secundarios","principales","protagonistas","centrales"],"a":0,"k":"영화·연극 어휘","t":"그녀는 항상 조연을 맡지만, 나는 이 여배우를 정말 좋아한다.","e":"'papel secundario'는 '조연'이라는 뜻입니다. 'Aunque(비록 ~이지만)'는 앞뒤가 서로 대조됨을 나타내므로, '좋아한다'와 대조되는 다소 아쉬운 내용, 즉 조연이 와야 합니다. '주연'은 'papel principal' 또는 'papel protagonista'입니다.","x":["secundarios: '조연의'로 aunque의 대조 의미와 맞습니다 → 정답 ✓","principales: '주요한(주연의)'으로 aunque와 함께 쓰면 대조가 생기지 않습니다 ✗","protagonistas: '주인공의'로 대조가 성립하지 않습니다 ✗","centrales: '중심의'로 대조가 성립하지 않으며 papel과 잘 쓰지 않습니다 ✗"]},{"id":"V195","q":"Nunca fui ____, por eso no terminé el bachillerato.","o":["estudioso","codicioso","habilidoso","meticuloso"],"a":0,"k":"성격 형용사","t":"나는 공부를 열심히 하는 편이 아니었어. 그래서 고등학교를 마치지 못했어.","e":"estudioso/a는 '공부를 좋아하는, 학구적인'이라는 뜻입니다. 고등학교(bachillerato)를 마치지 못한 이유로 '공부를 열심히 하지 않았다'가 가장 자연스럽습니다. bachillerato는 스페인에서 대학 입학 전 2년 과정(한국의 고등학교 2~3학년)에 해당합니다.","x":["estudioso: '학구적인'으로 학업을 마치지 못한 이유와 연결됩니다 → 정답 ✓","codicioso: '탐욕스러운'으로 학업과 관련이 없습니다 ✗","habilidoso: '솜씨 좋은, 손재주 있는'으로 학업 포기의 이유가 되지 않습니다 ✗","meticuloso: '꼼꼼한'으로 학업 포기의 이유로 잘 맞지 않습니다 ✗"]},{"id":"V196","q":"La adolescencia viene después de la ____.","o":["niñez","vejez","madurez","senectud"],"a":0,"k":"인생 단계 어휘","t":"사춘기는 유년기 다음에 온다.","e":"niñez는 '어린 시절, 유년기'로 niño(아이)에서 왔습니다. 인생의 단계는 niñez(유년기) → adolescencia(청소년기) → juventud(청년기) → madurez(장년기) → vejez(노년기) 순서입니다. 같은 뜻으로 'infancia'도 있습니다.","x":["niñez: '유년기'로 청소년기 바로 앞 단계입니다 → 정답 ✓","vejez: '노년기'로 인생의 마지막 단계입니다 ✗","madurez: '성숙기, 장년기'로 청소년기 이후입니다 ✗","senectud: '노년, 노쇠기'로 vejez와 비슷한 격식 있는 말입니다 ✗"]},{"id":"V197","q":"Deben ____ a todos los que fueron despedidos antes de que cumpliera su contrato.","o":["indemnizar","condecorar","premiar","cobrar"],"a":0,"k":"노동·법률 어휘","t":"계약 기간이 끝나기 전에 해고된 모든 사람에게 보상금을 지급해야 한다.","e":"indemnizar는 '(손해를) 배상하다, 보상금을 지급하다'라는 뜻입니다. 명사형은 indemnización(배상금, 해고 수당)입니다. 계약 만료 전에 해고된(despedidos) 사람들에게 회사가 해야 할 일은 보상금 지급입니다. 'antes de que + 접속법(cumpliera)'에 주의하세요.","x":["indemnizar: '보상금을 지급하다'로 부당하게 해고된 사람들에게 할 일입니다 → 정답 ✓","condecorar: '훈장을 수여하다'로 해고와 관련이 없습니다 ✗","premiar: '상을 주다'로 해고된 사람에게 하는 일이 아닙니다 ✗","cobrar: '(돈을) 받다, 청구하다'로 사람을 목적어로 하면 '~에게 돈을 받다'가 되어 반대입니다 ✗"]},{"id":"V198","q":"Adela es ____, aprendió italiano sin ningún tipo de ayuda.","o":["autóctona","autodidacta","automática","autosuficiente"],"a":1,"k":"auto- 합성어","t":"아델라는 독학한 사람이다. 아무 도움 없이 이탈리아어를 배웠다.","e":"autodidacta는 '독학하는 사람, 독학자'라는 뜻입니다. auto-(스스로) + didacta(가르치는 사람)로 이루어진 말로, 남녀 모두 -a로 끝나는 형태를 씁니다(un autodidacta, una autodidacta). 'sin ningún tipo de ayuda(아무 도움 없이)'가 힌트입니다.","x":["autóctona: '토착의, 그 지역 출신의'로 학습과 관련이 없습니다 ✗","autodidacta: '독학자'로 혼자 이탈리아어를 배운 상황에 맞습니다 → 정답 ✓","automática: '자동의'로 사람의 학습 방식을 나타내지 않습니다 ✗","autosuficiente: '자급자족하는, 혼자 다 해결하는'으로 학습에 특정된 말이 아닙니다 ✗"]},{"id":"V199","q":"Tengo que volver a mandar el correo electrónico porque olvidé el ____ adjunto.","o":["archivador","escrito","archivo","catálogo"],"a":2,"k":"IT 어휘","t":"첨부 파일을 깜빡해서 이메일을 다시 보내야 한다.","e":"'archivo adjunto'는 이메일의 '첨부 파일'입니다. archivo는 '파일, 기록 보관소'이고, adjunto는 '첨부된'이라는 뜻입니다. 예: Te envío el documento como archivo adjunto. (문서를 첨부 파일로 보낼게.) 중남미에서는 'el adjunto'라고만 하기도 합니다.","x":["archivador: '서류철, 파일 보관함'으로 실물 사무용품입니다 ✗","escrito: '글, 문서'로 'escrito adjunto'는 이메일 첨부 파일로 쓰지 않습니다 ✗","archivo: '파일'로 'archivo adjunto(첨부 파일)'라는 고정 표현입니다 → 정답 ✓","catálogo: '카탈로그, 목록'으로 문맥에 맞지 않습니다 ✗"]},{"id":"V200","q":"Al parecer, hay un nuevo ____ del virus en nuestra región.","o":["auge","comienzo","arranque","brote"],"a":3,"k":"질병 어휘","t":"듣자 하니 우리 지역에 바이러스가 새로 발생했다고 한다.","e":"brote는 원래 '싹, 새순'이라는 뜻이지만 질병에 쓰면 '(전염병의) 발생, 집단 발병'을 뜻합니다. 'brote de un virus', 'brote de gripe'처럼 뉴스에서 자주 씁니다. 'Al parecer'는 '듣자 하니, 보아하니'라는 뜻입니다.","x":["auge: '절정, 호황'으로 경제나 유행에 쓰며 바이러스 발생에는 쓰지 않습니다 ✗","comienzo: '시작'으로 바이러스와 짝을 이루는 표현이 아닙니다 ✗","arranque: '시동, 출발'로 바이러스 발생에 쓰지 않습니다 ✗","brote: '(전염병의) 발생'으로 'brote del virus'가 고정 표현입니다 → 정답 ✓"]},{"id":"V201","q":"Echa la leche y los cereales en el ____.","o":["frasco","plato","cuenco","vaso"],"a":2,"k":"식기 어휘","t":"우유와 시리얼을 그릇에 부어.","e":"cuenco는 국이나 시리얼을 담는 둥글고 오목한 '사발, 그릇(볼)'입니다. 우유와 시리얼을 함께 담기에 가장 알맞은 그릇입니다. 중남미에서는 'tazón' 또는 'bol'이라는 말도 많이 씁니다.","x":["frasco: '병, 유리병'으로 시리얼을 먹는 그릇이 아닙니다 ✗","plato: '접시'로 우유를 부으면 흘러넘치기 쉬워 부자연스럽습니다 ✗","cuenco: '사발, 볼'로 우유와 시리얼을 담기에 알맞습니다 → 정답 ✓","vaso: '컵'으로 음료를 마시는 용도이지 시리얼을 담지 않습니다 ✗"]},{"id":"V202","q":"Un buen gobierno debe tener una comunicación ____ con los partidos de la oposición.","o":["esporádica","eventual","fluida","deficiente"],"a":2,"k":"형용사 어휘","t":"좋은 정부는 야당과 원활한 소통을 해야 한다.","e":"fluido/a는 '유동적인, 막힘없는, 원활한'이라는 뜻으로 'comunicación fluida'는 '원활한 소통'입니다. 언어를 유창하게 할 때도 'hablar con fluidez'라고 합니다. 'Un buen gobierno debe~(좋은 정부는 ~해야 한다)'이므로 긍정적인 형용사가 와야 합니다.","x":["esporádica: '산발적인, 가끔 있는'으로 좋은 정부의 바람직한 소통이 아닙니다 ✗","eventual: '임시의, 우발적인'으로 바람직한 소통을 나타내지 않습니다 ✗","fluida: '원활한'으로 좋은 정부가 갖춰야 할 소통입니다 → 정답 ✓","deficiente: '부족한, 결함 있는'으로 부정적이라 문맥과 반대입니다 ✗"]},{"id":"V203","q":"La operación me dejó una ____ para toda la vida.","o":["cicatriz","señal","huella","llaga"],"a":0,"k":"신체·상처 어휘","t":"그 수술로 평생 남을 흉터가 생겼다.","e":"cicatriz는 상처가 아문 뒤 남는 '흉터'입니다. 수술(operación) 후 평생 남는(para toda la vida) 것이므로 cicatriz가 정답입니다. 동사 cicatrizar는 '(상처가) 아물다'라는 뜻입니다. 참고로 cicatriz의 복수형은 z가 c로 바뀌어 cicatrices입니다.","x":["cicatriz: '흉터'로 수술 후 평생 남는 자국입니다 → 정답 ✓","señal: '표시, 신호'로 너무 일반적이라 수술 자국을 정확히 나타내지 못합니다 ✗","huella: '발자국, 지문, 흔적'으로 피부에 남는 수술 자국을 말하지 않습니다 ✗","llaga: '궤양, 헌 데'로 아직 낫지 않은 상처라 평생 남는 자국이 아닙니다 ✗"]},{"id":"V204","q":"La mujer de mi hijo es mi ____.","o":["cuñada","sobrina","nuera","nieta"],"a":2,"k":"가족 어휘","t":"내 아들의 아내는 내 며느리이다.","e":"nuera는 '며느리'이고, 사위는 yerno입니다. 시부모·장인장모는 suegro/suegra, 처남·시누이 등 배우자의 형제자매는 cuñado/cuñada라고 합니다. 가족 관계 어휘는 함께 묶어 외우면 편합니다.","x":["cuñada: '시누이, 올케, 처제 등 배우자의 자매'로 아들의 아내가 아닙니다 ✗","sobrina: '조카딸'로 아들의 아내가 아닙니다 ✗","nuera: '며느리'로 아들의 아내입니다 → 정답 ✓","nieta: '손녀'로 아들의 딸이지 아내가 아닙니다 ✗"]},{"id":"V205","q":"Ernesto es ____ porque su madre es española y su padre alemán.","o":["bilingüe","monolingüe","polifacético","monótono"],"a":0,"k":"언어 어휘","t":"에르네스토는 어머니가 스페인 사람이고 아버지가 독일 사람이라서 2개 국어를 한다.","e":"bilingüe는 '2개 국어를 하는'이라는 뜻입니다. bi-(둘) + lingüe(언어)로 이루어져 있으며 ü 위의 점(diéresis)은 u를 발음하라는 표시입니다. 부모가 서로 다른 언어를 쓰므로 두 언어를 한다는 결론이 자연스럽습니다. 세 언어 이상은 'trilingüe', 'políglota'라고 합니다.","x":["bilingüe: '2개 국어를 하는'으로 부모의 국적이 다른 상황에 맞습니다 → 정답 ✓","monolingüe: '한 언어만 하는'으로 문맥과 반대입니다 ✗","polifacético: '다재다능한'으로 언어 능력에 특정된 말이 아닙니다 ✗","monótono: '단조로운'으로 문맥과 관련이 없습니다 ✗"]},{"id":"V206","q":"La ____ no tiene tinta, así que no podemos usarla.","o":["impresora","grapadora","perforadora","grabadora"],"a":0,"k":"사무용품 어휘","t":"프린터에 잉크가 없어서 쓸 수 없다.","e":"impresora는 '프린터'로 동사 imprimir(인쇄하다)에서 왔습니다. 잉크(tinta)가 필요한 기계는 프린터입니다. 이처럼 -dora/-ora로 끝나는 기계 이름이 많습니다. 예: lavadora(세탁기), grapadora(스테이플러).","x":["impresora: '프린터'로 잉크가 필요한 기계입니다 → 정답 ✓","grapadora: '스테이플러'로 잉크가 필요 없습니다 ✗","perforadora: '펀치(구멍 뚫는 기구)'로 잉크가 필요 없습니다 ✗","grabadora: '녹음기'로 잉크가 필요 없습니다 ✗"]},{"id":"V207","q":"Necesito un ____ para quitarle el tapón a la botella.","o":["tirachinas","abrelatas","sacacorchos","pararrayos"],"a":2,"k":"합성어 도구","t":"병마개를 빼려면 코르크 따개가 필요해.","e":"sacacorchos는 '코르크 따개, 와인 오프너'로 sacar(빼다) + corchos(코르크 마개들)로 만들어진 합성어입니다. 이런 '동사 + 복수 명사' 합성어는 단수·복수 형태가 같습니다(un sacacorchos). 병의 마개(tapón)를 빼는 도구이므로 정답입니다.","x":["tirachinas: '새총'(tirar 던지다 + chinas 돌멩이)으로 병과 관련이 없습니다 ✗","abrelatas: '깡통 따개'(abrir + latas)로 병마개가 아니라 캔을 엽니다 ✗","sacacorchos: '코르크 따개'로 병마개를 빼는 도구입니다 → 정답 ✓","pararrayos: '피뢰침'(parar + rayos)으로 병과 관련이 없습니다 ✗"]},{"id":"V208","q":"Dile al pintor que te haga un ____ para pintar la casa. Así sabrás cuánto te costará con antelación.","o":["presupuesto","impreso","manual","cálculo"],"a":0,"k":"비용 어휘","t":"페인트공에게 집 칠하는 견적서를 달라고 해. 그러면 비용이 얼마나 들지 미리 알 수 있을 거야.","e":"presupuesto는 '예산' 또는 '견적(서)'이라는 뜻입니다. 'hacer un presupuesto'는 '견적을 내다'이며, 일을 시작하기 전에 비용을 미리 알려 주는 문서를 말합니다. 'con antelación(미리)'이 힌트입니다. 'Dile que te haga'처럼 명령·요청을 전할 때는 접속법을 씁니다.","x":["presupuesto: '견적서'로 비용을 미리 알려 주는 문서입니다 → 정답 ✓","impreso: '서식, 인쇄물'로 비용을 알려 주는 문서가 아닙니다 ✗","manual: '설명서, 교재'로 문맥에 맞지 않습니다 ✗","cálculo: '계산'으로 뜻은 비슷하지만 공식 견적 문서를 가리키지 않습니다 ✗"]},{"id":"V209","q":"Lo primero que haré para arreglar el jardín es cortar la hierba con el ____.","o":["cortaúñas","quitanieves","quitamanchas","cortacésped"],"a":3,"k":"합성어 도구","t":"정원을 손질하기 위해 가장 먼저 할 일은 잔디 깎는 기계로 풀을 베는 것이다.","e":"cortacésped는 '잔디 깎는 기계'로 cortar(자르다) + césped(잔디)로 만들어진 합성어입니다. 정원(jardín)의 풀(hierba)을 자르는 도구이므로 정답입니다. 중남미에서는 'cortadora de césped' 또는 'podadora'라고도 합니다.","x":["cortaúñas: '손톱깎이'로 풀을 깎는 도구가 아닙니다 ✗","quitanieves: '제설기'로 눈을 치우는 기계입니다 ✗","quitamanchas: '얼룩 제거제'로 풀과 관련이 없습니다 ✗","cortacésped: '잔디 깎는 기계'로 정원 풀을 베는 도구입니다 → 정답 ✓"]},{"id":"V210","q":"Antes vivían en un pequeño apartamento, en cambio ahora viven en un ____ con jardín y piscina.","o":["cuchitril","antro","establecimiento","chalé"],"a":3,"k":"주거 어휘","t":"예전에는 작은 아파트에 살았는데, 지금은 정원과 수영장이 있는 단독 주택에 산다.","e":"chalé(또는 chalet)는 정원이 딸린 '단독 주택, 별장식 주택'입니다. 'en cambio(반면에)'는 앞의 '작은 아파트'와 대조되는 크고 좋은 집이 와야 함을 알려 줍니다. 'con jardín y piscina'가 결정적인 힌트입니다.","x":["cuchitril: '좁고 지저분한 방, 쪽방'으로 정원과 수영장과 맞지 않습니다 ✗","antro: '질 나쁜 술집, 소굴'로 사는 집이 아닙니다 ✗","establecimiento: '시설, 가게, 업소'로 사는 집이 아닙니다 ✗","chalé: '정원 딸린 단독 주택'으로 문맥에 맞습니다 → 정답 ✓"]},{"id":"V211","q":"Ve al ____ a por sellos y sobres, por favor.","o":["banco","ayuntamiento","estanco","supermercado"],"a":2,"k":"스페인 상점 어휘","t":"우표와 봉투를 사러 담배 가게에 좀 다녀와 줘.","e":"estanco는 스페인 특유의 '담배 가게'로, 담배뿐 아니라 우표(sellos)와 봉투, 각종 공식 서식 등을 판매합니다. 스페인 문화와 관련된 어휘라 중남미에서는 잘 쓰지 않습니다. 'ir a por algo'는 스페인 구어로 '~을 가지러/사러 가다'입니다.","x":["banco: '은행'으로 우표를 팔지 않습니다 ✗","ayuntamiento: '시청'으로 우표와 봉투를 사는 곳이 아닙니다 ✗","estanco: '담배 가게'로 스페인에서 우표와 봉투를 파는 곳입니다 → 정답 ✓","supermercado: '슈퍼마켓'으로 일반적으로 우표를 팔지 않습니다 ✗"]},{"id":"V212","q":"No tiene ____, le da igual lo que le pase a los demás.","o":["apatía","sensibilidad","crueldad","brutalidad"],"a":1,"k":"감정·성격 명사","t":"그는 감수성이 없어서 다른 사람들에게 무슨 일이 생기든 상관하지 않는다.","e":"sensibilidad는 '감수성, 감성, 남의 감정을 헤아리는 능력'이라는 뜻입니다. 'No tiene sensibilidad'는 '공감 능력이 없다, 무정하다'는 의미가 되어 '남에게 무슨 일이 생겨도 상관없다'는 설명과 일치합니다. 'darle igual algo a alguien'은 '~에게 ~가 상관없다'입니다.","x":["apatía: '무관심, 무기력'으로 'no tiene apatía'는 오히려 관심이 있다는 뜻이 되어 반대입니다 ✗","sensibilidad: '감수성, 공감 능력'으로 'no tiene'와 함께 무정함을 나타냅니다 → 정답 ✓","crueldad: '잔인함'으로 'no tiene crueldad'는 잔인하지 않다는 뜻이라 반대입니다 ✗","brutalidad: '잔혹함, 야만성'으로 'no tiene'와 함께 쓰면 문맥과 반대입니다 ✗"]},{"id":"V213","q":"No te preocupes, es una ____ formalidad.","o":["mera","compleja","ardua","intrincada"],"a":0,"k":"mero 형용사","t":"걱정하지 마, 그건 단순한 형식적인 절차일 뿐이야.","e":"mero/a는 명사 앞에 쓰여 '단순한, 그저 ~에 불과한'이라는 뜻을 나타냅니다. 'una mera formalidad'는 '그저 형식적인 절차일 뿐'이라는 자주 쓰는 표현입니다. 'No te preocupes(걱정하지 마)'가 별일 아니라는 힌트입니다. 예: Fue una mera coincidencia. (그저 우연일 뿐이었다.)","x":["mera: '단순한, ~에 불과한'으로 걱정할 필요 없다는 문맥에 맞습니다 → 정답 ✓","compleja: '복잡한'으로 걱정하지 말라는 말과 맞지 않습니다 ✗","ardua: '힘든, 고된'으로 걱정하지 말라는 말과 맞지 않습니다 ✗","intrincada: '뒤얽힌, 복잡한'으로 걱정하지 말라는 말과 맞지 않습니다 ✗"]},{"id":"V214","q":"Los ____ protestaron por las calles de la capital durante horas.","o":["manifestantes","viandantes","caminantes","transeúntes"],"a":0,"k":"사회 어휘","t":"시위대가 수도의 거리에서 몇 시간 동안 시위를 했다.","e":"manifestante는 '시위 참가자'로 동사 manifestarse(시위하다)에서 왔습니다. 'protestaron(항의했다)'과 함께 쓰이므로 시위대가 정답입니다. 나머지 보기는 모두 '길을 걸어가는 사람'을 뜻해 항의와 관련이 없습니다. 명사 manifestación은 '시위'입니다.","x":["manifestantes: '시위대'로 거리에서 항의하는 사람들입니다 → 정답 ✓","viandantes: '행인, 보행자'로 항의와 관련이 없습니다 ✗","caminantes: '걷는 사람, 나그네'로 항의와 관련이 없습니다 ✗","transeúntes: '행인, 지나가는 사람'으로 항의와 관련이 없습니다 ✗"]},{"id":"V215","q":"El turismo ____ tiene consecuencias negativas sobre el medio ambiente.","o":["pasivo","colectivo","masivo","ecológico"],"a":2,"k":"관광 어휘","t":"대규모 관광은 환경에 부정적인 영향을 미친다.","e":"masivo/a는 '대량의, 대규모의'라는 뜻으로 'turismo masivo'는 사람들이 한꺼번에 몰리는 '대중 관광, 과잉 관광'입니다. 환경에 부정적인 결과(consecuencias negativas)를 가져오는 원인으로 가장 알맞습니다. 비슷한 말로 'turismo de masas'가 있습니다.","x":["pasivo: '수동적인'으로 관광과 짝을 이루어 환경 문제를 나타내지 않습니다 ✗","colectivo: '단체의'로 환경에 해롭다는 의미가 분명하지 않습니다 ✗","masivo: '대규모의'로 환경을 해치는 관광을 나타냅니다 → 정답 ✓","ecológico: '생태적인, 친환경의'로 환경에 해롭다는 말과 반대입니다 ✗"]},{"id":"V216","q":"Los ____ se ocupan de la salud de los niños.","o":["anestesistas","cirujanos","traumatólogos","pediatras"],"a":3,"k":"의료 직업 어휘","t":"소아과 의사들은 아이들의 건강을 돌본다.","e":"pediatra는 '소아과 의사'입니다. 그리스어 어원 pedi-(아이)가 들어 있습니다. -a로 끝나지만 남녀 모두에 쓰는 명사입니다(el/la pediatra). 'ocuparse de'는 '~을 맡다, 돌보다'라는 뜻입니다.","x":["anestesistas: '마취과 의사'로 아이들 건강 전반을 돌보지 않습니다 ✗","cirujanos: '외과 의사'로 수술을 하는 의사입니다 ✗","traumatólogos: '정형외과 의사'로 뼈·관절 부상을 다룹니다 ✗","pediatras: '소아과 의사'로 아이들의 건강을 돌봅니다 → 정답 ✓"]},{"id":"V217","q":"El texto que has escrito es demasiado ____, tienes que acortarlo.","o":["breve","conciso","extenso","escueto"],"a":2,"k":"글의 길이 어휘","t":"네가 쓴 글은 너무 길어, 줄여야 해.","e":"extenso/a는 '긴, 광범위한'이라는 뜻으로 글에 쓰면 '분량이 많은'입니다. 'tienes que acortarlo(줄여야 한다)'라고 했으므로 너무 긴 글이라는 뜻의 extenso가 맞습니다. 나머지 세 보기는 모두 '짧은, 간결한'이라는 반대 의미입니다.","x":["breve: '짧은'으로 줄여야 한다는 말과 모순됩니다 ✗","conciso: '간결한'으로 줄여야 한다는 말과 모순됩니다 ✗","extenso: '긴, 분량이 많은'으로 줄여야 하는 이유가 됩니다 → 정답 ✓","escueto: '간결한, 군더더기 없는'으로 문맥과 반대입니다 ✗"]},{"id":"V218","q":"Tengo un dolor de muelas ____, tengo que ir al dentista hoy mismo.","o":["admirable","insoportable","sorprendente","excepcional"],"a":1,"k":"통증 형용사","t":"어금니가 참을 수 없을 만큼 아파서 오늘 당장 치과에 가야 해.","e":"insoportable는 '참을 수 없는, 견딜 수 없는'이라는 뜻입니다(in- 부정 + soportar 견디다). 'hoy mismo(오늘 당장)' 치과에 가야 할 만큼 심한 통증이므로 정답입니다. 'dolor de muelas'는 '치통(어금니 통증)'으로 자주 쓰는 표현입니다.","x":["admirable: '감탄할 만한'으로 통증에 쓰지 않습니다 ✗","insoportable: '참을 수 없는'으로 당장 치과에 가야 할 이유가 됩니다 → 정답 ✓","sorprendente: '놀라운'으로 통증의 정도를 나타내는 데 부자연스럽습니다 ✗","excepcional: '예외적인, 뛰어난'으로 긍정적인 뉘앙스라 통증에 맞지 않습니다 ✗"]},{"id":"V219","q":"Tengo calambres en las piernas por mis problemas de ____.","o":["comunicación","transición","tráfico","circulación"],"a":3,"k":"의료 어휘","t":"나는 혈액순환 문제 때문에 다리에 쥐가 난다.","e":"circulación은 '순환'이라는 뜻으로 의학적으로는 '혈액순환(circulación sanguínea)'을 말합니다. 'calambres(쥐, 경련)'의 원인으로 혈액순환 문제가 적절합니다. circulación은 '교통, 차량 통행'이라는 뜻도 있지만 여기서는 몸과 관련된 의미입니다.","x":["comunicación: '의사소통'으로 다리 경련의 원인이 아닙니다 ✗","transición: '전환, 과도기'로 몸의 문제와 관련이 없습니다 ✗","tráfico: '교통'으로 신체 문제와 관련이 없습니다 ✗","circulación: '(혈액) 순환'으로 다리 경련의 원인이 됩니다 → 정답 ✓"]},{"id":"V220","q":"Con el ____ que gano, no puedo llegar fácilmente a final de mes.","o":["sueldo","saldo","beneficio","premio"],"a":0,"k":"돈 어휘","t":"내가 버는 월급으로는 월말까지 버티기가 쉽지 않다.","e":"sueldo는 '월급, 급여'입니다. 'ganar(벌다)'와 함께 쓰여 일해서 받는 돈을 뜻합니다. 'llegar a final de mes'는 '월말까지 (돈이) 버티다'라는 관용 표현으로, 돈이 빠듯하다는 뜻입니다. 비슷한 말로 salario가 있습니다.","x":["sueldo: '월급'으로 일해서 버는 돈입니다 → 정답 ✓","saldo: '(계좌) 잔액'으로 버는 돈이 아닙니다 ✗","beneficio: '이익, 혜택'으로 회사의 수익에 주로 쓰며 개인 급여가 아닙니다 ✗","premio: '상, 상금'으로 정기적으로 버는 돈이 아닙니다 ✗"]},{"id":"V221","q":"Lo siento, no puedo quedar hoy contigo porque tengo un ____ familiar.","o":["pacto","contrato","acuerdo","compromiso"],"a":3,"k":"약속 어휘","t":"미안, 오늘은 가족 일정이 있어서 너랑 만날 수 없어.","e":"compromiso는 '약속, 의무, 해야 할 일정'이라는 뜻입니다. 'tener un compromiso'는 '선약이 있다, 빠질 수 없는 일이 있다'로 거절할 때 자주 씁니다. 'quedar con alguien'은 '~와 만날 약속을 하다'입니다. compromiso는 '약혼'이라는 뜻도 있습니다.","x":["pacto: '협정, 맹약'으로 일상 일정에 쓰지 않습니다 ✗","contrato: '계약'으로 가족 일정과 맞지 않습니다 ✗","acuerdo: '합의'로 만날 수 없는 이유가 되는 일정이 아닙니다 ✗","compromiso: '(빠질 수 없는) 약속, 일정'으로 문맥에 맞습니다 → 정답 ✓"]},{"id":"V222","q":"Marcelo tiene la ____ por los suelos desde que lo dejó su última novia.","o":["autocrítica","autonomía","autodefensa","autoestima"],"a":3,"k":"auto- 합성어","t":"마르셀로는 마지막 여자친구에게 차인 뒤로 자존감이 바닥이다.","e":"autoestima는 '자존감'(auto- 자기 + estima 존중)입니다. 'tener la autoestima por los suelos'는 '자존감이 바닥이다'라는 자주 쓰는 표현이고, 'estar por los suelos'는 '바닥에 떨어지다, 최악이다'라는 관용구입니다. 실연 후 겪는 상태로 자연스럽습니다.","x":["autocrítica: '자기비판'으로 '바닥이다'라는 표현과 어울리지 않습니다 ✗","autonomía: '자율성'으로 실연과 관련이 약합니다 ✗","autodefensa: '자기방어'로 문맥과 관련이 없습니다 ✗","autoestima: '자존감'으로 'por los suelos'와 함께 자주 씁니다 → 정답 ✓"]},{"id":"V223","q":"No he hecho nada. ¡Soy ____!","o":["tolerante","inocente","indulgente","clemente"],"a":1,"k":"법률·성격 어휘","t":"나는 아무것도 안 했어. 나는 결백해!","e":"inocente는 '결백한, 죄가 없는'이라는 뜻입니다. 'No he hecho nada(아무것도 안 했다)'라고 했으므로 자신이 죄가 없다고 주장하는 것입니다. inocente는 '순진한'이라는 뜻도 있습니다. 반대말은 culpable(유죄의)입니다.","x":["tolerante: '관대한, 너그러운'으로 결백을 주장하는 말이 아닙니다 ✗","inocente: '결백한'으로 아무것도 안 했다는 주장과 맞습니다 → 정답 ✓","indulgente: '관대한, 너그럽게 용서하는'으로 문맥에 맞지 않습니다 ✗","clemente: '자비로운'으로 결백과 관련이 없습니다 ✗"]},{"id":"V224","q":"Necesito una balanza de gran ____, no una que no refleje el peso exacto.","o":["precisión","sencillez","claridad","determinación"],"a":0,"k":"정확성 어휘","t":"정확한 무게를 보여 주지 못하는 저울이 아니라 정밀도가 높은 저울이 필요하다.","e":"precisión은 '정밀성, 정확성'으로 'de gran precisión'은 '정밀도가 높은'이라는 뜻입니다. 뒤 문장 'no una que no refleje el peso exacto(정확한 무게를 반영하지 않는 것 말고)'가 힌트입니다. 형용사는 preciso/a(정확한)입니다.","x":["precisión: '정밀도'로 정확한 무게를 재는 저울에 맞습니다 → 정답 ✓","sencillez: '단순함'으로 정확한 무게와 관련이 없습니다 ✗","claridad: '명확함, 밝음'으로 저울의 성능을 나타내기에 부적절합니다 ✗","determinación: '결단력, 결정'으로 저울과 관련이 없습니다 ✗"]},{"id":"V225","q":"La boda fue privada a ____ de los novios.","o":["razón","petición","juicio","pedido"],"a":1,"k":"a petición de","t":"결혼식은 신랑 신부의 요청에 따라 비공개로 진행되었다.","e":"'a petición de alguien'은 '~의 요청에 따라'라는 고정 표현입니다. petición은 '요청, 청원'입니다. 예: Se cambió la fecha a petición del cliente. (고객의 요청으로 날짜가 변경되었다.) 비슷한 표현으로 'a pedido de'가 중남미에서 쓰입니다.","x":["razón: '이유'로 'a razón de'는 '~의 비율로'라는 다른 뜻입니다 ✗","petición: '요청'으로 'a petición de(~의 요청으로)'라는 고정 표현입니다 → 정답 ✓","juicio: '판단, 재판'으로 'a juicio de'는 '~의 견해로는'이라는 뜻입니다 ✗","pedido: '주문'으로 스페인에서는 'a petición de'를 쓰며, 'a pedido de'는 중남미 표현입니다 ✗"]},{"id":"V226","q":"Se han ____ todas las entradas para el concierto. ¡Qué pena!","o":["liquidado","exportado","entregado","agotado"],"a":3,"k":"agotarse 동사","t":"콘서트 표가 모두 매진되었어. 정말 아쉽다!","e":"agotarse는 '다 떨어지다, 매진되다'라는 뜻입니다. 'Se han agotado las entradas'는 '표가 매진되었다'라는 표현입니다. 형용사로 'agotado'는 '매진된, 품절된' 또는 사람에게 '녹초가 된'이라는 뜻입니다. 예: Este libro está agotado. (이 책은 품절이다.)","x":["liquidado: '청산된, 떨이 판매된'으로 표 매진에 쓰지 않습니다 ✗","exportado: '수출된'으로 표와 관련이 없습니다 ✗","entregado: '전달된'으로 '¡Qué pena!(아쉽다)'라는 반응과 맞지 않습니다 ✗","agotado: '매진된'으로 표를 살 수 없어 아쉬운 상황에 맞습니다 → 정답 ✓"]},{"id":"V227","q":"Sigue una dieta de adelgazamiento y ahora está como un ____.","o":["tallarín","fideo","macarrón","espagueti"],"a":1,"k":"비유 표현","t":"다이어트를 하더니 지금은 국수 가락처럼 말랐다.","e":"'estar como un fideo'(직역: 국수 같다)는 '아주 말랐다, 비쩍 말랐다'라는 관용 표현입니다. fideo는 '가는 국수'입니다. 다이어트(dieta de adelgazamiento) 결과 매우 날씬해졌다는 뜻입니다. 비슷한 표현으로 'estar en los huesos(뼈만 남다)'가 있습니다.","x":["tallarín: '칼국수 같은 넓은 면'으로 이 관용 표현에 쓰지 않습니다 ✗","fideo: '가는 국수'로 'estar como un fideo(비쩍 말랐다)'라는 관용 표현입니다 → 정답 ✓","macarrón: '마카로니'로 마른 몸을 비유하지 않습니다 ✗","espagueti: '스파게티'로 가늘지만 관용 표현으로는 fideo를 씁니다 ✗"]},{"id":"V228","q":"No soporto tener vello corporal, así que ____ constantemente.","o":["me enjuago","me peino","me bronceo","me depilo"],"a":3,"k":"재귀동사 미용","t":"나는 몸에 털이 있는 걸 못 참아서 자주 제모를 한다.","e":"depilarse는 '(자기 몸의) 털을 제거하다, 제모하다'라는 재귀동사입니다. 'vello corporal(체모)'을 못 참는다고 했으므로 depilarse가 정답입니다. 명사형은 depilación(제모)입니다. 재귀동사는 자기 자신에게 하는 행동을 나타냅니다.","x":["me enjuago: '헹구다'로 체모와 관련이 없습니다 ✗","me peino: '머리를 빗다'로 체모 제거가 아닙니다 ✗","me bronceo: '피부를 태우다'로 체모와 관련이 없습니다 ✗","me depilo: '제모하다'로 체모를 없애는 행동입니다 → 정답 ✓"]},{"id":"V229","q":"Acatar las reglas es una de las normas del juego ____.","o":["sucio","limpio","justo","claro"],"a":1,"k":"juego limpio","t":"규칙을 지키는 것은 페어플레이의 기본 규범 중 하나이다.","e":"'juego limpio'(직역: 깨끗한 경기)는 '페어플레이, 정정당당한 경기'라는 뜻입니다. 반대말 'juego sucio'는 '반칙, 비열한 수법'입니다. acatar는 '(규칙·명령을) 따르다, 준수하다'입니다.","x":["sucio: '더러운'으로 'juego sucio'는 반칙이라 규칙 준수와 반대입니다 ✗","limpio: '깨끗한'으로 'juego limpio(페어플레이)'라는 고정 표현입니다 → 정답 ✓","justo: '공정한'으로 의미는 비슷하지만 'juego justo'는 고정 표현이 아닙니다 ✗","claro: '분명한'으로 'juego'와 짝을 이루어 페어플레이를 뜻하지 않습니다 ✗"]},{"id":"V230","q":"Se siente ____ debido a la traición de su mejor amigo.","o":["calmado","afortunado","complacido","dolido"],"a":3,"k":"감정 형용사","t":"그는 가장 친한 친구의 배신 때문에 마음에 상처를 입었다.","e":"dolido/a는 '마음이 아픈, 상처받은'으로 doler(아프다)에서 왔습니다. 친구의 배신(traición) 때문에 느끼는 감정으로 가장 알맞습니다. 'sentirse + 형용사'는 '~하게 느끼다'입니다. 예: Está dolida por lo que le dijiste. (그녀는 네가 한 말에 상처받았다.)","x":["calmado: '침착한'으로 배신당한 감정이 아닙니다 ✗","afortunado: '운이 좋은'으로 배신과 반대되는 감정입니다 ✗","complacido: '만족한, 기쁜'으로 배신당한 감정과 반대입니다 ✗","dolido: '상처받은'으로 배신당한 사람의 감정입니다 → 정답 ✓"]},{"id":"V231","q":"Nadie merece vivir en ____.","o":["un palacete","un departamento","una covacha","un ático"],"a":2,"k":"주거 어휘","t":"누구도 오두막 같은 판잣집에 살아서는 안 된다.","e":"covacha는 '작은 동굴' 또는 '누추하고 비좁은 집, 판잣집'을 뜻합니다. 'Nadie merece vivir en~(아무도 ~에서 살 만하지 않다)'이라는 말은 살기 나쁜 곳을 가리키므로 covacha가 정답입니다. 비슷한 말로 chabola(스페인의 판자촌 집), cuchitril(쪽방)이 있습니다.","x":["un palacete: '작은 궁전, 저택'으로 좋은 집이라 문맥과 반대입니다 ✗","un departamento: 중남미에서 '아파트'를 뜻하는 말로 살기 나쁜 곳이 아닙니다 ✗","una covacha: '누추한 판잣집'으로 아무도 살아서는 안 될 곳입니다 → 정답 ✓","un ático: '꼭대기 층 집(펜트하우스)'으로 오히려 좋은 집입니다 ✗"]},{"id":"V232","q":"Necesitan ____ fuerzas después del maratón.","o":["recomponer","componer","reponer","rehacer"],"a":2,"k":"reponer fuerzas","t":"마라톤을 마친 뒤에는 기운을 회복해야 한다.","e":"'reponer fuerzas'는 '기력을 회복하다, 원기를 되찾다'라는 고정 표현입니다. reponer는 '다시 채우다, 보충하다'라는 뜻입니다. 예: Comimos algo para reponer fuerzas. (기운을 차리려고 뭘 좀 먹었다.) 비슷한 표현으로 'recuperar fuerzas'가 있습니다.","x":["recomponer: '다시 조립하다, 수리하다'로 'fuerzas'와 짝을 이루지 않습니다 ✗","componer: '구성하다, 작곡하다'로 문맥에 맞지 않습니다 ✗","reponer: '보충하다'로 'reponer fuerzas(기운을 되찾다)'라는 고정 표현입니다 → 정답 ✓","rehacer: '다시 하다'로 'fuerzas'와 함께 쓰지 않습니다 ✗"]},{"id":"V233","q":"Es imposible razonar con él, es demasiado ____.","o":["complaciente","sumiso","obediente","cabezota"],"a":3,"k":"성격 형용사","t":"그와는 이성적으로 얘기하는 게 불가능해, 너무 고집이 세.","e":"cabezota는 '고집 센, 황소고집인'이라는 구어 표현으로 cabeza(머리)에서 왔습니다. 남녀 모두 같은 형태를 씁니다. 'razonar con él(그와 이성적으로 대화하다)'이 불가능한 이유로 가장 알맞습니다. 비슷한 말로 terco, testarudo가 있습니다.","x":["complaciente: '남의 뜻을 잘 맞춰 주는'으로 대화가 어려운 이유가 아닙니다 ✗","sumiso: '순종적인'으로 문맥과 반대입니다 ✗","obediente: '말을 잘 듣는'으로 문맥과 반대입니다 ✗","cabezota: '고집 센'으로 설득하기 어려운 이유가 됩니다 → 정답 ✓"]},{"id":"V234","q":"____ que la gente grite cuando habla por teléfono, es que no lo soporto.","o":["Detesto","Adoro","Estimo","Me encanta"],"a":0,"k":"감정 동사","t":"사람들이 전화할 때 소리 지르는 게 정말 싫어, 도저히 못 참겠어.","e":"detestar는 '몹시 싫어하다, 혐오하다'라는 뜻입니다. 'no lo soporto(못 참겠다)'가 강한 부정적 감정을 보여 줍니다. 감정 동사 뒤에 'que + 다른 주어'가 오면 접속법을 쓰므로 'que la gente grite'가 됩니다. 비슷한 말로 odiar가 있습니다.","x":["Detesto: '몹시 싫어하다'로 못 참겠다는 말과 맞습니다 → 정답 ✓","Adoro: '아주 좋아하다'로 문맥과 반대입니다 ✗","Estimo: '존경하다, 평가하다'로 문맥과 맞지 않습니다 ✗","Me encanta: '아주 좋아하다'로 문맥과 반대입니다 ✗"]},{"id":"V235","q":"Las primeras ____ de Mafalda aparecieron en una revista.","o":["historietas","melodías","leyendas","telenovelas"],"a":0,"k":"만화 어휘","t":"마팔다의 첫 만화는 한 잡지에 실렸다.","e":"historieta는 '만화(연재 만화), 짧은 이야기'입니다. 마팔다(Mafalda)는 아르헨티나 만화가 키노(Quino)가 그린 유명한 연재 만화의 주인공입니다. 만화를 뜻하는 말로 cómic, tebeo(스페인), tira cómica도 있습니다.","x":["historietas: '만화'로 마팔다 작품을 가리킵니다 → 정답 ✓","melodías: '멜로디'로 잡지에 실리는 것이 아닙니다 ✗","leyendas: '전설'로 마팔다와 관련이 없습니다 ✗","telenovelas: 'TV 연속극'으로 잡지에 실리지 않습니다 ✗"]},{"id":"V236","q":"No es momento de ____ abajo, tenemos que intentar ganar a nuestro rival.","o":["ponerse","venirse","perderse","echarse"],"a":1,"k":"venirse abajo","t":"지금은 기죽을 때가 아니야, 상대를 이기도록 노력해야 해.","e":"'venirse abajo'는 '무너지다' 또는 '(사람이) 기가 꺾이다, 낙담하다'라는 관용 표현입니다. 예: Cuando perdió el trabajo, se vino abajo. (그는 일자리를 잃었을 때 무너졌다.) 'No es momento de~(~할 때가 아니다)' 뒤에 오므로 포기하지 말라는 뜻입니다.","x":["ponerse: 'ponerse abajo'라는 관용 표현은 없습니다 ✗","venirse: 'venirse abajo(기가 꺾이다)'라는 관용 표현입니다 → 정답 ✓","perderse: '길을 잃다'로 'abajo'와 관용 표현을 이루지 않습니다 ✗","echarse: 'echarse abajo'는 쓰지 않으며 'echarse atrás(물러서다)'가 다른 표현입니다 ✗"]},{"id":"V237","q":"No soy una persona ____, me encanta tener compañía.","o":["comunicativa","solitaria","parlanchina","sociable"],"a":1,"k":"성격 형용사","t":"나는 혼자 있는 걸 좋아하는 사람이 아니야, 사람들과 함께 있는 게 정말 좋아.","e":"solitario/a는 '혼자 있기를 좋아하는, 고독한'이라는 뜻입니다. 'No soy una persona ~'라고 부정한 뒤 '함께 있는 걸 좋아한다'고 했으므로, 부정되는 성격은 그 반대인 solitaria여야 합니다. 나머지는 모두 사람과 어울리기 좋아하는 성격이라 부정하면 모순입니다.","x":["comunicativa: '말하기 좋아하는'으로 부정하면 뒤 문장과 모순됩니다 ✗","solitaria: '혼자 있기 좋아하는'으로 부정하면 문맥에 맞습니다 → 정답 ✓","parlanchina: '수다스러운'으로 부정하면 뒤 문장과 맞지 않습니다 ✗","sociable: '사교적인'으로 부정하면 뒤 문장과 모순됩니다 ✗"]},{"id":"V238","q":"____ emocional es muy normal en la adolescencia.","o":["El desorden","El lío","La confusión","El alboroto"],"a":2,"k":"감정 명사","t":"정서적 혼란은 사춘기에 아주 흔한 일이다.","e":"'confusión emocional'은 '감정적 혼란'이라는 뜻으로 심리학 분야에서 자주 쓰는 표현입니다. confusión은 '혼란, 헷갈림'으로 마음이나 생각이 정리되지 않은 상태를 말합니다. 사춘기의 불안정한 감정을 설명하기에 알맞습니다.","x":["El desorden: '무질서, 어지러움'으로 주로 방이나 물건 상태에 씁니다 ✗","El lío: '엉망, 골칫거리'라는 구어로 'emocional'과 잘 쓰지 않습니다 ✗","La confusión: '혼란'으로 'confusión emocional'이 자연스러운 짝입니다 → 정답 ✓","El alboroto: '소동, 떠들썩함'으로 감정 상태를 나타내지 않습니다 ✗"]},{"id":"V239","q":"El soneto es una composición poética que tiene catorce ____.","o":["versos","rayas","renglones","líneas"],"a":0,"k":"문학 어휘","t":"소네트는 14행으로 된 시의 형식이다.","e":"verso는 시의 한 줄인 '시행'입니다. 소네트(soneto)는 14개의 시행으로 이루어진 정형시입니다. 시가 아닌 일반 글의 한 줄은 'línea' 또는 'renglón'이라고 합니다. 참고로 'en verso'는 '운문으로', 'en prosa'는 '산문으로'라는 뜻입니다.","x":["versos: '시행'으로 시의 한 줄을 가리킵니다 → 정답 ✓","rayas: '줄, 선'으로 시의 행을 말하지 않습니다 ✗","renglones: '(공책·글의) 줄'로 시에는 쓰지 않습니다 ✗","líneas: '선, 줄'로 일반 글에 쓰며 시의 행은 verso라고 합니다 ✗"]},{"id":"V240","q":"No nos esperaba, así que cuando llegamos a la fiesta nos miró con cara de ____.","o":["indiferencia","desdén","desgana","asombro"],"a":3,"k":"표정 어휘","t":"그는 우리가 올 줄 몰랐기 때문에, 우리가 파티에 도착하자 놀란 얼굴로 쳐다봤다.","e":"asombro는 '놀람, 경탄'입니다. 'No nos esperaba(우리를 기다리지 않았다, 예상 못 했다)'가 놀란 이유입니다. 'cara de + 감정 명사'는 '~한 표정'이라는 표현입니다. 예: cara de sueño(졸린 얼굴), cara de pocos amigos(시무룩한 얼굴).","x":["indiferencia: '무관심'으로 예상치 못한 방문에 대한 반응이 아닙니다 ✗","desdén: '경멸'으로 예상치 못했다는 이유와 연결되지 않습니다 ✗","desgana: '내키지 않음, 무기력'으로 문맥과 맞지 않습니다 ✗","asombro: '놀람'으로 예상치 못한 방문에 대한 반응입니다 → 정답 ✓"]},{"id":"V241","q":"¡Qué alegría! No me ha quedado ninguna asignatura ____ para septiembre.","o":["pendiente","ausente","adjunta","restante"],"a":0,"k":"학업 어휘","t":"너무 기뻐! 9월로 넘어가는 낙제 과목이 하나도 없어.","e":"pendiente는 '미결의, 남아 있는'이라는 뜻입니다. 스페인에서는 낙제한 과목을 9월 재시험으로 넘기는데, 이를 'asignatura pendiente(남은 과목)'라고 합니다. 'quedarle una asignatura'는 '과목 하나가 낙제로 남다'라는 표현입니다. 비유적으로 '아직 못 해 본 일'이라는 뜻으로도 씁니다.","x":["pendiente: '남아 있는, 미결의'로 'asignatura pendiente'라는 고정 표현입니다 → 정답 ✓","ausente: '결석한, 부재한'으로 과목에 쓰지 않습니다 ✗","adjunta: '첨부된, 부속의'로 과목과 맞지 않습니다 ✗","restante: '나머지의'로 낙제 과목을 뜻하는 표현이 아닙니다 ✗"]},{"id":"V242","q":"¿Quién fue el ____ del átomo?","o":["creador","inventor","descubridor","diseñador"],"a":2,"k":"발견 어휘","t":"원자를 발견한 사람은 누구였나요?","e":"descubridor는 '발견자'입니다. 원자(átomo)는 원래 자연에 존재하는 것이므로 '만들거나 발명하는' 것이 아니라 '발견하는' 것입니다. 이처럼 descubrir(발견하다)와 inventar(발명하다)의 차이에 주의하세요. 예: Colón fue el descubridor de América. (콜럼버스는 아메리카의 '발견자'로 불렸다.)","x":["creador: '창조자'로 자연에 있는 원자에는 맞지 않습니다 ✗","inventor: '발명가'로 새로 만들어 낸 것에 쓰므로 원자에는 맞지 않습니다 ✗","descubridor: '발견자'로 자연에 있던 원자를 찾아낸 사람입니다 → 정답 ✓","diseñador: '디자이너, 설계자'로 원자와 맞지 않습니다 ✗"]},{"id":"V243","q":"En ese ____ pone que está prohibido pisar el césped.","o":["cartel","póster","mapa","dibujo"],"a":0,"k":"표지판 어휘","t":"그 표지판에 잔디밭에 들어가지 말라고 쓰여 있다.","e":"cartel은 '게시물, 표지판, 포스터'로 안내나 경고 문구가 적힌 것을 말합니다. 'pone que~'는 구어로 '~라고 쓰여 있다'라는 표현입니다. 'prohibido pisar el césped(잔디밭 출입 금지)'는 공원 등의 경고 표지판 문구입니다.","x":["cartel: '표지판, 게시물'로 금지 문구가 적힌 것입니다 → 정답 ✓","póster: '(장식용) 포스터'로 금지 안내에는 잘 쓰지 않습니다 ✗","mapa: '지도'로 금지 문구를 적어 두는 것이 아닙니다 ✗","dibujo: '그림'으로 문구가 적힌 안내판이 아닙니다 ✗"]},{"id":"V244","q":"La profesora que me ____ la tesis siempre está dispuesta a ayudarme.","o":["dirige","lidera","conduce","administra"],"a":0,"k":"dirigir 동사","t":"내 논문을 지도해 주시는 교수님은 항상 나를 도와주실 준비가 되어 있다.","e":"'dirigir una tesis'는 '논문을 지도하다'라는 고정 표현입니다. dirigir는 '이끌다, 지휘하다, 감독하다'라는 넓은 뜻을 가집니다. 논문 지도 교수는 'director/a de tesis'라고 합니다. 예: dirigir una película(영화를 감독하다).","x":["dirige: '지도하다'로 'dirigir una tesis'라는 고정 표현입니다 → 정답 ✓","lidera: '이끌다, 선두에 서다'로 팀이나 조직에 쓰며 논문에는 쓰지 않습니다 ✗","conduce: '운전하다, 인도하다'로 논문 지도에 쓰지 않습니다 ✗","administra: '관리하다, 운영하다'로 논문 지도에 쓰지 않습니다 ✗"]},{"id":"V245","q":"Esta casa está muy ____, hay que hacerle una reforma completa.","o":["desordenada","bien comunicada","aislada","deteriorada"],"a":3,"k":"주택 상태 어휘","t":"이 집은 많이 낡아서 전면 리모델링을 해야 한다.","e":"deteriorado/a는 '낡은, 손상된, 파손된'이라는 뜻입니다. 전면 공사(reforma completa)가 필요한 이유로 가장 알맞습니다. 동사 deteriorarse는 '악화되다, 낡다'입니다. 'hacerle una reforma'는 '~를 개보수하다'입니다.","x":["desordenada: '어질러진'으로 정리만 하면 되지 전면 공사가 필요한 이유가 아닙니다 ✗","bien comunicada: '교통이 편리한'으로 긍정적이라 공사의 이유가 아닙니다 ✗","aislada: '고립된, 단열된'으로 리모델링의 이유로 부족합니다 ✗","deteriorada: '낡은, 손상된'으로 전면 공사가 필요한 이유입니다 → 정답 ✓"]},{"id":"V246","q":"Comer en exceso puede ____ en enfermedades como la obesidad.","o":["residir","desembocar","basarse","consistir"],"a":1,"k":"desembocar en","t":"과식은 비만 같은 질병으로 이어질 수 있다.","e":"'desembocar en'은 원래 '(강이) ~로 흘러들다'라는 뜻이고, 비유적으로 '~라는 결과로 이어지다'라는 의미로 씁니다. 예: La discusión desembocó en una pelea. (말다툼이 싸움으로 번졌다.) 비슷한 표현으로 'derivar en', 'acabar en'이 있습니다.","x":["residir: '거주하다, (~에) 있다'로 결과를 나타내지 않습니다 ✗","desembocar: '(~라는 결과로) 이어지다'로 'en'과 함께 씁니다 → 정답 ✓","basarse: '~에 근거하다'로 원인과 결과 관계가 뒤바뀝니다 ✗","consistir: '~로 이루어지다'로 결과를 나타내지 않습니다 ✗"]},{"id":"V247","q":"Quiero ____ en la vida, no estar estancado.","o":["detenerme","fracasar","retroceder","progresar"],"a":3,"k":"인생 동사","t":"나는 인생에서 발전하고 싶지, 정체되고 싶지 않다.","e":"progresar는 '발전하다, 진보하다, 나아가다'입니다. 'no estar estancado(정체되지 않다)'와 대조되므로 앞으로 나아간다는 뜻의 progresar가 맞습니다. estancado는 '고인, 정체된'으로 estanque(연못)와 관련된 말입니다.","x":["detenerme: '멈추다'로 정체되고 싶지 않다는 말과 모순됩니다 ✗","fracasar: '실패하다'로 원하는 것이 아닙니다 ✗","retroceder: '후퇴하다'로 원하는 것과 반대입니다 ✗","progresar: '발전하다'로 정체와 대조되는 원하는 상태입니다 → 정답 ✓"]},{"id":"V248","q":"El ____ es uno de mis condimentos preferidos.","o":["chorizo","garbanzo","romero","atún"],"a":2,"k":"요리 어휘","t":"로즈메리는 내가 가장 좋아하는 향신료 중 하나이다.","e":"romero는 '로즈메리'로 스페인 요리에서 자주 쓰는 허브입니다. condimento는 '양념, 조미료'로 음식에 맛과 향을 더하는 재료입니다. 나머지 보기(초리소, 병아리콩, 참치)는 양념이 아니라 주재료입니다.","x":["chorizo: '초리소(스페인식 소시지)'로 양념이 아니라 음식입니다 ✗","garbanzo: '병아리콩'으로 양념이 아닙니다 ✗","romero: '로즈메리'로 양념(허브)입니다 → 정답 ✓","atún: '참치'로 양념이 아닙니다 ✗"]},{"id":"V249","q":"Es muy ____ en su trabajo, no deja nada sin supervisión.","o":["meticulosa","olvidadiza","incompetente","perezosa"],"a":0,"k":"성격 형용사","t":"그녀는 일에 아주 꼼꼼해서 아무것도 확인하지 않고 넘기는 법이 없다.","e":"meticuloso/a는 '꼼꼼한, 세심한'이라는 뜻입니다. 'no deja nada sin supervisión(아무것도 확인 없이 두지 않는다)'이 꼼꼼함을 설명합니다. 비슷한 말로 minucioso, detallista가 있습니다.","x":["meticulosa: '꼼꼼한'으로 모든 것을 점검한다는 설명과 맞습니다 → 정답 ✓","olvidadiza: '잘 잊어버리는'으로 문맥과 반대입니다 ✗","incompetente: '무능한'으로 문맥과 반대입니다 ✗","perezosa: '게으른'으로 문맥과 반대입니다 ✗"]},{"id":"V250","q":"Su divorcio le causó ____ que aún no ha superado.","o":["un vigor","un trauma","una emoción","un sobresalto"],"a":1,"k":"심리 어휘","t":"이혼은 그에게 아직 극복하지 못한 트라우마를 남겼다.","e":"trauma는 '정신적 외상, 트라우마'입니다. 'que aún no ha superado(아직 극복하지 못한)'라는 말과 함께 쓰여 오래 남는 심리적 상처를 나타냅니다. trauma는 -a로 끝나지만 남성 명사(un trauma)라는 점에 주의하세요.","x":["un vigor: '활력, 기운'으로 극복해야 할 대상이 아닙니다 ✗","un trauma: '트라우마'로 이혼 후 극복하지 못한 상처입니다 → 정답 ✓","una emoción: '감정, 감동'으로 극복해야 할 대상으로 부자연스럽습니다 ✗","un sobresalto: '깜짝 놀람'으로 순간적이라 오래 극복하지 못하는 것이 아닙니다 ✗"]},{"id":"V251","q":"''Bodas de sangre'' es una de las obras más ____ de Federico García Lorca.","o":["probadas","representativas","inciertas","dudosas"],"a":1,"k":"평가 형용사","t":"「피의 결혼식」은 페데리코 가르시아 로르카의 가장 대표적인 작품 중 하나이다.","e":"representativo/a는 '대표적인'이라는 뜻입니다. 'una de las obras más representativas de~'는 '~의 가장 대표적인 작품 중 하나'라는 자주 쓰는 표현입니다. 「Bodas de sangre」는 스페인 시인·극작가 로르카의 유명한 희곡입니다.","x":["probadas: '증명된, 시험해 본'으로 작품을 평가하는 말이 아닙니다 ✗","representativas: '대표적인'으로 작품을 평가하는 표현입니다 → 정답 ✓","inciertas: '불확실한'으로 작품 평가에 맞지 않습니다 ✗","dudosas: '의심스러운'으로 작품 평가에 맞지 않습니다 ✗"]},{"id":"V252","q":"Trabajamos en una ____ porcina.","o":["lechería","granja","plantación","huerta"],"a":1,"k":"농업 어휘","t":"우리는 양돈 농장에서 일한다.","e":"granja는 가축을 기르는 '농장'입니다. porcino/a는 '돼지의'라는 형용사(돼지를 뜻하는 라틴어 porcus에서 유래)로 'granja porcina'는 '양돈장'입니다. 예: granja avícola(양계장).","x":["lechería: '우유 가게, 낙농장'으로 돼지와 관련이 없습니다 ✗","granja: '(가축) 농장'으로 'granja porcina(양돈장)'가 됩니다 → 정답 ✓","plantación: '대규모 농원(플랜테이션)'으로 식물을 재배하는 곳입니다 ✗","huerta: '채소밭, 과수원'으로 동물을 기르는 곳이 아닙니다 ✗"]},{"id":"V253","q":"Es mejor que no hables con Marga ahora, está ____.","o":["desocupada","risueña","abierta","cabreada"],"a":3,"k":"감정 구어","t":"지금은 마르가랑 얘기하지 않는 게 좋아, 화가 나 있어.","e":"cabreado/a는 스페인 구어로 '화난, 열 받은'이라는 뜻입니다(동사 cabrearse: 화내다). 지금 이야기하지 말라는 이유로 가장 알맞습니다. 다소 비격식 표현이므로 격식 있는 자리에서는 enfadado(스페인), enojado(중남미)를 쓰세요.","x":["desocupada: '한가한'으로 오히려 이야기하기 좋은 상태입니다 ✗","risueña: '잘 웃는, 명랑한'으로 이야기하지 말라는 이유가 아닙니다 ✗","abierta: '마음이 열린'으로 이야기하지 말라는 이유가 아닙니다 ✗","cabreada: '화가 난'으로 지금 말을 걸지 말라는 이유가 됩니다 → 정답 ✓"]},{"id":"V254","q":"La profesora de español nos ha pedido que escribamos ____ de esa película.","o":["el informe","la crónica","el artículo","la reseña"],"a":3,"k":"글의 종류 어휘","t":"스페인어 선생님이 그 영화의 리뷰를 쓰라고 하셨다.","e":"reseña는 책·영화·공연 등에 대한 '짧은 평, 리뷰'입니다. 영화(película)에 대해 쓰는 글로 가장 알맞습니다. 'pedir que + 접속법(escribamos)'은 '~하라고 요청하다'라는 구문입니다.","x":["el informe: '보고서'로 영화에 대한 글로는 부적절합니다 ✗","la crónica: '연대기, 기사(르포)'로 사건을 기록하는 글입니다 ✗","el artículo: '기사, 논설'로 영화 리뷰를 특정하지 않습니다 ✗","la reseña: '리뷰, 짧은 평'으로 영화에 대한 글입니다 → 정답 ✓"]},{"id":"V255","q":"Tras un periodo de inestabilidad profesional, lo que quiero es un trabajo ____.","o":["fijo","temporal","precario","inseguro"],"a":0,"k":"노동 어휘","t":"직업적으로 불안정한 시기를 겪은 뒤라 나는 안정된 정규직을 원한다.","e":"'trabajo fijo'는 '정규직, 고정된 일자리'라는 뜻입니다. fijo는 '고정된, 확실한'입니다. 'Tras un periodo de inestabilidad(불안정한 시기 후에)'와 대조되는 안정적인 일자리가 와야 합니다. 반대말은 'trabajo temporal(임시직)'입니다.","x":["fijo: '고정된, 정규의'로 불안정한 시기 후 원하는 일자리입니다 → 정답 ✓","temporal: '임시의'로 불안정함이 계속되어 문맥과 반대입니다 ✗","precario: '불안정한, 열악한'으로 문맥과 반대입니다 ✗","inseguro: '불안정한'으로 문맥과 반대입니다 ✗"]},{"id":"V256","q":"No me gusta nada ese programa de televisión, es más, lo ____.","o":["sigo","adoro","detesto","recomiendo"],"a":2,"k":"감정 동사","t":"나는 그 TV 프로그램이 전혀 마음에 들지 않아, 아니 오히려 아주 싫어해.","e":"detestar는 '아주 싫어하다'입니다. 'es más'는 '게다가, 아니 오히려'라는 뜻으로 앞 내용을 더 강하게 만들 때 씁니다. '좋아하지 않는다'를 더 강하게 하면 '아주 싫어한다'가 됩니다.","x":["sigo: '(프로그램을) 챙겨 보다'로 싫어한다는 말과 모순됩니다 ✗","adoro: '아주 좋아하다'로 문맥과 반대입니다 ✗","detesto: '몹시 싫어하다'로 'es más'와 함께 감정을 강조합니다 → 정답 ✓","recomiendo: '추천하다'로 문맥과 반대입니다 ✗"]},{"id":"V257","q":"No veía mi maleta porque la estaba esperando en la ____ equivocada.","o":["tira","correa","cinta","banda"],"a":2,"k":"공항 어휘","t":"내 여행 가방이 안 보였던 건 엉뚱한 수하물 컨베이어 벨트에서 기다리고 있었기 때문이다.","e":"cinta는 '리본, 테이프' 외에 '컨베이어 벨트'라는 뜻이 있습니다. 공항에서 짐을 찾는 곳은 'cinta de equipaje' 또는 'cinta transportadora'라고 합니다. 'la estaba esperando'의 la는 maleta를 받는 직접목적격 대명사입니다.","x":["tira: '가늘고 긴 조각, 띠'로 수하물 벨트를 뜻하지 않습니다 ✗","correa: '가죽끈, 벨트, 개 목줄'로 공항 수하물 벨트에는 쓰지 않습니다 ✗","cinta: '컨베이어 벨트'로 공항에서 짐을 찾는 곳입니다 → 정답 ✓","banda: '띠, 밴드'로 'banda transportadora'도 있지만 공항 수하물에는 cinta가 일반적입니다 ✗"]},{"id":"V258","q":"No ____ porque tienen que despertarse muy pronto cada mañana.","o":["trasnochan","duermen","se levantan","madrugan"],"a":0,"k":"trasnochar 동사","t":"그들은 매일 아침 아주 일찍 일어나야 해서 밤늦게까지 깨어 있지 않는다.","e":"trasnochar는 '밤을 새우다, 늦게까지 안 자다'라는 뜻입니다(tras- 넘어서 + noche 밤). 아침 일찍 일어나야 하므로 늦게 자지 않는다는 문장이 됩니다. 반대 의미의 madrugar는 '일찍 일어나다'입니다.","x":["trasnochan: '밤늦게까지 안 자다'로 부정하면 일찍 일어나야 하는 이유와 맞습니다 → 정답 ✓","duermen: '자다'로 'No duermen'은 일찍 일어나는 이유와 모순됩니다 ✗","se levantan: '일어나다'로 부정하면 문맥과 맞지 않습니다 ✗","madrugan: '일찍 일어나다'로 부정하면 뒤 문장과 모순됩니다 ✗"]},{"id":"V259","q":"El ____ les pidió los billetes a todos los pasajeros del tren.","o":["vigilante","portero","guardia","revisor"],"a":3,"k":"교통 직업 어휘","t":"검표원이 기차의 모든 승객에게 표를 요구했다.","e":"revisor/a는 기차나 버스에서 표를 확인하는 '검표원'입니다. 동사 revisar(검사하다)에서 왔습니다. 기차(tren)에서 승객의 표(billetes)를 요구하는 사람이므로 정답입니다. 참고로 중남미에서는 표를 'boleto'라고 합니다.","x":["vigilante: '경비원'으로 표를 검사하는 사람이 아닙니다 ✗","portero: '수위, 골키퍼'로 기차에서 표를 확인하지 않습니다 ✗","guardia: '경비대, 경찰'로 표를 검사하는 직업이 아닙니다 ✗","revisor: '검표원'으로 승객의 표를 확인하는 사람입니다 → 정답 ✓"]},{"id":"V260","q":"El ____ de los dos autos provocó un auténtico caos en la autovía.","o":["colapso","encuentro","choque","empujón"],"a":2,"k":"교통사고 어휘","t":"두 자동차의 충돌로 고속도로에 큰 혼란이 일어났다.","e":"choque는 '충돌'로, 동사 chocar(부딪치다)에서 왔습니다. 두 차가 부딪치는 사고를 나타내는 가장 일반적인 단어입니다. auto는 중남미에서 많이 쓰는 '자동차'(스페인은 coche, 중남미 일부는 carro)입니다. autovía는 스페인의 '고속도로'입니다.","x":["colapso: '붕괴, 교통 마비'로 두 차가 부딪친 것을 말하지 않습니다 ✗","encuentro: '만남'으로 차 사고에 쓰지 않습니다 ✗","choque: '충돌'로 두 차가 부딪친 사고입니다 → 정답 ✓","empujón: '밀침'으로 사람이 미는 동작이라 차 사고에 쓰지 않습니다 ✗"]},{"id":"V261","q":"¡Qué ____ eres! Es obvio que te encantan los dulces.","o":["tragona","comilona","glotona","golosa"],"a":3,"k":"성격 형용사","t":"너 정말 단것을 좋아하는구나! 네가 단 음식을 엄청 좋아하는 게 뻔히 보여.","e":"goloso/a는 '단것을 좋아하는'이라는 뜻입니다. 뒤 문장 'te encantan los dulces(단것을 아주 좋아한다)'가 결정적인 힌트입니다. 나머지 보기는 모두 '많이 먹는, 대식가'라는 뜻으로 단것에 특정되지 않습니다. 단맛을 좋아하는 입맛은 'ser de dulce'라고도 합니다.","x":["tragona: '많이 먹어 치우는'으로 단것에 특정되지 않습니다 ✗","comilona: '대식가'로 단것에 특정되지 않습니다 ✗","glotona: '먹보, 식탐 많은'으로 단것에 특정되지 않습니다 ✗","golosa: '단것을 좋아하는'으로 문맥에 딱 맞습니다 → 정답 ✓"]},{"id":"V262","q":"Diríjase al ____ de facturación antes de pasar por el control del aeropuerto.","o":["mostrador","escritorio","expositor","receptor"],"a":0,"k":"공항 어휘","t":"공항 보안 검색대를 통과하기 전에 체크인 카운터로 가십시오.","e":"'mostrador de facturación'은 공항의 '체크인 카운터'입니다. mostrador는 상점이나 공항의 '카운터, 계산대'입니다. facturar는 공항에서 '(짐을) 부치다, 체크인하다'라는 뜻입니다. 'Diríjase'는 usted에 대한 명령형(가십시오)입니다.","x":["mostrador: '카운터'로 'mostrador de facturación(체크인 카운터)'입니다 → 정답 ✓","escritorio: '책상'으로 공항 카운터에 쓰지 않습니다 ✗","expositor: '진열대, 전시자'로 체크인 장소가 아닙니다 ✗","receptor: '수신기, 받는 사람'으로 장소가 아닙니다 ✗"]},{"id":"V263","q":"Olivia se hizo un ____ de tobillo cuando jugaba al baloncesto.","o":["roce","tirón","esguince","corte"],"a":2,"k":"부상 어휘","t":"올리비아는 농구를 하다가 발목을 삐었다.","e":"esguince는 '염좌, 삠'으로 인대가 늘어나거나 다친 상태입니다. 'hacerse un esguince de tobillo'는 '발목을 삐다'라는 자주 쓰는 표현입니다. 운동 중 발목에 생기는 대표적인 부상이므로 정답입니다. 구어로는 'torcerse el tobillo'라고도 합니다.","x":["roce: '스침, 찰과'로 'de tobillo'와 함께 부상 이름이 되지 않습니다 ✗","tirón: '(근육) 당김'으로 주로 근육에 쓰며 발목 부상 이름으로는 부적절합니다 ✗","esguince: '염좌'로 'esguince de tobillo(발목 염좌)'가 됩니다 → 정답 ✓","corte: '베인 상처'로 농구 중 발목 부상으로 부자연스럽습니다 ✗"]},{"id":"V264","q":"Cuando cocino, me pongo un ____ para no mancharme la ropa.","o":["casco","chaleco","gorro","delantal"],"a":3,"k":"의류 어휘","t":"요리할 때 옷이 더러워지지 않도록 앞치마를 입는다.","e":"delantal은 '앞치마'로 delante(앞)에서 온 말입니다. 'para no mancharme la ropa(옷을 더럽히지 않으려고)'가 힌트입니다. 'ponerse(입다, 착용하다)'는 재귀동사로 옷이나 액세서리를 착용할 때 씁니다.","x":["casco: '헬멧'으로 요리할 때 옷을 보호하지 않습니다 ✗","chaleco: '조끼'로 옷을 보호하는 용도가 아닙니다 ✗","gorro: '모자'로 옷을 보호하지 않습니다 ✗","delantal: '앞치마'로 요리할 때 옷을 보호합니다 → 정답 ✓"]},{"id":"V265","q":"Destacan por la calidad de sus productos y por sus precios ____.","o":["inasequibles","competitivos","prohibitivos","discutibles"],"a":1,"k":"가격 형용사","t":"그들은 제품의 품질과 경쟁력 있는 가격으로 두각을 나타낸다.","e":"'precios competitivos'는 '경쟁력 있는 가격, 저렴한 가격'이라는 뜻의 비즈니스 표현입니다. 'Destacan por~(~로 두드러진다)'라는 긍정적인 문맥이므로 장점이 와야 합니다. 나머지 보기는 모두 '비싼'이거나 부정적인 뜻입니다.","x":["inasequibles: '살 수 없는(너무 비싼)'으로 장점이 아닙니다 ✗","competitivos: '경쟁력 있는'으로 장점으로 두드러지는 가격입니다 → 정답 ✓","prohibitivos: '엄청나게 비싼'으로 장점이 아닙니다 ✗","discutibles: '논란의 여지가 있는'으로 장점이 아닙니다 ✗"]},{"id":"V266","q":"Los ____ de hacienda comprueban que los contribuyentes pagan sus impuestos.","o":["guardias","protectores","defensores","inspectores"],"a":3,"k":"세무 어휘","t":"세무 조사관들은 납세자들이 세금을 내는지 확인한다.","e":"inspector/a는 '조사관, 감독관'입니다. 'inspector de Hacienda'는 '세무 조사관'이고, Hacienda는 스페인의 '재무부, 국세청'입니다. contribuyente는 '납세자'입니다. 다른 보기도 사람을 가리키지만 세금 확인 업무와 맞지 않습니다.","x":["guardias: '경비원, 경찰'로 세금을 조사하지 않습니다 ✗","protectores: '보호자'로 세무 업무가 아닙니다 ✗","defensores: '옹호자, 변호인'으로 세무 업무가 아닙니다 ✗","inspectores: '조사관'으로 'inspectores de hacienda(세무 조사관)'입니다 → 정답 ✓"]},{"id":"V267","q":"Estamos en una lista de ____ por no haber pagado las últimas facturas.","o":["odiosos","penosos","perezosos","morosos"],"a":3,"k":"금융 어휘","t":"우리는 최근 청구서를 내지 않아서 체납자 명단에 올라 있다.","e":"moroso/a는 '(빚·요금을) 체납한, 연체자'라는 뜻입니다. 'lista de morosos'는 '체납자 명단, 신용 불량자 명단'이라는 표현입니다. 'por no haber pagado(내지 않았기 때문에)'가 결정적인 힌트입니다. 명사형은 morosidad(연체)입니다.","x":["odiosos: '얄미운, 가증스러운'으로 문맥과 관련이 없습니다 ✗","penosos: '비참한, 한심한'으로 문맥에 맞지 않습니다 ✗","perezosos: '게으른'으로 요금 미납과 직접 관련이 없습니다 ✗","morosos: '체납자'로 요금을 내지 않은 사람입니다 → 정답 ✓"]},{"id":"V268","q":"Mi jersey ____ al lavarlo en la lavadora.","o":["encogió","se redujo","disminuyó","se contrajo"],"a":0,"k":"encoger 동사","t":"내 스웨터는 세탁기에 빨았더니 줄어들었다.","e":"encoger는 '(옷이) 줄어들다'라는 뜻으로 세탁 후 옷이 줄 때 쓰는 대표 동사입니다. 이 뜻일 때는 재귀 없이 'El jersey encogió' 또는 'se encogió' 둘 다 씁니다. jersey는 스페인에서 '스웨터'(중남미 suéter)입니다.","x":["encogió: '(옷이) 줄어들다'로 세탁 후 옷에 쓰는 표현입니다 → 정답 ✓","se redujo: '줄다, 감소하다'로 양이나 수에 쓰며 옷에는 잘 쓰지 않습니다 ✗","disminuyó: '감소하다'로 수치에 쓰며 옷에는 쓰지 않습니다 ✗","se contrajo: '수축하다'로 근육 등에 쓰며 옷이 줄 때에는 쓰지 않습니다 ✗"]},{"id":"V269","q":"No tienes por qué llorar, no ha sido para ____.","o":["tanto","tal","bien","mucho"],"a":0,"k":"no es para tanto","t":"울 필요 없어, 그렇게까지 할 일은 아니었어.","e":"'no es/ha sido para tanto'는 '그렇게까지 할 일은 아니다, 별것 아니다'라는 관용 표현입니다. 상대가 과하게 반응할 때 진정시키며 씁니다. 예: Tranquilo, no es para tanto. (진정해, 그렇게까지 할 일 아니야.) 'no tener por qué + 동사원형'은 '~할 이유가 없다'입니다.","x":["tanto: 'no es para tanto(별일 아니다)'라는 관용 표현입니다 → 정답 ✓","tal: 'para tal'은 이 관용 표현에 쓰지 않습니다 ✗","bien: 'para bien'은 '좋은 쪽으로'라는 뜻으로 문맥과 맞지 않습니다 ✗","mucho: 'para mucho'는 관용 표현이 아니라 어색합니다 ✗"]},{"id":"V270","q":"Estamos ante una noticia ____, pues este medio de comunicación nunca publica falsedades.","o":["inexacta","falsa","dudosa","fiable"],"a":3,"k":"신뢰 형용사","t":"이 언론사는 결코 거짓을 보도하지 않으니 이것은 믿을 만한 뉴스이다.","e":"fiable는 '믿을 만한, 신뢰할 수 있는'이라는 뜻으로 fiar(믿다)에서 왔습니다. 'pues(왜냐하면)' 뒤의 '거짓을 보도하지 않는다'는 이유와 연결됩니다. 중남미에서는 'confiable'을 더 자주 씁니다.","x":["inexacta: '부정확한'으로 이유와 모순됩니다 ✗","falsa: '거짓의'로 이유와 모순됩니다 ✗","dudosa: '의심스러운'으로 이유와 모순됩니다 ✗","fiable: '믿을 만한'으로 거짓 보도를 하지 않는다는 이유와 맞습니다 → 정답 ✓"]},{"id":"V271","q":"Mi familia tiene ____, nada es más importante para mí.","o":["autoridad","ventaja","prioridad","mérito"],"a":2,"k":"우선순위 어휘","t":"내게는 가족이 최우선이야, 그 무엇도 나에게 그보다 중요하지 않아.","e":"prioridad는 '우선권, 우선순위'로 'tener prioridad'는 '우선이다, 우선권을 갖다'라는 표현입니다. 'nada es más importante para mí(나에게 무엇도 더 중요하지 않다)'가 힌트입니다. 예: Los peatones tienen prioridad. (보행자에게 우선권이 있다.)","x":["autoridad: '권위, 권한'으로 가장 중요하다는 뜻이 아닙니다 ✗","ventaja: '이점, 유리함'으로 가장 중요하다는 뜻이 아닙니다 ✗","prioridad: '우선순위'로 무엇보다 중요하다는 뜻입니다 → 정답 ✓","mérito: '공로, 가치'로 'tener mérito'는 '훌륭하다'는 뜻이라 문맥과 다릅니다 ✗"]},{"id":"V272","q":"La ciencia está dividida en múltiples ____.","o":["caras","ramas","lados","bandos"],"a":1,"k":"분야 어휘","t":"과학은 여러 분야로 나뉜다.","e":"rama는 '나뭇가지'라는 뜻에서 '(학문의) 분야, 부문'이라는 비유적 의미로 확장되었습니다. 'las ramas de la ciencia'는 '과학의 여러 분야'입니다. 예: La biología es una rama de la ciencia. (생물학은 과학의 한 분야다.)","x":["caras: '얼굴, 면'으로 학문 분야를 뜻하지 않습니다 ✗","ramas: '(학문의) 분야'로 과학의 분과를 나타냅니다 → 정답 ✓","lados: '쪽, 면'으로 학문 분야를 뜻하지 않습니다 ✗","bandos: '편, 파벌'로 대립하는 집단을 뜻해 학문 분야가 아닙니다 ✗"]},{"id":"V273","q":"Fumar es ____.","o":["un vicio","una rareza","un pecado","una anomalía"],"a":0,"k":"습관 어휘","t":"흡연은 나쁜 습관(악습)이다.","e":"vicio는 '악습, 나쁜 버릇, 중독적인 습관'입니다. 흡연·음주·도박처럼 끊기 어려운 나쁜 습관에 씁니다. 예: Tiene el vicio de morderse las uñas. (그는 손톱을 물어뜯는 버릇이 있다.)","x":["un vicio: '악습, 중독적 습관'으로 흡연을 설명하기에 알맞습니다 → 정답 ✓","una rareza: '희귀한 것, 별난 점'으로 흡연을 설명하지 않습니다 ✗","un pecado: '죄(종교적)'로 흡연을 일반적으로 설명하는 말이 아닙니다 ✗","una anomalía: '이상, 변칙'으로 흡연과 맞지 않습니다 ✗"]},{"id":"V274","q":"Ayer hacía un tiempo ____, por eso no nos fuimos de pícnic.","o":["lluvioso","variable","estable","despejado"],"a":0,"k":"날씨 어휘","t":"어제는 비가 많이 오는 날씨였다. 그래서 우리는 소풍을 가지 않았다.","e":"lluvioso/a는 '비가 오는, 비가 많은'이라는 뜻으로 lluvia(비)에서 왔습니다. 소풍을 가지 않은 이유(por eso)가 되려면 나쁜 날씨여야 합니다. 'hacer un tiempo + 형용사'는 '날씨가 ~하다'라는 표현입니다.","x":["lluvioso: '비 오는'으로 소풍을 가지 않은 이유가 됩니다 → 정답 ✓","variable: '변덕스러운'으로 소풍을 취소할 확실한 이유로는 약합니다 ✗","estable: '안정된'으로 소풍 가기 좋은 날씨입니다 ✗","despejado: '맑게 갠'으로 소풍 가기 좋은 날씨라 문맥과 반대입니다 ✗"]},{"id":"V275","q":"Rocío es una persona de ideas ____, te aseguro que no va a cambiar de opinión.","o":["fijas","cambiantes","inconsistentes","absurdas"],"a":0,"k":"ideas fijas","t":"로시오는 생각이 확고한 사람이라서 의견을 바꾸지 않을 거라고 장담해.","e":"'de ideas fijas'는 '생각이 확고한, 고집 있는'이라는 표현입니다. fijo는 '고정된'입니다. 'no va a cambiar de opinión(의견을 바꾸지 않을 것)'이 힌트입니다. 참고로 'idea fija'는 '고정관념, 집착하는 생각'이라는 뜻도 있습니다.","x":["fijas: '고정된'으로 의견을 바꾸지 않는다는 설명과 맞습니다 → 정답 ✓","cambiantes: '변하는'으로 문맥과 반대입니다 ✗","inconsistentes: '일관성 없는'으로 문맥과 반대입니다 ✗","absurdas: '터무니없는'으로 의견을 바꾸지 않는 이유가 아닙니다 ✗"]},{"id":"V276","q":"Ángela es altísima, por eso no suele llevar zapatos ____.","o":["cerrados","planos","de tacón","cómodos"],"a":2,"k":"신발 어휘","t":"앙헬라는 키가 아주 커서 보통 굽 높은 구두를 신지 않는다.","e":"'zapatos de tacón'은 '굽 높은 구두, 하이힐'입니다. tacón은 '구두 굽'입니다. 키가 아주 크니 더 커 보이게 하는 하이힐을 잘 신지 않는다는 문맥입니다. 반대로 굽이 없는 신발은 'zapatos planos'입니다.","x":["cerrados: '앞이 막힌'으로 키와 관련이 없습니다 ✗","planos: '굽 없는'으로 키 큰 사람이 피할 이유가 없습니다 ✗","de tacón: '굽 높은'으로 키 큰 사람이 피할 만한 신발입니다 → 정답 ✓","cómodos: '편한'으로 키와 관련이 없습니다 ✗"]},{"id":"V277","q":"Mamá, ¿te importaría ____ a la universidad? Si voy a pie llegaré tarde.","o":["acercarme","dirigirme","guiarme","aproximarme"],"a":0,"k":"acercar 동사","t":"엄마, 나 대학교까지 좀 태워다 줄 수 있어? 걸어가면 늦을 거야.","e":"acercar는 '가까이 가져가다'라는 뜻 외에, 구어로 'acercar a alguien a un lugar'는 '~를 어디까지 (차로) 태워다 주다'라는 뜻이 있습니다. 'Si voy a pie(걸어가면)'가 차로 데려다 달라는 부탁임을 보여 줍니다. '¿Te importaría + 동사원형?'은 '~해 줄 수 있겠니?'라는 공손한 부탁 표현입니다.","x":["acercarme: '(나를) 태워다 주다'로 걸어가면 늦는 상황에 맞습니다 → 정답 ✓","dirigirme: '(나를) 이끌다, 지도하다'로 태워다 준다는 뜻이 없습니다 ✗","guiarme: '(나를) 안내하다'로 길을 알려 준다는 뜻이라 맞지 않습니다 ✗","aproximarme: '(나를) 근접시키다'로 격식 있는 말이라 태워 달라는 뜻으로 쓰지 않습니다 ✗"]},{"id":"V278","q":"Odio tener el pelo tan liso, por eso me lo ____.","o":["mojo","tiño","seco","rizo"],"a":3,"k":"미용 동사","t":"머리가 너무 곧은 게 싫어서 나는 파마를 해서 곱슬곱슬하게 한다.","e":"rizar는 '(머리를) 곱슬곱슬하게 하다, 웨이브를 넣다'라는 뜻입니다. pelo liso(곧은 생머리)가 싫다고 했으므로 그 반대로 만드는 rizar가 정답입니다. 형용사 rizado는 '곱슬곱슬한'입니다. 'me lo rizo'의 lo는 el pelo를 받는 직접목적격 대명사입니다.","x":["mojo: '적시다'로 생머리를 바꾸는 방법이 아닙니다 ✗","tiño: '염색하다'로 색을 바꿀 뿐 곧은 머리를 바꾸지 않습니다 ✗","seco: '말리다'로 생머리를 바꾸지 않습니다 ✗","rizo: '곱슬곱슬하게 하다'로 생머리가 싫은 이유와 맞습니다 → 정답 ✓"]},{"id":"V279","q":"Le recomiendo esta loción ____ si observa pérdida de cabello.","o":["anticaída","antiséptica","anticelulítica","antiarrugas"],"a":0,"k":"anti- 합성어","t":"머리카락이 빠지는 것을 발견하시면 이 탈모 방지 로션을 추천해 드립니다.","e":"anticaída는 '탈모 방지의'(anti- 방지 + caída 떨어짐)라는 뜻입니다. 'pérdida de cabello(머리카락 빠짐)'가 결정적인 힌트입니다. 접두사 anti-는 '~을 막는'이라는 뜻으로 화장품·약품 이름에 자주 쓰입니다.","x":["anticaída: '탈모 방지의'로 머리카락이 빠질 때 쓰는 로션입니다 → 정답 ✓","antiséptica: '소독용의'로 탈모와 관련이 없습니다 ✗","anticelulítica: '셀룰라이트 방지의'로 탈모와 관련이 없습니다 ✗","antiarrugas: '주름 방지의'로 탈모와 관련이 없습니다 ✗"]},{"id":"V280","q":"Voy a ____ este bizcocho con un poco de vainilla.","o":["aromatizar","salar","perfumar","salpimentar"],"a":0,"k":"요리 동사","t":"이 스펀지케이크에 바닐라를 조금 넣어 향을 낼 거야.","e":"aromatizar는 '향을 내다, 향을 더하다'라는 뜻으로 aroma(향)에서 왔습니다. 음식에 바닐라·계피 등으로 향을 낼 때 씁니다. perfumar도 '향기롭게 하다'지만 주로 향수나 공간에 씁니다. bizcocho는 '카스텔라 같은 스펀지케이크'입니다.","x":["aromatizar: '향을 내다'로 바닐라를 넣는 요리 동작입니다 → 정답 ✓","salar: '소금을 치다'로 바닐라와 맞지 않습니다 ✗","perfumar: '향수를 뿌리다'로 주로 사람·공간에 쓰며 요리에는 잘 쓰지 않습니다 ✗","salpimentar: '소금과 후추로 간하다'로 케이크와 바닐라에 맞지 않습니다 ✗"]},{"id":"V281","q":"Todos los medicamentos tienen ____ secundarios.","o":["efectos","resultados","objetivos","objetos"],"a":0,"k":"efecto secundario","t":"모든 약에는 부작용이 있다.","e":"'efectos secundarios'는 '부작용'이라는 고정 표현입니다(직역: 이차적 효과). efecto는 '효과, 영향'입니다. 의약품 설명서나 병원에서 자주 듣는 표현입니다. 비슷한 말로 'efectos adversos'가 있습니다.","x":["efectos: '효과'로 'efectos secundarios(부작용)'라는 고정 표현입니다 → 정답 ✓","resultados: '결과'로 'resultados secundarios'는 부작용을 뜻하지 않습니다 ✗","objetivos: '목표'로 약의 부작용과 관련이 없습니다 ✗","objetos: '물건'으로 문맥에 맞지 않습니다 ✗"]},{"id":"V282","q":"Tenemos que llamar a un ____ para que arregle las puertas de la casa.","o":["mecánico","fontanero","carpintero","plomero"],"a":2,"k":"직업 어휘","t":"집 문을 고치기 위해 목수를 불러야 한다.","e":"carpintero/a는 '목수'로 나무로 된 가구나 문을 만들고 수리합니다. 문(puertas)을 고치는 일은 목수의 일입니다. fontanero(스페인)와 plomero(중남미)는 둘 다 '배관공'입니다.","x":["mecánico: '정비공'으로 자동차·기계를 고칩니다 ✗","fontanero: '배관공(스페인)'으로 수도관을 고칩니다 ✗","carpintero: '목수'로 문을 고치는 사람입니다 → 정답 ✓","plomero: '배관공(중남미)'으로 수도관을 고칩니다 ✗"]},{"id":"V283","q":"Hace un calor ____, así que protégete del sol y bebe mucha agua.","o":["motivador","demoledor","abrasador","exprimidor"],"a":2,"k":"날씨 형용사","t":"타는 듯이 더우니 햇볕을 피하고 물을 많이 마셔.","e":"abrasador/a는 '타는 듯한, 이글거리는'이라는 뜻으로 abrasar(태우다)에서 왔습니다. 'calor abrasador'는 '찌는 듯한 더위'라는 자주 쓰는 표현입니다. 햇볕을 피하고 물을 많이 마시라는 조언과 잘 연결됩니다. 비슷한 표현으로 'calor sofocante'가 있습니다.","x":["motivador: '동기를 부여하는'으로 날씨와 관련이 없습니다 ✗","demoledor: '파괴적인'으로 'calor'와 짝을 이루는 일반 표현이 아닙니다 ✗","abrasador: '타는 듯한'으로 'calor abrasador'가 자연스러운 짝입니다 → 정답 ✓","exprimidor: '착즙기'라는 명사로 날씨와 관련이 없습니다 ✗"]},{"id":"V284","q":"Susana ____ con sus abuelos porque sus padres no podían hacerse cargo de ella.","o":["ascendió","se crio","se agrandó","se desarrolló"],"a":1,"k":"criarse 동사","t":"수사나는 부모님이 그녀를 돌볼 수 없어서 조부모님 밑에서 자랐다.","e":"criarse는 '(누구의 손에서) 자라다, 길러지다'라는 뜻입니다. 'criarse con alguien'은 '~와 함께/~ 밑에서 자라다'입니다. 'hacerse cargo de~'는 '~를 맡다, 돌보다'라는 표현입니다. criar(기르다)의 과거형은 강세 규칙상 crio처럼 악센트 없이 씁니다.","x":["ascendió: '올라가다, 승진하다'로 자라는 것을 뜻하지 않습니다 ✗","se crio: '자랐다'로 조부모님 밑에서 길러진 상황에 맞습니다 → 정답 ✓","se agrandó: '커지다(크기가)'로 사람이 자라는 데 쓰지 않습니다 ✗","se desarrolló: '발달하다'로 신체적 성장을 말하며 누구와 함께 자랐는지를 나타내지 않습니다 ✗"]},{"id":"V285","q":"Lo consideran un ____ porque le salvó la vida a un niño que estaba a punto de ahogarse.","o":["maestro","galán","virtuoso","héroe"],"a":3,"k":"인물 어휘","t":"그는 물에 빠지기 직전이던 아이의 생명을 구했기 때문에 영웅으로 여겨진다.","e":"héroe는 '영웅'입니다(여성형 heroína). 아이의 목숨을 구한 사람을 부르는 말로 알맞습니다. 'estar a punto de + 동사원형'은 '막 ~하려던 참이다', ahogarse는 '물에 빠지다, 익사하다'입니다.","x":["maestro: '선생님, 거장'으로 생명을 구한 사람을 부르는 말이 아닙니다 ✗","galán: '미남, 멋쟁이 남자'로 문맥과 관련이 없습니다 ✗","virtuoso: '거장, 명연주자'로 생명을 구한 행동과 관련이 없습니다 ✗","héroe: '영웅'으로 아이를 구한 사람에게 맞습니다 → 정답 ✓"]},{"id":"V286","q":"La parte superior de un árbol es ____.","o":["el tronco","la rama","la raíz","la copa"],"a":3,"k":"나무 어휘","t":"나무의 윗부분은 수관(나무 꼭대기의 가지와 잎 부분)이다.","e":"copa는 나무 꼭대기의 가지와 잎이 모인 '수관, 우듬지'입니다. copa는 '와인잔, 우승컵'이라는 뜻도 있습니다. 나무 구조는 raíz(뿌리) → tronco(줄기) → rama(가지) → copa(꼭대기 전체) 순서로 기억하세요.","x":["el tronco: '줄기'로 나무의 가운데 부분입니다 ✗","la rama: '가지'로 윗부분 전체를 가리키지 않습니다 ✗","la raíz: '뿌리'로 나무의 아랫부분입니다 ✗","la copa: '수관, 우듬지'로 나무의 윗부분입니다 → 정답 ✓"]},{"id":"V287","q":"Deberíamos enseñar a nuestros hijos a que sientan ____ por las personas mayores.","o":["respeto","antipatía","desprecio","aversión"],"a":0,"k":"감정 명사","t":"우리 아이들에게 어르신들을 존중하도록 가르쳐야 한다.","e":"respeto는 '존경, 존중'입니다. 'sentir respeto por alguien'은 '~를 존중하다'라는 표현입니다. 'Deberíamos enseñar(가르쳐야 한다)'라는 문맥이므로 긍정적인 감정이 와야 합니다. 'enseñar a que + 접속법(sientan)'에 주의하세요.","x":["respeto: '존중'으로 아이들에게 가르쳐야 할 감정입니다 → 정답 ✓","antipatía: '반감'으로 가르칠 감정이 아닙니다 ✗","desprecio: '경멸'로 가르칠 감정이 아닙니다 ✗","aversión: '혐오'로 가르칠 감정이 아닙니다 ✗"]},{"id":"V288","q":"El reencuentro de los dos viejos amigos fue un momento ____ y tierno.","o":["humillante","entrañable","incómodo","molesto"],"a":1,"k":"감정 형용사","t":"두 오랜 친구의 재회는 정겹고 따뜻한 순간이었다.","e":"entrañable는 '정겨운, 마음 깊이 따뜻한, 애틋한'이라는 뜻입니다. entrañas(내장, 마음 깊은 곳)에서 온 말로 진심으로 정이 느껴지는 것을 말합니다. 'y tierno(그리고 다정한)'와 함께 쓰였으므로 긍정적인 의미의 형용사가 와야 합니다.","x":["humillante: '굴욕적인'으로 다정한 재회와 맞지 않습니다 ✗","entrañable: '정겨운, 애틋한'으로 'tierno'와 잘 어울립니다 → 정답 ✓","incómodo: '불편한'으로 'tierno'와 맞지 않습니다 ✗","molesto: '귀찮은, 짜증 나는'으로 'tierno'와 맞지 않습니다 ✗"]},{"id":"V289","q":"Se creen mejor que nosotros, tienen complejo de ____.","o":["superioridad","culpa","persecución","inferioridad"],"a":0,"k":"심리 표현","t":"그들은 자신들이 우리보다 낫다고 생각해, 우월감에 빠져 있어.","e":"'complejo de superioridad'는 '우월감(우월 콤플렉스)'입니다. 'Se creen mejor que nosotros(자기가 우리보다 낫다고 생각한다)'가 힌트입니다. 반대말은 'complejo de inferioridad(열등감)'입니다. 'creerse + 형용사'는 '자기가 ~라고 착각하다'입니다.","x":["superioridad: '우월'로 'complejo de superioridad(우월감)'가 됩니다 → 정답 ✓","culpa: '죄책감'으로 남보다 낫다고 생각하는 것과 관련이 없습니다 ✗","persecución: '피해망상'으로 문맥과 관련이 없습니다 ✗","inferioridad: '열등'으로 문맥과 반대입니다 ✗"]},{"id":"V290","q":"Mi familia es de ____ media, no somos ni ricos ni pobres.","o":["categoría","condición","clase","escala"],"a":2,"k":"clase media","t":"우리 가족은 중산층이라 부자도 가난하지도 않다.","e":"'clase media'는 '중산층'이라는 고정 표현입니다. clase는 '수업' 외에 '(사회) 계층'이라는 뜻이 있습니다. 'ni ricos ni pobres(부자도 가난하지도 않은)'가 힌트입니다. 'clase alta(상류층)', 'clase baja(하층민)', 'clase obrera(노동자 계급)'도 함께 기억하세요.","x":["categoría: '범주, 등급'으로 'categoría media'는 사회 계층을 뜻하지 않습니다 ✗","condición: '조건, 신분'으로 'de condición humilde(가난한 신분의)'처럼 쓰지만 'media'와 함께 쓰지 않습니다 ✗","clase: '계층'으로 'clase media(중산층)'라는 고정 표현입니다 → 정답 ✓","escala: '척도, 규모'로 사회 계층을 나타내지 않습니다 ✗"]},{"id":"V291","q":"¿Cuánto dinero desea ____ en su cuenta corriente?","o":["introducir","esconder","depositar","almacenar"],"a":2,"k":"은행 어휘","t":"당좌예금 계좌에 얼마를 입금하시겠습니까?","e":"depositar는 '(돈을) 맡기다, 입금하다, 예금하다'라는 뜻입니다. 은행에서 계좌(cuenta)에 돈을 넣는 일을 말할 때 쓰는 정식 표현입니다. 'cuenta corriente'는 '당좌예금(입출금) 계좌'입니다. 비슷한 표현으로 'ingresar dinero'(스페인)가 있습니다.","x":["introducir: '집어넣다'로 물건을 넣을 때 쓰며 입금의 정식 표현이 아닙니다 ✗","esconder: '숨기다'로 은행 업무와 관련이 없습니다 ✗","depositar: '입금하다'로 계좌에 돈을 넣는 정식 표현입니다 → 정답 ✓","almacenar: '저장하다, 창고에 보관하다'로 물건에 쓰며 입금에 쓰지 않습니다 ✗"]},{"id":"V292","q":"El único ____ del crimen escapó del país.","o":["curioso","misterioso","receloso","sospechoso"],"a":3,"k":"범죄 어휘","t":"그 범죄의 유일한 용의자는 나라 밖으로 도망쳤다.","e":"sospechoso/a는 형용사로 '의심스러운', 명사로 '용의자'라는 뜻입니다. 'el sospechoso del crimen'은 '범죄의 용의자'입니다. 동사 sospechar는 '의심하다'입니다. 'escapar del país(나라 밖으로 도주하다)'가 범죄와 관련된 인물임을 보여 줍니다.","x":["curioso: '호기심 많은 사람, 구경꾼'으로 범죄 용의자가 아닙니다 ✗","misterioso: '신비로운'으로 명사로 쓰여 용의자를 뜻하지 않습니다 ✗","receloso: '경계하는, 의심하는(사람)'으로 의심받는 사람이 아니라 의심하는 쪽입니다 ✗","sospechoso: '용의자'로 범죄를 저질렀다고 의심받는 사람입니다 → 정답 ✓"]},{"id":"V293","q":"Odio que nos hable con tono ____. Se cree superior a nosotros.","o":["cortés","despectivo","llano","afectivo"],"a":1,"k":"말투 형용사","t":"그가 우리에게 깔보는 말투로 말하는 게 정말 싫어. 자기가 우리보다 잘났다고 생각해.","e":"despectivo/a는 '경멸적인, 깔보는'이라는 뜻입니다. 'Se cree superior a nosotros(자기가 우리보다 우월하다고 생각한다)'가 힌트입니다. 'tono despectivo'는 '깔보는 말투'라는 자주 쓰는 표현입니다. 'Odio que + 접속법(hable)'에도 주의하세요.","x":["cortés: '정중한'으로 싫어할 말투가 아닙니다 ✗","despectivo: '깔보는'으로 우월하다고 생각하는 태도와 맞습니다 → 정답 ✓","llano: '소박한, 꾸밈없는'으로 싫어할 이유가 되지 않습니다 ✗","afectivo: '정감 있는'으로 문맥과 반대입니다 ✗"]},{"id":"V294","q":"Si no bebes suficiente líquido, te vas a ____.","o":["marear","deshidratar","resfriar","desmayar"],"a":1,"k":"건강 동사","t":"충분히 수분을 섭취하지 않으면 탈수 상태가 될 거야.","e":"deshidratarse는 '탈수되다'라는 뜻입니다(des- 제거 + hidratar 수분을 공급하다). 'Si no bebes suficiente líquido(충분한 액체를 마시지 않으면)'의 직접적인 결과입니다. 'ir a + 동사원형'에서 재귀대명사 te가 앞에 나온 형태(te vas a deshidratar)입니다.","x":["marear: '어지럽다, 멀미 나다'로 결과일 수는 있지만 수분 부족의 직접적 결과는 탈수입니다 ✗","deshidratar: '탈수되다'로 물을 마시지 않은 직접적 결과입니다 → 정답 ✓","resfriar: '감기에 걸리다'로 수분 부족과 직접 관련이 없습니다 ✗","desmayar: '기절하다'로 수분 부족의 직접적 결과라기보다 그 다음 증상입니다 ✗"]},{"id":"V295","q":"Aprender otras lenguas tiene una ____ de beneficios.","o":["colectividad","enormidad","grandiosidad","infinidad"],"a":3,"k":"수량 표현","t":"다른 언어를 배우면 수많은 장점이 있다.","e":"'una infinidad de + 복수 명사'는 '셀 수 없이 많은 ~'이라는 표현입니다. infinidad는 '무한함'이라는 뜻에서 '엄청나게 많음'을 나타냅니다. 예: Hay una infinidad de libros. (책이 셀 수 없이 많다.) 비슷한 표현으로 'un sinfín de', 'un montón de'가 있습니다.","x":["colectividad: '공동체, 집단'으로 수량 표현이 아닙니다 ✗","enormidad: '거대함'으로 'una enormidad de'는 수량 표현으로 잘 쓰지 않습니다 ✗","grandiosidad: '웅장함'으로 수량을 나타내지 않습니다 ✗","infinidad: '무수함'으로 'una infinidad de beneficios(수많은 장점)'가 됩니다 → 정답 ✓"]},{"id":"V296","q":"Tras pasar el control del aeropuerto, se dirigieron a la ____ de embarque.","o":["puerta","meta","habitación","portería"],"a":0,"k":"공항 어휘","t":"공항 보안 검색대를 통과한 뒤, 그들은 탑승구로 향했다.","e":"'puerta de embarque'는 '탑승구, 게이트'입니다. embarque는 '탑승'으로 동사 embarcar(탑승하다)에서 왔습니다. 공항 순서: facturación(체크인) → control de seguridad(보안 검색) → puerta de embarque(탑승구)입니다.","x":["puerta: '문'으로 'puerta de embarque(탑승구)'라는 고정 표현입니다 → 정답 ✓","meta: '목표, 결승선'으로 공항 시설이 아닙니다 ✗","habitación: '방'으로 공항 탑승구를 뜻하지 않습니다 ✗","portería: '수위실, 골대'로 공항 시설이 아닙니다 ✗"]},{"id":"V297","q":"Los días de calor suelo ____ el pelo para estar más fresquita.","o":["secarme","recogerme","soltarme","teñirme"],"a":1,"k":"머리 손질 동사","t":"더운 날에는 좀 더 시원하게 있으려고 머리를 묶곤 한다.","e":"'recogerse el pelo'는 '머리를 묶다, 올리다'라는 표현입니다. recoger는 '줍다, 정리하다, 모으다'라는 뜻으로 머리를 한데 모아 묶는다는 의미가 됩니다. 반대로 'soltarse el pelo'는 '머리를 풀다'입니다. fresquita는 fresca(시원한)에 지소사(-ita, 작고 귀여운 느낌)를 붙인 말입니다.","x":["secarme: '말리다'로 더위를 피하는 머리 손질과 직접 관련이 없습니다 ✗","recogerme: '(머리를) 묶다'로 더울 때 시원하게 하는 방법입니다 → 정답 ✓","soltarme: '(머리를) 풀다'로 더울 때 오히려 덥습니다 ✗","teñirme: '염색하다'로 시원함과 관련이 없습니다 ✗"]},{"id":"V298","q":"La lírica es mi ____ literario preferido.","o":["patrón","género","tipo","modelo"],"a":1,"k":"문학 어휘","t":"서정시는 내가 가장 좋아하는 문학 장르이다.","e":"género는 '장르, 종류'로 'género literario'는 '문학 장르'입니다. lírica(서정시), narrativa(서사·소설), drama(극)가 대표적인 문학 장르입니다. género는 문법의 '성(남성/여성)'이라는 뜻도 있습니다.","x":["patrón: '본, 패턴'으로 문학 장르를 뜻하지 않습니다 ✗","género: '장르'로 'género literario(문학 장르)'라는 고정 표현입니다 → 정답 ✓","tipo: '종류'로 일반적인 말이라 'tipo literario'는 쓰지 않습니다 ✗","modelo: '모델, 본보기'로 문학 장르를 뜻하지 않습니다 ✗"]},{"id":"V299","q":"Qué pena... El mejor jugador ____ en el último partido.","o":["se recuperó","se repuso","se lesionó","se rehabilitó"],"a":2,"k":"스포츠 부상 어휘","t":"정말 아쉽다... 최고의 선수가 지난 경기에서 부상을 당했다.","e":"lesionarse는 '부상을 당하다'라는 재귀동사로, 명사형 lesión은 '부상'입니다. 'Qué pena(아쉽다)'라는 반응이 나쁜 소식임을 알려 줍니다. 나머지 보기는 모두 '회복하다'라는 긍정적인 뜻입니다.","x":["se recuperó: '회복했다'로 아쉬워할 소식이 아닙니다 ✗","se repuso: '기운을 되찾았다'로 아쉬워할 소식이 아닙니다 ✗","se lesionó: '부상을 당했다'로 아쉬운 소식입니다 → 정답 ✓","se rehabilitó: '재활했다, 회복했다'로 아쉬워할 소식이 아닙니다 ✗"]},{"id":"V300","q":"Está ____ porque se pasa el día en el gimnasio.","o":["griposa","musculosa","canija","resfriada"],"a":1,"k":"체형 형용사","t":"그녀는 하루 종일 헬스장에 있어서 근육질이다.","e":"musculoso/a는 '근육질의'라는 뜻으로 músculo(근육)에서 왔습니다. 'se pasa el día en el gimnasio(하루 종일 헬스장에 있다)'의 결과로 가장 자연스럽습니다. 'pasarse el día + 장소/현재분사'는 '하루 종일 ~하다'라는 표현입니다.","x":["griposa: '독감에 걸린'으로 헬스장에 있는 것과 관련이 없습니다 ✗","musculosa: '근육질의'로 헬스장에서 운동한 결과입니다 → 정답 ✓","canija: '비쩍 마르고 허약한'으로 문맥과 반대입니다 ✗","resfriada: '감기에 걸린'으로 헬스장과 관련이 없습니다 ✗"]},{"id":"V301","q":"Estas patatas fritas ya no están ____ porque se hicieron hace horas.","o":["cocidas","crudas","fritas","crujientes"],"a":3,"k":"음식 식감 형용사","t":"이 감자튀김은 몇 시간 전에 만든 것이라 더 이상 바삭하지 않다.","e":"crujiente는 '바삭바삭한'이라는 뜻으로, 튀김·과자·빵 껍질처럼 씹을 때 소리가 나는 식감을 말합니다. 튀긴 지 오래되어 눅눅해졌다는 내용이므로 'ya no están crujientes(더 이상 바삭하지 않다)'가 자연스럽습니다. 예: El pan está crujiente. (빵이 바삭하다.)","x":["cocidas: '삶은, 익힌'이라는 뜻으로, 감자튀김이 시간이 지나 '익지 않게' 되지는 않으므로 ✗","crudas: '날것의, 익히지 않은'이라는 뜻으로 이미 튀긴 감자에 맞지 않습니다 ✗","fritas: '튀긴'이라는 뜻으로, 시간이 지나도 튀긴 음식임은 변하지 않으므로 ✗","crujientes: '바삭한'이라는 뜻으로 오래되어 눅눅해진 상황과 딱 맞습니다 ✓"]},{"id":"V302","q":"Consiguió la ____ de oro en natación. ¡Todo un logro!","o":["moneda","medalla","pieza","chapa"],"a":1,"k":"스포츠 어휘","t":"그는 수영에서 금메달을 땄다. 정말 대단한 성과다!","e":"medalla de oro는 '금메달'입니다. 은메달은 medalla de plata, 동메달은 medalla de bronce라고 합니다. 'conseguir/ganar una medalla(메달을 따다)'라는 표현을 함께 기억해 두세요.","x":["moneda: '동전'이라는 뜻으로, moneda de oro는 '금화'라서 수영 대회 성과와 맞지 않습니다 ✗","medalla: '메달'이라는 뜻으로 medalla de oro(금메달)가 됩니다 ✓","pieza: '조각, 부품'이라는 뜻으로 대회 시상과 관계없습니다 ✗","chapa: '배지, 금속판, 병뚜껑'이라는 뜻으로 시상품을 가리키지 않습니다 ✗"]},{"id":"V303","q":"Me parece ____ que haya gente que no tenga sus necesidades básicas cubiertas.","o":["indignante","formidable","estupendo","irrelevante"],"a":0,"k":"감정·평가 형용사","t":"기본적인 필요조차 충족되지 않은 사람들이 있다는 것이 나는 분노스럽다고 생각한다.","e":"indignante는 '분개하게 하는, 화가 치미는'이라는 뜻으로, 부당한 일에 대한 도덕적 분노를 나타냅니다. 'Me parece + 형용사 + que + 접속법(바람·감정·평가를 나타낼 때 쓰는 동사 형태)' 구조라서 뒤에 haya, tenga가 왔습니다. 기본 생활이 보장되지 않는 현실에 대한 평가로 가장 알맞습니다.","x":["indignante: '분노스러운, 괘씸한'이라는 뜻으로 부당한 상황에 대한 평가로 딱 맞습니다 ✓","formidable: '훌륭한, 굉장한'이라는 긍정적 의미라 문맥과 반대입니다 ✗","estupendo: '아주 멋진'이라는 긍정적 의미라 맞지 않습니다 ✗","irrelevante: '중요하지 않은'이라는 뜻으로 사회 문제를 하찮게 여기는 말이 되어 어색합니다 ✗"]},{"id":"V304","q":"Pensé que era una meta ____, pero al final pude cumplir mi objetivo.","o":["lamentable","incurable","inalcanzable","irrecuperable"],"a":2,"k":"부정 접두사 in-","t":"도달할 수 없는 목표라고 생각했지만, 결국 나는 목표를 이룰 수 있었다.","e":"inalcanzable은 alcanzar(도달하다, 이루다) + 부정 접두사 in- + -able(~할 수 있는)로 만들어진 '도달할 수 없는'이라는 뜻입니다. 'pero al final pude cumplir(하지만 결국 이뤘다)'와 대조를 이루려면 '불가능해 보이는 목표'라는 말이 필요합니다. meta inalcanzable(이룰 수 없는 목표)은 자주 쓰는 표현입니다.","x":["lamentable: '유감스러운, 한심한'이라는 뜻으로 목표를 묘사하기에 어색합니다 ✗","incurable: '치료할 수 없는'이라는 뜻으로 질병에 쓰는 말입니다 ✗","inalcanzable: '도달할 수 없는'이라는 뜻으로 목표(meta)와 잘 어울립니다 ✓","irrecuperable: '회복할 수 없는, 되찾을 수 없는'이라는 뜻으로 목표와 어울리지 않습니다 ✗"]},{"id":"V305","q":"La ____ prolongada al sol es mala para la piel.","o":["aparición","exposición","exhibición","presentación"],"a":1,"k":"명사 의미 구별","t":"햇볕에 오래 노출되는 것은 피부에 나쁘다.","e":"exposición는 '노출'이라는 뜻으로, exposición al sol(햇볕 노출)처럼 'a + 대상'과 함께 씁니다. 'exposición'은 '전시회'라는 뜻도 있지만 여기서는 피부가 햇빛을 받는 것을 말합니다. 예: Evita la exposición prolongada al sol. (장시간 햇볕 노출을 피하세요.)","x":["aparición: '출현, 나타남'이라는 뜻으로 햇볕과 함께 쓰지 않습니다 ✗","exposición: '노출'이라는 뜻으로 exposición al sol이 정확한 표현입니다 ✓","exhibición: '전시, 시연, 과시'라는 뜻으로 피부가 햇빛을 받는 의미가 없습니다 ✗","presentación: '발표, 소개'라는 뜻으로 문맥과 맞지 않습니다 ✗"]},{"id":"V306","q":"Cuando se supo el notición, corrieron ____ de tinta.","o":["océanos","ríos","lagos","mares"],"a":1,"k":"관용 표현","t":"그 큰 뉴스가 알려지자 엄청난 화제가 되었다(수많은 기사가 쏟아졌다).","e":"'correr ríos de tinta'는 직역하면 '잉크의 강이 흐르다'로, 어떤 사건에 대해 많은 글과 기사가 쓰이고 크게 화제가 된다는 관용 표현입니다. 이 표현은 항상 ríos(강)를 씁니다. notición은 noticia(뉴스)에 확대 접미사 -ón이 붙어 '대형 뉴스'라는 뜻입니다.","x":["océanos: '대양'이라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","ríos: '강'이라는 뜻으로 'correr ríos de tinta'라는 고정 표현을 완성합니다 ✓","lagos: '호수'라는 뜻으로 흐르지 않는 물이라 이 표현에 맞지 않습니다 ✗","mares: '바다'라는 뜻으로 관용 표현의 형태가 아닙니다 ✗"]},{"id":"V307","q":"La ____ del aire en este entorno natural es una maravilla.","o":["polución","pureza","sequedad","suciedad"],"a":1,"k":"환경 어휘","t":"이 자연환경의 공기 맑음은 정말 경이롭다.","e":"pureza는 puro(순수한, 깨끗한)의 명사형으로 '순수함, 깨끗함'이라는 뜻입니다. 'es una maravilla(경이롭다)'라는 긍정적인 평가와 어울리는 것은 공기가 깨끗하다는 의미뿐입니다. pureza del aire(공기의 청정함)는 자주 쓰는 표현입니다.","x":["polución: '오염'이라는 뜻으로 '경이롭다'는 평가와 반대입니다 ✗","pureza: '깨끗함, 순수함'이라는 뜻으로 자연환경의 맑은 공기를 칭찬하는 말이 됩니다 ✓","sequedad: '건조함'이라는 뜻으로 보통 긍정적인 평가 대상이 아닙니다 ✗","suciedad: '더러움'이라는 뜻으로 문맥과 정반대입니다 ✗"]},{"id":"V308","q":"Vamos a ____ los calamares con huevo y harina.","o":["rebozar","salar","hervir","cocer"],"a":0,"k":"요리 동사","t":"오징어에 달걀과 밀가루로 튀김옷을 입히자.","e":"rebozar는 '(튀기기 전에) 달걀·밀가루 등으로 옷을 입히다'라는 뜻입니다. 스페인의 대표 요리 calamares rebozados(오징어 튀김)를 떠올리면 쉽습니다. 'con huevo y harina(달걀과 밀가루로)'라는 재료가 결정적인 단서입니다.","x":["rebozar: '튀김옷을 입히다'라는 뜻으로 달걀·밀가루와 딱 맞습니다 ✓","salar: '소금을 치다, 소금에 절이다'라는 뜻으로 달걀·밀가루와 맞지 않습니다 ✗","hervir: '끓이다'라는 뜻으로 달걀과 밀가루를 입히는 동작이 아닙니다 ✗","cocer: '삶다, 익히다'라는 뜻으로 재료를 묻히는 의미가 없습니다 ✗"]},{"id":"V309","q":"Eloísa vive en una bonita ____ a cinco minutos de aquí.","o":["calzada","barriada","vía","carretera"],"a":1,"k":"도시·주거 어휘","t":"엘로이사는 여기서 5분 거리에 있는 예쁜 동네에 산다.","e":"barriada는 '동네, 주거 구역'이라는 뜻으로 barrio와 비슷한 말입니다. 'vivir en(~에 살다)'과 어울리는 것은 사람이 사는 지역을 나타내는 말입니다. 나머지 보기는 모두 '길, 도로'를 뜻해서 사는 곳으로 쓰기 어렵습니다.","x":["calzada: '차도, 포장도로'라는 뜻으로 사람이 사는 곳이 아닙니다 ✗","barriada: '동네, 주거 구역'이라는 뜻으로 vivir en과 잘 어울립니다 ✓","vía: '길, 선로'라는 뜻으로 거주지로 쓰지 않습니다 ✗","carretera: '(지방) 도로, 국도'라는 뜻으로 사는 곳이 아닙니다 ✗"]},{"id":"V310","q":"Trabajamos de forma totalmente ____, es decir, sin máquinas.","o":["especializada","mecánica","artesanal","automática"],"a":2,"k":"제작 방식 형용사","t":"우리는 완전히 수작업 방식으로, 즉 기계 없이 일한다.","e":"artesanal은 '수공예의, 수작업의'라는 뜻으로, artesano(장인)와 관련된 단어입니다. 'es decir, sin máquinas(즉, 기계 없이)'라는 설명이 정답의 결정적 단서입니다. 예: pan artesanal (수제 빵)","x":["especializada: '전문화된'이라는 뜻으로 기계 사용 여부와 관계없습니다 ✗","mecánica: '기계적인'이라는 뜻으로 '기계 없이'와 반대입니다 ✗","artesanal: '수작업의'라는 뜻으로 '기계 없이'와 정확히 일치합니다 ✓","automática: '자동의'라는 뜻으로 기계를 쓰는 방식이라 반대입니다 ✗"]},{"id":"V311","q":"Tuve que pagar en el aeropuerto por ____ de equipaje.","o":["exageración","exceso","escasez","sobra"],"a":1,"k":"여행 어휘","t":"나는 공항에서 수하물 초과 요금을 내야 했다.","e":"exceso de equipaje는 '수하물 초과'라는 뜻의 고정 표현입니다. exceso는 '초과, 과다'라는 뜻으로 exceso de velocidad(과속), exceso de peso(중량 초과)처럼 쓰입니다. 'pagar por exceso de equipaje(수하물 초과로 돈을 내다)'로 통째로 기억하세요.","x":["exageración: '과장'이라는 뜻으로 말이나 행동을 부풀리는 것이라 짐과 맞지 않습니다 ✗","exceso: '초과'라는 뜻으로 exceso de equipaje(수하물 초과)가 됩니다 ✓","escasez: '부족, 결핍'이라는 뜻으로 돈을 더 내는 상황과 반대입니다 ✗","sobra: '남은 것, 여분'이라는 뜻으로 이 고정 표현에는 쓰지 않습니다 ✗"]},{"id":"V312","q":"Admiro la ____ con la que resuelves los problemas.","o":["bondad","maldad","facilidad","dificultad"],"a":2,"k":"추상 명사","t":"네가 문제를 쉽게 해결하는 능숙함이 존경스럽다.","e":"facilidad는 fácil(쉬운)의 명사형으로 '쉬움, 능숙함, 재능'을 뜻합니다. 'la facilidad con la que...'는 '~하는 능숙함/수월함'이라는 표현입니다. 존경(admiro)의 대상이 되려면 문제를 척척 해결하는 능력이 되어야 합니다.","x":["bondad: '선량함, 친절함'이라는 뜻으로 문제 해결 방식과 연결이 약합니다 ✗","maldad: '악의, 사악함'이라는 뜻으로 존경과 어울리지 않습니다 ✗","facilidad: '능숙함, 수월함'이라는 뜻으로 문제를 쉽게 해결하는 능력을 나타냅니다 ✓","dificultad: '어려움'이라는 뜻으로 존경할 만한 대상이 되지 않습니다 ✗"]},{"id":"V313","q":"A Laura no le cuesta nada ____ nuevas amistades, es muy sociable.","o":["adquirir","alcanzar","entablar","emprender"],"a":2,"k":"동사 연어(짝꿍)","t":"라우라는 새 친구를 사귀는 데 전혀 어려움이 없다. 매우 사교적이다.","e":"entablar는 '(관계·대화를) 시작하다, 맺다'라는 뜻으로 entablar amistad(친분을 맺다), entablar una conversación(대화를 시작하다)처럼 씁니다. 'no le cuesta nada + 동사원형'은 '~하는 것이 전혀 힘들지 않다'라는 표현입니다.","x":["adquirir: '획득하다, 구입하다'라는 뜻으로 물건·지식에 쓰고 친구 관계에는 어색합니다 ✗","alcanzar: '도달하다, 이루다'라는 뜻으로 목표에 쓰지 친구에는 쓰지 않습니다 ✗","entablar: '(관계를) 맺다'라는 뜻으로 entablar amistades가 자연스러운 짝입니다 ✓","emprender: '(사업·여행 등을) 착수하다'라는 뜻으로 친구 관계와 어울리지 않습니다 ✗"]},{"id":"V314","q":"¿Te importaría poner estas flores en ese ____?","o":["bol","jarrón","tarro","tazón"],"a":1,"k":"생활용품 어휘","t":"이 꽃들을 저 꽃병에 꽂아 주시겠어요?","e":"jarrón은 '꽃병, 화병'이라는 뜻입니다. 'jarra(주전자, 물병)'에 확대 접미사가 붙은 형태로, 장식용 큰 병을 말합니다. '¿Te importaría + 동사원형?'은 '~해 주겠니?'라는 공손한 부탁 표현입니다.","x":["bol: '사발, 볼(그릇)'이라는 뜻으로 음식을 담는 그릇입니다 ✗","jarrón: '꽃병'이라는 뜻으로 꽃을 꽂는 용기입니다 ✓","tarro: '(뚜껑 있는) 유리병, 단지'라는 뜻으로 잼·꿀 등을 보관합니다 ✗","tazón: '큰 그릇, 대접(머그)'이라는 뜻으로 수프·시리얼용입니다 ✗"]},{"id":"V315","q":"Me parece muy buena propuesta, pero creo que llevarla a cabo no es ____.","o":["inviable","imposible","impensable","factible"],"a":3,"k":"실현 가능성 형용사","t":"아주 좋은 제안이라고 생각하지만, 그것을 실행하는 것은 실현 가능하지 않다고 본다.","e":"factible은 '실현 가능한'이라는 뜻입니다. 'pero creo que ... no es ____(하지만 ~하지 않다고 생각한다)'에서 부정어 no가 있으므로, 긍정 의미의 단어가 와야 '실현 불가능하다'는 뜻이 됩니다. 나머지 보기는 이미 부정적 의미라 no와 겹치면 오히려 '가능하다'가 되어 'pero'와 맞지 않습니다.","x":["inviable: '실행 불가능한'이라는 뜻이라 no와 함께 쓰면 '실행 가능하다'가 되어 pero의 대조가 깨집니다 ✗","imposible: '불가능한'이라는 뜻이라 no es imposible은 '가능하다'가 되어 맞지 않습니다 ✗","impensable: '생각할 수 없는'이라는 뜻이라 부정과 겹쳐 의미가 어긋납니다 ✗","factible: '실현 가능한'이라는 뜻으로 no es factible(실현 불가능하다)이 문맥에 맞습니다 ✓"]},{"id":"V316","q":"Este bloque no tiene ____, tenemos que ir por las escaleras.","o":["azotea","portería","ascensor","garaje"],"a":2,"k":"건물 시설 어휘","t":"이 건물에는 엘리베이터가 없어서 계단으로 가야 한다.","e":"ascensor는 '엘리베이터'입니다. 'tenemos que ir por las escaleras(계단으로 가야 한다)'가 결정적 단서입니다. bloque는 스페인에서 '아파트 건물, 블록'을 뜻합니다. 참고로 중남미 일부에서는 elevador라고도 합니다.","x":["azotea: '옥상'이라는 뜻으로 계단 이용 여부와 직접 관계없습니다 ✗","portería: '관리실, 경비실'이라는 뜻으로 계단을 써야 하는 이유가 되지 않습니다 ✗","ascensor: '엘리베이터'라는 뜻으로 없으면 계단을 써야 하므로 딱 맞습니다 ✓","garaje: '차고, 주차장'이라는 뜻으로 계단과 관계없습니다 ✗"]},{"id":"V317","q":"Un horario de trabajo flexible permite ____ la vida laboral con la personal.","o":["garantizar","comparar","igualar","compaginar"],"a":3,"k":"일·생활 균형 어휘","t":"유연한 근무 시간은 직장 생활과 개인 생활을 병행할 수 있게 해 준다.","e":"compaginar는 '(두 가지를) 병행하다, 조화시키다'라는 뜻으로 'compaginar A con B(A와 B를 병행하다)' 구조로 씁니다. 일과 삶의 균형(워라밸)을 말할 때 자주 쓰는 동사입니다. 예: Compagino los estudios con el trabajo. (나는 공부와 일을 병행한다.)","x":["garantizar: '보장하다'라는 뜻으로 'A con B' 구조와 어울리지 않습니다 ✗","comparar: '비교하다'라는 뜻으로 유연 근무의 장점을 설명하지 못합니다 ✗","igualar: '같게 하다, 동등하게 만들다'라는 뜻으로 두 생활을 조화시킨다는 의미가 아닙니다 ✗","compaginar: '병행하다'라는 뜻으로 일과 개인 생활을 함께 해 나간다는 의미입니다 ✓"]},{"id":"V318","q":"No hay que huir de los problemas, al contrario, debemos ____.","o":["abordarlos","desdeñarlos","menospreciarlos","alejarlos"],"a":0,"k":"동사 + 대명사 결합","t":"문제로부터 도망쳐서는 안 된다. 반대로 우리는 그것들에 정면으로 맞서야 한다.","e":"abordar는 '(문제를) 다루다, 정면으로 맞서다'라는 뜻입니다. 동사원형 뒤에 직접목적격 대명사(~을/를에 해당) los(=los problemas)가 붙어 abordarlos가 되었습니다. 'huir(도망치다)'와 'al contrario(반대로)'가 있으므로 '맞서다'라는 의미가 필요합니다.","x":["abordarlos: '그것들을 다루다/맞서다'라는 뜻으로 '도망치지 말라'와 대조됩니다 ✓","desdeñarlos: '그것들을 경멸하다, 무시하다'라는 뜻으로 '반대로'의 대조가 성립하지 않습니다 ✗","menospreciarlos: '그것들을 과소평가하다'라는 뜻으로 해결 의지와 맞지 않습니다 ✗","alejarlos: '그것들을 멀리하다'라는 뜻으로 도망치는 것과 비슷한 의미라 맞지 않습니다 ✗"]},{"id":"V319","q":"En algunos países es obligatorio dejar ____ a los camareros.","o":["un obsequio","una ofrenda","un donativo","una propina"],"a":3,"k":"식당 어휘","t":"어떤 나라에서는 웨이터에게 팁을 남기는 것이 의무다.","e":"propina는 '팁, 봉사료'라는 뜻으로, 'dejar propina(팁을 남기다)'가 자주 쓰는 표현입니다. 웨이터(camareros)에게 서비스 대가로 주는 돈이라는 문맥에 맞습니다. 참고로 중남미에서는 웨이터를 mesero라고도 합니다.","x":["un obsequio: '선물'이라는 뜻으로 서비스 대가의 돈이 아닙니다 ✗","una ofrenda: '(신에게 바치는) 제물, 헌물'이라는 뜻으로 맞지 않습니다 ✗","un donativo: '기부금'이라는 뜻으로 자선 단체 등에 내는 돈입니다 ✗","una propina: '팁'이라는 뜻으로 웨이터에게 남기는 돈입니다 ✓"]},{"id":"V320","q":"No creo en los videntes, nadie puede ____ el futuro.","o":["conquistar","añorar","adivinar","atraer"],"a":2,"k":"동사 의미 구별","t":"나는 점쟁이를 믿지 않는다. 아무도 미래를 맞힐 수 없다.","e":"adivinar는 '알아맞히다, 점치다, 예언하다'라는 뜻입니다. vidente(예지자, 점쟁이)와 el futuro(미래)라는 단어가 단서입니다. adivino(점쟁이), adivinanza(수수께끼)도 같은 가족 단어입니다.","x":["conquistar: '정복하다'라는 뜻으로 미래를 '예측'하는 의미가 아닙니다 ✗","añorar: '그리워하다'라는 뜻으로 과거에 대해 주로 쓰고 문맥과 맞지 않습니다 ✗","adivinar: '알아맞히다, 점치다'라는 뜻으로 점쟁이에 대한 이야기와 맞습니다 ✓","atraer: '끌어당기다'라는 뜻으로 미래 예측과 관계없습니다 ✗"]},{"id":"V321","q":"Mis abuelos, que eran ____, apenas iban a la ciudad.","o":["campesinos","urbanitas","residentes","capitalinos"],"a":0,"k":"사람 어휘","t":"농부였던 우리 조부모님은 도시에 거의 가지 않으셨다.","e":"campesino는 '농부, 시골 사람'이라는 뜻으로 campo(시골, 들판)에서 왔습니다. 'apenas iban a la ciudad(도시에 거의 가지 않았다)'라는 내용으로 시골 사람이었음을 알 수 있습니다. apenas는 '거의 ~않다'라는 뜻입니다.","x":["campesinos: '농부, 시골 사람'이라는 뜻으로 도시에 거의 안 간 이유가 됩니다 ✓","urbanitas: '도시 사람'이라는 뜻으로 문맥과 반대입니다 ✗","residentes: '거주자'라는 뜻으로 어디 사는지 알려 주지 않아 이유가 되지 않습니다 ✗","capitalinos: '수도 사람'이라는 뜻으로 도시에 산다는 의미라 반대입니다 ✗"]},{"id":"V322","q":"Habéis jugado muy bien, por eso sois los ____.","o":["campeones","perdedores","fracasados","perjudicados"],"a":0,"k":"스포츠 어휘","t":"너희는 경기를 아주 잘했다. 그래서 너희가 챔피언이다.","e":"campeón은 '챔피언, 우승자'라는 뜻이며 복수형은 campeones(악센트가 사라짐)입니다. 'Habéis jugado muy bien, por eso(아주 잘했다, 그래서)'라는 인과 관계를 보면 긍정적인 결과가 필요합니다. habéis, sois는 스페인에서 쓰는 vosotros 형태이고, 중남미에서는 'Han jugado... son'처럼 ustedes를 씁니다.","x":["campeones: '챔피언들'이라는 뜻으로 잘한 결과로 자연스럽습니다 ✓","perdedores: '패자들'이라는 뜻으로 잘했다는 내용과 반대입니다 ✗","fracasados: '실패자들'이라는 뜻으로 문맥과 반대입니다 ✗","perjudicados: '피해자들, 손해 본 사람들'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V323","q":"Es un ____, en dos días ha roto dos platos y un vaso.","o":["descarado","pelele","genio","manazas"],"a":3,"k":"사람 성격 어휘","t":"그는 손재주가 엉망이다(덜렁이다). 이틀 만에 접시 두 개와 컵 하나를 깼다.","e":"manazas는 '손재주 없는 사람, 서투른 사람(덜렁이)'이라는 구어 표현입니다. mano(손)에 확대 접미사가 붙은 말로, 단수·복수 형태가 같아 'un manazas'로 씁니다. 그릇을 연달아 깬 상황과 정확히 어울립니다.","x":["descarado: '뻔뻔한 사람'이라는 뜻으로 그릇을 깨는 것과 관계없습니다 ✗","pelele: '꼭두각시, 줏대 없는 사람'이라는 뜻으로 맞지 않습니다 ✗","genio: '천재'라는 뜻으로 그릇을 깨는 서투름과 반대입니다(반어로도 정답 아님) ✗","manazas: '손이 서투른 사람'이라는 뜻으로 접시를 깨는 상황에 딱 맞습니다 ✓"]},{"id":"V324","q":"Súbete ____ del pantalón, de lo contrario harás el ridículo.","o":["la cremallera","la cadena","el botón","el bolsillo"],"a":0,"k":"의류 부속 어휘","t":"바지 지퍼 올려. 안 그러면 창피당할 거야.","e":"cremallera는 '지퍼'라는 뜻이며 'subirse/bajarse la cremallera(지퍼를 올리다/내리다)'로 씁니다. subir(올리다)라는 동사와 어울리는 것은 지퍼뿐입니다. 참고로 중남미에서는 cierre, zíper라고도 합니다.","x":["la cremallera: '지퍼'라는 뜻으로 '올리다(subir)'와 딱 맞습니다 ✓","la cadena: '사슬, 체인'이라는 뜻으로 바지 부품이 아닙니다 ✗","el botón: '단추'라는 뜻으로 '올리는' 것이 아니라 '채우는(abrochar)' 것이라 ✗","el bolsillo: '주머니'라는 뜻으로 올리는 대상이 아닙니다 ✗"]},{"id":"V325","q":"No soporto la ____, me parece una falta de respeto.","o":["amabilidad","fraternidad","impuntualidad","cordialidad"],"a":2,"k":"태도 관련 명사","t":"나는 시간을 안 지키는 것을 참을 수 없다. 그것은 무례하다고 생각한다.","e":"impuntualidad는 puntual(시간을 잘 지키는)에 부정 접두사 im-이 붙은 명사로 '시간을 안 지킴, 지각'이라는 뜻입니다. 'No soporto(참을 수 없다)', 'falta de respeto(무례함)'라는 부정적 평가와 어울리는 것은 이것뿐입니다.","x":["amabilidad: '친절함'이라는 뜻으로 무례하다는 평가와 반대입니다 ✗","fraternidad: '형제애, 우애'라는 뜻으로 긍정적이라 맞지 않습니다 ✗","impuntualidad: '시간을 안 지킴'이라는 뜻으로 무례하다고 볼 만한 행동입니다 ✓","cordialidad: '정중함, 다정함'이라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V326","q":"¡Qué ____ pasé cuando me caí en plena calle!","o":["vergüenza","calor","hambre","calvario"],"a":0,"k":"감정 표현","t":"길 한복판에서 넘어졌을 때 얼마나 창피했는지 몰라!","e":"'pasar vergüenza'는 '창피를 당하다'라는 표현입니다. 'en plena calle(길 한복판에서)' 넘어진 상황이므로 부끄러움이 가장 자연스럽습니다. '¡Qué + 명사 + 동사!'는 '정말 ~했다!'라는 감탄문입니다.","x":["vergüenza: '부끄러움, 창피'라는 뜻으로 길에서 넘어진 상황에 맞습니다 ✓","calor: '더위'라는 뜻으로 pasar calor(더위를 겪다)는 가능하지만 넘어진 것과 관계없습니다 ✗","hambre: '배고픔'이라는 뜻으로 넘어진 것과 관계없습니다 ✗","calvario: '고난, 시련'이라는 뜻으로 한 번 넘어진 일로는 과장되고 어색합니다 ✗"]},{"id":"V327","q":"Esta actriz ____ bien en todos los papeles que le ofrecen.","o":["actúa","compite","pinta","juega"],"a":0,"k":"공연 관련 동사","t":"이 여배우는 제안받는 모든 역할에서 연기를 잘한다.","e":"actuar는 '연기하다'라는 뜻으로, actriz(여배우)·papel(역할)과 짝을 이룹니다. 3인칭 단수 현재형 actúa는 ú에 악센트가 있다는 점에 주의하세요. papel은 '종이' 외에 '배역, 역할'이라는 뜻도 있습니다.","x":["actúa: '연기하다'라는 뜻으로 배우와 역할에 딱 맞습니다 ✓","compite: '경쟁하다'라는 뜻으로 배역을 연기하는 의미가 아닙니다 ✗","pinta: '그리다, 칠하다'라는 뜻으로 배우와 관계없습니다 ✗","juega: '놀다, 경기하다'라는 뜻으로 스페인어에서는 배역 연기에 쓰지 않습니다 ✗"]},{"id":"V328","q":"A la hora del ____ muchos alumnos salen al patio como locos.","o":["alto","espectáculo","desfile","recreo"],"a":3,"k":"학교 어휘","t":"쉬는 시간이 되면 많은 학생들이 미친 듯이 운동장으로 뛰어나간다.","e":"recreo는 '(학교의) 쉬는 시간'이라는 뜻입니다. 'a la hora del recreo(쉬는 시간에)'와 patio(운동장, 안뜰)가 함께 쓰이는 전형적인 학교 표현입니다. recrear(즐겁게 하다)와 같은 어원입니다.","x":["alto: '정지, 멈춤'이라는 뜻으로 hacer un alto(잠시 멈추다)처럼 쓰고 학교 쉬는 시간을 뜻하지 않습니다 ✗","espectáculo: '공연, 쇼'라는 뜻으로 학생들이 운동장에 나가는 시간이 아닙니다 ✗","desfile: '행진, 퍼레이드'라는 뜻으로 맞지 않습니다 ✗","recreo: '쉬는 시간'이라는 뜻으로 학생들이 운동장에 나가는 상황에 맞습니다 ✓"]},{"id":"V329","q":"Los asesinos ____ del cadáver echándolo al mar.","o":["se deshicieron","se vengaron","abusaron","se encargaron"],"a":0,"k":"대명동사 + de","t":"살인범들은 시체를 바다에 던져서 처리했다(없앴다).","e":"deshacerse de는 '~을 처분하다, 없애다'라는 대명동사(재귀대명사 se와 함께 쓰는 동사)입니다. deshacer의 과거형이 hacer처럼 불규칙이라 se deshicieron이 됩니다. 'echándolo al mar(바다에 던져서)'라는 방법이 단서입니다.","x":["se deshicieron: '~을 없앴다'라는 뜻으로 시체를 처리한 상황에 맞습니다 ✓","se vengaron: '복수했다'라는 뜻으로 'vengarse de + 사람'이라 시체와 맞지 않습니다 ✗","abusaron: '남용했다, 학대했다'라는 뜻으로 시체를 바다에 던진 행동과 맞지 않습니다 ✗","se encargaron: '맡았다, 담당했다'라는 뜻으로 'encargarse de'는 '처리를 맡다'일 뿐 '없애다'가 아닙니다 ✗"]},{"id":"V330","q":"No fue un pintor ____, pues solo pintó una decena de cuadros.","o":["reconocible","prolífico","anónimo","de renombre"],"a":1,"k":"인물 평가 형용사","t":"그는 다작하는 화가가 아니었다. 그림을 열 점 정도밖에 그리지 않았기 때문이다.","e":"prolífico는 '다작하는, 작품을 많이 내는'이라는 뜻입니다. 'pues solo pintó una decena de cuadros(그림을 10점 정도밖에 안 그렸으니까)'는 작품 수에 대한 이유이므로, 작품의 양을 말하는 단어가 필요합니다. pues는 여기서 '왜냐하면'이라는 뜻입니다.","x":["reconocible: '알아볼 수 있는'이라는 뜻으로 작품 수와 관계없습니다 ✗","prolífico: '다작하는'이라는 뜻으로 작품이 적었다는 이유와 정확히 연결됩니다 ✓","anónimo: '익명의'라는 뜻으로 작품 수와 관계없습니다 ✗","de renombre: '유명한'이라는 뜻으로 작품이 적다고 해서 유명하지 않은 것은 아니므로 ✗"]},{"id":"V331","q":"Isa es una mujer tranquila; su hermana, en cambio, es muy ____.","o":["temperamental","conservadora","tacaña","cotilla"],"a":0,"k":"성격 형용사","t":"이사는 차분한 여자다. 반면 그녀의 언니는 매우 감정 기복이 심하다.","e":"temperamental은 '감정 기복이 심한, 다혈질의, 변덕스러운'이라는 뜻입니다. 'en cambio(반면에)'는 대조를 나타내므로 tranquila(차분한)와 반대되는 성격이 와야 합니다. temperamento(기질)에서 나온 단어입니다.","x":["temperamental: '감정 기복이 심한, 다혈질의'라는 뜻으로 '차분한'과 대조됩니다 ✓","conservadora: '보수적인'이라는 뜻으로 '차분한'의 반대 개념이 아닙니다 ✗","tacaña: '인색한, 구두쇠의'라는 뜻으로 차분함과 대조되지 않습니다 ✗","cotilla: '수다쟁이, 남의 말 하기 좋아하는'이라는 뜻으로 차분함의 반대가 아닙니다 ✗"]},{"id":"V332","q":"Lo cesaron de su puesto porque su comportamiento era ____ de un director.","o":["impropio","propio","digno","característico"],"a":0,"k":"형용사 + de","t":"그의 행동은 이사에게 어울리지 않았기 때문에 그는 자리에서 해임되었다.","e":"impropio de는 '~에게 어울리지 않는, ~답지 않은'이라는 뜻입니다. 해임(lo cesaron)된 이유이므로 부정적인 평가가 필요합니다. 반대로 propio de는 '~다운, ~특유의'라는 뜻입니다. 예: Es un error impropio de un experto. (전문가답지 않은 실수다.)","x":["impropio: '~답지 않은'이라는 뜻으로 해임 이유로 자연스럽습니다 ✓","propio: '~다운, ~특유의'라는 뜻으로 해임 이유가 되지 않습니다 ✗","digno: '~에 걸맞은, 합당한'이라는 뜻으로 긍정적이라 해임과 맞지 않습니다 ✗","característico: '~의 특징적인'이라는 뜻으로 해임 이유로는 어색합니다 ✗"]},{"id":"V333","q":"Ese tipo de pantalones está ____ de moda, ahora se llevan otros estilos.","o":["acabado","finalizado","pasado","terminado"],"a":2,"k":"관용 표현","t":"그런 종류의 바지는 유행이 지났다. 지금은 다른 스타일이 유행한다.","e":"'pasado de moda'는 '유행이 지난'이라는 고정 표현입니다. 반대로 '유행하는'은 'de moda' 또는 'llevarse'(유행하다)를 씁니다. 문장 뒤의 'ahora se llevan otros estilos(지금은 다른 스타일이 유행한다)'도 같은 의미입니다.","x":["acabado: '끝난, 마무리된'이라는 뜻으로 'de moda'와 고정 표현을 이루지 않습니다 ✗","finalizado: '종료된'이라는 뜻으로 공식적인 행사·절차에 씁니다 ✗","pasado: 'pasado de moda(유행이 지난)'라는 고정 표현을 완성합니다 ✓","terminado: '끝난'이라는 뜻으로 유행에 대해서는 쓰지 않습니다 ✗"]},{"id":"V334","q":"Usa este ____ para quitarle el agua a la pasta.","o":["batidor","pelador","escurridor","cucharón"],"a":2,"k":"주방 도구 어휘","t":"파스타의 물기를 빼려면 이 채반을 써.","e":"escurridor는 '채반, 물기 빼는 그릇'이라는 뜻으로 escurrir(물기를 빼다)에서 왔습니다. 스페인어는 도구 이름에 -dor 접미사를 자주 씁니다(batidor 거품기, pelador 필러). 'quitarle el agua a la pasta(파스타의 물을 빼다)'라는 용도가 단서입니다.","x":["batidor: '거품기'라는 뜻으로 휘젓는 도구입니다 ✗","pelador: '껍질 벗기는 칼(필러)'이라는 뜻으로 물을 빼는 도구가 아닙니다 ✗","escurridor: '채반'이라는 뜻으로 파스타 물기를 빼는 도구입니다 ✓","cucharón: '국자'라는 뜻으로 국물을 뜨는 도구입니다 ✗"]},{"id":"V335","q":"Siempre he tenido ____, concretamente perros y gatos.","o":["fieras","bestias","animales salvajes","mascotas"],"a":3,"k":"동물 어휘","t":"나는 항상 반려동물을 키워 왔다. 구체적으로 말하면 개와 고양이다.","e":"mascota는 '반려동물, 애완동물'이라는 뜻입니다. 'concretamente perros y gatos(구체적으로 개와 고양이)'라는 설명이 결정적 단서입니다. mascota는 '(팀·행사의) 마스코트'라는 뜻도 있습니다.","x":["fieras: '맹수'라는 뜻으로 개와 고양이를 가리키지 않습니다 ✗","bestias: '짐승, 야수'라는 뜻으로 반려동물에 쓰지 않습니다 ✗","animales salvajes: '야생동물'이라는 뜻으로 개·고양이와 맞지 않습니다 ✗","mascotas: '반려동물'이라는 뜻으로 개와 고양이를 정확히 가리킵니다 ✓"]},{"id":"V336","q":"El día que me puse por primera vez la ____ de médico fue muy especial.","o":["corbata","camisa","blusa","bata"],"a":3,"k":"의류 어휘","t":"내가 처음으로 의사 가운을 입은 날은 아주 특별했다.","e":"bata는 '가운'이라는 뜻으로, bata de médico(의사 가운), bata blanca(흰 가운)처럼 씁니다. 집에서 입는 '실내 가운'도 bata라고 합니다. 'ponerse(입다)'와 함께 쓰는 표현입니다.","x":["corbata: '넥타이'라는 뜻으로 의사를 상징하는 옷이 아닙니다 ✗","camisa: '셔츠'라는 뜻으로 의사 고유의 옷이 아닙니다 ✗","blusa: '블라우스'라는 뜻으로 의사 복장과 관계없습니다 ✗","bata: '가운'이라는 뜻으로 bata de médico(의사 가운)가 됩니다 ✓"]},{"id":"V337","q":"El ____ es un juego de mesa.","o":["tiro al blanco","boxeo","ajedrez","voleibol"],"a":2,"k":"게임·스포츠 어휘","t":"체스는 보드게임이다.","e":"ajedrez는 '체스'로, juego de mesa(보드게임, 탁상 게임)의 대표적인 예입니다. juego de mesa는 직역하면 '탁자 위의 게임'입니다. 나머지는 모두 몸을 쓰는 스포츠입니다.","x":["tiro al blanco: '사격, 과녁 맞히기'라는 뜻으로 보드게임이 아닙니다 ✗","boxeo: '권투'라는 뜻으로 격투 스포츠입니다 ✗","ajedrez: '체스'라는 뜻으로 대표적인 보드게임입니다 ✓","voleibol: '배구'라는 뜻으로 구기 종목입니다 ✗"]},{"id":"V338","q":"Para suavizar el cabello ____, te recomiendo usar aceite de coco.","o":["cuidado","manejable","sedoso","áspero"],"a":3,"k":"머릿결 형용사","t":"거친 머리카락을 부드럽게 하려면 코코넛 오일을 쓰는 것을 추천해.","e":"áspero는 '거친, 까칠한'이라는 뜻으로 촉감이 부드럽지 않은 것을 말합니다. 'Para suavizar(부드럽게 하려면)'라는 목적이 있으므로, 원래 상태는 부드럽지 않아야 논리가 맞습니다. 예: piel áspera (거친 피부)","x":["cuidado: '손질된, 관리된'이라는 뜻으로 이미 좋은 상태라 부드럽게 할 필요가 없습니다 ✗","manejable: '다루기 쉬운'이라는 뜻으로 해결할 문제가 아닙니다 ✗","sedoso: '비단 같은, 윤기 있는'이라는 뜻으로 이미 부드러운 상태라 맞지 않습니다 ✗","áspero: '거친'이라는 뜻으로 부드럽게 만들어야 할 상태입니다 ✓"]},{"id":"V339","q":"Solo ____ a ser feliz en la vida, no me interesa lo material.","o":["recurro","me niego","aspiro","me arriesgo"],"a":2,"k":"동사 + 전치사 a","t":"나는 인생에서 오직 행복해지기만을 바란다. 물질적인 것엔 관심이 없다.","e":"aspirar a는 '~을 열망하다, 지향하다'라는 뜻으로 'aspirar a + 명사/동사원형'으로 씁니다. 삶의 목표를 말하는 문맥이라 가장 자연스럽습니다. aspirar는 '(공기를) 들이마시다'라는 뜻도 있습니다.","x":["recurro: 'recurrir a'는 '~에 의지하다, 호소하다'라는 뜻으로 행복을 목표로 하는 의미가 아닙니다 ✗","me niego: 'negarse a'는 '~하기를 거부하다'라는 뜻으로 문맥과 반대입니다 ✗","aspiro: 'aspirar a'는 '~을 열망하다'라는 뜻으로 인생의 목표를 나타냅니다 ✓","me arriesgo: 'arriesgarse a'는 '~할 위험을 무릅쓰다'라는 뜻으로 행복과 어울리지 않습니다 ✗"]},{"id":"V340","q":"Aprobé el examen teórico y ahora me queda la parte ____.","o":["válida","concreta","real","práctica"],"a":3,"k":"시험 관련 어휘","t":"나는 필기시험에 합격했고 이제 실기 부분이 남았다.","e":"práctico는 '실습의, 실기의'라는 뜻으로 teórico(이론의)와 짝을 이룹니다. 운전면허 시험처럼 examen teórico(필기시험)와 examen práctico(실기시험)로 나뉘는 상황입니다. 'me queda...'는 '~이 남아 있다'라는 뜻입니다.","x":["válida: '유효한'이라는 뜻으로 시험의 한 부분을 가리키지 않습니다 ✗","concreta: '구체적인'이라는 뜻으로 teórico의 짝이 아닙니다 ✗","real: '실제의, 진짜의'라는 뜻으로 시험 구분에 쓰지 않습니다 ✗","práctica: '실기의'라는 뜻으로 teórico(이론)와 대비됩니다 ✓"]},{"id":"V341","q":"Alberto es muy buena persona, siempre está ____ a ayudar a quien lo necesita.","o":["aficionado","acostumbrado","habituado","dispuesto"],"a":3,"k":"형용사 + a","t":"알베르토는 정말 좋은 사람이다. 항상 도움이 필요한 사람을 도울 준비가 되어 있다.","e":"estar dispuesto a는 '~할 준비가 되어 있다, 기꺼이 ~하다'라는 뜻입니다. 좋은 사람(buena persona)이라는 설명과 잘 어울립니다. 예: Estoy dispuesto a ayudarte. (기꺼이 너를 도와줄게.)","x":["aficionado: 'aficionado a'는 '~을 좋아하는, ~의 팬인'이라는 뜻으로 보통 명사(취미)와 씁니다 ✗","acostumbrado: 'acostumbrado a'는 '~에 익숙한'이라는 뜻으로 좋은 성품을 나타내지 않습니다 ✗","habituado: 'habituado a'는 '~에 익숙해진'이라는 뜻으로 맞지 않습니다 ✗","dispuesto: 'dispuesto a'는 '기꺼이 ~할 준비가 된'이라는 뜻으로 착한 성품에 맞습니다 ✓"]},{"id":"V342","q":"Con esta ____ de pan podemos hacer dos bocadillos.","o":["migaja","rebanada","barra","miga"],"a":2,"k":"빵 관련 어휘","t":"이 바게트 하나로 샌드위치 두 개를 만들 수 있다.","e":"barra de pan은 '긴 빵(바게트) 한 개'를 말합니다. bocadillo는 스페인식 바게트 샌드위치라서 바게트 한 개를 반으로 나누면 두 개를 만들 수 있습니다. 빵을 세는 단위 표현으로 함께 기억하세요.","x":["migaja: '빵 부스러기'라는 뜻으로 샌드위치를 만들 수 없습니다 ✗","rebanada: '(빵) 한 조각, 슬라이스'라는 뜻으로 한 조각으로 샌드위치 두 개는 어렵습니다 ✗","barra: '(빵의) 긴 덩어리'라는 뜻으로 barra de pan(바게트)이 됩니다 ✓","miga: '빵 속살, 부스러기'라는 뜻으로 샌드위치 재료가 되지 않습니다 ✗"]},{"id":"V343","q":"No me gusta la ropa de colores ____, prefiero los tonos discretos.","o":["apagados","suaves","oscuros","vistosos"],"a":3,"k":"색상 형용사","t":"나는 화려한 색 옷을 좋아하지 않는다. 차분한 색조를 더 좋아한다.","e":"vistoso는 '눈에 띄는, 화려한'이라는 뜻으로 ver(보다), vista(시선)와 관련된 단어입니다. 'prefiero los tonos discretos(차분한 색조를 선호한다)'와 대조되어야 하므로 화려한 색이 와야 합니다.","x":["apagados: '칙칙한, 차분한'이라는 뜻으로 discreto와 비슷해 대조가 되지 않습니다 ✗","suaves: '부드러운, 연한'이라는 뜻으로 차분한 색과 비슷합니다 ✗","oscuros: '어두운'이라는 뜻으로 차분한 색에 가까워 대조가 되지 않습니다 ✗","vistosos: '화려한, 눈에 띄는'이라는 뜻으로 '차분한 색'과 대조됩니다 ✓"]},{"id":"V344","q":"¿Quién fue el ____ de esta empresa?","o":["instigador","descubridor","fundador","inventor"],"a":2,"k":"사람 명사","t":"이 회사의 창립자는 누구였나요?","e":"fundador는 fundar(설립하다)에서 온 말로 '창립자, 설립자'라는 뜻입니다. 회사(empresa)·단체·도시를 세운 사람에게 씁니다. 동사에 -dor를 붙이면 '~하는 사람'이 됩니다.","x":["instigador: '선동자, 부추기는 사람'이라는 뜻으로 부정적 의미라 맞지 않습니다 ✗","descubridor: '발견자'라는 뜻으로 대륙·현상 등을 찾아낸 사람에게 씁니다 ✗","fundador: '창립자'라는 뜻으로 회사를 세운 사람입니다 ✓","inventor: '발명가'라는 뜻으로 물건을 발명한 사람에게 씁니다 ✗"]},{"id":"V345","q":"El teclado de mi ____ es inalámbrico.","o":["proyector","celular","móvil","portátil"],"a":3,"k":"전자기기 어휘","t":"내 노트북의 키보드는 무선이다.","e":"portátil은 '휴대용의'라는 형용사이지만, 스페인에서는 명사로 '노트북 컴퓨터(ordenador portátil)'를 뜻합니다. teclado(키보드)와 inalámbrico(무선의)가 단서입니다. 중남미에서는 laptop, computadora portátil이라고도 합니다.","x":["proyector: '프로젝터'라는 뜻으로 키보드가 달린 기기가 아닙니다 ✗","celular: '휴대폰(중남미식)'이라는 뜻으로 별도의 무선 키보드가 있는 기기가 아닙니다 ✗","móvil: '휴대폰(스페인식)'이라는 뜻으로 키보드와 맞지 않습니다 ✗","portátil: '노트북'이라는 뜻으로 키보드가 있는 기기입니다 ✓"]},{"id":"V346","q":"Nadie debería vivir en un lugar tan aislado e ____.","o":["impresionante","impecable","inhóspito","inconfundible"],"a":2,"k":"장소 묘사 형용사","t":"누구도 그렇게 고립되고 살기 힘든 곳에서 살아서는 안 된다.","e":"inhóspito는 '살기 힘든, 황량한, 사람을 반기지 않는'이라는 뜻으로 hospitalidad(환대)의 반대 개념입니다. aislado(고립된)와 'e'로 연결되어 비슷한 부정적 의미가 이어져야 합니다. y는 i-, hi- 로 시작하는 단어 앞에서 e로 바뀝니다.","x":["impresionante: '인상적인, 굉장한'이라는 뜻으로 '살면 안 된다'는 이유가 되지 않습니다 ✗","impecable: '흠잡을 데 없는'이라는 뜻으로 긍정적이라 맞지 않습니다 ✗","inhóspito: '살기 힘든, 황량한'이라는 뜻으로 고립된 장소와 잘 어울립니다 ✓","inconfundible: '틀림없는, 혼동할 수 없는'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V347","q":"Algo raro está pasando... Aquí hay ____ encerrado.","o":["perro","cerdo","gallo","gato"],"a":3,"k":"동물 관용 표현","t":"뭔가 이상한 일이 벌어지고 있어... 여기엔 뭔가 꿍꿍이가 있어.","e":"'aquí hay gato encerrado'는 직역하면 '여기 고양이가 갇혀 있다'로, '뭔가 숨겨진 속임수/수상한 점이 있다'는 관용 표현입니다. 'Algo raro está pasando(뭔가 이상한 일이 일어나고 있다)'와 같은 맥락입니다. 이 표현은 반드시 gato를 씁니다.","x":["perro: '개'라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","cerdo: '돼지'라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","gallo: '수탉'이라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","gato: '고양이'로 'hay gato encerrado(꿍꿍이가 있다)'를 완성합니다 ✓"]},{"id":"V348","q":"Después de leer la primera unidad del libro harán un ____ resumiendo su contenido.","o":["ensayo","relato","análisis","esquema"],"a":3,"k":"학습 활동 어휘","t":"책의 1단원을 읽은 뒤 그들은 내용을 요약하는 개요도를 만들 것이다.","e":"esquema는 '개요, 도식, 요약표'라는 뜻으로, 내용을 핵심만 정리할 때 씁니다. 'hacer un esquema(개요를 만들다)'는 학교에서 자주 쓰는 표현입니다. 'resumiendo su contenido(내용을 요약하면서)'가 단서입니다.","x":["ensayo: '에세이, 논문'이라는 뜻으로 요약이 아니라 자기 생각을 펼치는 글입니다 ✗","relato: '이야기, 단편'이라는 뜻으로 창작 서사라 요약과 맞지 않습니다 ✗","análisis: '분석'이라는 뜻으로 요약보다 깊이 따져 보는 작업입니다 ✗","esquema: '개요, 도식'이라는 뜻으로 내용을 요약 정리하는 것입니다 ✓"]},{"id":"V349","q":"Ese tío es un ____, no tiene ni un mínimo de educación.","o":["ladrón","estafador","delincuente","impresentable"],"a":3,"k":"사람 평가 어휘","t":"그 녀석은 정말 막돼먹은 사람이야. 최소한의 예의도 없어.","e":"impresentable은 직역하면 '내놓을 수 없는'으로, '예의 없고 창피한 사람, 막돼먹은 사람'을 뜻하는 구어 표현입니다. 'no tiene ni un mínimo de educación(최소한의 예의도 없다)'와 정확히 연결됩니다. tío는 스페인 구어에서 '녀석, 놈'이라는 뜻입니다.","x":["ladrón: '도둑'이라는 뜻으로 예의 문제가 아니라 범죄입니다 ✗","estafador: '사기꾼'이라는 뜻으로 예의 없는 것과는 다릅니다 ✗","delincuente: '범죄자'라는 뜻으로 예의 부족을 말하는 문맥과 맞지 않습니다 ✗","impresentable: '막돼먹은, 창피한 사람'이라는 뜻으로 예의 없는 사람을 가리킵니다 ✓"]},{"id":"V350","q":"¡Devuélvele el juguete a Pablito ____!","o":["tranquilamente","inmediatamente","repentinamente","lentamente"],"a":1,"k":"부사 의미","t":"파블리토에게 장난감 당장 돌려줘!","e":"inmediatamente는 '즉시, 당장'이라는 뜻입니다. 명령문과 느낌표로 강하게 재촉하는 상황이므로 '당장'이 가장 자연스럽습니다. 형용사 inmediato에 -mente를 붙여 부사가 됩니다.","x":["tranquilamente: '침착하게, 느긋하게'라는 뜻으로 재촉하는 명령과 맞지 않습니다 ✗","inmediatamente: '즉시'라는 뜻으로 강한 명령과 잘 어울립니다 ✓","repentinamente: '갑자기'라는 뜻으로 예상치 못한 일을 묘사할 때 쓰고 명령에는 어색합니다 ✗","lentamente: '천천히'라는 뜻으로 재촉하는 상황과 반대입니다 ✗"]},{"id":"V351","q":"Los camellos tienen cuatro ____.","o":["piernas","ancas","patas","tentáculos"],"a":2,"k":"신체 부위 어휘","t":"낙타는 다리가 네 개다.","e":"pata는 '동물의 다리(발)'를 말합니다. 스페인어는 사람의 다리는 pierna, 동물의 다리는 pata로 구별합니다. 사람에게 pata를 쓰면 농담조가 됩니다(예: meter la pata 실수하다).","x":["piernas: '(사람의) 다리'라는 뜻으로 동물에는 보통 쓰지 않습니다 ✗","ancas: '(말 등의) 엉덩이, 뒷다리 윗부분'이라는 뜻으로 네 개가 아닙니다 ✗","patas: '(동물의) 다리'라는 뜻으로 낙타에 맞습니다 ✓","tentáculos: '촉수'라는 뜻으로 문어 등에 쓰는 말입니다 ✗"]},{"id":"V352","q":"En los muros ____ la vigilancia es constante.","o":["fronterizos","huidizos","pasadizos","levadizos"],"a":0,"k":"접미사 -izo 형용사","t":"국경 장벽에서는 감시가 끊임없이 이루어진다.","e":"fronterizo는 frontera(국경)의 형용사로 '국경의'라는 뜻입니다. 국경 벽(muros fronterizos)이라서 감시(vigilancia)가 계속된다는 의미가 자연스럽습니다. 보기 모두 -izo로 끝나니 어근의 뜻을 확인하는 것이 핵심입니다.","x":["fronterizos: '국경의'라는 뜻으로 감시가 이루어지는 장벽에 맞습니다 ✓","huidizos: '잘 도망가는, 수줍은'이라는 뜻으로 벽에 쓸 수 없습니다 ✗","pasadizos: '통로'라는 뜻의 명사라 muros를 꾸밀 수 없습니다 ✗","levadizos: '들어 올릴 수 있는'이라는 뜻으로 puente levadizo(도개교)처럼 다리에 쓰입니다 ✗"]},{"id":"V353","q":"No supe responder a la pregunta del profesor porque estaba ____.","o":["desilusionada","descontenta","decepcionada","descolocada"],"a":3,"k":"감정 상태 형용사","t":"나는 당황해(정신이 없어) 있었기 때문에 선생님의 질문에 대답하지 못했다.","e":"descolocado는 '당황한, 어리둥절한, 허를 찔린'이라는 뜻의 구어 표현입니다. colocar(제자리에 두다)의 반대라서 '제자리에서 벗어난' 느낌입니다. 질문에 대답하지 못한 이유로는 정신이 혼란스러운 상태가 가장 알맞습니다.","x":["desilusionada: '실망한'이라는 뜻으로 대답하지 못한 이유가 되기 어렵습니다 ✗","descontenta: '불만스러운'이라는 뜻으로 대답 못한 이유와 연결되지 않습니다 ✗","decepcionada: '실망한'이라는 뜻으로 질문에 답 못하는 상황과 맞지 않습니다 ✗","descolocada: '당황한, 어리둥절한'이라는 뜻으로 대답하지 못한 이유로 자연스럽습니다 ✓"]},{"id":"V354","q":"¿Cómo puedes estar tranquilo si vamos con el tiempo ____ para tomar el vuelo?","o":["de sobra","justo","sobrante","excesivo"],"a":1,"k":"시간 관련 표현","t":"비행기를 타기에 시간이 빠듯한데 어떻게 그렇게 태평할 수 있어?","e":"'ir con el tiempo justo'는 '시간이 빠듯하다'라는 표현입니다. justo는 '공정한' 외에 '꼭 맞는, 빠듯한'이라는 뜻이 있습니다. '¿Cómo puedes estar tranquilo...?(어떻게 태평할 수 있어?)'라는 꾸지람으로 시간이 부족함을 알 수 있습니다.","x":["de sobra: '넉넉히'라는 뜻으로 시간이 남으면 태평해도 되므로 ✗","justo: '빠듯한'이라는 뜻으로 서둘러야 하는 상황에 맞습니다 ✓","sobrante: '남는, 여분의'라는 뜻으로 시간이 남는다는 의미라 ✗","excesivo: '과도한'이라는 뜻으로 시간이 지나치게 많다는 뜻이라 어색합니다 ✗"]},{"id":"V355","q":"¡Qué mal! ____ demasiados errores en el examen.","o":["Cometí","Creé","Elaboré","Inventé"],"a":0,"k":"동사 연어(짝꿍)","t":"이런! 시험에서 실수를 너무 많이 했어.","e":"cometer는 '(실수·범죄를) 저지르다'라는 뜻으로, cometer un error(실수하다), cometer un delito(범죄를 저지르다)처럼 짝을 이룹니다. 한국어 '실수를 하다'처럼 hacer를 쓰기도 하지만 cometer가 가장 정확한 짝꿍입니다.","x":["Cometí: '저질렀다'라는 뜻으로 errores와 짝을 이룹니다 ✓","Creé: '만들었다, 창조했다'라는 뜻으로 실수와 함께 쓰지 않습니다 ✗","Elaboré: '(정성 들여) 만들었다, 작성했다'라는 뜻으로 실수와 맞지 않습니다 ✗","Inventé: '발명했다, 지어냈다'라는 뜻으로 실수와 어울리지 않습니다 ✗"]},{"id":"V356","q":"Si no hace viento, no podremos jugar con las ____.","o":["raquetas","muñecas","cometas","pelotas"],"a":2,"k":"놀이 어휘","t":"바람이 불지 않으면 연날리기를 할 수 없을 거야.","e":"cometa는 '연'이라는 뜻입니다. 바람(viento)이 있어야 할 수 있는 놀이라는 단서로 쉽게 찾을 수 있습니다. 참고로 cometa는 남성형(el cometa)으로 쓰면 '혜성'이 됩니다. 멕시코 등 중남미 일부에서는 연을 papalote라고도 합니다.","x":["raquetas: '라켓'이라는 뜻으로 바람이 필요하지 않습니다 ✗","muñecas: '인형'이라는 뜻으로 바람과 관계없습니다 ✗","cometas: '연'이라는 뜻으로 바람이 있어야 날릴 수 있습니다 ✓","pelotas: '공'이라는 뜻으로 바람이 없어도 놀 수 있습니다 ✗"]},{"id":"V357","q":"Dar pena a propósito es sinónimo de ____ emocional.","o":["desequilibrio","amenaza","inestabilidad","chantaje"],"a":3,"k":"심리 관련 어휘","t":"일부러 동정심을 유발하는 것은 감정적 협박과 같은 의미다.","e":"chantaje emocional은 '감정적 협박(가스라이팅과 비슷한 정서적 조종)'이라는 고정 표현입니다. chantaje는 '공갈, 협박'이라는 뜻입니다. 'Dar pena a propósito(일부러 불쌍하게 보이다)'는 상대를 조종하려는 행동이라 이 표현과 연결됩니다.","x":["desequilibrio: '불균형'이라는 뜻으로 의도적인 조종 행위를 나타내지 않습니다 ✗","amenaza: '위협'이라는 뜻으로 동정심을 이용하는 것과는 다릅니다 ✗","inestabilidad: '불안정'이라는 뜻으로 상태를 말하지 행동을 말하지 않습니다 ✗","chantaje: '협박'이라는 뜻으로 chantaje emocional(감정적 협박)이 됩니다 ✓"]},{"id":"V358","q":"Ser ____ no es fácil, no todos pueden hacer reír a los demás.","o":["escultor","cómico","bailarín","diseñador"],"a":1,"k":"직업 어휘","t":"코미디언이 되는 것은 쉽지 않다. 모두가 남을 웃길 수 있는 것은 아니다.","e":"cómico는 명사로 '코미디언, 희극 배우'라는 뜻입니다. 'hacer reír a los demás(남들을 웃기다)'라는 설명이 결정적 단서입니다. humorista도 같은 의미로 쓰입니다.","x":["escultor: '조각가'라는 뜻으로 남을 웃기는 직업이 아닙니다 ✗","cómico: '코미디언'이라는 뜻으로 남을 웃기는 직업입니다 ✓","bailarín: '무용수'라는 뜻으로 웃기는 것과 관계없습니다 ✗","diseñador: '디자이너'라는 뜻으로 웃기는 것과 관계없습니다 ✗"]},{"id":"V359","q":"Aunque todos lo responsabilizan del desastre, él no se da por ____.","o":["aludido","señalado","referido","mencionado"],"a":0,"k":"관용 표현","t":"모두가 그에게 사태의 책임을 묻지만, 그는 자기 이야기라고 생각하지 않는다(모르는 척한다).","e":"'darse por aludido'는 '자기 이야기로 받아들이다'라는 관용 표현으로, 부정형 'no darse por aludido'는 '자기를 두고 하는 말인 줄 모른 척하다'라는 뜻입니다. aludir(암시하다, 언급하다)의 과거분사입니다. 'Aunque(~에도 불구하고)'로 시작해 모두가 비난해도 신경 쓰지 않는 모습을 그립니다.","x":["aludido: 'darse por aludido(자기 얘기로 받아들이다)'라는 고정 표현을 완성합니다 ✓","señalado: '지목된'이라는 뜻이지만 'darse por'와 고정 표현을 이루지 않습니다 ✗","referido: '언급된'이라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","mencionado: '언급된'이라는 뜻으로 이 관용 표현의 형태가 아닙니다 ✗"]},{"id":"V360","q":"Es ____ que sea cocinero cuando nunca le ha interesado la cocina.","o":["natural","sensato","paradójico","normal"],"a":2,"k":"평가 형용사 + 접속법","t":"요리에 전혀 관심이 없었는데 그가 요리사라니 역설적이다.","e":"paradójico는 '역설적인, 모순된'이라는 뜻입니다. 요리에 관심이 없었던 사람이 요리사라는 모순된 상황을 표현합니다. 'Es + 형용사 + que'처럼 가치 판단을 나타내면 뒤에 접속법(sea)이 옵니다.","x":["natural: '당연한'이라는 뜻으로 모순된 상황과 맞지 않습니다 ✗","sensato: '분별 있는, 현명한'이라는 뜻으로 상황을 평가하는 말로 어색합니다 ✗","paradójico: '역설적인'이라는 뜻으로 관심 없던 사람이 요리사가 된 모순을 나타냅니다 ✓","normal: '정상적인, 흔한'이라는 뜻으로 cuando의 대조와 맞지 않습니다 ✗"]},{"id":"V361","q":"Se trata de un artículo de opinión, por eso es ____.","o":["neutral","imparcial","objetivo","subjetivo"],"a":3,"k":"글의 성격 형용사","t":"이것은 칼럼(의견 기사)이라서 주관적이다.","e":"subjetivo는 '주관적인'이라는 뜻으로, 글쓴이의 개인적인 생각이 담긴 것을 말합니다. artículo de opinión(의견 기사, 칼럼)은 필자의 견해를 담는 글이므로 주관적일 수밖에 없습니다. 반대말은 objetivo(객관적인)입니다.","x":["neutral: '중립적인'이라는 뜻으로 의견을 펼치는 글의 특징과 반대입니다 ✗","imparcial: '공정한, 치우치지 않은'이라는 뜻으로 의견 기사와 맞지 않습니다 ✗","objetivo: '객관적인'이라는 뜻으로 의견 기사의 성격과 반대입니다 ✗","subjetivo: '주관적인'이라는 뜻으로 필자의 의견이 담긴 글에 맞습니다 ✓"]},{"id":"V362","q":"El fontanero compró unos ____ de repuesto.","o":["rodillos","rastrillos","pinceles","alicates"],"a":3,"k":"공구 어휘","t":"배관공은 예비용 펜치를 몇 개 샀다.","e":"alicates는 '펜치, 니퍼'라는 뜻으로 보통 복수형으로 씁니다. fontanero(배관공)가 수리 작업에 쓰는 공구로 가장 자연스럽습니다. 'de repuesto'는 '예비용, 교체용'이라는 표현입니다. 중남미에서는 배관공을 plomero라고도 합니다.","x":["rodillos: '롤러(페인트 롤러, 밀대)'라는 뜻으로 칠장이·요리에 쓰는 도구입니다 ✗","rastrillos: '갈퀴'라는 뜻으로 정원 일에 쓰는 도구입니다 ✗","pinceles: '붓'이라는 뜻으로 화가가 쓰는 도구입니다 ✗","alicates: '펜치'라는 뜻으로 배관공이 쓰는 공구입니다 ✓"]},{"id":"V363","q":"¿Quieres dejar de ____? ¿Qué te importa la vida de los demás?","o":["contemplar","mirar","observar","fisgonear"],"a":3,"k":"동사 뉘앙스 구별","t":"남의 일 좀 그만 캐고 다닐래? 다른 사람 인생이 너랑 무슨 상관이야?","e":"fisgonear는 '(남의 일을) 엿보다, 캐고 다니다'라는 부정적인 뉘앙스의 동사입니다. '¿Qué te importa la vida de los demás?(남의 인생이 너와 무슨 상관이야?)'라는 핀잔이 단서입니다. 'dejar de + 동사원형'은 '~하는 것을 그만두다'입니다.","x":["contemplar: '(경치 등을) 감상하다, 바라보다'라는 뜻으로 부정적 뉘앙스가 없습니다 ✗","mirar: '보다'라는 일반적인 뜻으로 남의 일에 참견한다는 의미가 없습니다 ✗","observar: '관찰하다'라는 중립적인 뜻으로 핀잔과 맞지 않습니다 ✗","fisgonear: '남의 일을 캐고 다니다'라는 뜻으로 참견을 꾸짖는 문맥에 맞습니다 ✓"]},{"id":"V364","q":"Esta cantante ____ la lista de los artistas más escuchados del momento.","o":["dirige","guía","encabeza","conduce"],"a":2,"k":"동사 연어(짝꿍)","t":"이 가수는 현재 가장 많이 듣는 아티스트 목록의 1위를 차지하고 있다.","e":"encabezar는 '(목록·순위의) 맨 위에 서다, 선두에 서다'라는 뜻으로 cabeza(머리)에서 왔습니다. encabezar la lista/la clasificación(목록/순위의 1위를 하다)처럼 씁니다. 시위·운동을 '이끌다'라는 뜻으로도 씁니다.","x":["dirige: '지휘하다, 감독하다'라는 뜻으로 순위 목록과 함께 쓰지 않습니다 ✗","guía: '안내하다'라는 뜻으로 순위 1위를 나타내지 않습니다 ✗","encabeza: '맨 위에 있다'라는 뜻으로 순위 목록 1위를 나타냅니다 ✓","conduce: '운전하다, 이끌다'라는 뜻으로 목록과 어울리지 않습니다 ✗"]},{"id":"V365","q":"No te recomiendo a ese albañil. Nos hizo una ____ cuando decidimos reformar el baño.","o":["virguería","labor","maravilla","chapuza"],"a":3,"k":"구어 표현","t":"그 미장이는 추천하지 않아. 우리가 욕실을 리모델링하기로 했을 때 엉망으로 일을 해 놨어.","e":"chapuza는 '날림 공사, 엉터리 일'이라는 구어 표현입니다. 'hacer una chapuza'는 '대충 엉망으로 해 놓다'라는 뜻입니다. 'No te recomiendo(추천하지 않는다)'는 부정적인 평가가 단서입니다.","x":["virguería: '정교한 솜씨, 멋진 작품'이라는 긍정적인 뜻이라 추천하지 않는 이유가 되지 않습니다 ✗","labor: '일, 작업'이라는 중립적인 뜻으로 부정적 평가가 없습니다 ✗","maravilla: '경이로운 것'이라는 긍정적인 뜻이라 문맥과 반대입니다 ✗","chapuza: '날림 공사'라는 뜻으로 추천하지 않는 이유가 됩니다 ✓"]},{"id":"V366","q":"Este chico no tiene ____, es muy basto.","o":["modales","señales","avales","rivales"],"a":0,"k":"예절 어휘","t":"이 아이는 예의범절이 없다. 아주 거칠다.","e":"modales는 항상 복수로 쓰며 '예의범절, 매너'라는 뜻입니다. 'tener buenos/malos modales(매너가 좋다/나쁘다)', 'no tener modales(매너가 없다)'로 씁니다. basto는 '거친, 상스러운'이라는 뜻입니다.","x":["modales: '예의범절'이라는 뜻으로 거친 아이를 묘사하는 데 맞습니다 ✓","señales: '신호, 표지'라는 뜻으로 사람의 태도와 관계없습니다 ✗","avales: '보증, 보증인'이라는 뜻으로 문맥과 맞지 않습니다 ✗","rivales: '경쟁자'라는 뜻으로 거칠다는 설명과 연결되지 않습니다 ✗"]},{"id":"V367","q":"Afortunadamente, los implicados en el accidente solo tienen heridas ____.","o":["ligeras","graves","leves","serias"],"a":2,"k":"부상 정도 형용사","t":"다행히도 사고 관련자들은 경상만 입었다.","e":"heridas leves는 '경상(가벼운 부상)'이라는 고정 표현이며 반대는 heridas graves(중상)입니다. Afortunadamente(다행히)와 solo(~만)가 단서입니다. ligero도 '가벼운'이라는 뜻이지만 부상에는 보통 leve를 씁니다.","x":["ligeras: '가벼운'이라는 뜻이지만 부상 정도를 말할 때는 leve가 표준적인 짝입니다 ✗","graves: '심각한'이라는 뜻으로 '다행히'와 맞지 않습니다 ✗","leves: '경미한'이라는 뜻으로 heridas leves(경상)가 됩니다 ✓","serias: '심각한'이라는 뜻으로 '다행히'와 반대입니다 ✗"]},{"id":"V368","q":"Trabajo como técnico de ____ en una televisión privada.","o":["farmacia","laboratorio","fútbol","sonido"],"a":3,"k":"직업 어휘","t":"나는 민영 방송사에서 음향 기술자로 일한다.","e":"técnico de sonido는 '음향 기술자(사운드 엔지니어)'입니다. televisión privada(민영 방송국)에서 일하는 기술직으로 가장 자연스럽습니다. técnico de iluminación(조명 기술자)도 함께 알아 두세요.","x":["farmacia: '약국'이라는 뜻으로 방송국과 관계없습니다 ✗","laboratorio: '실험실'이라는 뜻으로 방송국 업무와 맞지 않습니다 ✗","fútbol: '축구'라는 뜻으로 técnico de fútbol는 방송국 직업이 아닙니다 ✗","sonido: '소리, 음향'이라는 뜻으로 técnico de sonido(음향 기술자)가 됩니다 ✓"]},{"id":"V369","q":"No podíamos creerlo, parecía un fenómeno ____.","o":["peculiar","habitual","milagroso","cotidiano"],"a":2,"k":"현상 묘사 형용사","t":"우리는 믿을 수 없었다. 마치 기적 같은 현상 같았다.","e":"milagroso는 milagro(기적)의 형용사로 '기적적인'이라는 뜻입니다. 'No podíamos creerlo(믿을 수 없었다)'라는 반응과 잘 어울립니다. 예: una curación milagrosa (기적적인 치유)","x":["peculiar: '독특한, 특이한'이라는 뜻으로 믿을 수 없을 정도의 놀라움을 나타내기엔 약합니다 ✗","habitual: '평소의, 흔한'이라는 뜻으로 믿을 수 없는 일과 반대입니다 ✗","milagroso: '기적적인'이라는 뜻으로 믿기 힘든 일에 맞습니다 ✓","cotidiano: '일상적인'이라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V370","q":"____ lo que le ha pasado, espero que se recupere pronto.","o":["Me fascina","Admiro","Lamento","Celebro"],"a":2,"k":"감정 동사","t":"그에게 일어난 일에 유감을 표합니다. 빨리 회복하기를 바랍니다.","e":"lamentar는 '유감으로 생각하다, 안타까워하다'라는 뜻입니다. 'espero que se recupere pronto(빨리 회복하길 바란다)'로 보아 나쁜 일이 일어났음을 알 수 있습니다. 'Lo lamento(유감입니다)'는 위로할 때 자주 쓰는 표현입니다.","x":["Me fascina: '매료되다'라는 뜻으로 불행한 일에 쓰면 무례합니다 ✗","Admiro: '존경하다, 감탄하다'라는 뜻으로 사고 소식에 맞지 않습니다 ✗","Lamento: '유감이다'라는 뜻으로 나쁜 일에 대한 위로로 알맞습니다 ✓","Celebro: '기뻐하다, 축하하다'라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V371","q":"¡Qué canción tan ____! No se me quita de la cabeza.","o":["estúpida","pegadiza","vulgar","rara"],"a":1,"k":"노래 묘사 형용사","t":"정말 중독성 있는 노래야! 머릿속에서 떠나질 않아.","e":"pegadizo는 '귀에 쏙 들어오는, 중독성 있는'이라는 뜻으로 pegar(붙이다)에서 왔습니다. 'No se me quita de la cabeza(머릿속에서 떠나지 않는다)'가 결정적 단서입니다. canción pegadiza는 '수능 금지곡' 같은 노래를 말합니다.","x":["estúpida: '바보 같은'이라는 뜻으로 머릿속에 맴도는 이유가 되지 않습니다 ✗","pegadiza: '중독성 있는'이라는 뜻으로 머릿속에서 떠나지 않는 노래에 맞습니다 ✓","vulgar: '저속한, 평범한'이라는 뜻으로 머릿속에 맴도는 것과 관계없습니다 ✗","rara: '이상한'이라는 뜻으로 맴도는 이유를 설명하지 못합니다 ✗"]},{"id":"V372","q":"Todos ____ sus palabras, nadie cree en él.","o":["confirman","disculpan","respaldan","cuestionan"],"a":3,"k":"동사 의미 구별","t":"모두가 그의 말을 의심한다. 아무도 그를 믿지 않는다.","e":"cuestionar는 '의문을 제기하다, 의심하다'라는 뜻입니다. 'nadie cree en él(아무도 그를 믿지 않는다)'라는 뒷문장과 같은 방향의 의미가 필요합니다. cuestión(문제, 질문)과 같은 어원입니다.","x":["confirman: '확인하다, 사실로 인정하다'라는 뜻으로 '아무도 믿지 않는다'와 반대입니다 ✗","disculpan: '용서하다, 변명해 주다'라는 뜻으로 믿지 않는다는 내용과 맞지 않습니다 ✗","respaldan: '지지하다'라는 뜻으로 문맥과 반대입니다 ✗","cuestionan: '의심하다'라는 뜻으로 아무도 믿지 않는다는 내용과 일치합니다 ✓"]},{"id":"V373","q":"Debe avisar al banco del robo de su ____ de crédito.","o":["carta","tarjeta","ficha","billete"],"a":1,"k":"은행 어휘","t":"은행에 신용카드 도난 사실을 알려야 합니다.","e":"tarjeta de crédito는 '신용카드'입니다. 체크카드는 tarjeta de débito입니다. carta는 '편지', 카드놀이의 '카드', 식당의 '메뉴판'이라는 뜻이라 헷갈리지 않도록 주의하세요.","x":["carta: '편지, 메뉴판'이라는 뜻으로 신용카드를 뜻하지 않습니다 ✗","tarjeta: '카드'라는 뜻으로 tarjeta de crédito(신용카드)가 됩니다 ✓","ficha: '(게임의) 칩, 카드식 기록표'라는 뜻으로 은행 카드가 아닙니다 ✗","billete: '지폐, 표'라는 뜻으로 crédito와 짝을 이루지 않습니다 ✗"]},{"id":"V374","q":"No me gusta el chocolate negro por su sabor ____.","o":["amargo","picante","ácido","salado"],"a":0,"k":"맛 형용사","t":"나는 다크 초콜릿을 쓴맛 때문에 좋아하지 않는다.","e":"amargo는 '쓴'이라는 뜻으로, 카카오 함량이 높은 chocolate negro(다크 초콜릿)의 특징입니다. 기본 맛 형용사 dulce(단), salado(짠), ácido(신), picante(매운)도 함께 기억하세요.","x":["amargo: '쓴'이라는 뜻으로 다크 초콜릿의 맛입니다 ✓","picante: '매운'이라는 뜻으로 초콜릿 맛과 맞지 않습니다 ✗","ácido: '신'이라는 뜻으로 다크 초콜릿의 대표적인 맛이 아닙니다 ✗","salado: '짠'이라는 뜻으로 다크 초콜릿 맛이 아닙니다 ✗"]},{"id":"V375","q":"Tengo que ____ mi DNI, me caducó hace unos días.","o":["renovar","reconstruir","modernizar","transformar"],"a":0,"k":"서류 관련 동사","t":"신분증을 갱신해야 해. 며칠 전에 만료됐거든.","e":"renovar는 '갱신하다, 새로 하다'라는 뜻으로 서류·계약에 씁니다. caducar는 '(유효기간이) 만료되다'라는 뜻입니다. DNI(Documento Nacional de Identidad)는 스페인의 주민등록증입니다.","x":["renovar: '갱신하다'라는 뜻으로 만료된 신분증에 맞습니다 ✓","reconstruir: '재건하다'라는 뜻으로 건물 등에 씁니다 ✗","modernizar: '현대화하다'라는 뜻으로 서류 갱신에 쓰지 않습니다 ✗","transformar: '변형하다'라는 뜻으로 신분증 갱신과 맞지 않습니다 ✗"]},{"id":"V376","q":"Ve al ____ lo antes posible para que te vea tu médico.","o":["comercio","laboratorio","almacén","ambulatorio"],"a":3,"k":"의료 시설 어휘","t":"주치의에게 진료받을 수 있도록 최대한 빨리 동네 의원에 가.","e":"ambulatorio는 스페인에서 '(입원 없이 진료하는) 외래 진료소, 동네 보건소'를 뜻합니다. tu médico(주치의)가 있는 곳이라 의료 시설이어야 합니다. 비슷한 말로 centro de salud가 있습니다.","x":["comercio: '상점, 상업'이라는 뜻으로 의사가 없습니다 ✗","laboratorio: '실험실, 검사소'라는 뜻으로 주치의 진료를 받는 곳이 아닙니다 ✗","almacén: '창고'라는 뜻으로 의료 시설이 아닙니다 ✗","ambulatorio: '외래 진료소'라는 뜻으로 의사에게 진료받는 곳입니다 ✓"]},{"id":"V377","q":"Debes madurar, a tu edad no se puede tener esa actitud tan ____.","o":["negativa","adulta","pueril","juiciosa"],"a":2,"k":"태도 형용사","t":"너는 철 좀 들어야 해. 네 나이에 그렇게 유치한 태도를 가지면 안 돼.","e":"pueril은 '유치한, 어린애 같은'이라는 뜻의 격식 있는 단어로 infantil과 비슷합니다. 'Debes madurar(철이 들어야 한다)'와 'a tu edad(네 나이에)'가 단서입니다.","x":["negativa: '부정적인'이라는 뜻으로 성숙함(madurar)과 직접 대비되지 않습니다 ✗","adulta: '어른스러운'이라는 뜻으로 철들라는 충고와 반대입니다 ✗","pueril: '유치한'이라는 뜻으로 철들라는 충고와 잘 연결됩니다 ✓","juiciosa: '분별 있는'이라는 뜻으로 긍정적이라 맞지 않습니다 ✗"]},{"id":"V378","q":"Esta camisa tiene otro color porque se lavó con ____.","o":["lejía","lavavajillas","jabón","detergente"],"a":0,"k":"세제 어휘","t":"이 셔츠는 표백제와 함께 세탁해서 색이 변했다.","e":"lejía는 '락스(염소 표백제)'라는 뜻으로 색깔 옷의 색을 빼 버릴 수 있습니다. 색이 바뀌었다(tiene otro color)는 결과의 원인으로 가장 알맞습니다. 중남미에서는 cloro, lavandina라고도 합니다.","x":["lejía: '락스, 표백제'라는 뜻으로 옷의 색을 변하게 합니다 ✓","lavavajillas: '주방 세제, 식기세척기'라는 뜻으로 옷 세탁에 쓰지 않습니다 ✗","jabón: '비누'라는 뜻으로 보통 옷 색을 바꾸지 않습니다 ✗","detergente: '(세탁) 세제'라는 뜻으로 일반 세탁에 쓰는 것이라 색이 변한 원인이 되지 않습니다 ✗"]},{"id":"V379","q":"Que seas ____ no significa que no tengas el virus.","o":["polifacético","dogmático","analítico","asintomático"],"a":3,"k":"의학 어휘","t":"네가 무증상이라고 해서 바이러스가 없다는 뜻은 아니다.","e":"asintomático는 a-(없음) + síntoma(증상)로 '무증상의'라는 뜻입니다. 'Que + 접속법(seas)'으로 시작하는 주어절은 '~라는 것이'라는 뜻이며, 문장 맨 앞에 que절이 오면 접속법을 씁니다. 바이러스 감염과 관련된 말이라 의학 용어가 필요합니다.","x":["polifacético: '다재다능한'이라는 뜻으로 바이러스와 관계없습니다 ✗","dogmático: '독단적인'이라는 뜻으로 감염 여부와 관계없습니다 ✗","analítico: '분석적인'이라는 뜻으로 바이러스와 관계없습니다 ✗","asintomático: '무증상의'라는 뜻으로 바이러스가 있어도 증상이 없는 상태입니다 ✓"]},{"id":"V380","q":"Las novelas ____ tratan crímenes de diversa naturaleza.","o":["románticas","históricas","filosóficas","policiacas"],"a":3,"k":"문학 장르","t":"추리 소설은 다양한 종류의 범죄를 다룬다.","e":"novela policiaca(또는 policíaca)는 '추리 소설, 탐정 소설'입니다. crímenes(범죄)를 다루는 장르라는 설명이 단서입니다. policiaca와 policíaca 두 표기가 모두 인정됩니다. novela negra(하드보일드 범죄 소설)라는 말도 있습니다.","x":["románticas: '로맨스의'라는 뜻으로 사랑 이야기를 다룹니다 ✗","históricas: '역사의'라는 뜻으로 역사적 사건을 다룹니다 ✗","filosóficas: '철학의'라는 뜻으로 사상을 다룹니다 ✗","policiacas: '추리의'라는 뜻으로 범죄를 다루는 장르입니다 ✓"]},{"id":"V381","q":"Ana María va a ____ a otra operación de cirugía estética.","o":["entregarse","exponerse","adaptarse","someterse"],"a":3,"k":"대명동사 + a","t":"아나 마리아는 또 다른 성형 수술을 받을 것이다.","e":"someterse a는 '(수술·검사 등을) 받다'라는 뜻의 대명동사입니다. someterse a una operación(수술을 받다), someterse a un tratamiento(치료를 받다)처럼 씁니다. someter는 원래 '복종시키다'라는 뜻입니다.","x":["entregarse: 'entregarse a'는 '~에 몰두하다, 항복하다'라는 뜻으로 수술과 맞지 않습니다 ✗","exponerse: 'exponerse a'는 '(위험에) 노출되다'라는 뜻으로 수술을 받는다는 의미가 아닙니다 ✗","adaptarse: 'adaptarse a'는 '~에 적응하다'라는 뜻으로 맞지 않습니다 ✗","someterse: 'someterse a'는 '(수술을) 받다'라는 뜻으로 정답입니다 ✓"]},{"id":"V382","q":"Como ambos tenemos el mismo horario de trabajo, tenemos que dejar a nuestro bebé en la ____.","o":["facultad","guardería","escuela","academia"],"a":1,"k":"교육 기관 어휘","t":"우리 둘 다 근무 시간이 같아서 아기를 어린이집에 맡겨야 한다.","e":"guardería는 '어린이집, 보육원'이라는 뜻으로 guardar(지키다, 맡아 두다)에서 왔습니다. bebé(아기)를 맡기는 곳이므로 가장 알맞습니다. 중남미에서는 jardín infantil, kínder라고도 합니다.","x":["facultad: '(대학의) 단과대학'이라는 뜻으로 아기를 맡기는 곳이 아닙니다 ✗","guardería: '어린이집'이라는 뜻으로 아기를 맡기는 곳입니다 ✓","escuela: '학교'라는 뜻으로 아기가 다니기엔 이릅니다 ✗","academia: '학원'이라는 뜻으로 아기를 맡기는 곳이 아닙니다 ✗"]},{"id":"V383","q":"Debes ser realista y ____ la verdad con entereza.","o":["esquivar","rehuir","evitar","afrontar"],"a":3,"k":"동사 의미 구별","t":"너는 현실적이어야 하고 진실을 의연하게 받아들여야 한다.","e":"afrontar는 '(어려움에) 맞서다, 정면으로 받아들이다'라는 뜻입니다. 'con entereza(의연하게, 굳건하게)'와 'ser realista(현실적이 되다)'가 단서입니다. 나머지 세 보기는 모두 '피하다'라는 비슷한 뜻이라 함께 정리해 두세요.","x":["esquivar: '피하다, 비켜 가다'라는 뜻으로 의연하게 대한다는 의미와 반대입니다 ✗","rehuir: '회피하다'라는 뜻으로 문맥과 반대입니다 ✗","evitar: '피하다'라는 뜻으로 문맥과 반대입니다 ✗","afrontar: '맞서다'라는 뜻으로 진실을 의연하게 받아들인다는 의미입니다 ✓"]},{"id":"V384","q":"El presidente del gobierno ____ una rueda de prensa para informar al país de lo ocurrido.","o":["invocó","convocó","suplicó","provocó"],"a":1,"k":"동사 연어(짝꿍)","t":"총리는 일어난 일을 국민에게 알리기 위해 기자회견을 소집했다.","e":"convocar는 '소집하다, 개최를 알리다'라는 뜻으로 convocar una rueda de prensa(기자회견을 열다), convocar una reunión(회의를 소집하다)처럼 씁니다. 스페인에서 presidente del gobierno는 '총리'를 가리킵니다. 보기들이 모두 -vocar/-plicar처럼 비슷하게 생겨 혼동하기 쉬우니 주의하세요.","x":["invocó: '(신·영혼을) 불렀다, 기원했다'라는 뜻으로 기자회견과 맞지 않습니다 ✗","convocó: '소집했다'라는 뜻으로 rueda de prensa와 짝을 이룹니다 ✓","suplicó: '간청했다'라는 뜻으로 기자회견과 어울리지 않습니다 ✗","provocó: '유발했다, 도발했다'라는 뜻으로 기자회견을 연다는 의미가 아닙니다 ✗"]},{"id":"V385","q":"Me encanta la escena en la que ese personaje aparece en primer ____.","o":["sitio","perfil","plan","plano"],"a":3,"k":"영화 용어","t":"그 인물이 클로즈업으로 나오는 장면이 정말 좋다.","e":"primer plano는 영화·사진 용어로 '클로즈업'이라는 뜻입니다. 비유적으로 'estar en primer plano(주목받다, 전면에 나서다)'처럼도 씁니다. plan은 '계획'이라 plano(평면, 화면, 지도)와 혼동하지 마세요.","x":["sitio: 'primer sitio'는 '첫 번째 자리'라는 뜻으로 영화 화면 용어가 아닙니다 ✗","perfil: '옆모습, 프로필'이라는 뜻으로 'de perfil'처럼 쓰고 primer와 짝을 이루지 않습니다 ✗","plan: '계획'이라는 뜻으로 영화 화면을 뜻하지 않습니다 ✗","plano: 'primer plano(클로즈업)'라는 영화 용어를 완성합니다 ✓"]},{"id":"V386","q":"Es lógico que estés ____ al llegar a una nueva ciudad.","o":["integrado","acostumbrado","asentado","desubicado"],"a":3,"k":"감정 상태 형용사","t":"새 도시에 도착하면 어리둥절한(적응하지 못한) 것이 당연하다.","e":"desubicado는 '방향을 못 잡는, 낯설어 어리둥절한'이라는 뜻으로 ubicar(위치시키다)의 반대 개념입니다. 'Es lógico que + 접속법(estés)'은 '~하는 것은 당연하다'라는 표현입니다. 새 도시에 막 도착한 상황이므로 아직 적응하지 못한 상태가 자연스럽습니다.","x":["integrado: '통합된, 잘 어울리는'이라는 뜻으로 막 도착했을 때 상태로 맞지 않습니다 ✗","acostumbrado: '익숙한'이라는 뜻으로 새 도시에 막 도착한 상황과 반대입니다 ✗","asentado: '정착한'이라는 뜻으로 막 도착한 상태와 맞지 않습니다 ✗","desubicado: '어리둥절한, 적응 못한'이라는 뜻으로 새 도시에 막 도착한 상태에 맞습니다 ✓"]},{"id":"V387","q":"Todos tienen que esperar su ____, no se cuelen.","o":["periodo","etapa","turno","tiempo"],"a":2,"k":"생활 어휘","t":"모두 자기 차례를 기다려야 합니다. 새치기하지 마세요.","e":"turno는 '차례, 순번'이라는 뜻으로 'esperar su turno(차례를 기다리다)'로 씁니다. colarse는 '새치기하다'라는 뜻이며, 'no se cuelen'은 ustedes에 대한 부정 명령입니다. turno는 '교대 근무'(turno de noche 야간 근무)라는 뜻도 있습니다.","x":["periodo: '기간'이라는 뜻으로 줄 서서 기다리는 차례가 아닙니다 ✗","etapa: '단계'라는 뜻으로 줄의 순서와 관계없습니다 ✗","turno: '차례'라는 뜻으로 줄을 서는 상황에 맞습니다 ✓","tiempo: '시간'이라는 뜻으로 '자기 차례'를 나타내지 못합니다 ✗"]},{"id":"V388","q":"Un hotel de 5 estrellas es un hotel ____.","o":["rural","sobrio","de lujo","sencillo"],"a":2,"k":"숙박 어휘","t":"5성급 호텔은 고급 호텔이다.","e":"de lujo는 '고급의, 호화로운'이라는 뜻으로 명사 뒤에 붙어 형용사처럼 씁니다. 별 다섯 개(5 estrellas)는 최고 등급이라 고급 호텔이 됩니다. lujo는 '사치, 호화'라는 뜻입니다.","x":["rural: '시골의'라는 뜻으로 호텔 등급과 관계없습니다 ✗","sobrio: '검소한, 수수한'이라는 뜻으로 5성급과 맞지 않습니다 ✗","de lujo: '고급의'라는 뜻으로 5성급 호텔에 맞습니다 ✓","sencillo: '간소한'이라는 뜻으로 5성급과 반대입니다 ✗"]},{"id":"V389","q":"La maestra nos castigó por nuestro mal ____.","o":["pensamiento","comportamiento","espíritu","entendimiento"],"a":1,"k":"행동 관련 명사","t":"선생님은 우리의 나쁜 행동 때문에 우리에게 벌을 주셨다.","e":"comportamiento는 '행동, 품행'이라는 뜻으로 comportarse(행동하다)의 명사형입니다. 벌(castigó)을 받은 이유로는 겉으로 드러난 나쁜 행동이 가장 자연스럽습니다. mal comportamiento(나쁜 행실)는 자주 쓰는 표현입니다.","x":["pensamiento: '생각'이라는 뜻으로 겉으로 드러나지 않아 벌의 이유로 어색합니다 ✗","comportamiento: '행동'이라는 뜻으로 벌을 받은 이유가 됩니다 ✓","espíritu: '정신, 영혼'이라는 뜻으로 벌의 이유로 맞지 않습니다 ✗","entendimiento: '이해력'이라는 뜻으로 벌받을 이유가 되지 않습니다 ✗"]},{"id":"V390","q":"Me gustaría ____ al mercado laboral en cuanto termine mis estudios.","o":["incorporarme","adherirme","engancharme","afiliarme"],"a":0,"k":"대명동사 + a","t":"공부를 마치는 대로 노동 시장에 진입하고(취업하고) 싶다.","e":"incorporarse a는 '~에 합류하다, 들어가다'라는 뜻으로 incorporarse al mercado laboral(취업 시장에 뛰어들다), incorporarse a un puesto(직무에 합류하다)처럼 씁니다. 'en cuanto + 접속법(termine)'은 미래의 일에 대해 '~하자마자'라는 뜻입니다.","x":["incorporarme: '합류하다'라는 뜻으로 mercado laboral과 자연스럽게 어울립니다 ✓","adherirme: 'adherirse a'는 '(의견·단체에) 동조하다, 가입하다'라는 뜻으로 노동 시장과 쓰지 않습니다 ✗","engancharme: 'engancharse a'는 '~에 중독되다, 걸리다'라는 뜻으로 맞지 않습니다 ✗","afiliarme: 'afiliarse a'는 '(정당·노조에) 가입하다'라는 뜻으로 노동 시장과 쓰지 않습니다 ✗"]},{"id":"V391","q":"El domingo pasé un ____ muy agradable con mis primos.","o":["segundo","ciclo","instante","rato"],"a":3,"k":"시간 명사 구별","t":"일요일에 나는 사촌들과 아주 즐거운 시간을 보냈다.","e":"rato는 '(어느 정도의) 짧은 시간, 한동안'이라는 뜻으로 'pasar un buen rato(즐거운 시간을 보내다)'라는 표현이 아주 자주 쓰입니다. 정확한 길이 없이 '얼마간의 시간'을 말할 때 씁니다. 예: Espera un rato. (잠깐 기다려.)","x":["segundo: '초'라는 뜻으로 즐거운 시간을 보내기엔 너무 짧습니다 ✗","ciclo: '주기, 사이클'이라는 뜻으로 시간을 보내는 표현에 쓰지 않습니다 ✗","instante: '순간'이라는 뜻으로 사촌들과 보낸 시간으로는 너무 짧습니다 ✗","rato: '한동안의 시간'이라는 뜻으로 pasar un rato agradable가 자연스럽습니다 ✓"]},{"id":"V392","q":"Mientras yo friego los platos, tú puedes ____ el polvo.","o":["vaciar","sacar","quitar","pasar"],"a":2,"k":"집안일 표현","t":"내가 설거지하는 동안 너는 먼지를 털어 줄 수 있어.","e":"'quitar el polvo'는 '먼지를 털다/닦다'라는 고정 표현입니다. fregar los platos(설거지하다)와 함께 대표적인 집안일 표현입니다. quitar는 '제거하다, 없애다'라는 뜻입니다.","x":["vaciar: '비우다'라는 뜻으로 먼지와 함께 쓰지 않습니다 ✗","sacar: '꺼내다'라는 뜻으로 sacar la basura(쓰레기를 내다)처럼 쓰고 먼지에는 쓰지 않습니다 ✗","quitar: '없애다'라는 뜻으로 quitar el polvo(먼지를 털다)가 고정 표현입니다 ✓","pasar: pasar la aspiradora(청소기를 돌리다)처럼 쓰지만 el polvo와는 짝이 아닙니다 ✗"]},{"id":"V393","q":"Esta niña duerme como un ____, no se despierta con nada.","o":["lirón","loro","tigre","león"],"a":0,"k":"동물 비유 표현","t":"이 여자아이는 정말 곯아떨어져 잔다. 무슨 일이 있어도 깨지 않는다.","e":"'dormir como un lirón'은 '푹 자다, 곯아떨어지다'라는 비유 표현입니다. lirón은 '겨울잠쥐'로, 겨울잠을 오래 자는 동물이라 이런 표현이 생겼습니다. 'no se despierta con nada(무엇에도 깨지 않는다)'가 단서입니다.","x":["lirón: '겨울잠쥐'라는 뜻으로 dormir como un lirón(푹 자다)을 완성합니다 ✓","loro: '앵무새'라는 뜻으로 hablar como un loro(수다를 떨다)처럼 씁니다 ✗","tigre: '호랑이'라는 뜻으로 잠과 관련된 비유가 아닙니다 ✗","león: '사자'라는 뜻으로 잠과 관련된 비유가 아닙니다 ✗"]},{"id":"V394","q":"Al ____ un árbol, este se corta desde su base.","o":["limpiar","plantar","talar","pelar"],"a":2,"k":"자연 관련 동사","t":"나무를 벌목할 때는 밑동부터 자른다.","e":"talar는 '(나무를) 베어 넘기다, 벌목하다'라는 뜻입니다. 'se corta desde su base(밑동부터 자른다)'라는 설명이 정의와 일치합니다. tala(벌목)라는 명사도 함께 기억하세요.","x":["limpiar: '청소하다, 깨끗이 하다'라는 뜻으로 나무를 자르는 의미가 없습니다 ✗","plantar: '심다'라는 뜻으로 자르는 것과 반대입니다 ✗","talar: '벌목하다'라는 뜻으로 밑동부터 자른다는 설명과 맞습니다 ✓","pelar: '껍질을 벗기다'라는 뜻으로 과일·채소에 씁니다 ✗"]},{"id":"V395","q":"Podrán solicitar la beca quienes lleven ____ en el país más de un año.","o":["subsistiendo","alojándose","existiendo","residiendo"],"a":3,"k":"llevar + 현재분사","t":"1년 넘게 이 나라에 거주하고 있는 사람은 장학금을 신청할 수 있다.","e":"residir는 '거주하다'라는 격식 있는 동사입니다. 'llevar + 기간 + 현재분사(-ndo)'는 '~동안 계속 ~하고 있다'라는 구조로, llevar residiendo는 '계속 거주해 왔다'라는 뜻입니다. 장학금 자격처럼 공식 문서에 잘 나오는 표현입니다.","x":["subsistiendo: '근근이 살아가며, 존속하며'라는 뜻으로 거주 조건을 말하는 데 쓰지 않습니다 ✗","alojándose: '숙박하며'라는 뜻으로 호텔 등 임시 체류에 씁니다 ✗","existiendo: '존재하며'라는 뜻으로 나라에 사는 것을 나타내지 않습니다 ✗","residiendo: '거주하며'라는 뜻으로 공식적인 거주 조건에 맞습니다 ✓"]},{"id":"V396","q":"Los guantes ____ son fundamentales en los centros médicos y en los hospitales.","o":["reutilizables","de lana","desechables","de algodón"],"a":2,"k":"재질·용도 형용사","t":"일회용 장갑은 의료 기관과 병원에서 필수적이다.","e":"desechable은 '일회용의, 쓰고 버리는'이라는 뜻으로 desechar(버리다)에서 왔습니다. 위생이 중요한 병원에서는 한 번 쓰고 버리는 장갑을 씁니다. 예: vasos desechables (일회용 컵)","x":["reutilizables: '재사용 가능한'이라는 뜻으로 위생이 중요한 병원과 맞지 않습니다 ✗","de lana: '털실로 된'이라는 뜻으로 병원 장갑이 아닙니다 ✗","desechables: '일회용의'라는 뜻으로 병원에서 쓰는 장갑입니다 ✓","de algodón: '면으로 된'이라는 뜻으로 의료용 장갑으로 쓰지 않습니다 ✗"]},{"id":"V397","q":"Vuestra casa está muy bien ____, por eso es tan acogedora.","o":["decorada","colocada","situada","maquillada"],"a":0,"k":"집 꾸미기 어휘","t":"너희 집은 아주 잘 꾸며져 있어서 그렇게 아늑하다.","e":"decorado는 decorar(장식하다)의 과거분사로 '꾸며진, 장식된'이라는 뜻입니다. acogedor(아늑한)한 이유로는 인테리어가 가장 자연스럽습니다. vuestra, estáis는 스페인식 vosotros 형태이고, 중남미에서는 'su casa'를 씁니다.","x":["decorada: '꾸며진'이라는 뜻으로 아늑함의 이유가 됩니다 ✓","colocada: '놓인, 배치된'이라는 뜻으로 집 전체에는 쓰지 않습니다 ✗","situada: '위치한'이라는 뜻으로 위치가 좋다고 해서 아늑해지는 것은 아닙니다 ✗","maquillada: '화장한'이라는 뜻으로 사람에게 씁니다 ✗"]},{"id":"V398","q":"Desde que ____ nuestra tienda, la clientela no ha dejado de subir.","o":["inauguramos","clausuramos","descubrimos","cerramos"],"a":0,"k":"상업 관련 동사","t":"우리 가게를 개업한 이후로 손님이 계속 늘고 있다.","e":"inaugurar는 '개업하다, 개관하다, 개통하다'라는 뜻입니다. 'Desde que(~한 이후로)'와 'no ha dejado de subir(계속 늘어났다)'를 보면 가게를 연 시점이 기준이 됩니다. 반대말은 clausurar(폐쇄하다)입니다.","x":["inauguramos: '개업했다'라는 뜻으로 손님이 늘어난 시작점이 됩니다 ✓","clausuramos: '폐쇄했다'라는 뜻으로 손님이 늘어날 수 없습니다 ✗","descubrimos: '발견했다'라는 뜻으로 우리 가게에 쓰기 어색합니다 ✗","cerramos: '닫았다'라는 뜻으로 손님 증가와 모순됩니다 ✗"]},{"id":"V399","q":"Por mucho que juegue a la ____, nunca me toca nada.","o":["comba","lotería","petanca","oca"],"a":1,"k":"놀이·게임 어휘","t":"아무리 복권을 사도 나는 한 번도 당첨된 적이 없다.","e":"jugar a la lotería는 '복권을 하다(사다)'라는 표현이고, 'tocar'는 '(복권·경품이) 당첨되다'라는 뜻입니다. 'nunca me toca nada(아무것도 당첨되지 않는다)'가 결정적 단서입니다. 'Por mucho que + 접속법'은 '아무리 ~해도'라는 뜻입니다.","x":["comba: '줄넘기'라는 뜻으로 당첨과 관계없습니다 ✗","lotería: '복권'이라는 뜻으로 당첨(tocar)과 잘 어울립니다 ✓","petanca: '페탕크(쇠공 굴리기 놀이)'라는 뜻으로 당첨과 관계없습니다 ✗","oca: '거위 게임(주사위 보드게임)'이라는 뜻으로 상금 당첨과 관계없습니다 ✗"]},{"id":"V400","q":"Macarena es muy ____, le cuesta hablar con personas que no conoce.","o":["tímida","atrevida","abierta","confiada"],"a":0,"k":"성격 형용사","t":"마카레나는 아주 수줍음이 많아서 모르는 사람과 이야기하는 것을 어려워한다.","e":"tímido는 '수줍은, 소심한'이라는 뜻입니다. 'le cuesta hablar con personas que no conoce(모르는 사람과 말하기 어려워한다)'라는 설명과 일치합니다. 반대말은 extrovertido(외향적인), abierto(개방적인)입니다.","x":["tímida: '수줍은'이라는 뜻으로 낯선 사람과 말하기 힘든 성격입니다 ✓","atrevida: '대담한'이라는 뜻으로 설명과 반대입니다 ✗","abierta: '개방적인, 외향적인'이라는 뜻으로 설명과 반대입니다 ✗","confiada: '남을 잘 믿는, 자신만만한'이라는 뜻으로 설명과 맞지 않습니다 ✗"]},{"id":"V401","q":"El conductor casi ____ al perro que apareció de pronto en la carretera.","o":["ataca","atropella","asalta","aborda"],"a":1,"k":"교통사고 어휘","t":"운전자는 도로에 갑자기 나타난 개를 하마터면 칠 뻔했다.","e":"atropellar는 '(차가 사람·동물을) 치다'라는 뜻입니다. 'casi + 현재형'은 과거의 일을 생생하게 말하는 구어 표현으로 '하마터면 ~할 뻔했다'라는 뜻입니다. atropello(교통사고, 치임)라는 명사도 있습니다.","x":["ataca: '공격하다'라는 뜻으로 차가 개를 치는 상황에 맞지 않습니다 ✗","atropella: '(차로) 치다'라는 뜻으로 운전자와 개의 상황에 맞습니다 ✓","asalta: '습격하다, 강도질하다'라는 뜻으로 맞지 않습니다 ✗","aborda: '다루다, 다가가 말을 걸다'라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V402","q":"La policía está ____ a uno de los principales sospechosos del crimen.","o":["interrogando","entrenando","ilustrando","encuestando"],"a":0,"k":"수사 관련 동사","t":"경찰은 범죄의 주요 용의자 중 한 명을 심문하고 있다.","e":"interrogar는 '심문하다, 신문하다'라는 뜻으로 경찰이 용의자(sospechoso)에게 질문하는 행위입니다. 'estar + 현재분사(-ndo)'는 '~하고 있다'라는 진행형입니다. 사람이 목적어라 'a uno de...'처럼 전치사 a가 붙었습니다.","x":["interrogando: '심문하고 있는'이라는 뜻으로 경찰과 용의자 상황에 맞습니다 ✓","entrenando: '훈련시키고 있는'이라는 뜻으로 용의자와 맞지 않습니다 ✗","ilustrando: '설명하고/삽화를 넣고 있는'이라는 뜻으로 맞지 않습니다 ✗","encuestando: '설문 조사하고 있는'이라는 뜻으로 용의자 심문과 다릅니다 ✗"]},{"id":"V403","q":"Aunque gane un buen ____ mensual, no me gusta trabajar aquí.","o":["sueldo","registro","logro","saldo"],"a":0,"k":"직장 어휘","t":"매달 월급을 잘 받기는 하지만 나는 여기서 일하는 것이 싫다.","e":"sueldo는 '급여, 월급'이라는 뜻입니다. 'ganar un buen sueldo(급여를 잘 받다)'로 자주 씁니다. 여기서 'Aunque + 접속법(gane)'은 '설령 ~하더라도/~하긴 하지만'이라는 양보 표현입니다. salario도 비슷한 뜻입니다.","x":["sueldo: '월급'이라는 뜻으로 ganar와 mensual에 잘 어울립니다 ✓","registro: '등록, 기록'이라는 뜻으로 버는 대상이 아닙니다 ✗","logro: '성과, 업적'이라는 뜻으로 mensual(매달의)과 어울리지 않습니다 ✗","saldo: '(계좌) 잔액, 할인 상품'이라는 뜻으로 버는 것이 아닙니다 ✗"]},{"id":"V404","q":"En el nuevo apartamento no funciona casi ninguna luz, habrá que llamar a un ____.","o":["carpintero","arquitecto","electricista","fontanero"],"a":2,"k":"직업 어휘","t":"새 아파트에 불이 거의 하나도 안 들어와서 전기 기사를 불러야겠다.","e":"electricista는 '전기 기사'입니다. -ista로 끝나는 직업 명사는 남녀 형태가 같습니다(el/la electricista). 'habrá que + 동사원형'은 '~해야 할 것이다'라는 미래 의무 표현입니다.","x":["carpintero: '목수'라는 뜻으로 전등 고장을 고치지 않습니다 ✗","arquitecto: '건축가'라는 뜻으로 수리 기사가 아닙니다 ✗","electricista: '전기 기사'라는 뜻으로 전등 문제를 고칩니다 ✓","fontanero: '배관공'이라는 뜻으로 수도 문제를 고칩니다 ✗"]},{"id":"V405","q":"Gracias por invitarme a comer, pero no tengo ____.","o":["apetito","inquietud","inapetencia","desgana"],"a":0,"k":"식욕 관련 어휘","t":"식사에 초대해 줘서 고마워. 하지만 나는 입맛이 없어.","e":"apetito는 '식욕, 입맛'이라는 뜻으로 'no tengo apetito(입맛이 없다)'로 씁니다. 함정은 inapetencia와 desgana로, 이미 '식욕 부진'이라는 뜻이라 no tengo와 함께 쓰면 '식욕 부진이 없다'가 되어 거절 이유가 되지 않습니다.","x":["apetito: '식욕'이라는 뜻으로 no tengo apetito(입맛이 없다)가 거절 이유가 됩니다 ✓","inquietud: '불안, 걱정'이라는 뜻으로 식사 거절 이유와 연결되지 않습니다 ✗","inapetencia: '식욕 부진'이라는 뜻이라 no tengo와 합치면 '입맛이 있다'는 의미가 됩니다 ✗","desgana: '식욕 부진, 의욕 없음'이라는 뜻이라 no tengo와 합치면 의미가 반대가 됩니다 ✗"]},{"id":"V406","q":"¡Qué susceptible estás hoy! ____ por todo.","o":["Te deprimes","Te ofendes","Bostezas","Te ríes"],"a":1,"k":"감정 대명동사","t":"너 오늘 왜 이렇게 예민해! 모든 일에 기분 나빠하잖아.","e":"ofenderse는 '기분 상하다, 모욕감을 느끼다'라는 대명동사입니다. susceptible는 '예민한, 쉽게 기분 상하는'이라는 뜻이라 서로 잘 연결됩니다. 'por todo'는 '모든 일에, 사사건건'이라는 뜻입니다.","x":["Te deprimes: '우울해하다'라는 뜻으로 susceptible(예민한)의 설명으로는 정확하지 않습니다 ✗","Te ofendes: '기분 상하다'라는 뜻으로 예민하다는 말과 잘 맞습니다 ✓","Bostezas: '하품하다'라는 뜻으로 예민함과 관계없습니다 ✗","Te ríes: '웃다'라는 뜻으로 예민하다는 말과 맞지 않습니다 ✗"]},{"id":"V407","q":"No soy nada ____, soy demasiado racional.","o":["ansioso","misericordioso","supersticioso","misterioso"],"a":2,"k":"성격 형용사","t":"나는 전혀 미신을 믿지 않는다. 너무 이성적이다.","e":"supersticioso는 '미신을 믿는'이라는 뜻으로 superstición(미신)에서 왔습니다. 'soy demasiado racional(너무 이성적이다)'라는 이유와 정확히 대비됩니다. 'no ser nada + 형용사'는 '전혀 ~하지 않다'입니다.","x":["ansioso: '불안한, 갈망하는'이라는 뜻으로 이성적이라는 이유와 직접 대비되지 않습니다 ✗","misericordioso: '자비로운'이라는 뜻으로 이성과 관계없습니다 ✗","supersticioso: '미신을 믿는'이라는 뜻으로 이성적인 사람과 반대입니다 ✓","misterioso: '신비로운'이라는 뜻으로 성격의 이성 여부와 관계없습니다 ✗"]},{"id":"V408","q":"El vecino del cuarto es un ____, así que no le cuentes nada de tu vida privada.","o":["tonto","ingenuo","necio","chismoso"],"a":3,"k":"사람 성격 어휘","t":"5층 이웃은 수다쟁이니까 그에게 네 사생활은 아무것도 얘기하지 마.","e":"chismoso는 '남의 이야기를 퍼뜨리는 사람, 수다쟁이'라는 뜻으로 chisme(소문, 뒷말)에서 왔습니다. 사생활을 말하지 말라는 충고의 이유로 딱 맞습니다. 스페인에서는 cotilla도 같은 뜻으로 많이 씁니다.","x":["tonto: '바보'라는 뜻으로 사생활을 숨겨야 할 이유가 되지 않습니다 ✗","ingenuo: '순진한'이라는 뜻으로 비밀을 퍼뜨린다는 의미가 없습니다 ✗","necio: '어리석은, 고집 센'이라는 뜻으로 소문과 관계없습니다 ✗","chismoso: '소문을 퍼뜨리는 사람'이라는 뜻으로 사생활을 숨겨야 할 이유가 됩니다 ✓"]},{"id":"V409","q":"Use esta ____ para las picaduras de insectos.","o":["pomada","colonia","poción","esencia"],"a":0,"k":"약품 어휘","t":"벌레 물린 데에는 이 연고를 바르세요.","e":"pomada는 '연고'라는 뜻으로 피부에 바르는 약입니다. picadura는 '(벌레에) 물림, 쏘임'이라는 뜻입니다. Use는 usted에 대한 긍정 명령형입니다.","x":["pomada: '연고'라는 뜻으로 벌레 물린 곳에 바르는 약입니다 ✓","colonia: '향수(오드콜로뉴)'라는 뜻으로 치료제가 아닙니다 ✗","poción: '물약, 마법의 약'이라는 뜻으로 마시는 것이라 맞지 않습니다 ✗","esencia: '에센스, 정유(향료)'라는 뜻으로 치료용이 아닙니다 ✗"]},{"id":"V410","q":"El ____ me dijo que necesito unas gafas nuevas.","o":["traumatólogo","dermatólogo","oculista","otorrino"],"a":2,"k":"의사 전문 분야","t":"안과 의사가 나에게 새 안경이 필요하다고 말했다.","e":"oculista는 '안과 의사'로, oftalmólogo와 같은 뜻입니다. gafas(안경)와 관련된 진료를 하는 의사입니다. 중남미에서는 안경을 lentes, anteojos라고도 합니다.","x":["traumatólogo: '정형외과 의사'라는 뜻으로 뼈·관절을 진료합니다 ✗","dermatólogo: '피부과 의사'라는 뜻으로 피부를 진료합니다 ✗","oculista: '안과 의사'라는 뜻으로 안경 처방과 맞습니다 ✓","otorrino: '이비인후과 의사'라는 뜻으로 귀·코·목을 진료합니다 ✗"]},{"id":"V411","q":"Son ____, por eso son como dos gotas de agua.","o":["hermanastros","parientes","primos","gemelos"],"a":3,"k":"가족 어휘","t":"그들은 쌍둥이라서 붕어빵처럼 똑같이 생겼다.","e":"gemelos는 '쌍둥이'라는 뜻입니다. 'ser como dos gotas de agua(두 물방울 같다)'는 '똑같이 생겼다'는 관용 표현입니다. 이란성 쌍둥이는 mellizos라고 구별하기도 합니다.","x":["hermanastros: '의붓형제'라는 뜻으로 피가 섞이지 않아 닮을 이유가 없습니다 ✗","parientes: '친척'이라는 뜻으로 똑같이 생긴 이유가 되지 않습니다 ✗","primos: '사촌'이라는 뜻으로 똑같이 생긴 이유로 약합니다 ✗","gemelos: '쌍둥이'라는 뜻으로 똑같이 생긴 이유가 됩니다 ✓"]},{"id":"V412","q":"Le ____ una enfermedad pulmonar.","o":["determinaron","dictaminaron","anunciaron","diagnosticaron"],"a":3,"k":"의학 동사","t":"그는 폐 질환을 진단받았다.","e":"diagnosticar는 '진단하다'라는 뜻으로 diagnóstico(진단)의 동사형입니다. 'Le diagnosticaron...'처럼 3인칭 복수로 써서 '(의사들이) 그에게 진단을 내렸다', 즉 '진단받았다'는 뜻이 됩니다.","x":["determinaron: '결정했다, 밝혀냈다'라는 뜻으로 병명에 대한 표준 동사가 아닙니다 ✗","dictaminaron: '(전문가가) 판정을 내렸다'라는 뜻으로 법률·공식 판정에 주로 씁니다 ✗","anunciaron: '발표했다'라는 뜻으로 질병 진단에 쓰지 않습니다 ✗","diagnosticaron: '진단했다'라는 뜻으로 질병과 짝을 이룹니다 ✓"]},{"id":"V413","q":"Mi marido es ____ a que nuestra hija tenga teléfono móvil, considera que es demasiado pequeña.","o":["tendente","proclive","reacio","propenso"],"a":2,"k":"형용사 + a","t":"남편은 딸이 휴대폰을 갖는 것을 꺼린다. 너무 어리다고 생각하기 때문이다.","e":"reacio a는 '~을 꺼리는, ~에 반대하는'이라는 뜻입니다. 'ser reacio a que + 접속법(tenga)'으로 쓰였습니다. 'considera que es demasiado pequeña(너무 어리다고 생각한다)'라는 이유로 반대하는 입장임을 알 수 있습니다. 나머지 보기는 모두 '~하는 경향이 있는'이라는 뜻입니다.","x":["tendente: 'tendente a'는 '~을 지향하는, ~하는 경향의'라는 뜻으로 반대 입장과 맞지 않습니다 ✗","proclive: 'proclive a'는 '~에 기울어진, ~하기 쉬운'이라는 뜻으로 반대 입장과 맞지 않습니다 ✗","reacio: 'reacio a'는 '~을 꺼리는'이라는 뜻으로 너무 어리다는 이유와 맞습니다 ✓","propenso: 'propenso a'는 '~하기 쉬운(체질·경향)'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V414","q":"Me dedico a la ____, es decir, trabajo con oro, plata y otros metales.","o":["cacería","abogacía","enseñanza","orfebrería"],"a":3,"k":"직업 분야 어휘","t":"나는 금은세공 일을 한다. 즉 금, 은 그리고 다른 금속들로 작업한다.","e":"orfebrería는 '금은세공(업)'이라는 뜻으로, 금·은 등 귀금속을 가공해 장신구나 공예품을 만드는 일입니다. 'es decir, trabajo con oro, plata...(즉, 금·은으로 일한다)'가 정의 역할을 합니다. 세공사는 orfebre라고 합니다.","x":["cacería: '사냥'이라는 뜻으로 금속과 관계없습니다 ✗","abogacía: '변호사업'이라는 뜻으로 금속 작업과 관계없습니다 ✗","enseñanza: '교육, 가르치는 일'이라는 뜻으로 맞지 않습니다 ✗","orfebrería: '금은세공'이라는 뜻으로 금·은으로 작업하는 일입니다 ✓"]},{"id":"V415","q":"Sacó un sobresaliente por haber hecho un estudio tan completo y ____.","o":["genérico","inexacto","minucioso","irrelevante"],"a":2,"k":"평가 형용사","t":"그는 아주 완벽하고 꼼꼼한 연구를 해서 최고 점수를 받았다.","e":"minucioso는 '꼼꼼한, 세밀한'이라는 뜻입니다. completo(완벽한)와 y로 연결되어 함께 긍정적인 평가를 나타내야 합니다. sobresaliente는 스페인 성적 체계에서 '수(최우수)'에 해당합니다.","x":["genérico: '일반적인, 포괄적인'이라는 뜻으로 최고 점수의 이유로 약합니다 ✗","inexacto: '부정확한'이라는 뜻으로 최고 점수와 맞지 않습니다 ✗","minucioso: '꼼꼼한'이라는 뜻으로 최고 점수를 받은 이유가 됩니다 ✓","irrelevante: '중요하지 않은'이라는 뜻으로 부정적이라 맞지 않습니다 ✗"]},{"id":"V416","q":"Los ____ son dichos populares que hay en todos los idiomas.","o":["poemas","himnos","refranes","chistes"],"a":2,"k":"언어 표현 장르","t":"속담은 모든 언어에 있는 민간의 격언이다.","e":"refrán은 '속담'이라는 뜻으로 복수형은 refranes(악센트가 사라짐)입니다. dichos populares(민간에서 전해 오는 말)라는 정의와 정확히 일치합니다. 예: Más vale tarde que nunca. (늦더라도 안 하는 것보다 낫다.)","x":["poemas: '시'라는 뜻으로 dichos populares가 아닙니다 ✗","himnos: '찬가, 국가'라는 뜻으로 맞지 않습니다 ✗","refranes: '속담'이라는 뜻으로 민간의 격언에 해당합니다 ✓","chistes: '농담, 우스갯소리'라는 뜻으로 격언이 아닙니다 ✗"]},{"id":"V417","q":"Ponerte ese vestido fue todo un ____, te queda muy bien.","o":["error","acierto","fallo","disparate"],"a":1,"k":"평가 명사","t":"그 드레스를 입은 것은 정말 탁월한 선택이었어. 너한테 아주 잘 어울려.","e":"acierto는 '적중, 탁월한 선택, 잘한 결정'이라는 뜻으로 acertar(맞히다)에서 왔습니다. 'te queda muy bien(아주 잘 어울린다)'라는 긍정적 평가와 맞습니다. 'ser todo un acierto'는 '정말 잘한 선택이다'라는 표현입니다.","x":["error: '실수'라는 뜻으로 잘 어울린다는 칭찬과 반대입니다 ✗","acierto: '탁월한 선택'이라는 뜻으로 칭찬과 맞습니다 ✓","fallo: '실패, 결함'이라는 뜻으로 칭찬과 반대입니다 ✗","disparate: '터무니없는 짓'이라는 뜻으로 칭찬과 반대입니다 ✗"]},{"id":"V418","q":"Dio una respuesta tan ____ que nadie hizo ninguna otra pregunta.","o":["incierta","ambigua","dudosa","tajante"],"a":3,"k":"답변 묘사 형용사","t":"그가 너무 단호한 답을 해서 아무도 다른 질문을 하지 않았다.","e":"tajante는 '단호한, 딱 잘라 말하는'이라는 뜻입니다. 'tan ... que(너무 ~해서 ~하다)' 구조에서 결과가 '아무도 더 질문하지 않았다'이므로 명확하고 단호한 답이어야 합니다. 나머지 보기는 모두 '애매한'이라는 뜻이라 오히려 질문이 더 생깁니다.","x":["incierta: '불확실한'이라는 뜻으로 오히려 질문을 부를 답입니다 ✗","ambigua: '모호한'이라는 뜻으로 추가 질문이 생길 답입니다 ✗","dudosa: '의심스러운'이라는 뜻으로 질문이 끝날 이유가 되지 않습니다 ✗","tajante: '단호한'이라는 뜻으로 더 이상 질문하지 못하게 한 답입니다 ✓"]},{"id":"V419","q":"La última película de esta cineasta fue un ____ éxito.","o":["pleno","terminante","rotundo","firme"],"a":2,"k":"형용사 연어(짝꿍)","t":"이 영화감독의 최신작은 대성공이었다.","e":"rotundo는 '완전한, 단호한'이라는 뜻으로 éxito rotundo(대성공), rotundo no(단호한 거절)처럼 짝을 이룹니다. 형용사가 명사 앞에 와서 'un rotundo éxito'처럼 강조하기도 합니다. cineasta는 '영화인, 영화감독'으로 남녀 형태가 같습니다.","x":["pleno: '완전한, 한창의'라는 뜻으로 en pleno verano처럼 쓰고 éxito의 대표 짝은 아닙니다 ✗","terminante: '단호한, 결정적인'이라는 뜻으로 금지·명령에 쓰고 성공에는 쓰지 않습니다 ✗","rotundo: éxito rotundo(대성공)라는 연어를 이룹니다 ✓","firme: '확고한'이라는 뜻으로 성공과 짝을 이루지 않습니다 ✗"]},{"id":"V420","q":"No te olvides de hacer el ____ de la llave. Así no tendremos una sola.","o":["duplicado","par","duplo","doble"],"a":0,"k":"복사·사본 어휘","t":"열쇠 복사하는 것 잊지 마. 그러면 하나만 갖고 있지 않게 될 거야.","e":"duplicado는 '복제품, 사본'이라는 뜻의 명사로 hacer un duplicado de la llave(열쇠를 복사하다)처럼 씁니다. 공문서의 '부본'도 duplicado라고 합니다. 'Así no tendremos una sola(그러면 하나만 있지 않을 것이다)'가 단서입니다.","x":["duplicado: '사본, 복제품'이라는 뜻으로 열쇠 복사에 맞습니다 ✓","par: '한 쌍, 짝'이라는 뜻으로 복제한다는 의미가 없습니다 ✗","duplo: '두 배'라는 뜻의 수학적 표현이라 열쇠에 쓰지 않습니다 ✗","doble: '두 배, 대역'이라는 뜻으로 열쇠 복사에는 쓰지 않습니다 ✗"]},{"id":"V421","q":"La ____ del virus por todo el continente fue inevitable.","o":["desintegración","prolongación","propagación","ampliación"],"a":2,"k":"확산 관련 명사","t":"바이러스가 대륙 전체로 퍼지는 것은 피할 수 없었다.","e":"propagación는 '확산, 전파'라는 뜻으로 propagar(퍼뜨리다)의 명사형입니다. 질병·화재·소문이 퍼지는 것에 씁니다. 'por todo el continente(대륙 전체로)'와 잘 어울립니다.","x":["desintegración: '분해, 붕괴'라는 뜻으로 바이러스가 퍼지는 것과 반대입니다 ✗","prolongación: '연장'이라는 뜻으로 기간·길이를 늘이는 것이라 맞지 않습니다 ✗","propagación: '확산'이라는 뜻으로 바이러스가 대륙 전체로 퍼지는 것을 나타냅니다 ✓","ampliación: '확장, 증축'이라는 뜻으로 건물·시설에 주로 쓰고 바이러스에는 쓰지 않습니다 ✗"]},{"id":"V422","q":"La sopa está sosa, voy a echarle una ____ de sal.","o":["pizca","migaja","chispa","gota"],"a":0,"k":"분량 표현","t":"수프가 싱거워서 소금을 조금 넣을게.","e":"pizca는 '아주 조금, 한 꼬집'이라는 뜻으로 una pizca de sal(소금 한 꼬집)처럼 씁니다. soso는 '싱거운'이라는 뜻입니다. 비유적으로 'ni pizca(조금도 ~않다)'라는 표현도 자주 씁니다.","x":["pizca: '한 꼬집'이라는 뜻으로 소금을 넣는 양으로 딱 맞습니다 ✓","migaja: '빵 부스러기'라는 뜻으로 소금의 양에 쓰지 않습니다 ✗","chispa: '불꽃, 아주 조금'이라는 뜻으로 소금과는 보통 쓰지 않습니다 ✗","gota: '방울'이라는 뜻으로 액체에 쓰므로 소금에는 맞지 않습니다 ✗"]},{"id":"V423","q":"Los crucigramas están entre mis ____ favoritos.","o":["pasatiempos","quehaceres","asuntos","trabajos"],"a":0,"k":"여가 어휘","t":"십자말풀이는 내가 가장 좋아하는 취미 중 하나다.","e":"pasatiempo는 pasar(보내다) + tiempo(시간)가 합쳐진 말로 '취미, 소일거리'라는 뜻입니다. 신문의 퍼즐 코너도 pasatiempos라고 부릅니다. crucigrama는 '십자말풀이'입니다.","x":["pasatiempos: '취미, 오락'이라는 뜻으로 십자말풀이에 맞습니다 ✓","quehaceres: '할 일, 집안일'이라는 뜻으로 좋아하는 놀이가 아닙니다 ✗","asuntos: '일, 사안'이라는 뜻으로 취미를 나타내지 않습니다 ✗","trabajos: '일, 작업'이라는 뜻으로 취미가 아닙니다 ✗"]},{"id":"V424","q":"Sufrí un gran ____ cuando me enteré de que mi ex estaba casado.","o":["pesimismo","declive","desengaño","desinterés"],"a":2,"k":"감정 명사","t":"전 남자친구가 결혼했다는 것을 알았을 때 나는 큰 환멸을 느꼈다.","e":"desengaño는 '환멸, 실망, (기대가 깨지는) 깨달음'이라는 뜻입니다. engaño(속임)에 des-가 붙어 '착각에서 깨어남'이라는 의미가 됩니다. 'sufrir un desengaño(실망하다, 상처받다)'는 특히 연애에서 자주 쓰는 표현입니다.","x":["pesimismo: '비관주의'라는 뜻으로 한 번의 소식에 '겪는' 감정으로 어색합니다 ✗","declive: '쇠퇴, 하락'이라는 뜻으로 감정을 나타내지 않습니다 ✗","desengaño: '환멸, 실망'이라는 뜻으로 전 연인의 결혼 소식에 맞습니다 ✓","desinterés: '무관심'이라는 뜻으로 큰 충격을 받은 상황과 맞지 않습니다 ✗"]},{"id":"V425","q":"Esta es una asociación sin ____ de lucro.","o":["ánimo","idea","causa","motivo"],"a":0,"k":"고정 표현","t":"이곳은 비영리 단체다.","e":"'sin ánimo de lucro'는 '비영리의'라는 고정 표현입니다. ánimo는 '의도, 의욕'이고 lucro는 '이익, 영리'라는 뜻입니다. 중남미에서는 'sin fines de lucro'라는 표현을 더 많이 씁니다.","x":["ánimo: 'sin ánimo de lucro(비영리)'라는 고정 표현을 완성합니다 ✓","idea: '생각'이라는 뜻으로 이 고정 표현에 쓰지 않습니다 ✗","causa: '원인, 대의'라는 뜻으로 이 표현에 쓰지 않습니다 ✗","motivo: '이유, 동기'라는 뜻으로 고정 표현의 형태가 아닙니다 ✗"]},{"id":"V426","q":"La prensa ____ también es conocida como prensa del corazón.","o":["amarilla","blanca","roja","rosa"],"a":3,"k":"언론 색깔 표현","t":"가십 언론은 '연예 신문(prensa del corazón)'이라고도 불린다.","e":"prensa rosa는 직역하면 '분홍 언론'으로, 유명인의 연애·사생활을 다루는 가십 잡지·방송을 말합니다. prensa del corazón(마음의 언론)과 같은 뜻입니다. prensa amarilla(황색 언론)는 선정적인 보도를 하는 언론이라 구별하세요.","x":["amarilla: prensa amarilla는 '선정적 황색 언론'이라는 뜻으로 prensa del corazón과는 다릅니다 ✗","blanca: prensa blanca는 쓰이지 않는 표현입니다 ✗","roja: prensa roja는 정해진 언론 분류가 아닙니다 ✗","rosa: prensa rosa는 연예 가십 언론으로 prensa del corazón과 같은 뜻입니다 ✓"]},{"id":"V427","q":"Los ____ forman parte del aparato urinario.","o":["huesos","riñones","pulmones","músculos"],"a":1,"k":"신체 기관 어휘","t":"신장은 비뇨기계의 일부이다.","e":"riñón은 '신장, 콩팥'이며 복수형은 riñones(악센트가 사라짐)입니다. aparato urinario(비뇨기계)는 소변을 만들고 배출하는 기관입니다. 참고로 aparato digestivo(소화기계), aparato respiratorio(호흡기계)도 함께 알아 두세요.","x":["huesos: '뼈'라는 뜻으로 골격계에 속합니다 ✗","riñones: '신장'이라는 뜻으로 비뇨기계에 속합니다 ✓","pulmones: '폐'라는 뜻으로 호흡기계에 속합니다 ✗","músculos: '근육'이라는 뜻으로 근육계에 속합니다 ✗"]},{"id":"V428","q":"Necesito un cambio de ____, me aburre estar siempre igual.","o":["imagen","perfil","forma","fachada"],"a":0,"k":"고정 표현","t":"나는 이미지 변신이 필요해. 늘 똑같은 모습이 지겨워.","e":"cambio de imagen은 '이미지 변신, 스타일 변화'라는 고정 표현입니다. 헤어스타일·옷차림 등을 바꾸는 것을 말합니다. 'me aburre estar siempre igual(늘 똑같은 게 지겹다)'라는 이유와 잘 연결됩니다.","x":["imagen: cambio de imagen(이미지 변신)이라는 고정 표현이 됩니다 ✓","perfil: '프로필, 옆모습'이라는 뜻으로 cambio de perfil은 일반적인 표현이 아닙니다 ✗","forma: '형태'라는 뜻으로 외모 변화를 나타내는 고정 표현이 아닙니다 ✗","fachada: '(건물) 정면, 겉치레'라는 뜻으로 사람의 외모 변화에 쓰지 않습니다 ✗"]},{"id":"V429","q":"Las enfermedades ____ son tan serias como los problemas físicos.","o":["somáticas","mentales","corporales","tangibles"],"a":1,"k":"질병 관련 형용사","t":"정신 질환은 신체적인 문제만큼이나 심각하다.","e":"mental은 '정신의'라는 뜻으로 enfermedades mentales는 '정신 질환'입니다. 'tan serias como los problemas físicos(신체 문제만큼 심각하다)'에서 físico(신체의)와 대비되는 말이 필요합니다. salud mental(정신 건강)도 자주 쓰는 표현입니다.","x":["somáticas: '신체의'라는 뜻으로 físicos와 같은 의미라 대비가 되지 않습니다 ✗","mentales: '정신의'라는 뜻으로 신체 문제와 대비됩니다 ✓","corporales: '몸의'라는 뜻으로 신체 문제와 같아 대비가 되지 않습니다 ✗","tangibles: '만질 수 있는, 실체적인'이라는 뜻으로 질병 분류에 쓰지 않습니다 ✗"]},{"id":"V430","q":"Hoy todos los ____ tienen las mismas noticias en sus portadas.","o":["cuadernos","panfletos","diarios","folletos"],"a":2,"k":"언론 매체 어휘","t":"오늘은 모든 신문이 1면에 같은 뉴스를 싣고 있다.","e":"diario는 '일간지, 신문'이라는 뜻입니다(periódico와 같음). portada는 '1면, 표지'라는 뜻으로 신문의 첫 면을 가리킵니다. diario는 형용사로 '매일의', 명사로 '일기'라는 뜻도 있습니다.","x":["cuadernos: '공책'이라는 뜻으로 뉴스를 싣지 않습니다 ✗","panfletos: '(정치적) 전단, 소책자'라는 뜻으로 매일 뉴스를 싣는 매체가 아닙니다 ✗","diarios: '신문'이라는 뜻으로 1면에 뉴스를 싣는 매체입니다 ✓","folletos: '안내 책자, 팸플릿'이라는 뜻으로 뉴스 매체가 아닙니다 ✗"]},{"id":"V431","q":"Tienes casi 30 años, ya es hora de que te ____ y te busques la vida por ti mismo.","o":["independices","inscribas","agobies","hartes"],"a":0,"k":"접속법 + 대명동사","t":"너 거의 서른 살이야. 이제 독립해서 스스로 살길을 찾을 때가 됐어.","e":"independizarse는 '독립하다'라는 대명동사입니다. 'ya es hora de que + 접속법(te independices)'은 '이제 ~할 때다'라는 표현이라 접속법이 옵니다. -zar 동사는 접속법에서 z가 c로 바뀝니다(independice). 'buscarse la vida'는 '스스로 먹고살 길을 찾다'라는 구어 표현입니다.","x":["independices: '독립하다'라는 뜻으로 서른 살 즈음의 충고에 딱 맞습니다 ✓","inscribas: '등록하다'라는 뜻으로 스스로 살길을 찾는다는 내용과 맞지 않습니다 ✗","agobies: '숨 막혀하다, 압박을 느끼다'라는 뜻으로 충고 내용과 맞지 않습니다 ✗","hartes: '질리다, 지치다'라는 뜻으로 문맥과 어울리지 않습니다 ✗"]},{"id":"V432","q":"Cabe ____ que estar bien hidratado es crucial cuando el calor aprieta.","o":["marcar","señalar","delinear","trazar"],"a":1,"k":"격식 표현","t":"더위가 기승을 부릴 때는 수분을 충분히 섭취하는 것이 매우 중요하다는 점을 짚고 넘어갈 필요가 있다.","e":"'cabe señalar que...'는 '~임을 언급할 필요가 있다, 짚어 둘 만하다'라는 격식 있는 고정 표현입니다. señalar는 '가리키다, 지적하다'라는 뜻입니다. 'cuando el calor aprieta'는 '더위가 기승을 부릴 때'라는 표현입니다. 비슷하게 'cabe destacar/mencionar'도 씁니다.","x":["marcar: '표시하다'라는 뜻으로 cabe와 함께 의견을 언급하는 표현을 만들지 않습니다 ✗","señalar: '지적하다'라는 뜻으로 cabe señalar(짚어 둘 만하다)라는 표현이 됩니다 ✓","delinear: '윤곽을 그리다'라는 뜻으로 이 표현에 쓰지 않습니다 ✗","trazar: '(선을) 긋다, 계획을 세우다'라는 뜻으로 이 표현에 쓰지 않습니다 ✗"]},{"id":"V433","q":"Esta palabra tiene significados diferentes según el ____.","o":["contexto","lugar","argumento","concepto"],"a":0,"k":"언어 관련 어휘","t":"이 단어는 문맥에 따라 다른 의미를 가진다.","e":"contexto는 '문맥, 맥락'이라는 뜻입니다. 'según el contexto(문맥에 따라)'는 단어 뜻이 달라지는 이유를 설명할 때 가장 자주 쓰는 표현입니다. lugar(장소)도 가능해 보이지만 단어 의미를 결정하는 것은 문맥입니다.","x":["contexto: '문맥'이라는 뜻으로 단어 의미가 달라지는 기준이 됩니다 ✓","lugar: '장소'라는 뜻으로 단어 의미를 결정하는 표준적인 기준이 아닙니다 ✗","argumento: '논거, 줄거리'라는 뜻으로 단어 의미의 기준이 아닙니다 ✗","concepto: '개념'이라는 뜻으로 의미가 달라지는 기준을 나타내지 않습니다 ✗"]},{"id":"V434","q":"____ cuando mis hijos vuelven tarde a casa. No me tranquilizo hasta que llegan.","o":["Me angustio","Me animo","Gozo","Disfruto"],"a":0,"k":"감정 대명동사","t":"아이들이 늦게 집에 돌아오면 나는 애가 탄다. 도착할 때까지 마음이 놓이지 않는다.","e":"angustiarse는 '몹시 불안해하다, 애태우다'라는 뜻의 대명동사입니다. 'No me tranquilizo hasta que llegan(도착할 때까지 안심이 안 된다)'라는 설명이 결정적 단서입니다. angustia(극심한 불안)라는 명사도 함께 기억하세요.","x":["Me angustio: '애가 탄다'라는 뜻으로 불안한 마음과 일치합니다 ✓","Me animo: '기운이 난다'라는 뜻으로 불안함과 반대입니다 ✗","Gozo: '즐긴다'라는 뜻으로 문맥과 반대입니다 ✗","Disfruto: '즐긴다'라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V435","q":"Consiguieron llegar a la final gracias a su esfuerzo y a su ____.","o":["negligencia","tesón","dejadez","pereza"],"a":1,"k":"성격·태도 명사","t":"그들은 노력과 끈기 덕분에 결승에 진출할 수 있었다.","e":"tesón은 '끈기, 불굴의 의지'라는 뜻입니다. esfuerzo(노력)와 함께 성공의 이유로 쓰이므로 긍정적인 자질이어야 합니다. 비슷한 말로 constancia, perseverancia가 있습니다.","x":["negligencia: '태만, 부주의'라는 뜻으로 성공 이유가 될 수 없습니다 ✗","tesón: '끈기'라는 뜻으로 노력과 함께 성공의 이유가 됩니다 ✓","dejadez: '게으름, 방치'라는 뜻으로 부정적이라 맞지 않습니다 ✗","pereza: '게으름'이라는 뜻으로 성공과 반대입니다 ✗"]},{"id":"V436","q":"El avión está a punto de ____, abróchense los cinturones, por favor.","o":["despegar","emerger","levantarse","remontar"],"a":0,"k":"항공 어휘","t":"비행기가 곧 이륙합니다. 안전벨트를 매 주세요.","e":"despegar는 '(비행기가) 이륙하다'라는 뜻이며 반대말은 aterrizar(착륙하다)입니다. 'estar a punto de + 동사원형'은 '막 ~하려고 하다'라는 표현입니다. despegar는 '(붙은 것을) 떼다'라는 뜻도 있습니다.","x":["despegar: '이륙하다'라는 뜻으로 비행기와 안전벨트 상황에 맞습니다 ✓","emerger: '(물 위로) 떠오르다'라는 뜻으로 잠수함 등에 씁니다 ✗","levantarse: '일어나다'라는 뜻으로 비행기 이륙에는 쓰지 않습니다 ✗","remontar: '거슬러 오르다, 극복하다'라는 뜻으로 이륙을 뜻하지 않습니다 ✗"]},{"id":"V437","q":"Comer en exceso suele provocar sobrepeso, es mejor comer con ____.","o":["prisa","calma","moderación","lentitud"],"a":2,"k":"건강 습관 어휘","t":"과식은 보통 과체중을 유발하므로 적당히 먹는 것이 좋다.","e":"moderación은 '절제, 적당함'이라는 뜻으로 'con moderación(적당히, 절제하며)'으로 씁니다. 'Comer en exceso(과식)'와 대비되는 개념으로, 양을 조절하라는 의미입니다. calma나 lentitud는 먹는 속도를 말하므로 양의 문제와 맞지 않습니다.","x":["prisa: '서두름'이라는 뜻으로 과식 문제의 해결책이 아닙니다 ✗","calma: '침착함'이라는 뜻으로 속도에 관한 것이라 양 조절과 다릅니다 ✗","moderación: '절제'라는 뜻으로 과식과 대비되는 해결책입니다 ✓","lentitud: '느림'이라는 뜻으로 먹는 양이 아니라 속도를 말합니다 ✗"]},{"id":"V438","q":"Isabel me tiene ____ porque he aprobado todas las asignaturas y ella no.","o":["pavor","envidia","fobia","miedo"],"a":1,"k":"감정 명사","t":"이사벨은 내가 모든 과목에 합격했는데 자기는 그러지 못해서 나를 질투한다.","e":"'tener envidia a alguien'은 '누군가를 부러워하다/질투하다'라는 표현입니다. 내가 합격하고 그녀는 못한 상황이 이유이므로 질투가 자연스럽습니다. 여기서 me는 간접목적격 대명사(~에게에 해당)입니다.","x":["pavor: '공포'라는 뜻으로 합격 여부와 연결되지 않습니다 ✗","envidia: '질투, 부러움'이라는 뜻으로 상황과 정확히 맞습니다 ✓","fobia: '공포증'이라는 뜻으로 시험 결과와 관계없습니다 ✗","miedo: '두려움'이라는 뜻으로 질투할 상황과 맞지 않습니다 ✗"]},{"id":"V439","q":"No creo que los terrícolas seamos los únicos, creo que hay vida ____.","o":["terrestre","extraterrestre","extraordinaria","extravagante"],"a":1,"k":"접두사 extra-","t":"우리 지구인만이 유일하다고 생각하지 않는다. 외계 생명체가 있다고 믿는다.","e":"extraterrestre는 extra-(~밖의) + terrestre(지구의)로 '외계의'라는 뜻입니다. terrícolas(지구인)가 유일하지 않다는 말 다음이므로 지구 밖의 생명이 와야 합니다. 'No creo que + 접속법(seamos)'은 부정적 믿음 표현이라 접속법을 씁니다.","x":["terrestre: '지구의, 육지의'라는 뜻으로 지구인 외의 생명을 나타내지 못합니다 ✗","extraterrestre: '외계의'라는 뜻으로 지구 밖 생명체를 뜻합니다 ✓","extraordinaria: '특별한, 비범한'이라는 뜻으로 외계 생명을 뜻하지 않습니다 ✗","extravagante: '괴상한, 별난'이라는 뜻으로 문맥과 맞지 않습니다 ✗"]},{"id":"V440","q":"¿Qué crema hidratante usas? Tienes ____ en perfecto estado.","o":["las pestañas","la dentadura","el cabello","el cutis"],"a":3,"k":"신체 부위 어휘","t":"너 어떤 보습 크림 써? 피부(얼굴 피부)가 완벽한 상태네.","e":"cutis는 '(특히 얼굴의) 피부, 살결'이라는 뜻의 남성 명사로 단수·복수 형태가 같습니다. crema hidratante(보습 크림)를 바르는 부위이므로 얼굴 피부가 가장 자연스럽습니다.","x":["las pestañas: '속눈썹'이라는 뜻으로 보습 크림을 바르는 곳이 아닙니다 ✗","la dentadura: '치아(전체)'라는 뜻으로 크림과 관계없습니다 ✗","el cabello: '머리카락'이라는 뜻으로 보습 크림보다는 헤어 제품을 씁니다 ✗","el cutis: '얼굴 피부'라는 뜻으로 보습 크림을 바르는 부위입니다 ✓"]},{"id":"V441","q":"Mi marido tiene una salud de ____. ¡Nunca ha estado enfermo!","o":["oro","bronce","hierro","acero"],"a":2,"k":"관용 표현","t":"우리 남편은 무쇠 같은 건강을 가졌다. 한 번도 아픈 적이 없다!","e":"'tener una salud de hierro'는 '무쇠처럼 튼튼한 건강을 가지다'라는 관용 표현입니다. hierro(쇠)는 튼튼함을 상징합니다. 비슷하게 'voluntad de hierro(강철 같은 의지)'라는 표현도 있습니다.","x":["oro: '금'이라는 뜻으로 'corazón de oro(착한 마음)'처럼 쓰고 건강에는 쓰지 않습니다 ✗","bronce: '청동'이라는 뜻으로 건강 관용 표현에 쓰지 않습니다 ✗","hierro: '쇠'라는 뜻으로 salud de hierro(튼튼한 건강)를 완성합니다 ✓","acero: '강철'이라는 뜻으로 의미는 비슷하지만 이 관용 표현에는 hierro를 씁니다 ✗"]},{"id":"V442","q":"Alicia es la reina de la ____ de baile, sobre todo cuando ponen su música preferida.","o":["cancha","pieza","mesa","pista"],"a":3,"k":"장소 어휘","t":"알리시아는 무대(댄스 플로어)의 여왕이다. 특히 자기가 좋아하는 음악이 나오면 그렇다.","e":"pista de baile는 '댄스 플로어'라는 뜻입니다. pista는 '트랙, 코트, 활주로' 등 특정 활동을 하는 평평한 공간을 말합니다(pista de tenis 테니스 코트, pista de aterrizaje 활주로). 'ser la reina de la pista'는 춤을 가장 잘 추는 사람을 말합니다.","x":["cancha: '(구기 종목) 경기장, 코트'라는 뜻으로 춤추는 곳이 아닙니다 ✗","pieza: '조각, 곡'이라는 뜻으로 장소가 아닙니다 ✗","mesa: '탁자'라는 뜻으로 춤추는 공간이 아닙니다 ✗","pista: '플로어, 트랙'이라는 뜻으로 pista de baile(댄스 플로어)가 됩니다 ✓"]},{"id":"V443","q":"Está enojado porque ____ sus maletas.","o":["extraditaron","extraviaron","extrapolaron","extrañaron"],"a":1,"k":"형태가 비슷한 동사","t":"그는 (항공사가) 짐을 분실해서 화가 나 있다.","e":"extraviar는 '분실하다, 잃어버리다'라는 격식 있는 동사로, 항공사가 수하물을 분실했을 때 자주 씁니다. 3인칭 복수(extraviaron)로 써서 '누군가가 분실했다'는 무인칭 의미가 됩니다. enojado(화가 난)는 중남미에서 주로 쓰고 스페인에서는 enfadado를 더 많이 씁니다.","x":["extraditaron: '(범죄인을) 인도했다'라는 뜻으로 가방과 관계없습니다 ✗","extraviaron: '분실했다'라는 뜻으로 화가 난 이유가 됩니다 ✓","extrapolaron: '(결론을) 확대 적용했다'라는 뜻으로 가방과 맞지 않습니다 ✗","extrañaron: '그리워했다'라는 뜻으로 화가 난 이유가 되지 않습니다 ✗"]},{"id":"V444","q":"Tiene los dientes ____ de tanto fumar.","o":["verdosos","grisáceos","amarillentos","azulados"],"a":2,"k":"색상 접미사","t":"그는 담배를 너무 많이 피워서 이가 누렇다.","e":"amarillento는 amarillo(노란)에 접미사 -ento가 붙어 '누르스름한'이라는 뜻입니다. 흡연으로 치아가 누렇게 변하는 것을 표현합니다. 'de tanto + 동사원형'은 '너무 ~해서'라는 원인 표현입니다.","x":["verdosos: '푸르스름한(초록빛의)'이라는 뜻으로 흡연으로 인한 치아 색과 맞지 않습니다 ✗","grisáceos: '회색빛의'라는 뜻으로 흡연의 대표적 결과가 아닙니다 ✗","amarillentos: '누르스름한'이라는 뜻으로 흡연으로 변색된 치아에 맞습니다 ✓","azulados: '푸르스름한(파란빛의)'이라는 뜻으로 치아 변색과 관계없습니다 ✗"]},{"id":"V445","q":"Si inviertes tu dinero, ____ el riesgo de perderlo.","o":["corres","soportas","pasas","aguantas"],"a":0,"k":"동사 연어(짝꿍)","t":"돈을 투자하면 잃을 위험을 감수하게 된다.","e":"'correr el riesgo de...'는 '~할 위험을 무릅쓰다/감수하다'라는 고정 표현입니다. 위험(riesgo)과 짝을 이루는 동사는 correr입니다. 비슷하게 'correr peligro(위험에 처하다)'라는 표현도 있습니다.","x":["corres: correr el riesgo(위험을 감수하다)라는 고정 표현을 만듭니다 ✓","soportas: '견디다'라는 뜻으로 riesgo와 짝을 이루지 않습니다 ✗","pasas: '겪다, 지나가다'라는 뜻으로 riesgo와 고정 표현을 이루지 않습니다 ✗","aguantas: '참다'라는 뜻으로 riesgo와 함께 쓰지 않습니다 ✗"]},{"id":"V446","q":"El rescate de los accidentados por parte del equipo de ____ fue todo un éxito.","o":["mantenimiento","defensa","liberación","salvamento"],"a":3,"k":"구조 관련 어휘","t":"구조대가 사고 피해자들을 구조한 것은 대성공이었다.","e":"equipo de salvamento는 '구조대'라는 뜻입니다. salvamento는 salvar(구하다)에서 온 명사로 '구조, 구출'을 뜻합니다. rescate(구조)와 accidentados(사고를 당한 사람들)가 단서입니다.","x":["mantenimiento: '유지 보수'라는 뜻으로 사람을 구조하는 팀이 아닙니다 ✗","defensa: '방어, 수비'라는 뜻으로 구조와 관계없습니다 ✗","liberación: '해방, 석방'이라는 뜻으로 인질 등에 쓰고 사고 구조대를 뜻하지 않습니다 ✗","salvamento: '구조'라는 뜻으로 equipo de salvamento(구조대)가 됩니다 ✓"]},{"id":"V447","q":"En verano hace tanto calor que no podemos dormir sin ____.","o":["ventilador","brasero","radiador","estufa"],"a":0,"k":"가전제품 어휘","t":"여름에는 너무 더워서 선풍기 없이는 잘 수가 없다.","e":"ventilador는 '선풍기'라는 뜻으로 ventilar(환기시키다)에서 왔습니다. 여름 더위(calor)를 식혀 주는 기기입니다. 나머지는 모두 난방 기구라서 여름과 맞지 않습니다. 참고로 에어컨은 aire acondicionado입니다.","x":["ventilador: '선풍기'라는 뜻으로 여름 더위에 필요한 기기입니다 ✓","brasero: '화로'라는 뜻으로 난방 기구라 여름과 맞지 않습니다 ✗","radiador: '라디에이터(난방기)'라는 뜻으로 겨울용입니다 ✗","estufa: '난로'라는 뜻으로 겨울용입니다 ✗"]},{"id":"V448","q":"Pilar nació en el ____ de una familia de clase alta.","o":["seno","pecho","busto","corazón"],"a":0,"k":"관용 표현","t":"필라르는 상류층 가정에서 태어났다.","e":"'en el seno de'는 '~의 품에서, ~내부에서'라는 격식 있는 표현입니다. nacer en el seno de una familia(~한 가정에서 태어나다)는 자주 쓰는 고정 표현입니다. seno는 원래 '가슴, 품'이라는 뜻입니다.","x":["seno: 'en el seno de(~의 품에서)'라는 고정 표현을 완성합니다 ✓","pecho: '가슴'이라는 뜻으로 신체 부위를 말하며 이 표현에 쓰지 않습니다 ✗","busto: '흉상, 상반신'이라는 뜻으로 이 표현에 쓰지 않습니다 ✗","corazón: '심장, 마음'이라는 뜻으로 'en el corazón de'는 '~의 중심부에'라는 뜻이라 가정과 어울리지 않습니다 ✗"]},{"id":"V449","q":"Los futbolistas suelen ____ a los treinta y tantos años.","o":["alejarse","distanciarse","escaparse","retirarse"],"a":3,"k":"직업 관련 동사","t":"축구 선수들은 보통 서른 몇 살에 은퇴한다.","e":"retirarse는 '은퇴하다, 물러나다'라는 대명동사입니다. 운동선수의 은퇴를 말할 때 가장 일반적으로 씁니다. 'treinta y tantos'는 '서른 몇'이라는 뜻의 구어 표현입니다.","x":["alejarse: '멀어지다'라는 뜻으로 은퇴를 의미하지 않습니다 ✗","distanciarse: '거리를 두다'라는 뜻으로 사람 관계에 주로 씁니다 ✗","escaparse: '도망치다'라는 뜻으로 은퇴와 관계없습니다 ✗","retirarse: '은퇴하다'라는 뜻으로 선수들의 은퇴에 맞습니다 ✓"]},{"id":"V450","q":"No tengo intención de comprar nada en esta tienda, sólo quiero ____ un vistazo.","o":["echar","hacer","tener","poner"],"a":0,"k":"동사 연어(짝꿍)","t":"이 가게에서 뭘 살 생각은 없어요. 그냥 한번 둘러보고 싶을 뿐이에요.","e":"'echar un vistazo'는 '한번 훑어보다, 둘러보다'라는 고정 표현입니다. vistazo는 '힐끗 봄'이라는 뜻이며 항상 echar와 짝을 이룹니다. 'echar una mano(도와주다)'처럼 echar는 다양한 관용 표현에 쓰입니다.","x":["echar: echar un vistazo(훑어보다)라는 고정 표현을 만듭니다 ✓","hacer: '하다'라는 뜻이지만 vistazo와 짝을 이루지 않습니다 ✗","tener: '가지다'라는 뜻으로 vistazo와 함께 쓰지 않습니다 ✗","poner: '놓다'라는 뜻으로 vistazo와 함께 쓰지 않습니다 ✗"]},{"id":"V451","q":"Nuestros padres nos inculcaron ____ esenciales como el esfuerzo y la gratitud.","o":["beneficios","valoraciones","intereses","valores"],"a":3,"k":"가치관 어휘","t":"우리 부모님은 우리에게 노력과 감사 같은 본질적인 가치들을 심어 주셨다.","e":"valores는 valor(가치)의 복수형으로, 사람이 소중히 여기는 도덕적 원칙, 즉 '가치관'을 뜻합니다. inculcar(가르쳐 심어 주다)와 함께 'inculcar valores(가치관을 심어 주다)'라는 표현으로 자주 쓰입니다. 예: Los valores familiares son importantes.(가족의 가치관은 중요하다.)","x":["beneficios: '이익, 혜택'이라는 뜻이라 노력·감사 같은 덕목을 가리킬 수 없습니다 ✗","valoraciones: '평가, 감정(가격 매기기)'라는 뜻이라 문맥과 맞지 않습니다 ✗","intereses: '관심사, 이자'라는 뜻이라 덕목을 뜻하지 않습니다 ✗","valores: '가치(관)'으로, 노력과 감사 같은 덕목에 딱 맞습니다 ✓"]},{"id":"V452","q":"Fue expulsado del campo por ____ a un compañero.","o":["agredir","atracar","robar","secuestrar"],"a":0,"k":"범죄·폭력 동사","t":"그는 동료를 폭행해서 경기장에서 퇴장당했다.","e":"agredir는 '(신체적·언어적으로) 공격하다, 폭행하다'라는 뜻입니다. 축구 경기에서 상대를 때려 퇴장(expulsado del campo)당하는 상황에 가장 자연스럽습니다. 명사형은 agresión(폭행, 공격)입니다.","x":["agredir: '폭행하다, 공격하다'로 퇴장 사유에 딱 맞습니다 ✓","atracar: '(무기로 위협해) 강도질하다' 또는 '배를 정박하다'라는 뜻이라 경기 상황과 안 맞습니다 ✗","robar: '훔치다'라는 뜻으로, 사람을 목적어로 하는 퇴장 사유로는 어색합니다 ✗","secuestrar: '납치하다'라는 뜻이라 문맥과 전혀 맞지 않습니다 ✗"]},{"id":"V453","q":"Es necesario que haya canales de televisión con programas ____ para niños.","o":["restrictivos","repetitivos","educativos","nocivos"],"a":2,"k":"방송 프로그램 어휘","t":"어린이를 위한 교육용 프로그램이 있는 TV 채널이 필요하다.","e":"educativo는 '교육적인, 교육용의'라는 뜻으로 'programas educativos(교육 프로그램)'는 아주 흔한 조합입니다. 'Es necesario que haya'는 접속법(바람·필요를 나타낼 때 쓰는 동사 형태) haya가 쓰인 구조로, 무언가가 필요하다는 긍정적 의미이므로 긍정적인 형용사가 와야 합니다.","x":["restrictivos: '제한적인'이라는 뜻이라 어린이 프로그램을 권하는 문맥과 맞지 않습니다 ✗","repetitivos: '반복적인'이라는 뜻으로 부정적 뉘앙스라 필요성을 말하는 문장에 안 맞습니다 ✗","educativos: '교육적인'으로 어린이를 위한 좋은 프로그램을 뜻합니다 ✓","nocivos: '해로운'이라는 뜻이라 필요하다고 말할 수 없습니다 ✗"]},{"id":"V454","q":"Prefiero la comunicación ____, por escrito no soy muy bueno.","o":["ordinaria","oral","habitual","regular"],"a":1,"k":"의사소통 방식","t":"나는 구두(말로 하는) 의사소통이 더 좋다. 글로는 잘 못한다.","e":"oral은 '구두의, 말로 하는'이라는 뜻으로, 뒤에 나오는 'por escrito(글로, 서면으로)'와 반대되는 개념입니다. 'comunicación oral(구두 의사소통)'과 'comunicación escrita(서면 의사소통)'를 짝으로 기억해 두세요. 예: examen oral(구술시험).","x":["ordinaria: '평범한, 보통의'라는 뜻이라 글과의 대비가 성립하지 않습니다 ✗","oral: '구두의, 말로 하는'으로 'por escrito'와 대조됩니다 ✓","habitual: '습관적인, 평소의'라는 뜻이라 문맥과 맞지 않습니다 ✗","regular: '규칙적인, 보통의'라는 뜻이라 말/글의 대비를 나타내지 못합니다 ✗"]},{"id":"V455","q":"No me sé de memoria ningún ____ navideño.","o":["cántico","canto","cantar","villancico"],"a":3,"k":"크리스마스 어휘","t":"나는 크리스마스 캐럴을 하나도 외우지 못한다.","e":"villancico는 크리스마스에 부르는 전통 노래, 즉 '캐럴'을 뜻합니다. 그 자체로 크리스마스 노래라는 뜻이 있어서 navideño(크리스마스의)와 함께 자연스럽게 쓰입니다. 'saberse algo de memoria'는 '~을 외우고 있다'라는 표현입니다.","x":["cántico: '찬가, 성가'라는 뜻으로 문어적이며 캐럴을 가리키는 일반적인 말이 아닙니다 ✗","canto: '노래하기, 노래(소리)'라는 뜻으로 특정 크리스마스 노래를 가리키는 말로는 어색합니다 ✗","cantar: '노래하다'라는 동사(명사로는 옛 시가)라 여기에 맞지 않습니다 ✗","villancico: '크리스마스 캐럴'로 문맥에 딱 맞습니다 ✓"]},{"id":"V456","q":"Cuando era adolescente era muy rebelde, por eso solía ____ a mis padres.","o":["desobedecer","atender","regañar","reñir"],"a":0,"k":"성격·행동 동사","t":"나는 청소년 때 매우 반항적이어서 부모님 말씀을 자주 듣지 않곤 했다.","e":"desobedecer는 obedecer(복종하다, 말을 듣다)에 부정 접두사 des-가 붙어 '말을 듣지 않다, 불복종하다'라는 뜻입니다. rebelde(반항적인)라는 앞 문장과 자연스럽게 이어집니다. 'soler + 동사원형'은 '~하곤 하다'라는 뜻입니다.","x":["desobedecer: '말을 듣지 않다'로 반항적인 청소년의 행동에 맞습니다 ✓","atender: '돌보다, 주의를 기울이다'라는 뜻이라 반항과 반대됩니다 ✗","regañar: '꾸짖다'는 보통 부모가 자녀에게 하는 행동이라 주어와 맞지 않습니다 ✗","reñir: '꾸짖다, 다투다'라는 뜻으로 반항의 결과로 보기에 문맥이 어색합니다 ✗"]},{"id":"V457","q":"Beber suficiente agua es muy ____.","o":["perjudicial","nocivo","saludable","insalubre"],"a":2,"k":"건강 형용사","t":"물을 충분히 마시는 것은 매우 건강에 좋다.","e":"saludable는 '건강에 좋은'이라는 뜻입니다. salud(건강)에서 나온 말로, 'comida saludable(건강식)', 'hábitos saludables(건강한 습관)'처럼 자주 쓰입니다. 물을 충분히 마시는 것은 긍정적인 행동이므로 긍정적 형용사가 필요합니다.","x":["perjudicial: '해로운'이라는 뜻이라 물 마시기와 맞지 않습니다 ✗","nocivo: '유해한'이라는 뜻으로 반대 의미입니다 ✗","saludable: '건강에 좋은'으로 정답입니다 ✓","insalubre: '비위생적인, 건강에 나쁜'이라는 뜻이라 반대 의미입니다 ✗"]},{"id":"V458","q":"Este guiso está ____, voy a echarle una pizca de sal.","o":["salado","de rechupete","jugoso","insípido"],"a":3,"k":"음식 맛 형용사","t":"이 스튜는 싱거워서 소금을 한 꼬집 넣을 거야.","e":"insípido는 '맛이 없는, 싱거운'이라는 뜻입니다. 소금을 더 넣겠다(echarle una pizca de sal)는 말은 음식이 싱겁다는 뜻이므로 insípido가 맞습니다. 참고로 일상에서는 'soso(싱거운)'도 많이 씁니다.","x":["salado: '짠'이라는 뜻이라 소금을 더 넣는 이유가 될 수 없습니다 ✗","de rechupete: '아주 맛있는'이라는 구어 표현이라 소금을 더 넣을 필요가 없습니다 ✗","jugoso: '육즙이 많은, 즙이 많은'이라는 뜻으로 소금과 관련이 없습니다 ✗","insípido: '싱거운, 맛이 없는'으로 소금을 넣는 이유에 딱 맞습니다 ✓"]},{"id":"V459","q":"La ropa de ____ es muy adecuada para los días de calor.","o":["lino","pana","lana","cuero"],"a":0,"k":"옷감 어휘","t":"리넨 옷은 더운 날에 아주 적합하다.","e":"lino는 '리넨(아마로 만든 천)'으로, 가볍고 통풍이 잘 되어 여름옷에 많이 쓰입니다. 'ropa de + 재료'는 '~로 만든 옷'이라는 표현입니다. 예: camisa de algodón(면 셔츠).","x":["lino: '리넨'으로 시원해서 더운 날에 적합합니다 ✓","pana: '코듀로이(골덴)'로 두툼해서 주로 겨울에 입습니다 ✗","lana: '양모, 울'로 따뜻해서 추운 날에 입습니다 ✗","cuero: '가죽'으로 덥고 무거워 여름옷에 적합하지 않습니다 ✗"]},{"id":"V460","q":"Para solicitar este puesto, le recomiendo que envíe una carta de ____ además de su currículum.","o":["queja","reclamación","presentación","agradecimiento"],"a":2,"k":"구직 서류 어휘","t":"이 자리에 지원하려면 이력서 외에 자기소개서도 보내실 것을 권합니다.","e":"'carta de presentación'은 구직 시 이력서와 함께 보내는 '자기소개서, 커버레터'입니다. 'le recomiendo que envíe'에서 envíe는 접속법(권유·바람을 나타낼 때 쓰는 동사 형태)입니다. 'solicitar un puesto'는 '일자리에 지원하다'라는 뜻입니다.","x":["queja: 'carta de queja'는 '항의 편지'라서 지원 서류가 아닙니다 ✗","reclamación: 'carta de reclamación'은 '이의 제기·클레임 서한'이라 맞지 않습니다 ✗","presentación: 'carta de presentación'은 '자기소개서'로 정답입니다 ✓","agradecimiento: 'carta de agradecimiento'는 '감사 편지'로 지원 단계에 맞지 않습니다 ✗"]},{"id":"V461","q":"No puedo seguir trabajando, así que voy a solicitar la ____ anticipada.","o":["independencia","jubilación","liberación","emancipación"],"a":1,"k":"직장 생활 어휘","t":"더 이상 일을 계속할 수 없어서 조기 퇴직을 신청할 것이다.","e":"jubilación는 '(정년) 퇴직, 은퇴'이고, 'jubilación anticipada'는 '조기 퇴직'입니다. 동사는 jubilarse(은퇴하다), 퇴직자는 jubilado/a입니다. 예: Mi padre se jubiló a los 65 años.(아버지는 65세에 은퇴하셨다.)","x":["independencia: '독립'이라는 뜻으로 일을 그만두는 것과 관련이 없습니다 ✗","jubilación: '은퇴, 퇴직'으로 'jubilación anticipada(조기 퇴직)'가 됩니다 ✓","liberación: '해방, 석방'이라는 뜻이라 맞지 않습니다 ✗","emancipación: '(부모로부터의) 독립, 해방'이라는 뜻이라 직장과 무관합니다 ✗"]},{"id":"V462","q":"Trabajo por cuenta ____, es decir, soy autónomo.","o":["individual","libre","ajena","propia"],"a":3,"k":"고용 형태 표현","t":"나는 자영업으로 일한다, 즉 프리랜서(자영업자)이다.","e":"'trabajar por cuenta propia'는 '자기 계산으로 일하다', 즉 '자영업을 하다'라는 뜻입니다. 반대로 'trabajar por cuenta ajena'는 '남의 회사에 고용되어 일하다'입니다. autónomo는 스페인에서 '자영업자, 개인사업자'를 뜻합니다.","x":["individual: '개인의'라는 뜻이지만 'por cuenta individual'이라는 표현은 쓰지 않습니다 ✗","libre: '자유로운'이지만 고정 표현이 아닙니다 ✗","ajena: 'por cuenta ajena'는 '고용되어(남을 위해) 일하다'라서 autónomo와 반대입니다 ✗","propia: 'por cuenta propia'는 '자영업으로'로 autónomo와 같은 뜻입니다 ✓"]},{"id":"V463","q":"Me alegra que ____ vuestro negocio. ¡Bien hecho!","o":["quiebre","naufrague","se hunda","prospere"],"a":3,"k":"사업 성패 동사","t":"너희 사업이 번창해서 기쁘다. 잘했어!","e":"prosperar는 '번영하다, 번창하다, 잘되다'라는 뜻입니다. 'Me alegra que' 다음에는 감정 표현이므로 접속법(감정을 나타낼 때 쓰는 동사 형태) prospere가 옵니다. '기쁘다'와 '잘했어!'라는 말로 보아 긍정적 결과가 필요합니다.","x":["quiebre: quebrar(파산하다)의 접속법으로, 기쁨과 맞지 않습니다 ✗","naufrague: naufragar(난파하다, 실패하다)의 접속법이라 부정적입니다 ✗","se hunda: hundirse(가라앉다, 망하다)의 접속법이라 부정적입니다 ✗","prospere: prosperar(번창하다)의 접속법으로 정답입니다 ✓"]},{"id":"V464","q":"En mi familia ____ la igualdad de género, por eso todos contribuimos en las tareas domésticas.","o":["se ignora","se fomenta","se desconoce","se menosprecia"],"a":1,"k":"사회 가치 동사","t":"우리 가족은 성평등을 장려한다. 그래서 모두가 집안일에 기여한다.","e":"fomentar는 '장려하다, 촉진하다'라는 뜻이고, 'se fomenta'는 무인칭 se 구문(주어를 특정하지 않고 '~가 이루어진다'로 표현)입니다. 모두가 집안일을 함께 한다는 결과를 보면 성평등을 장려한다는 의미가 맞습니다. 예: fomentar la lectura(독서를 장려하다).","x":["se ignora: '무시된다, 모른다'라는 뜻이라 뒤의 결과와 모순됩니다 ✗","se fomenta: '장려된다'로 모두가 집안일을 하는 결과와 맞습니다 ✓","se desconoce: '알려져 있지 않다'라는 뜻이라 문맥과 맞지 않습니다 ✗","se menosprecia: '경시된다, 무시된다'라는 뜻이라 반대 의미입니다 ✗"]},{"id":"V465","q":"En épocas de poca energía, suelo tomar ____ de vitaminas y minerales.","o":["aditivos","suplementos","sustitutos","añadidos"],"a":1,"k":"건강 보조 어휘","t":"기운이 없는 시기에는 비타민과 미네랄 보충제를 먹곤 한다.","e":"suplemento는 '보충(물), 보조제'라는 뜻이고 'suplementos vitamínicos'나 'suplementos de vitaminas'는 '비타민 보충제'입니다. 부족한 영양을 채우기 위해 먹는 것이므로 suplementos가 맞습니다.","x":["aditivos: '(식품) 첨가물'이라는 뜻으로 영양 보충과는 다릅니다 ✗","suplementos: '보충제'로 비타민·미네랄과 함께 쓰는 정답입니다 ✓","sustitutos: '대체물'이라는 뜻이라 보충의 의미가 아닙니다 ✗","añadidos: '덧붙인 것'이라는 일반적인 말로 영양제를 뜻하지 않습니다 ✗"]},{"id":"V466","q":"¡Qué maja es Verónica! Es ____.","o":["un meteorito","una brisa","una luna","un sol"],"a":3,"k":"사람 칭찬 관용구","t":"베로니카는 정말 착하다! 정말 사랑스러운 사람이야.","e":"'ser un sol'은 '해님 같다', 즉 '아주 다정하고 사랑스러운 사람이다'라는 관용 표현입니다. maja는 스페인에서 '착한, 호감 가는'이라는 뜻으로 많이 씁니다. 여성에게도 'es un sol'처럼 남성 명사 sol 그대로 씁니다.","x":["un meteorito: '운석'이라는 뜻으로 사람을 칭찬하는 표현이 아닙니다 ✗","una brisa: '산들바람'이지만 이런 관용 표현은 없습니다 ✗","una luna: '달'이지만 사람을 칭찬하는 관용 표현으로 쓰지 않습니다 ✗","un sol: 'ser un sol(아주 사랑스러운 사람이다)'라는 관용 표현입니다 ✓"]},{"id":"V467","q":"Elena es muy ____, no le cuesta nada convencer a los demás.","o":["simpática","dicharachera","seductora","persuasiva"],"a":3,"k":"성격 형용사","t":"엘레나는 설득력이 아주 뛰어나서 다른 사람들을 설득하는 데 전혀 어려움이 없다.","e":"persuasivo/a는 '설득력 있는'이라는 뜻으로 persuadir(설득하다)에서 나왔습니다. 뒤 문장 'convencer a los demás(다른 사람을 설득하다)'와 의미가 직접 연결됩니다. 'no le cuesta nada + 동사원형'은 '~하는 게 전혀 어렵지 않다'라는 표현입니다.","x":["simpática: '상냥한, 호감 가는'이지만 설득 능력과 직접 연결되지 않습니다 ✗","dicharachera: '말이 많고 재치 있는'이라는 뜻으로 설득력과는 다릅니다 ✗","seductora: '매혹적인, 유혹하는'이라는 뜻으로 설득과 거리가 있습니다 ✗","persuasiva: '설득력 있는'으로 남을 쉽게 설득한다는 내용과 맞습니다 ✓"]},{"id":"V468","q":"La cobra es una ____ venenosa.","o":["medusa","serpiente","lagartija","araña"],"a":1,"k":"동물 어휘","t":"코브라는 독이 있는 뱀이다.","e":"serpiente는 '뱀'입니다. 코브라(cobra)는 뱀의 한 종류이므로 정답입니다. venenoso/a는 '독이 있는'이라는 뜻이고, veneno는 '독'입니다.","x":["medusa: '해파리'라서 코브라가 아닙니다 ✗","serpiente: '뱀'으로 코브라가 속하는 동물입니다 ✓","lagartija: '도마뱀(작은 도마뱀)'이라 코브라가 아닙니다 ✗","araña: '거미'라서 코브라가 아닙니다 ✗"]},{"id":"V469","q":"Los perros tienen ____ del olfato muy desarrollado.","o":["el sentido","el sentimiento","la percepción","la sensación"],"a":0,"k":"감각 어휘","t":"개는 후각이 매우 발달해 있다.","e":"'el sentido del olfato'는 '후각(냄새 맡는 감각)'입니다. 오감은 los cinco sentidos로, vista(시각), oído(청각), olfato(후각), gusto(미각), tacto(촉각)입니다. sentido는 '감각' 외에 '의미, 방향'이라는 뜻도 있습니다.","x":["el sentido: '감각'으로 'sentido del olfato(후각)'가 됩니다 ✓","el sentimiento: '감정, 느낌'이라 신체 감각을 말할 때 쓰지 않습니다 ✗","la percepción: '지각, 인식'이지만 'percepción del olfato'는 관용적이지 않고 성(여성)도 'desarrollado'와 맞지 않습니다 ✗","la sensación: '느낌, 감각적 인상'이라 오감 기관을 말하지 않고 성도 맞지 않습니다 ✗"]},{"id":"V470","q":"La ____ escritora dio un breve discurso al recoger su premio.","o":["galardonada","fracasada","derrotada","vencida"],"a":0,"k":"수상 관련 어휘","t":"수상한 그 작가는 상을 받으며 짧은 연설을 했다.","e":"galardonado/a는 galardonar(상을 수여하다)의 과거분사로 '수상한, 상을 받은'이라는 뜻입니다. 상을 받는다(recoger su premio)는 문맥과 정확히 맞습니다. galardón은 '상, 영예'라는 명사입니다.","x":["galardonada: '수상한'으로 상을 받는 작가에게 딱 맞습니다 ✓","fracasada: '실패한'이라는 뜻이라 상을 받는 상황과 반대입니다 ✗","derrotada: '패배한'이라는 뜻이라 수상과 맞지 않습니다 ✗","vencida: '패배한, 기한이 지난'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V471","q":"Es normal que no haya recordado la fecha de tu cumpleaños, es muy ____.","o":["arisca","atenta","olvidadiza","desagradecida"],"a":2,"k":"성격 형용사","t":"그녀가 네 생일 날짜를 기억하지 못한 건 당연해, 그녀는 건망증이 아주 심하거든.","e":"olvidadizo/a는 olvidar(잊다)에서 나온 형용사로 '잘 잊어버리는, 건망증이 있는'이라는 뜻입니다. 생일을 기억하지 못한 이유를 설명하므로 olvidadiza가 자연스럽습니다. 'Es normal que no haya recordado'에는 접속법 현재완료가 쓰였습니다.","x":["arisca: '무뚝뚝한, 쌀쌀맞은'이라는 뜻으로 기억력과 관련이 없습니다 ✗","atenta: '세심한, 배려하는'이라는 뜻이라 생일을 잊은 것과 반대됩니다 ✗","olvidadiza: '잘 잊어버리는'으로 생일을 잊은 이유가 됩니다 ✓","desagradecida: '배은망덕한'이라는 뜻이라 잊어버린 이유로는 맞지 않습니다 ✗"]},{"id":"V472","q":"Durante mi primer año en la universidad, vivía en ____ de estudiantes.","o":["una residencia","un rancho","una finca","un asilo"],"a":0,"k":"주거 어휘","t":"대학 1학년 때 나는 학생 기숙사에 살았다.","e":"'residencia de estudiantes'는 '학생 기숙사'입니다. residencia는 일반적으로 '거주지, 거주'를 뜻하고, 'residencia de ancianos(양로원)'처럼 시설 이름에도 쓰입니다. 대학 1학년 때 산 곳으로 가장 자연스럽습니다.","x":["una residencia: 'residencia de estudiantes(학생 기숙사)'로 정답입니다 ✓","un rancho: '목장, 농장(특히 중남미)'이라 학생 거주지가 아닙니다 ✗","una finca: '농장, 시골 부동산'이라 학생 숙소가 아닙니다 ✗","un asilo: '보호 시설, 양로원' 또는 '망명'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V473","q":"Si crees que te han cobrado más de la cuenta, deberías poner una ____.","o":["excusa","reclamación","apelación","sanción"],"a":1,"k":"소비자 불만 어휘","t":"돈을 더 많이 청구당했다고 생각하면 클레임(이의 신청)을 제기해야 한다.","e":"'poner una reclamación'은 '클레임을 제기하다, 이의를 신청하다'라는 표현입니다. 'cobrar más de la cuenta'는 '정해진 것보다 더 많이 청구하다'라는 뜻입니다. 가게나 회사에 정식으로 불만을 제기할 때 reclamación을 씁니다.","x":["excusa: '변명, 핑계'라는 뜻이라 소비자 불만 제기와 맞지 않습니다 ✗","reclamación: '클레임, 이의 신청'으로 'poner una reclamación'이 정답입니다 ✓","apelación: '항소(법원 판결에 대한)'라는 법률 용어라 이 상황에는 맞지 않습니다 ✗","sanción: '제재, 벌금'으로 소비자가 거는 것이 아닙니다 ✗"]},{"id":"V474","q":"¡Qué ____ es Ricardo! Ha tenido muchísimas novias.","o":["reservado","enamoradizo","cerrado","introvertido"],"a":1,"k":"성격 형용사","t":"리카르도는 정말 금사빠야! 여자 친구가 엄청 많았어.","e":"enamoradizo/a는 enamorarse(사랑에 빠지다)에서 나온 말로 '쉽게 사랑에 빠지는'이라는 뜻입니다. 연애를 많이 했다는 뒷문장과 정확히 연결됩니다. -dizo 어미는 '~하기 쉬운' 성질을 나타냅니다(예: olvidadizo 잘 잊는, asustadizo 잘 놀라는).","x":["reservado: '내성적인, 말이 없는'이라는 뜻이라 연애가 많은 것과 연결되지 않습니다 ✗","enamoradizo: '쉽게 사랑에 빠지는'으로 정답입니다 ✓","cerrado: '폐쇄적인, 마음을 잘 안 여는'이라는 뜻이라 맞지 않습니다 ✗","introvertido: '내향적인'이라는 뜻이라 문맥과 맞지 않습니다 ✗"]},{"id":"V475","q":"¿Qué te gusta más del huevo, ____ o la yema?","o":["la clara","lo blanco","lo amarillo","lo oscuro"],"a":0,"k":"음식 어휘","t":"너는 달걀에서 흰자가 좋아, 노른자가 좋아?","e":"달걀의 '흰자'는 la clara, '노른자'는 la yema입니다. 색으로 'lo blanco', 'lo amarillo'라고 풀어 말할 수도 있겠지만 정식 명칭은 clara입니다. 예: Bate las claras a punto de nieve.(흰자를 단단하게 거품 내세요.)","x":["la clara: '(달걀) 흰자'라는 정식 명칭으로 정답입니다 ✓","lo blanco: '흰 부분'이라는 풀어 쓴 말로 정식 단어가 아닙니다 ✗","lo amarillo: '노란 부분'이라 오히려 노른자를 가리키며 yema와 중복됩니다 ✗","lo oscuro: '어두운 부분'이라 달걀과 관련이 없습니다 ✗"]},{"id":"V476","q":"Esta asignatura es ____, no obligatoria.","o":["optativa","imprescindible","indispensable","forzosa"],"a":0,"k":"교육 어휘","t":"이 과목은 선택 과목이지, 필수가 아니다.","e":"optativo/a는 '선택할 수 있는, 선택의'라는 뜻으로 'asignatura optativa'는 '선택 과목'입니다. 뒤의 'no obligatoria(필수가 아닌)'와 대비되어 정답이 분명합니다. 참고로 '필수 과목'은 'asignatura obligatoria'입니다.","x":["optativa: '선택의'로 'no obligatoria'와 의미가 이어집니다 ✓","imprescindible: '꼭 필요한'이라는 뜻이라 'no obligatoria'와 모순됩니다 ✗","indispensable: '없어서는 안 되는'이라는 뜻이라 모순됩니다 ✗","forzosa: '강제의, 의무적인'이라는 뜻이라 모순됩니다 ✗"]},{"id":"V477","q":"En esta parte de la ciudad, muchas personas de diferentes nacionalidades ____ en armonía.","o":["subsisten","reviven","perviven","conviven"],"a":3,"k":"공존 관련 동사","t":"이 지역에서는 다양한 국적의 많은 사람들이 조화롭게 함께 살아간다.","e":"convivir는 con(함께) + vivir(살다)로 '함께 살다, 공존하다'라는 뜻입니다. 'convivir en armonía(조화롭게 공존하다)'는 자주 쓰는 표현입니다. 명사형은 convivencia(공존, 함께 사는 것)입니다.","x":["subsisten: subsistir(근근이 살아가다, 존속하다)라는 뜻이라 조화와 연결되지 않습니다 ✗","reviven: revivir(되살아나다)라는 뜻이라 맞지 않습니다 ✗","perviven: pervivir(오래 살아남다, 존속하다)라는 뜻이라 문맥에 맞지 않습니다 ✗","conviven: convivir(함께 살다, 공존하다)로 정답입니다 ✓"]},{"id":"V478","q":"Estoy harto de recibir en mi correo ____ comercial, no me interesa comprar nada.","o":["divulgación","propaganda","mensajería","notificación"],"a":1,"k":"광고 어휘","t":"메일로 상업 광고를 받는 게 지긋지긋하다. 나는 아무것도 살 생각이 없다.","e":"propaganda는 '광고, 선전'을 뜻하고 'propaganda comercial'은 '상업 광고(스팸 광고)'입니다. 스페인에서는 우편함이나 메일로 오는 광고물을 흔히 propaganda라고 부릅니다. 'estar harto de'는 '~에 질리다, 지긋지긋하다'라는 뜻입니다.","x":["divulgación: '보급, (지식의) 대중화'라는 뜻으로 광고를 뜻하지 않습니다 ✗","propaganda: '광고, 선전'으로 'propaganda comercial'이 정답입니다 ✓","mensajería: '메시지 서비스, 택배'라는 뜻이라 맞지 않습니다 ✗","notificación: '알림, 통지'라는 뜻으로 물건 구매와 연결되지 않습니다 ✗"]},{"id":"V479","q":"Tenemos que escribir una ____ de trescientas palabras para la clase de francés.","o":["revelación","puntuación","variación","redacción"],"a":3,"k":"글쓰기 어휘","t":"우리는 프랑스어 수업을 위해 300단어짜리 작문을 써야 한다.","e":"redacción는 '작문, 글쓰기'라는 뜻입니다. 학교 과제로 '몇 단어짜리 글'을 쓸 때 'escribir una redacción'이라고 합니다. 동사는 redactar(작성하다)입니다.","x":["revelación: '폭로, 계시'라는 뜻이라 과제 글이 아닙니다 ✗","puntuación: '구두점, 점수'라는 뜻이라 맞지 않습니다 ✗","variación: '변화, 변형'이라는 뜻이라 맞지 않습니다 ✗","redacción: '작문'으로 정답입니다 ✓"]},{"id":"V480","q":"Preparo muchos zumos, de ahí que use tanto el ____.","o":["exprimidor","horno","hervidor","refrigerador"],"a":0,"k":"주방 기구 어휘","t":"나는 주스를 많이 만들어서 착즙기를 자주 쓴다.","e":"exprimidor는 exprimir(짜다)에서 나온 말로 '(과즙) 착즙기, 스퀴저'입니다. zumo는 스페인에서 '과일 주스'를 뜻하며 중남미에서는 jugo를 씁니다. 'de ahí que'는 '그래서 ~하다'라는 뜻으로 뒤에 접속법(use)이 옵니다.","x":["exprimidor: '착즙기'로 주스 만들기에 딱 맞습니다 ✓","horno: '오븐'이라 주스와 관련이 없습니다 ✗","hervidor: '전기 주전자'라 물을 끓이는 데 씁니다 ✗","refrigerador: '냉장고'로 보관에는 쓰지만 주스를 만드는 도구는 아닙니다 ✗"]},{"id":"V481","q":"La ceremonia de ____ de premios fue demasiado larga en mi opinión.","o":["envío","cesión","entrega","retribución"],"a":2,"k":"시상식 어휘","t":"내 생각에 시상식이 너무 길었다.","e":"'entrega de premios'는 '시상(상을 건네주는 것)'이고 'ceremonia de entrega de premios'는 '시상식'입니다. entrega는 entregar(건네주다, 전달하다)의 명사형입니다. 예: entrega a domicilio(택배, 배달).","x":["envío: '발송, 배송'이라는 뜻으로 시상식에는 쓰지 않습니다 ✗","cesión: '양도, 이전'이라는 법률적 뜻이라 맞지 않습니다 ✗","entrega: '수여, 전달'로 'entrega de premios(시상)'가 정답입니다 ✓","retribución: '보수, 보상'이라는 뜻이라 시상과 무관합니다 ✗"]},{"id":"V482","q":"Las ____ canutas para acabar mis estudios, pero al final lo conseguí.","o":["hice","di","pasé","tuve"],"a":2,"k":"관용 표현","t":"공부를 마치느라 아주 고생했지만 결국 해냈다.","e":"'pasarlas canutas'는 '몹시 고생하다, 죽을 고생을 하다'라는 스페인의 구어 관용 표현입니다. 여기서 las는 특정 명사를 가리키지 않는 고정된 대명사입니다. 예: Lo pasé fatal.(정말 힘들었다.)도 비슷한 뜻입니다.","x":["hice: hacer는 이 관용 표현에 쓰지 않습니다 ✗","di: dar는 이 관용 표현에 쓰지 않습니다 ✗","pasé: 'pasarlas canutas(몹시 고생하다)'로 정답입니다 ✓","tuve: tener는 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"V483","q":"Elvira tiene un ____ académico realmente bueno.","o":["expediente","resumen","sumario","documento"],"a":0,"k":"학업 어휘","t":"엘비라는 학업 성적(성적 기록)이 정말 좋다.","e":"'expediente académico'는 학생의 성적과 이수 기록을 모은 '학업 성적표, 성적 기록'입니다. expediente는 '서류철, 기록 파일'이라는 뜻이며 'expediente médico(의료 기록)'처럼도 씁니다.","x":["expediente: 'expediente académico(학업 성적 기록)'로 정답입니다 ✓","resumen: '요약'이라는 뜻이라 성적 기록을 뜻하지 않습니다 ✗","sumario: '요약, (법률) 예심 기록'이라 학업과 무관합니다 ✗","documento: '서류, 문서'라는 일반적인 말로 'documento académico'는 성적을 뜻하는 고정 표현이 아닙니다 ✗"]},{"id":"V484","q":"Antes de publicar la noticia, deben ____.","o":["relacionarla","asimilarla","contrastarla","enlazarla"],"a":2,"k":"언론 관련 동사","t":"뉴스를 내보내기 전에 그것을 사실 확인(대조 검증)해야 한다.","e":"contrastar는 '대조하다, 비교 검증하다'라는 뜻으로, 언론에서 'contrastar una noticia'는 여러 출처와 비교해 사실인지 확인하는 것을 말합니다. contrastarla의 la는 직접목적격 대명사(~을/를에 해당)로 la noticia를 가리킵니다.","x":["relacionarla: '연관시키다'라는 뜻이라 발표 전 확인 작업과 맞지 않습니다 ✗","asimilarla: '이해하다, 흡수하다'라는 뜻이라 맞지 않습니다 ✗","contrastarla: '사실 대조·검증하다'로 정답입니다 ✓","enlazarla: '연결하다, 링크를 걸다'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V485","q":"El niño no me hace caso, hace lo que le ____ la gana.","o":["pone","da","lleva","trae"],"a":1,"k":"관용 표현","t":"그 아이는 내 말을 듣지 않고 자기 하고 싶은 대로 한다.","e":"'dar la gana'는 '~하고 싶은 마음이 들다'라는 구어 표현으로, 'hacer lo que le da la gana'는 '제멋대로 하다'라는 뜻입니다. gustar처럼 간접목적격 대명사(le)를 씁니다. 'no hacer caso'는 '말을 듣지 않다, 무시하다'입니다.","x":["pone: poner는 이 관용 표현에 쓰지 않습니다 ✗","da: 'dar la gana(하고 싶어지다)'로 정답입니다 ✓","lleva: llevar는 이 표현과 결합하지 않습니다 ✗","trae: traer는 이 표현과 결합하지 않습니다 ✗"]},{"id":"V486","q":"____ eran las viviendas originales de los indios de América del Norte.","o":["Los tipis","Las cabañas","Los iglús","Las chozas"],"a":0,"k":"주거 형태 어휘","t":"티피는 북아메리카 원주민의 원래 주거 형태였다.","e":"tipi는 북아메리카 평원 원주민이 쓰던 원뿔형 천막집 '티피'입니다. 'indios de América del Norte(북미 원주민)'와 가장 밀접하게 연관된 전통 가옥입니다.","x":["Los tipis: '티피'로 북미 원주민의 전통 주거입니다 ✓","Las cabañas: '오두막'이라는 일반적인 말로 특정 민족의 주거를 가리키지 않습니다 ✗","Los iglús: '이글루'로 북극 지방 이누이트의 얼음집이라 맞지 않습니다 ✗","Las chozas: '초가, 움막'이라는 일반적인 말이라 북미 원주민을 특정하지 않습니다 ✗"]},{"id":"V487","q":"Mi padre no es ni muy alto ni muy bajo, es de estatura ____.","o":["considerable","media","grande","pequeña"],"a":1,"k":"외모 묘사 어휘","t":"우리 아버지는 아주 크지도 아주 작지도 않고 중간 키이다.","e":"'de estatura media'는 '중간 키의, 보통 키의'라는 표현입니다. estatura는 '키, 신장'입니다. 'ni muy alto ni muy bajo(너무 크지도 작지도 않은)'를 한마디로 정리하는 말입니다.","x":["considerable: '상당한'이라는 뜻이라 큰 키를 암시해 앞 문장과 맞지 않습니다 ✗","media: '중간의'로 'de estatura media'가 정답입니다 ✓","grande: '큰'이라는 뜻이라 앞 문장과 모순됩니다 ✗","pequeña: '작은'이라는 뜻이라 앞 문장과 모순됩니다 ✗"]},{"id":"V488","q":"Sirio es una de las estrellas que más ____, por eso se ve desde muchos puntos de la Tierra.","o":["se borra","se difumina","brilla","nubla"],"a":2,"k":"천체 관련 동사","t":"시리우스는 가장 밝게 빛나는 별 중 하나라서 지구의 여러 곳에서 보인다.","e":"brillar는 '빛나다'라는 뜻입니다. 별이 지구 곳곳에서 보이는 이유는 밝게 빛나기 때문이므로 brilla가 맞습니다. 'una de las estrellas que más brilla(n)'는 '가장 많이 빛나는 별 중 하나'라는 구조입니다.","x":["se borra: '지워지다, 사라지다'라는 뜻이라 잘 보이는 것과 반대입니다 ✗","se difumina: '흐려지다, 희미해지다'라는 뜻이라 반대 의미입니다 ✗","brilla: '빛나다'로 잘 보이는 이유가 됩니다 ✓","nubla: nublar(흐리게 하다)라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V489","q":"Este medicamento solo se dispensa con ____ médica.","o":["agenda","libreta","carta","receta"],"a":3,"k":"의료 어휘","t":"이 약은 의사 처방전이 있어야만 판매된다.","e":"'receta médica'는 '의사 처방전'입니다. receta는 '요리법(레시피)'이라는 뜻도 있으니 함께 기억하세요. dispensar는 약국에서 '약을 내주다, 조제하다'라는 뜻입니다.","x":["agenda: '일정표, 수첩'이라는 뜻이라 맞지 않습니다 ✗","libreta: '공책, 수첩'이라는 뜻이라 맞지 않습니다 ✗","carta: '편지, 메뉴판'이라는 뜻이라 약 처방과 무관합니다 ✗","receta: 'receta médica(처방전)'로 정답입니다 ✓"]},{"id":"V490","q":"Es ____ hablar francés para trabajar aquí. Sin este requisito no será aceptada su solicitud.","o":["opcional","conveniente","útil","imprescindible"],"a":3,"k":"필수 조건 형용사","t":"여기서 일하려면 프랑스어를 할 줄 아는 것이 필수다. 이 조건이 없으면 지원서가 받아들여지지 않는다.","e":"imprescindible는 '반드시 필요한, 필수적인'이라는 뜻입니다. 뒤에 'Sin este requisito no será aceptada(이 조건 없이는 받아들여지지 않는다)'라고 하므로 가장 강한 필요성을 나타내는 단어가 맞습니다.","x":["opcional: '선택적인'이라는 뜻이라 필수 조건과 모순됩니다 ✗","conveniente: '바람직한, 편리한'이라는 뜻으로 필수라는 의미가 약합니다 ✗","útil: '유용한'이라는 뜻이라 필수 요건을 나타내기에 약합니다 ✗","imprescindible: '필수적인'으로 정답입니다 ✓"]},{"id":"V491","q":"Fran ____ un catarro, por eso no está viniendo a trabajar esta semana.","o":["ha tomado","ha sujetado","ha atrapado","ha pillado"],"a":3,"k":"질병 관련 동사","t":"프란은 감기에 걸려서 이번 주에 일하러 오지 않고 있다.","e":"'pillar un catarro/resfriado'는 '감기에 걸리다'라는 스페인의 구어 표현입니다. pillar는 원래 '붙잡다'라는 뜻입니다. 더 일반적으로는 'coger un catarro'(스페인)나 'agarrar/pescar un resfriado'(중남미)라고도 합니다.","x":["ha tomado: tomar는 '먹다, 잡다'이지만 감기와 함께 쓰지 않습니다 ✗","ha sujetado: sujetar는 '붙잡아 고정하다'라는 뜻이라 질병에 쓰지 않습니다 ✗","ha atrapado: atrapar는 '(도망가는 것을) 붙잡다'라서 감기와는 잘 쓰지 않습니다 ✗","ha pillado: 'pillar un catarro(감기에 걸리다)'로 정답입니다 ✓"]},{"id":"V492","q":"La libertad de expresión es contraria a cualquier tipo de ____.","o":["postura","aventura","censura","cordura"],"a":2,"k":"사회·정치 어휘","t":"표현의 자유는 어떤 종류의 검열과도 상반된다.","e":"censura는 '검열'이라는 뜻으로, 말하거나 출판할 자유를 제한하는 것입니다. 표현의 자유(libertad de expresión)와 정반대 개념이므로 정답입니다. 동사는 censurar(검열하다, 비난하다)입니다.","x":["postura: '입장, 자세'라는 뜻이라 표현의 자유와 반대 개념이 아닙니다 ✗","aventura: '모험'이라는 뜻이라 문맥과 무관합니다 ✗","censura: '검열'로 표현의 자유와 정반대입니다 ✓","cordura: '분별력, 제정신'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V493","q":"Me levanté tarde porque no escuché ____ del despertador.","o":["el aviso","la señal","la alarma","la advertencia"],"a":2,"k":"일상 사물 어휘","t":"자명종 알람을 못 들어서 늦게 일어났다.","e":"alarma는 '알람, 경보'라는 뜻으로 'la alarma del despertador'는 '자명종 알람'입니다. despertador는 '자명종 시계'입니다. 예: Pon la alarma a las siete.(알람을 7시에 맞춰.)","x":["el aviso: '알림, 통지'라는 일반적인 말이라 자명종 소리를 가리키지 않습니다 ✗","la señal: '신호, 표시'라는 뜻이라 자명종 소리로는 어색합니다 ✗","la alarma: '알람'으로 자명종 소리를 뜻하는 정답입니다 ✓","la advertencia: '경고, 주의'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V494","q":"Niños, ____ atención, por favor.","o":["haced","aportad","dad","prestad"],"a":3,"k":"동사+명사 연어","t":"얘들아, 주목해 주세요.","e":"'prestar atención'은 '주의를 기울이다, 주목하다'라는 고정 표현입니다. 여기서는 vosotros(너희) 명령형 prestad가 쓰였습니다. 중남미에서는 vosotros 대신 ustedes를 써서 'presten atención'이라고 합니다.","x":["haced: hacer의 vosotros 명령형이지만 'hacer atención'은 쓰지 않습니다 ✗","aportad: aportar(기여하다)의 명령형이라 atención과 맞지 않습니다 ✗","dad: dar의 명령형이지만 'dar atención'은 '관심을 주다'로 '주목하라'는 표현이 아닙니다 ✗","prestad: 'prestar atención(주목하다)'의 vosotros 명령형으로 정답입니다 ✓"]},{"id":"V495","q":"Mis actuales ____ siempre pagan el alquiler el primer día de cada mes.","o":["usuarios","consumidores","clientes","inquilinos"],"a":3,"k":"주거 계약 어휘","t":"지금 세입자들은 항상 매달 1일에 월세를 낸다.","e":"inquilino/a는 집을 빌려 사는 '세입자'입니다. alquiler(월세, 임대료)를 내는 사람이므로 정답입니다. 반대로 집주인은 casero/a 또는 propietario/a라고 합니다.","x":["usuarios: '사용자, 이용자'라는 뜻이라 월세를 내는 사람을 가리키지 않습니다 ✗","consumidores: '소비자'라는 뜻이라 맞지 않습니다 ✗","clientes: '고객'이라는 뜻이라 임대 관계에는 어색합니다 ✗","inquilinos: '세입자'로 월세를 내는 사람입니다 ✓"]},{"id":"V496","q":"No lavarse las manos antes de comer es ____.","o":["antisocial","antidemocrático","antinatural","antihigiénico"],"a":3,"k":"anti- 접두사 형용사","t":"밥 먹기 전에 손을 씻지 않는 것은 비위생적이다.","e":"antihigiénico는 anti-(반대) + higiénico(위생적인)로 '비위생적인'이라는 뜻입니다. 손을 씻지 않는 것은 위생(higiene)과 관련된 문제이므로 정답입니다.","x":["antisocial: '반사회적인'이라는 뜻이라 손 씻기와 무관합니다 ✗","antidemocrático: '반민주적인'이라는 뜻이라 맞지 않습니다 ✗","antinatural: '부자연스러운'이라는 뜻이라 위생 문제와 맞지 않습니다 ✗","antihigiénico: '비위생적인'으로 정답입니다 ✓"]},{"id":"V497","q":"La anciana que llevaba días desaparecida apareció ____ y sin saber su nombre.","o":["desenfocada","desorientada","desterrada","desviada"],"a":1,"k":"des- 접두사 형용사","t":"며칠째 실종되었던 할머니가 방향 감각을 잃은 채 자기 이름도 모르는 상태로 발견되었다.","e":"desorientado/a는 '방향 감각을 잃은, 혼란스러운'이라는 뜻입니다. 자기 이름도 모르는 상태와 잘 어울립니다. orientarse(길을 찾다, 방향을 잡다)의 반대 개념입니다.","x":["desenfocada: '초점이 맞지 않은'이라는 뜻으로 사진 등에 씁니다 ✗","desorientada: '방향 감각을 잃은, 혼란스러운'으로 정답입니다 ✓","desterrada: '추방된, 유배된'이라는 뜻이라 맞지 않습니다 ✗","desviada: '(길에서) 벗어난, 우회된'이라는 뜻으로 사람의 정신 상태를 나타내지 않습니다 ✗"]},{"id":"V498","q":"Nuestro padre dio un ____ en la mesa y todos nos quedamos de piedra.","o":["puñado","puñetazo","puñal","puño"],"a":1,"k":"puño 파생어","t":"우리 아버지가 식탁을 주먹으로 쾅 치자 우리 모두 얼어붙었다.","e":"puñetazo는 puño(주먹) + -azo(타격)로 '주먹으로 치기'라는 뜻이고, 'dar un puñetazo'는 '주먹으로 치다'입니다. 'quedarse de piedra'는 '돌처럼 굳다, 깜짝 놀라 얼어붙다'라는 관용 표현입니다.","x":["puñado: '한 줌'이라는 뜻이라 dar와 맞지 않습니다 ✗","puñetazo: '주먹질'로 'dar un puñetazo(주먹으로 치다)'가 정답입니다 ✓","puñal: '단도'라는 뜻이라 맞지 않습니다 ✗","puño: '주먹' 자체를 뜻하며 '때리다'라는 동작은 puñetazo로 표현합니다 ✗"]},{"id":"V499","q":"Los recién casados ____ un romántico paseo por la playa.","o":["hicieron","echaron","tomaron","dieron"],"a":3,"k":"동사+명사 연어","t":"신혼부부는 해변에서 낭만적인 산책을 했다.","e":"'dar un paseo'는 '산책하다'라는 가장 일반적인 표현입니다. 'dar una vuelta(한 바퀴 돌다)'도 비슷한 뜻입니다. 참고로 스페인 구어에서는 'echar un paseo'도 쓰지만 표준적으로는 dar가 가장 자연스럽습니다.","x":["hicieron: 'hacer un paseo'는 자연스러운 표현이 아닙니다 ✗","echaron: 'echar un paseo'는 스페인 구어에서 쓰기도 하지만 교재 정답은 dar입니다 ✗","tomaron: 'tomar un paseo'는 영어식 표현으로 쓰지 않습니다 ✗","dieron: 'dar un paseo(산책하다)'로 정답입니다 ✓"]},{"id":"V500","q":"Es una cafetería ____ porque tienen buen servicio y precios asequibles.","o":["cara","lujosa","desconocida","concurrida"],"a":3,"k":"장소 묘사 형용사","t":"서비스가 좋고 가격이 저렴해서 손님이 많은 카페다.","e":"concurrido/a는 '사람이 많이 모이는, 붐비는'이라는 뜻입니다. 서비스가 좋고 값이 싸다는 이유가 손님이 많은 결과로 이어집니다. asequible는 '(가격이) 적당한, 감당할 수 있는'이라는 뜻입니다.","x":["cara: '비싼'이라는 뜻이라 'precios asequibles'와 모순됩니다 ✗","lujosa: '호화로운'이라는 뜻으로 저렴한 가격의 결과가 아닙니다 ✗","desconocida: '알려지지 않은'이라는 뜻이라 좋은 서비스의 결과로 맞지 않습니다 ✗","concurrida: '손님이 많은, 붐비는'으로 정답입니다 ✓"]},{"id":"V501","q":"La lavadora es uno de los ____ más útiles que hay.","o":["muebles","instrumentos","electrodomésticos","utensilios"],"a":2,"k":"가전제품 어휘","t":"세탁기는 가장 유용한 가전제품 중 하나다.","e":"electrodoméstico는 '가전제품'입니다. 세탁기(lavadora), 냉장고(frigorífico/nevera), 전자레인지(microondas) 등이 여기에 속합니다. electro(전기) + doméstico(가정의)로 기억하면 쉽습니다.","x":["muebles: '가구'라는 뜻으로 세탁기는 가구가 아닙니다 ✗","instrumentos: '도구, 악기'라는 뜻이라 세탁기를 가리키기에 부적절합니다 ✗","electrodomésticos: '가전제품'으로 정답입니다 ✓","utensilios: '(손으로 쓰는) 도구, 기구'라는 뜻이라 세탁기에는 맞지 않습니다 ✗"]},{"id":"V502","q":"Cuando esté listo el arroz con leche, lo voy a espolvorear con ____.","o":["perejil","azafrán","pimentón","canela"],"a":3,"k":"향신료 어휘","t":"라이스 푸딩이 다 되면 그 위에 계핏가루를 뿌릴 거야.","e":"canela는 '계피, 시나몬'입니다. 'arroz con leche(우유로 끓인 달콤한 쌀 디저트)'는 스페인·중남미의 전통 디저트로 보통 위에 계핏가루를 뿌립니다. espolvorear는 '가루를 뿌리다'라는 뜻입니다.","x":["perejil: '파슬리'로 짭짤한 요리에 쓰는 허브라 디저트와 맞지 않습니다 ✗","azafrán: '사프란'으로 파에야 같은 요리에 쓰여 이 디저트에는 맞지 않습니다 ✗","pimentón: '파프리카 가루'로 짭짤한 요리용이라 맞지 않습니다 ✗","canela: '계피'로 arroz con leche에 뿌리는 정답입니다 ✓"]},{"id":"V503","q":"No nos une ningún ____, solo somos buenos amigos.","o":["pariente","parentesco","descendiente","sucesor"],"a":1,"k":"친족 관계 어휘","t":"우리는 아무런 친척 관계가 아니고, 그냥 좋은 친구일 뿐이다.","e":"parentesco는 '친척 관계, 혈연관계'라는 추상 명사입니다. 'No nos une ningún parentesco'는 '우리를 이어 주는 친척 관계는 없다'는 뜻입니다. pariente는 '친척(사람)'이라 관계 자체를 말할 때는 parentesco를 씁니다.","x":["pariente: '친척(사람)'이라 '우리를 잇는 것'이라는 관계를 나타내지 못합니다 ✗","parentesco: '친척 관계'로 정답입니다 ✓","descendiente: '후손'이라는 뜻이라 맞지 않습니다 ✗","sucesor: '후계자'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V504","q":"Mis alumnos ____ varios poemas de Antonio Machado en la fiesta del colegio.","o":["recitaron","emularon","imitaron","plagiaron"],"a":0,"k":"문학 관련 동사","t":"내 학생들은 학교 축제에서 안토니오 마차도의 시 몇 편을 낭송했다.","e":"recitar는 '(시 등을) 낭송하다, 암송하다'라는 뜻입니다. poema(시)와 가장 잘 어울리는 동사입니다. 안토니오 마차도는 스페인의 유명한 시인(98세대)입니다.","x":["recitaron: '낭송했다'로 시와 함께 쓰는 정답입니다 ✓","emularon: '모방하여 경쟁했다'라는 뜻이라 축제 발표와 맞지 않습니다 ✗","imitaron: '흉내 냈다'라는 뜻이라 시와 어울리지 않습니다 ✗","plagiaron: '표절했다'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V505","q":"En aquella guerra murieron cientos de miles de personas, fue ____.","o":["una matanza","un homicidio","un asesinato","una muerte"],"a":0,"k":"죽음 관련 어휘","t":"그 전쟁에서 수십만 명이 죽었다. 그것은 대학살이었다.","e":"matanza는 '대량 살육, 학살'이라는 뜻으로 많은 사람이 죽은 상황에 씁니다. matar(죽이다)에서 나온 말입니다. homicidio와 asesinato는 보통 개인 한 명을 죽이는 범죄를 가리킵니다.","x":["una matanza: '학살'로 수십만 명의 죽음에 맞습니다 ✓","un homicidio: '살인(죄)'로 보통 개별 사건에 씁니다 ✗","un asesinato: '(계획적) 살인'으로 개별 범죄를 가리킵니다 ✗","una muerte: '죽음' 하나를 뜻해 수십만 명의 죽음을 표현하지 못합니다 ✗"]},{"id":"V506","q":"Debe ____ antes de que le hagan el análisis de sangre, es decir, no coma nada.","o":["almorzar","ayunar","merendar","desayunar"],"a":1,"k":"식사 관련 동사","t":"혈액 검사를 받기 전에 금식해야 합니다, 즉 아무것도 드시지 마세요.","e":"ayunar는 '금식하다, 굶다'라는 뜻입니다. 'es decir, no coma nada(즉, 아무것도 먹지 마세요)'라는 설명이 바로 뜻을 알려 줍니다. 명사는 ayuno(금식)이고, 'en ayunas'는 '공복 상태로'라는 표현입니다.","x":["almorzar: '점심(또는 오전 간식)을 먹다'라서 금식과 반대입니다 ✗","ayunar: '금식하다'로 정답입니다 ✓","merendar: '오후 간식을 먹다'라서 맞지 않습니다 ✗","desayunar: '아침을 먹다'라서 금식과 반대입니다 ✗"]},{"id":"V507","q":"No olvide ____ de baja su línea telefónica antes de marcharse de la vivienda.","o":["hacer","meter","dar","poner"],"a":2,"k":"행정 관용 표현","t":"집에서 나가기 전에 전화선을 해지하는 것을 잊지 마세요.","e":"'dar de baja'는 '(서비스·회원 등록을) 해지하다, 탈퇴시키다'라는 뜻입니다. 반대로 'dar de alta'는 '가입·등록하다'입니다. 예: Me di de baja del gimnasio.(헬스장을 탈퇴했다.)","x":["hacer: 'hacer de baja'라는 표현은 없습니다 ✗","meter: 'meter de baja'라는 표현은 없습니다 ✗","dar: 'dar de baja(해지하다)'로 정답입니다 ✓","poner: 'poner de baja'는 표준 표현이 아닙니다 ✗"]},{"id":"V508","q":"____ a Jimena y ahora cobra un sueldo mejor.","o":["Han ascendido","Han subido","Han elevado","Han promovido"],"a":0,"k":"직장 생활 동사","t":"히메나가 승진해서 이제 더 좋은 월급을 받는다.","e":"ascender는 '승진시키다, 오르다'라는 뜻으로 'ascender a alguien'은 '누구를 승진시키다'입니다. 명사형 ascenso는 '승진'입니다. 사람을 목적어로 할 때 'a Jimena'처럼 전치사 a를 붙입니다.","x":["Han ascendido: '승진시켰다'로 정답입니다 ✓","Han subido: subir는 '올리다'이지만 사람을 승진시킨다는 뜻으로는 잘 쓰지 않습니다 ✗","Han elevado: elevar는 '높이다, 들어 올리다'라서 승진에 쓰지 않습니다 ✗","Han promovido: promover는 '추진하다, 장려하다'가 주된 뜻으로 '승진시키다'는 영어식 표현에 가깝습니다 ✗"]},{"id":"V509","q":"Mi celular no tiene batería. ¿Me dejas tu ____?","o":["auricular","monitor","altavoz","cargador"],"a":3,"k":"전자기기 어휘","t":"내 휴대폰 배터리가 없어. 네 충전기 좀 빌려줄래?","e":"cargador는 cargar(충전하다)에서 나온 말로 '충전기'입니다. 배터리가 없다는 문제를 해결하는 물건입니다. celular는 중남미에서 '휴대폰'을 뜻하며 스페인에서는 móvil이라고 합니다.","x":["auricular: '이어폰, 수화기'라서 배터리 문제를 해결하지 못합니다 ✗","monitor: '모니터'라서 맞지 않습니다 ✗","altavoz: '스피커'라서 맞지 않습니다 ✗","cargador: '충전기'로 정답입니다 ✓"]},{"id":"V510","q":"Los actores van a ____ una vez más antes de salir al escenario.","o":["proyectar","entrenar","probar","ensayar"],"a":3,"k":"공연 관련 동사","t":"배우들은 무대에 오르기 전에 한 번 더 리허설을 할 것이다.","e":"ensayar는 '(공연을) 연습하다, 리허설하다'라는 뜻입니다. 명사형 ensayo는 '리허설'이자 '수필, 실험'이라는 뜻도 있습니다. 공연 전 연습에는 entrenar가 아니라 ensayar를 씁니다.","x":["proyectar: '상영하다, 계획하다'라는 뜻이라 배우의 연습과 맞지 않습니다 ✗","entrenar: '훈련하다'로 주로 운동에 씁니다 ✗","probar: '시험해 보다, 맛보다'라서 공연 연습을 뜻하지 않습니다 ✗","ensayar: '리허설하다'로 정답입니다 ✓"]},{"id":"V511","q":"Deberías pensar por ti mismo y no dejar que te ____ la opinión de los demás.","o":["influya","favorezca","apoye","respalde"],"a":0,"k":"영향 관련 동사","t":"너는 스스로 생각해야 하고, 다른 사람들의 의견이 너에게 영향을 미치게 두면 안 된다.","e":"influir는 '영향을 미치다'라는 뜻이고, 여기서는 'dejar que + 접속법' 구조라서 접속법 influya가 쓰였습니다. 'pensar por ti mismo(스스로 생각하다)'와 대비되는 것은 남의 의견에 영향받는 것입니다.","x":["influya: influir(영향을 미치다)의 접속법으로 정답입니다 ✓","favorezca: favorecer(유리하게 하다, 어울리다)라는 뜻이라 맞지 않습니다 ✗","apoye: apoyar(지지하다)라는 뜻이라 문맥과 맞지 않습니다 ✗","respalde: respaldar(뒷받침하다)라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V512","q":"Me llena de ____ saber que mis hijos son personas decentes.","o":["pena","amargura","aflicción","orgullo"],"a":3,"k":"감정 어휘","t":"내 아이들이 올바른 사람이라는 것을 알면 자부심으로 가득 찬다.","e":"orgullo는 '자부심, 자랑스러움'이라는 뜻입니다. 'llenar de orgullo'는 '자부심으로 가득 채우다'라는 표현입니다. 아이들이 decente(바른, 품위 있는) 사람이라는 긍정적 사실에 대한 감정이므로 정답입니다.","x":["pena: '슬픔, 유감'이라는 뜻이라 긍정적인 사실과 맞지 않습니다 ✗","amargura: '쓰라림, 비통함'이라는 뜻이라 맞지 않습니다 ✗","aflicción: '고통, 비탄'이라는 뜻이라 맞지 않습니다 ✗","orgullo: '자부심'으로 정답입니다 ✓"]},{"id":"V513","q":"Es muy lista, por eso respondió a todas las preguntas con ____.","o":["simpleza","bajeza","agudeza","torpeza"],"a":2,"k":"-eza 명사 어휘","t":"그녀는 아주 똑똑해서 모든 질문에 예리하게 대답했다.","e":"agudeza는 agudo(날카로운, 예리한)에서 나온 명사로 '예리함, 재치'라는 뜻입니다. 'con agudeza'는 '재치 있게, 예리하게'입니다. 똑똑하다(lista)는 앞 문장과 의미가 이어집니다.","x":["simpleza: '단순함, 어리석음'이라는 뜻이라 똑똑함과 반대입니다 ✗","bajeza: '비열함'이라는 뜻이라 맞지 않습니다 ✗","agudeza: '예리함, 재치'로 정답입니다 ✓","torpeza: '서투름, 둔함'이라는 뜻이라 반대 의미입니다 ✗"]},{"id":"V514","q":"El argumento del filme es tan ____ que no me enteré de nada.","o":["enrevesado","simple","sencillo","trillado"],"a":0,"k":"줄거리 묘사 형용사","t":"영화 줄거리가 너무 복잡해서 하나도 이해하지 못했다.","e":"enrevesado/a는 '복잡하게 얽힌, 난해한'이라는 뜻입니다. 'no me enteré de nada(아무것도 이해 못 했다)'의 이유가 됩니다. 'tan + 형용사 + que'는 '너무 ~해서 …하다'라는 구조입니다.","x":["enrevesado: '복잡하게 얽힌'으로 이해하지 못한 이유가 됩니다 ✓","simple: '단순한'이라는 뜻이라 이해 못 한 이유가 되지 않습니다 ✗","sencillo: '간단한'이라는 뜻이라 반대 의미입니다 ✗","trillado: '진부한, 흔해 빠진'이라는 뜻으로 이해하기 어려운 이유는 아닙니다 ✗"]},{"id":"V515","q":"Voy a cambiar las ____ de la cama.","o":["sábanas","telas","camisas","toallas"],"a":0,"k":"침구 어휘","t":"침대 시트를 갈려고 한다.","e":"sábana는 '(침대) 시트'입니다. 'cambiar las sábanas'는 '침대 시트를 갈다'라는 일상 표현입니다. 함께 알아 두면 좋은 단어: almohada(베개), manta(담요), edredón(이불).","x":["sábanas: '침대 시트'로 정답입니다 ✓","telas: '천, 옷감'이라는 일반적인 말이라 침대와 함께 쓰지 않습니다 ✗","camisas: '셔츠'라서 침대와 무관합니다 ✗","toallas: '수건'이라서 침대에 쓰지 않습니다 ✗"]},{"id":"V516","q":"Esta tierra es muy ____, por eso da tantos frutos.","o":["seca","árida","estéril","fértil"],"a":3,"k":"토양 형용사","t":"이 땅은 매우 비옥해서 열매가 아주 많이 열린다.","e":"fértil은 '비옥한, 기름진'이라는 뜻입니다. 열매가 많이 열리는(da tantos frutos) 이유가 되므로 정답입니다. 반대말은 estéril(불모의)입니다.","x":["seca: '건조한'이라는 뜻이라 열매가 많은 이유가 되지 않습니다 ✗","árida: '메마른, 건조한'이라는 뜻이라 반대 의미입니다 ✗","estéril: '불모의'라는 뜻이라 반대 의미입니다 ✗","fértil: '비옥한'으로 정답입니다 ✓"]},{"id":"V517","q":"No te tomes en serio lo que te diga Javier, es un ____.","o":["juerguista","envidioso","bromista","caradura"],"a":2,"k":"성격 명사","t":"하비에르가 하는 말은 진지하게 받아들이지 마, 그는 장난꾸러기야.","e":"bromista는 broma(농담, 장난)에서 나온 말로 '농담을 잘하는 사람, 장난꾸러기'입니다. 그의 말을 진지하게 받아들이지 말라는 이유가 됩니다. 'tomarse algo en serio'는 '~을 진지하게 받아들이다'라는 표현입니다.","x":["juerguista: '노는 것을 좋아하는 사람, 파티광'이라는 뜻으로 말을 믿지 말라는 이유로는 약합니다 ✗","envidioso: '질투심 많은 사람'이라는 뜻이라 맞지 않습니다 ✗","bromista: '농담을 잘하는 사람'으로 정답입니다 ✓","caradura: '뻔뻔한 사람'이라는 뜻으로 진지하게 받아들이지 말라는 이유와 거리가 있습니다 ✗"]},{"id":"V518","q":"¡Qué cama tan ____! Aquí no se puede dormir.","o":["incómoda","práctica","funcional","confortable"],"a":0,"k":"편안함 형용사","t":"침대가 정말 불편하다! 여기서는 잘 수가 없다.","e":"incómodo/a는 '불편한'이라는 뜻입니다. 'Aquí no se puede dormir(여기선 잘 수 없다)'라는 뒷문장의 이유가 됩니다. '¡Qué + 명사 + tan + 형용사!'는 '정말 ~한 ~구나!'라는 감탄 구조입니다.","x":["incómoda: '불편한'으로 잠을 잘 수 없는 이유가 됩니다 ✓","práctica: '실용적인'이라는 뜻이라 잘 수 없는 이유가 되지 않습니다 ✗","funcional: '기능적인'이라는 뜻이라 맞지 않습니다 ✗","confortable: '편안한'이라는 뜻이라 반대 의미입니다 ✗"]},{"id":"V519","q":"El enfermero me puso una ____ para que el medicamento actuase más rápido.","o":["venda","gasa","escayola","inyección"],"a":3,"k":"의료 어휘","t":"간호사가 약이 더 빨리 듣도록 나에게 주사를 놓았다.","e":"inyección는 '주사'이고 'poner una inyección'은 '주사를 놓다'입니다. 약이 더 빨리 효과를 내도록(para que actuase más rápido) 하는 방법으로 가장 자연스럽습니다. actuase는 접속법 과거입니다.","x":["venda: '붕대'로 약을 빨리 작용하게 하지 않습니다 ✗","gasa: '거즈'로 상처를 덮는 데 씁니다 ✗","escayola: '깁스(석고)'로 골절에 씁니다 ✗","inyección: '주사'로 정답입니다 ✓"]},{"id":"V520","q":"Me tiño el pelo porque no me gusta verme las ____.","o":["canas","arrugas","mejillas","cejas"],"a":0,"k":"외모 어휘","t":"나는 흰머리가 보이는 게 싫어서 머리를 염색한다.","e":"cana는 '흰머리, 새치'입니다. 머리를 염색하는(teñirse el pelo) 이유로 가장 적절합니다. 참고로 'echar una cana al aire'는 '가끔 일탈해 즐기다'라는 관용 표현입니다.","x":["canas: '흰머리'로 정답입니다 ✓","arrugas: '주름'이라 염색으로 가릴 수 없습니다 ✗","mejillas: '뺨'이라 머리 염색과 관련이 없습니다 ✗","cejas: '눈썹'이라 머리 염색의 이유가 되지 않습니다 ✗"]},{"id":"V521","q":"Voy a usar agua oxigenada para ____ la herida.","o":["secar","desinfectar","humedecer","tapar"],"a":1,"k":"응급처치 동사","t":"상처를 소독하려고 과산화수소수를 쓸 것이다.","e":"desinfectar는 '소독하다'라는 뜻입니다. 'agua oxigenada(과산화수소수)'는 상처 소독에 쓰는 약품이므로 정답입니다. 명사형은 desinfección(소독), 소독약은 desinfectante입니다.","x":["secar: '말리다'라는 뜻으로 과산화수소수의 용도가 아닙니다 ✗","desinfectar: '소독하다'로 정답입니다 ✓","humedecer: '적시다'라는 뜻으로 상처 처치 목적이 아닙니다 ✗","tapar: '덮다'라는 뜻으로 보통 붕대나 반창고로 합니다 ✗"]},{"id":"V522","q":"Consumir comida ____ no es bueno para nadie.","o":["recalentada","típica","basura","orgánica"],"a":2,"k":"음식 어휘","t":"정크 푸드를 먹는 것은 누구에게도 좋지 않다.","e":"'comida basura'는 직역하면 '쓰레기 음식'으로 '정크 푸드'를 뜻합니다. 여기서 basura는 형용사처럼 명사 뒤에 붙어 형태가 변하지 않습니다. 비슷한 표현: 'comida rápida(패스트푸드)'.","x":["recalentada: '데운'이라는 뜻으로 반드시 몸에 나쁘다고 할 수 없습니다 ✗","típica: '전통적인, 대표적인'이라는 뜻이라 맞지 않습니다 ✗","basura: 'comida basura(정크 푸드)'로 정답입니다 ✓","orgánica: '유기농'이라는 뜻으로 오히려 건강에 좋습니다 ✗"]},{"id":"V523","q":"No salgas todavía, está lloviendo ____.","o":["a lo grande","a cántaros","a patadas","a lo loco"],"a":1,"k":"날씨 관용 표현","t":"아직 나가지 마, 비가 억수같이 쏟아지고 있어.","e":"'llover a cántaros'는 '항아리(cántaro)로 붓듯이 비가 오다', 즉 '비가 억수같이 쏟아지다'라는 관용 표현입니다. 비슷한 표현으로 'llover a mares'도 있습니다.","x":["a lo grande: '성대하게, 화려하게'라는 뜻이라 비와 쓰지 않습니다 ✗","a cántaros: 'llover a cántaros(비가 억수같이 오다)'로 정답입니다 ✓","a patadas: '아주 많이(구어)' 또는 '발길질로'라는 뜻으로 비와는 쓰지 않습니다 ✗","a lo loco: '무턱대고, 아무렇게나'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V524","q":"Si paso el periodo de ____, me contratarán en esta empresa.","o":["desaprobación","prueba","aprobación","comprobación"],"a":1,"k":"채용 관련 어휘","t":"수습 기간을 통과하면 이 회사에 채용될 것이다.","e":"'periodo de prueba'는 '수습 기간, 시용 기간'입니다. prueba는 '시험, 테스트'라는 뜻입니다. 'pasar el periodo de prueba'는 '수습 기간을 통과하다'라는 자연스러운 표현입니다.","x":["desaprobación: '반대, 불승인'이라는 뜻이라 맞지 않습니다 ✗","prueba: 'periodo de prueba(수습 기간)'로 정답입니다 ✓","aprobación: '승인'이라는 뜻으로 'periodo de aprobación'은 쓰지 않습니다 ✗","comprobación: '확인, 검증'이라는 뜻으로 고용 관련 고정 표현이 아닙니다 ✗"]},{"id":"V525","q":"Vamos a parar cinco minutos para descansar y tomar ____.","o":["una comilona","un primer plato","un tentempié","un menú"],"a":2,"k":"식사 어휘","t":"5분 쉬면서 간단히 요기 좀 하자.","e":"tentempié는 '간단한 간식, 요기'라는 뜻입니다. 5분 쉬는 동안 먹을 수 있는 가벼운 음식이므로 정답입니다. 비슷한 말로 aperitivo(식전 간단한 음식)나 picoteo(주전부리)가 있습니다.","x":["una comilona: '진수성찬, 거하게 먹는 식사'라서 5분 휴식에 맞지 않습니다 ✗","un primer plato: '첫 번째 코스 요리'라서 짧은 휴식과 맞지 않습니다 ✗","un tentempié: '간단한 요기'로 정답입니다 ✓","un menú: '(정식) 메뉴, 세트 요리'라서 짧은 휴식에 맞지 않습니다 ✗"]},{"id":"V526","q":"¡Muy bien! ¡____ todas las respuestas!","o":["Han mezclado","Han confundido","Han acertado","Han fallado"],"a":2,"k":"시험 관련 동사","t":"아주 잘했어요! 모든 답을 다 맞혔군요!","e":"acertar는 '(정답을) 맞히다'라는 뜻입니다. '¡Muy bien!'이라는 칭찬과 자연스럽게 이어집니다. 반대말은 fallar(틀리다)입니다. 예: Acerté la respuesta.(정답을 맞혔다.)","x":["Han mezclado: '섞었다'라는 뜻이라 칭찬과 맞지 않습니다 ✗","Han confundido: '혼동했다'라는 뜻이라 칭찬과 모순됩니다 ✗","Han acertado: '맞혔다'로 정답입니다 ✓","Han fallado: '틀렸다'라는 뜻이라 칭찬과 반대입니다 ✗"]},{"id":"V527","q":"No hablemos de ese tema, por favor, no hace falta ____ en la herida.","o":["rascar","profundizar","hurgar","escarbar"],"a":2,"k":"관용 표현","t":"제발 그 얘기는 하지 말자, 상처를 들쑤실 필요는 없잖아.","e":"'hurgar en la herida'는 '상처를 쑤시다', 즉 '아픈 기억을 다시 들추다'라는 관용 표현입니다. hurgar는 '쑤시다, 뒤지다'라는 뜻입니다. 비슷하게 'echar sal en la herida(상처에 소금을 뿌리다)'도 있습니다.","x":["rascar: '긁다'라는 뜻이지만 이 관용 표현에 쓰지 않습니다 ✗","profundizar: '깊이 파고들다'라는 뜻이지만 'profundizar en la herida'는 관용 표현이 아닙니다 ✗","hurgar: 'hurgar en la herida(상처를 들쑤시다)'로 정답입니다 ✓","escarbar: '(흙 등을) 파헤치다'라는 뜻으로 이 관용구에 쓰지 않습니다 ✗"]},{"id":"V528","q":"Ya es tarde para solucionar el problema, por eso estamos ____.","o":["jubilosos","sometidos","aliviados","resignados"],"a":3,"k":"감정 상태 형용사","t":"문제를 해결하기에는 이미 늦어서 우리는 체념한 상태다.","e":"resignado/a는 '체념한, 받아들인'이라는 뜻입니다. 해결하기에 너무 늦었으니 받아들일 수밖에 없는 상황이므로 정답입니다. 동사는 resignarse(체념하다)입니다.","x":["jubilosos: '환희에 찬'이라는 뜻이라 문제 상황과 맞지 않습니다 ✗","sometidos: '복종한, 굴복한'이라는 뜻으로 누군가에게 지배받는 상태라 맞지 않습니다 ✗","aliviados: '안도한'이라는 뜻이라 해결 못 한 상황과 맞지 않습니다 ✗","resignados: '체념한'으로 정답입니다 ✓"]},{"id":"V529","q":"Esos atletas son profesionales, es decir, deportistas de alto ____.","o":["estatus","rendimiento","alcance","aprovechamiento"],"a":1,"k":"스포츠 어휘","t":"그 선수들은 프로, 즉 엘리트(고성능) 운동선수들이다.","e":"'deportista de alto rendimiento'는 '엘리트 선수, 고성능 운동선수'라는 고정 표현입니다. rendimiento는 '성과, 효율, 성능'이라는 뜻입니다. 예: rendimiento académico(학업 성취도).","x":["estatus: '지위, 신분'이라는 뜻이라 'alto estatus'는 운동선수 고정 표현이 아닙니다 ✗","rendimiento: 'alto rendimiento(고성능, 엘리트)'로 정답입니다 ✓","alcance: '범위, 사정거리'라는 뜻이라 맞지 않습니다 ✗","aprovechamiento: '활용'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V530","q":"Hay que ser ____ para saltar en paracaídas.","o":["asustadizo","gallina","apocado","osado"],"a":3,"k":"성격 형용사","t":"스카이다이빙을 하려면 대담해야 한다.","e":"osado/a는 '대담한, 겁 없는'이라는 뜻입니다. 낙하산으로 뛰어내리는(saltar en paracaídas) 데 필요한 성격이므로 정답입니다. 나머지 보기는 모두 '겁 많은'이라는 반대 의미입니다.","x":["asustadizo: '잘 놀라는, 겁 많은'이라는 뜻이라 반대 의미입니다 ✗","gallina: '겁쟁이(원래 뜻은 암탉)'라서 반대 의미입니다 ✗","apocado: '소심한'이라는 뜻이라 반대 의미입니다 ✗","osado: '대담한'으로 정답입니다 ✓"]},{"id":"V531","q":"No quiero jugar con mi hermano al parchís porque siempre hace ____.","o":["trampa","engaño","fraude","estafa"],"a":0,"k":"놀이 관련 표현","t":"형(동생)이 늘 반칙을 해서 같이 파르치스 게임을 하고 싶지 않다.","e":"'hacer trampa(s)'는 '(게임에서) 속임수를 쓰다, 반칙하다'라는 고정 표현입니다. parchís는 스페인에서 인기 있는 주사위 보드게임입니다. 사기꾼은 tramposo/a라고 합니다.","x":["trampa: 'hacer trampa(반칙하다)'로 정답입니다 ✓","engaño: '속임'이라는 뜻이지만 'hacer engaño'라는 표현은 쓰지 않습니다 ✗","fraude: '사기, 부정'이라는 법률·경제 용어라 게임에는 어색합니다 ✗","estafa: '(금전) 사기'라는 뜻이라 게임 상황과 맞지 않습니다 ✗"]},{"id":"V532","q":"Estoy sin blanca. Tendré que pedirle un ____ a mi jefa para llegar a fin de mes.","o":["anticipo","adelantamiento","aplazamiento","retraso"],"a":0,"k":"금전 어휘","t":"나는 빈털터리다. 월말까지 버티려면 상사에게 가불을 요청해야겠다.","e":"anticipo는 '선불, 가불(월급을 미리 받는 것)'입니다. 'estar sin blanca'는 '돈이 한 푼도 없다'는 스페인 구어 표현이고, 'llegar a fin de mes'는 '월말까지 버티다'입니다.","x":["anticipo: '가불, 선지급'으로 정답입니다 ✓","adelantamiento: '(차량) 추월'이라는 뜻이라 돈과 무관합니다 ✗","aplazamiento: '연기, 미루기'라는 뜻이라 돈을 받는 것이 아닙니다 ✗","retraso: '지연'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V533","q":"Cuando estoy estresado, voy a que me den un masaje ____ para sentirme mejor.","o":["relajante","asfixiante","sofocante","fatigante"],"a":0,"k":"건강·휴식 형용사","t":"스트레스를 받으면 기분이 나아지도록 이완 마사지를 받으러 간다.","e":"relajante는 relajar(긴장을 풀다)에서 나온 말로 '긴장을 풀어 주는, 편안하게 해 주는'이라는 뜻입니다. 'masaje relajante(이완 마사지)'는 자주 쓰는 조합입니다. 스트레스 해소 목적과 정확히 맞습니다.","x":["relajante: '긴장을 풀어 주는'으로 정답입니다 ✓","asfixiante: '숨 막히는'이라는 뜻이라 반대 의미입니다 ✗","sofocante: '숨 막히는, 무더운'이라는 뜻이라 맞지 않습니다 ✗","fatigante: '피곤하게 하는'이라는 뜻이라 반대 의미입니다 ✗"]},{"id":"V534","q":"Mi abuela ____ una enfermedad pulmonar.","o":["padece","vive","experimenta","siente"],"a":0,"k":"질병 관련 동사","t":"우리 할머니는 폐 질환을 앓고 계신다.","e":"padecer는 '(병을) 앓다, 고통을 겪다'라는 뜻으로 'padecer una enfermedad'는 매우 자연스러운 조합입니다. 비슷한 동사로 sufrir가 있습니다. 예: Padece diabetes.(그는 당뇨를 앓고 있다.)","x":["padece: '(병을) 앓다'로 정답입니다 ✓","vive: '살다'라서 병을 목적어로 쓰지 않습니다 ✗","experimenta: '경험하다'라서 병을 앓는다는 뜻으로는 어색합니다 ✗","siente: '느끼다'라서 병을 목적어로 쓰지 않습니다 ✗"]},{"id":"V535","q":"Trabajar muchas horas puede aumentar nuestros ingresos, pero la otra ____ de la moneda es el cansancio que conlleva.","o":["zona","superficie","parte","cara"],"a":3,"k":"관용 표현","t":"오래 일하면 수입을 늘릴 수 있지만, 동전의 다른 면은 그에 따르는 피로다.","e":"'la otra cara de la moneda'는 '동전의 다른 면', 즉 '이면, 반대 측면'이라는 관용 표현입니다. cara는 '얼굴' 외에 '면'이라는 뜻도 있습니다. conllevar는 '수반하다'라는 뜻입니다.","x":["zona: '지역, 구역'이라는 뜻으로 이 관용구에 쓰지 않습니다 ✗","superficie: '표면'이라는 뜻이지만 관용구에 쓰지 않습니다 ✗","parte: '부분'이라는 뜻이지만 이 관용구는 cara를 씁니다 ✗","cara: 'la otra cara de la moneda(동전의 이면)'로 정답입니다 ✓"]},{"id":"V536","q":"Después de la conferencia, podrán ____ las preguntas que quieran.","o":["reproducir","inventar","interpretar","formular"],"a":3,"k":"질문 관련 동사","t":"강연이 끝난 후에 원하는 질문을 하실 수 있습니다.","e":"formular는 '(질문·의견을) 제시하다, 표현하다'라는 격식 있는 동사입니다. 'formular preguntas'는 '질문을 하다'라는 뜻으로 공식적인 상황에서 자주 씁니다. 일상에서는 'hacer preguntas'라고 합니다.","x":["reproducir: '재생하다, 복제하다'라는 뜻이라 질문과 맞지 않습니다 ✗","inventar: '지어내다, 발명하다'라는 뜻이라 맞지 않습니다 ✗","interpretar: '해석하다, 연주하다'라는 뜻이라 맞지 않습니다 ✗","formular: '(질문을) 하다, 제시하다'로 정답입니다 ✓"]},{"id":"V537","q":"Hay que conducir con ____ para evitar accidentes.","o":["imprudencia","previsión","discreción","precaución"],"a":3,"k":"운전 관련 어휘","t":"사고를 피하려면 조심해서 운전해야 한다.","e":"precaución는 '조심, 주의, 예방 조치'라는 뜻이며 'con precaución'은 '조심해서'입니다. 사고를 피하기 위한 운전 태도로 가장 적절합니다. 비슷한 표현: con cuidado(조심해서).","x":["imprudencia: '경솔함, 부주의'라는 뜻이라 사고를 부릅니다 ✗","previsión: '예측, 대비'라는 뜻이지만 'conducir con previsión'은 일반적이지 않습니다 ✗","discreción: '신중함, 분별, 비밀 유지'라는 뜻으로 운전과 어울리지 않습니다 ✗","precaución: '조심'으로 'con precaución'이 정답입니다 ✓"]},{"id":"V538","q":"Es normal que esté estresada, ____ un cargo de mucha responsabilidad.","o":["emplea","ocupa","establece","empeña"],"a":1,"k":"직위 관련 동사","t":"그녀가 스트레스를 받는 것은 당연하다. 책임이 아주 큰 직책을 맡고 있으니까.","e":"'ocupar un cargo'는 '직위·직책을 맡다'라는 고정 표현입니다. ocupar는 '차지하다, 점유하다'라는 뜻입니다. 예: Ocupa el cargo de directora.(그녀는 이사직을 맡고 있다.)","x":["emplea: emplear(고용하다, 사용하다)라서 직책과 맞지 않습니다 ✗","ocupa: 'ocupar un cargo(직책을 맡다)'로 정답입니다 ✓","establece: establecer(설립하다, 정하다)라서 맞지 않습니다 ✗","empeña: empeñar(저당 잡히다)라서 맞지 않습니다 ✗"]},{"id":"V539","q":"¡Qué desastre! El banco me ha denegado el ____ que solicité.","o":["sueldo","favor","préstamo","premio"],"a":2,"k":"은행 어휘","t":"이런 낭패가! 은행이 내가 신청한 대출을 거절했다.","e":"préstamo는 '대출, 빌려줌'이라는 뜻입니다. 은행에 신청하고(solicitar) 은행이 거절(denegar)할 수 있는 것은 대출입니다. 동사 prestar는 '빌려주다'입니다.","x":["sueldo: '월급'이라서 은행에 신청하는 것이 아닙니다 ✗","favor: '부탁, 호의'라서 은행과 맞지 않습니다 ✗","préstamo: '대출'로 정답입니다 ✓","premio: '상'이라서 은행에 신청하지 않습니다 ✗"]},{"id":"V540","q":"Cuando el jugador cayó ____ todo el público se quedó de piedra.","o":["consciente","paciente","ausente","inconsciente"],"a":3,"k":"의식 상태 형용사","t":"그 선수가 의식을 잃고 쓰러지자 관중 모두가 얼어붙었다.","e":"inconsciente는 '의식이 없는'이라는 뜻입니다. 'caer inconsciente'는 '의식을 잃고 쓰러지다'라는 표현입니다. 관중이 놀라 얼어붙은(se quedó de piedra) 이유가 됩니다.","x":["consciente: '의식이 있는'이라는 뜻이라 놀랄 이유가 되지 않습니다 ✗","paciente: '참을성 있는, 환자'라는 뜻이라 맞지 않습니다 ✗","ausente: '부재중인, 멍한'이라는 뜻으로 쓰러지는 상태를 정확히 나타내지 못합니다 ✗","inconsciente: '의식이 없는'으로 정답입니다 ✓"]},{"id":"V541","q":"Para ____ mis argumentos necesitas demostrar la validez de los tuyos.","o":["rebatir","excusar","predecir","recriminar"],"a":0,"k":"논쟁 관련 동사","t":"내 주장을 반박하려면 네 주장의 타당성을 증명해야 한다.","e":"rebatir는 '(주장·의견을) 반박하다'라는 뜻입니다. 'rebatir argumentos(주장을 반박하다)'는 토론에서 자주 쓰는 표현입니다. 자신의 주장이 타당함을 보여야 상대 주장을 반박할 수 있다는 논리입니다.","x":["rebatir: '반박하다'로 정답입니다 ✓","excusar: '변명하다, 면제하다'라는 뜻이라 맞지 않습니다 ✗","predecir: '예측하다'라는 뜻이라 맞지 않습니다 ✗","recriminar: '비난하다, 나무라다'라는 뜻으로 주장을 목적어로 하기에 어색합니다 ✗"]},{"id":"V542","q":"Las personas con movilidad ____ necesitan ayuda extra.","o":["ilimitada","reducida","total","absoluta"],"a":1,"k":"장애 관련 어휘","t":"이동이 불편한(거동이 불편한) 사람들은 추가적인 도움이 필요하다.","e":"'movilidad reducida'는 '줄어든 이동성', 즉 '거동 불편, 이동 약자'를 가리키는 공식 표현입니다. 'personas con movilidad reducida'는 공공장소 안내문 등에서 자주 볼 수 있습니다.","x":["ilimitada: '무제한의'라는 뜻이라 도움이 필요한 이유가 되지 않습니다 ✗","reducida: '줄어든'으로 'movilidad reducida(거동 불편)'가 정답입니다 ✓","total: '완전한'이라는 뜻이라 도움이 필요하지 않습니다 ✗","absoluta: '절대적인'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V543","q":"Rubén está ____ porque nadie reconoce el valor de su trabajo.","o":["inspirado","desmotivado","ilusionado","conforme"],"a":1,"k":"감정 상태 형용사","t":"루벤은 아무도 자기 일의 가치를 인정해 주지 않아서 의욕을 잃었다.","e":"desmotivado/a는 '의욕을 잃은, 동기가 떨어진'이라는 뜻입니다. 노력을 인정받지 못하면 의욕이 떨어지므로 정답입니다. 반대말은 motivado/a(의욕 있는)입니다.","x":["inspirado: '영감을 받은'이라는 뜻이라 인정받지 못한 상황과 맞지 않습니다 ✗","desmotivado: '의욕을 잃은'으로 정답입니다 ✓","ilusionado: '기대에 부푼'이라는 뜻이라 반대 의미입니다 ✗","conforme: '만족한, 동의하는'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V544","q":"Al llegar al aeropuerto, debemos ____ el equipaje.","o":["inscribir","registrar","facturar","señalar"],"a":2,"k":"공항 어휘","t":"공항에 도착하면 짐을 부쳐야 한다.","e":"facturar는 공항에서 '(짐을) 부치다, 체크인하다'라는 뜻입니다. 'facturar el equipaje'는 공항에서 꼭 쓰는 표현입니다. 일반적으로는 '청구서를 발행하다'라는 뜻도 있습니다. 중남미에서는 'despachar el equipaje'라고도 합니다.","x":["inscribir: '등록하다'라는 뜻으로 짐에는 쓰지 않습니다 ✗","registrar: '기록하다, 수색하다'라는 뜻으로 짐을 부치는 표현이 아닙니다 ✗","facturar: '(짐을) 부치다'로 정답입니다 ✓","señalar: '가리키다, 표시하다'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V545","q":"Actualmente, el ____ más alto del mundo tiene ciento sesenta y tres pisos.","o":["rascacielos","templo","palacete","alcázar"],"a":0,"k":"건축물 어휘","t":"현재 세계에서 가장 높은 마천루는 163층이다.","e":"rascacielos는 rascar(긁다) + cielos(하늘)로 '하늘을 긁는 건물', 즉 '마천루, 초고층 빌딩'입니다. 단수와 복수 형태가 같습니다(el rascacielos / los rascacielos). 163층이라는 정보와 정확히 맞습니다.","x":["rascacielos: '마천루'로 정답입니다 ✓","templo: '사원, 신전'이라 163층 건물이 아닙니다 ✗","palacete: '작은 저택'이라 고층 건물이 아닙니다 ✗","alcázar: '(이슬람식) 성채, 궁전'이라 고층 건물이 아닙니다 ✗"]},{"id":"V546","q":"Fui a un ____ de belleza para que me hicieran la manicura.","o":["salón","local","espacio","aula"],"a":0,"k":"미용 관련 어휘","t":"매니큐어를 받으려고 미용실(뷰티 살롱)에 갔다.","e":"'salón de belleza'는 '미용실, 뷰티 살롱'이라는 고정 표현입니다. 'hacer la manicura'는 '손톱 손질을 하다'입니다. 비슷하게 'peluquería'는 '미용실(머리 손질)'입니다.","x":["salón: 'salón de belleza(뷰티 살롱)'로 정답입니다 ✓","local: '가게, 점포'라는 일반적인 말로 고정 표현이 아닙니다 ✗","espacio: '공간'이라는 뜻으로 고정 표현이 아닙니다 ✗","aula: '교실'이라서 미용과 관련이 없습니다 ✗"]},{"id":"V547","q":"Rompí con mi novia porque me fue ____.","o":["leal","infiel","sincera","honesta"],"a":1,"k":"연애 관련 형용사","t":"여자 친구가 바람을 피워서 헤어졌다.","e":"infiel은 '부정한, 바람피우는'이라는 뜻이고 'ser infiel a alguien'은 '~를 두고 바람을 피우다'입니다. 'romper con alguien'은 '~와 헤어지다'라는 표현입니다. 반대말은 fiel(충실한)입니다.","x":["leal: '충실한'이라는 뜻이라 헤어질 이유가 아닙니다 ✗","infiel: '바람피운'으로 헤어진 이유가 됩니다 ✓","sincera: '진솔한'이라는 뜻이라 헤어질 이유가 되지 않습니다 ✗","honesta: '정직한'이라는 뜻이라 헤어질 이유가 되지 않습니다 ✗"]},{"id":"V548","q":"Óscar no conoce la modestia, es una de las personas más ____ que conozco.","o":["vanidosas","humildes","sencillas","aprensivas"],"a":0,"k":"성격 형용사","t":"오스카르는 겸손이라곤 모른다. 내가 아는 사람 중 가장 허영심 많은 사람 중 하나다.","e":"vanidoso/a는 '허영심이 많은, 자만하는'이라는 뜻입니다. 'no conoce la modestia(겸손을 모른다)'와 의미가 이어집니다. 명사형은 vanidad(허영심)입니다.","x":["vanidosas: '허영심 많은'으로 정답입니다 ✓","humildes: '겸손한'이라는 뜻이라 반대 의미입니다 ✗","sencillas: '소박한'이라는 뜻이라 반대 의미입니다 ✗","aprensivas: '걱정이 많은, 겁 많은'이라는 뜻으로 겸손과 관계가 없습니다 ✗"]},{"id":"V549","q":"No tengo ninguna vivienda en ____, vivo de alquiler.","o":["posesión","poder","pertenencia","propiedad"],"a":3,"k":"부동산 어휘","t":"나는 소유한 집이 없고, 월세로 산다.","e":"'en propiedad'는 '소유물로, 자기 소유로'라는 뜻입니다. 'vivienda en propiedad'는 '자가 주택'이고 'vivir de alquiler'는 '세 들어 살다'입니다. 두 표현이 대비됩니다.","x":["posesión: '소유, 점유'라는 뜻이지만 'en posesión'은 주택 소유를 말하는 고정 표현이 아닙니다 ✗","poder: 'en poder de'는 '~의 수중에'라는 뜻으로 여기에 맞지 않습니다 ✗","pertenencia: '소속, 소지품'이라는 뜻이라 맞지 않습니다 ✗","propiedad: 'en propiedad(자가 소유로)'로 정답입니다 ✓"]},{"id":"V550","q":"Después de la lluvia, algunas calles están llenas de ____.","o":["barro","arena","tierra","polvo"],"a":0,"k":"자연 어휘","t":"비가 온 후 몇몇 거리는 진흙투성이다.","e":"barro는 '진흙'으로, 흙과 물이 섞인 것입니다. 비가 온 뒤 거리에 생기는 것이므로 정답입니다. 비슷하게 'lodo'도 '진흙'을 뜻합니다.","x":["barro: '진흙'으로 비 온 뒤에 생기는 것입니다 ✓","arena: '모래'로 비와 직접 관련이 없습니다 ✗","tierra: '흙'이지만 젖은 상태를 나타내지 않습니다 ✗","polvo: '먼지'로 비가 온 뒤에는 오히려 사라집니다 ✗"]},{"id":"V551","q":"Ese hombre es un conocido ____ de televisión.","o":["granjero","barrendero","reportero","ganadero"],"a":2,"k":"직업 어휘","t":"그 남자는 유명한 TV 기자다.","e":"reportero/a는 '기자, 리포터'입니다. 'reportero de televisión(TV 기자)'는 텔레비전과 연결되는 유일한 직업입니다. 비슷한 말: periodista(기자, 저널리스트).","x":["granjero: '농부'로 TV와 관련이 없습니다 ✗","barrendero: '환경미화원'으로 TV와 관련이 없습니다 ✗","reportero: 'TV 기자'로 정답입니다 ✓","ganadero: '목축업자'로 TV와 관련이 없습니다 ✗"]},{"id":"V552","q":"No necesito un teléfono ____, pues sólo lo uso para sus funciones básicas.","o":["económico","rebajado","de ocasión","costoso"],"a":3,"k":"가격 형용사","t":"나는 비싼 전화기가 필요 없다, 기본 기능만 쓰니까.","e":"costoso/a는 '비싼, 비용이 많이 드는'이라는 뜻입니다. 기본 기능만 쓰니까 비싼 전화기가 필요 없다는 논리이므로 정답입니다. pues는 여기서 '왜냐하면'이라는 뜻입니다.","x":["económico: '저렴한'이라는 뜻이라 '필요 없다'와 논리가 맞지 않습니다 ✗","rebajado: '할인된'이라는 뜻이라 논리가 맞지 않습니다 ✗","de ocasión: '중고의, 특가의'라는 뜻이라 맞지 않습니다 ✗","costoso: '비싼'으로 정답입니다 ✓"]},{"id":"V553","q":"Es ____, no sabe leer ni escribir.","o":["analfabeto","inofensivo","inquieto","instruido"],"a":0,"k":"교육 수준 어휘","t":"그는 문맹이라 읽을 줄도 쓸 줄도 모른다.","e":"analfabeto/a는 '문맹의, 글을 모르는'이라는 뜻입니다. 'no sabe leer ni escribir(읽지도 쓰지도 못한다)'는 그 정의 그대로입니다. 명사형은 analfabetismo(문맹)입니다.","x":["analfabeto: '문맹의'로 정답입니다 ✓","inofensivo: '해가 없는'이라는 뜻이라 맞지 않습니다 ✗","inquieto: '불안한, 가만히 있지 못하는'이라는 뜻이라 맞지 않습니다 ✗","instruido: '교육받은, 박식한'이라는 뜻이라 반대 의미입니다 ✗"]},{"id":"V554","q":"¿Cuántas personas ____ a la inauguración de la tienda?","o":["corrieron","viajaron","acudieron","anduvieron"],"a":2,"k":"참석 관련 동사","t":"가게 개업식에 몇 명이 왔니?","e":"acudir는 '(어떤 장소·행사에) 가다, 참석하다'라는 뜻으로 'acudir a un evento'처럼 씁니다. inauguración는 '개업, 개관식'입니다. 예: Mucha gente acudió a la manifestación.(많은 사람이 시위에 참가했다.)","x":["corrieron: '달렸다'라는 뜻이라 참석과 맞지 않습니다 ✗","viajaron: '여행했다'라는 뜻이라 개업식 참석에는 어색합니다 ✗","acudieron: '참석했다, 왔다'로 정답입니다 ✓","anduvieron: '걸었다'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V555","q":"Hacer este pastel es ____ y cantar, no es nada complicado.","o":["cocinar","tender","coser","planchar"],"a":2,"k":"관용 표현","t":"이 케이크 만들기는 식은 죽 먹기야, 전혀 어렵지 않아.","e":"'ser coser y cantar'는 '바느질하며 노래하기', 즉 '아주 쉽다, 식은 죽 먹기다'라는 관용 표현입니다. 비슷한 표현: 'ser pan comido(누워서 떡 먹기)'.","x":["cocinar: '요리하다'지만 이 관용 표현에 쓰지 않습니다 ✗","tender: '(빨래를) 널다'지만 이 관용 표현에 쓰지 않습니다 ✗","coser: 'coser y cantar(아주 쉬운 일)'로 정답입니다 ✓","planchar: '다림질하다'지만 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"V556","q":"Estamos totalmente ____ a esta serie de televisión.","o":["enganchadas","encadenadas","atadas","amarradas"],"a":0,"k":"구어 형용사","t":"우리는 이 TV 시리즈에 완전히 빠져 있다.","e":"enganchado/a는 원래 '걸린, 낚인'이라는 뜻인데, 구어에서는 '~에 푹 빠진, 중독된'이라는 의미로 씁니다. 'estar enganchado a algo'는 드라마·게임 등에 빠졌을 때 자주 씁니다. 주어가 여성 복수(nosotras)라서 enganchadas입니다.","x":["enganchadas: '푹 빠진'으로 정답입니다 ✓","encadenadas: '사슬에 묶인'이라는 뜻으로 시리즈에 빠진 상태를 나타내는 관용 표현이 아닙니다 ✗","atadas: '묶인'이라는 뜻이라 맞지 않습니다 ✗","amarradas: '(밧줄로) 묶인'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V557","q":"Jordi no se atreve a pedirle a Inma que salga con él por miedo a ser ____.","o":["rechazado","delatado","acusado","admirado"],"a":0,"k":"인간관계 어휘","t":"호르디는 거절당할까 봐 이냐에게 데이트 신청을 하지 못한다.","e":"rechazado/a는 rechazar(거절하다)의 과거분사로 '거절당한'이라는 뜻입니다. 'por miedo a ser rechazado'는 '거절당할까 두려워서'라는 수동 구조입니다. atreverse a는 '감히 ~하다'라는 뜻입니다.","x":["rechazado: '거절당한'으로 정답입니다 ✓","delatado: '고발당한, 밀고당한'이라는 뜻이라 연애 상황과 맞지 않습니다 ✗","acusado: '고소당한, 비난받은'이라는 뜻이라 맞지 않습니다 ✗","admirado: '감탄받은'이라는 뜻으로 두려워할 이유가 아닙니다 ✗"]},{"id":"V558","q":"Solo un ____ podría cometer esos crímenes tan horribles.","o":["ángel","trol","genio","monstruo"],"a":3,"k":"사람 묘사 명사","t":"괴물 같은 사람만이 그런 끔찍한 범죄를 저지를 수 있을 것이다.","e":"monstruo는 '괴물'이며, 사람에게 쓰면 '잔인하고 비인간적인 사람'을 뜻합니다. 끔찍한 범죄(crímenes tan horribles)를 저지를 사람으로 가장 적절합니다. 'cometer un crimen'은 '범죄를 저지르다'입니다.","x":["ángel: '천사'라는 뜻이라 범죄와 반대됩니다 ✗","trol: '트롤(인터넷 악성 사용자, 괴물)'이지만 범죄자를 표현하는 일반적인 말이 아닙니다 ✗","genio: '천재'라는 뜻이라 범죄와 무관합니다 ✗","monstruo: '괴물 같은 사람'으로 정답입니다 ✓"]},{"id":"V559","q":"Estos yogures están ____, no te los comas.","o":["desfasados","caducados","atrasados","anticuados"],"a":1,"k":"식품 상태 형용사","t":"이 요구르트들은 유통기한이 지났으니 먹지 마.","e":"caducado/a는 caducar(기한이 만료되다)의 과거분사로 '유통기한이 지난'이라는 뜻입니다. 식품뿐 아니라 여권·카드 등의 만료에도 씁니다. 예: Mi pasaporte está caducado.(내 여권이 만료됐다.) 중남미에서는 vencido도 많이 씁니다.","x":["desfasados: '시대에 뒤처진, 어긋난'이라는 뜻으로 식품에 쓰지 않습니다 ✗","caducados: '유통기한이 지난'으로 정답입니다 ✓","atrasados: '늦은, 뒤처진'이라는 뜻으로 식품 상태를 말하지 않습니다 ✗","anticuados: '구식의'라는 뜻으로 식품에 쓰지 않습니다 ✗"]},{"id":"V560","q":"Manuel es un hombre ____ que siempre tiene algún proyecto en mente.","o":["reprimido","provocador","receloso","emprendedor"],"a":3,"k":"성격 형용사","t":"마누엘은 항상 어떤 프로젝트를 구상하고 있는 진취적인 사람이다.","e":"emprendedor/a는 '진취적인, 기업가 정신이 있는'이라는 뜻입니다. 항상 새로운 프로젝트를 생각한다는 설명과 맞습니다. emprender(착수하다)에서 나왔으며 명사로는 '창업가'라는 뜻도 있습니다.","x":["reprimido: '억눌린, 억압된'이라는 뜻이라 맞지 않습니다 ✗","provocador: '도발적인'이라는 뜻이라 프로젝트와 연결되지 않습니다 ✗","receloso: '의심이 많은'이라는 뜻이라 맞지 않습니다 ✗","emprendedor: '진취적인'으로 정답입니다 ✓"]},{"id":"V561","q":"Una ____ es una suposición.","o":["hipótesis","afirmación","proposición","tesis"],"a":0,"k":"학문 어휘","t":"가설은 추측(가정)이다.","e":"hipótesis는 '가설'로, 아직 증명되지 않은 가정, 즉 suposición입니다. 단수와 복수 형태가 같습니다(la hipótesis / las hipótesis). 정의를 묻는 문제이므로 suposición과 가장 가까운 단어를 고르면 됩니다.","x":["hipótesis: '가설'로 suposición(추측)과 같은 뜻입니다 ✓","afirmación: '단언, 주장'이라는 뜻으로 추측과 다릅니다 ✗","proposición: '제안, 명제'라는 뜻으로 추측과 같지 않습니다 ✗","tesis: '논지, 학위 논문'이라는 뜻으로 추측과 다릅니다 ✗"]},{"id":"V562","q":"La lengua es un ____.","o":["hueso","músculo","tendón","nervio"],"a":1,"k":"신체 어휘","t":"혀는 근육이다.","e":"músculo는 '근육'입니다. 혀(lengua)는 여러 근육으로 이루어진 기관입니다. lengua는 '혀' 외에 '언어'라는 뜻도 있으니 함께 기억하세요.","x":["hueso: '뼈'라서 혀가 아닙니다 ✗","músculo: '근육'으로 정답입니다 ✓","tendón: '힘줄'이라서 혀가 아닙니다 ✗","nervio: '신경'이라서 혀가 아닙니다 ✗"]},{"id":"V563","q":"La alta tasa de ____ escolar es un serio problema en esta región.","o":["huida","olvido","dimisión","abandono"],"a":3,"k":"교육 문제 어휘","t":"높은 학업 중단율은 이 지역의 심각한 문제다.","e":"'abandono escolar'는 '학업 중단, 중도 탈락'이라는 고정 표현입니다. abandono는 '포기, 버림'이라는 뜻이며 tasa는 '비율'입니다. 예: tasa de desempleo(실업률).","x":["huida: '도주'라는 뜻으로 학업 중단을 표현하지 않습니다 ✗","olvido: '망각'이라는 뜻이라 맞지 않습니다 ✗","dimisión: '사임, 사직'이라는 뜻으로 직장에 씁니다 ✗","abandono: 'abandono escolar(학업 중단)'로 정답입니다 ✓"]},{"id":"V564","q":"Las mandarinas pertenecen al grupo de los ____.","o":["granos","lácteos","frutos secos","cítricos"],"a":3,"k":"과일 분류 어휘","t":"귤은 감귤류에 속한다.","e":"cítrico는 '감귤류(시트러스)'입니다. 귤(mandarina), 오렌지(naranja), 레몬(limón), 자몽(pomelo) 등이 여기에 속합니다. 'pertenecer a'는 '~에 속하다'라는 뜻입니다.","x":["granos: '곡물, 낟알'이라 귤이 아닙니다 ✗","lácteos: '유제품'이라 귤이 아닙니다 ✗","frutos secos: '견과류'라 귤이 아닙니다 ✗","cítricos: '감귤류'로 정답입니다 ✓"]},{"id":"V565","q":"Juan leyó una ____ dirigida a su mujer como señal de agradecimiento.","o":["súplica","petición","réplica","dedicatoria"],"a":3,"k":"글 종류 어휘","t":"후안은 감사의 표시로 아내에게 바치는 헌사를 읽었다.","e":"dedicatoria는 '헌사(누군가에게 바치는 짧은 글)'입니다. 'dirigida a su mujer(아내를 향한)'와 'señal de agradecimiento(감사의 표시)'에 딱 맞습니다. 동사 dedicar는 '바치다, 헌정하다'입니다.","x":["súplica: '간청, 애원'이라는 뜻이라 감사 표시와 맞지 않습니다 ✗","petición: '요청, 청원'이라는 뜻이라 감사와 맞지 않습니다 ✗","réplica: '반박, 대답'이라는 뜻이라 맞지 않습니다 ✗","dedicatoria: '헌사'로 정답입니다 ✓"]},{"id":"V566","q":"Mi abuela siempre me trataba con ____, era una mujer muy dulce.","o":["ternura","insensibilidad","arrogancia","crueldad"],"a":0,"k":"감정 어휘","t":"우리 할머니는 늘 나를 다정하게 대해 주셨다. 아주 상냥한 분이셨다.","e":"ternura는 '다정함, 애정 어린 부드러움'이라는 뜻입니다. 'tratar con ternura'는 '다정하게 대하다'입니다. dulce(상냥한, 다정한)와 의미가 이어집니다. 형용사형은 tierno/a(다정한, 부드러운)입니다.","x":["ternura: '다정함'으로 정답입니다 ✓","insensibilidad: '무감각, 냉담함'이라는 뜻이라 반대 의미입니다 ✗","arrogancia: '오만함'이라는 뜻이라 반대 의미입니다 ✗","crueldad: '잔인함'이라는 뜻이라 반대 의미입니다 ✗"]},{"id":"V567","q":"Tened cuidado al caminar por ahí, hay pendientes ____.","o":["bajas","pronunciadas","inapreciables","medianas"],"a":1,"k":"지형 묘사 형용사","t":"그쪽으로 걸을 때 조심해, 경사가 가파르거든.","e":"pronunciado/a는 '두드러진, 뚜렷한'이라는 뜻이고 'pendiente pronunciada'는 '가파른 경사'입니다. 조심하라는 경고의 이유가 됩니다. pendiente는 명사로 '경사, 비탈'이며 '귀걸이'라는 뜻도 있습니다.","x":["bajas: '낮은'이라는 뜻이라 조심할 이유가 되지 않습니다 ✗","pronunciadas: '가파른'으로 정답입니다 ✓","inapreciables: '눈에 띄지 않는'이라는 뜻이라 위험하지 않습니다 ✗","medianas: '중간 정도의'라는 뜻으로 경고 이유로 약합니다 ✗"]},{"id":"V568","q":"Solo ____ los codos podrás aprobar todos los exámenes.","o":["apretando","fijando","bajando","hincando"],"a":3,"k":"관용 표현","t":"열심히 공부해야만 모든 시험에 합격할 수 있다.","e":"'hincar los codos'는 '팔꿈치를 (책상에) 박다', 즉 '열심히 공부하다'라는 스페인 관용 표현입니다. hincar는 '박다, 꽂다'라는 뜻입니다. 여기서는 현재분사 hincando가 '~함으로써'의 뜻으로 쓰였습니다.","x":["apretando: apretar(누르다)지만 이 관용 표현에 쓰지 않습니다 ✗","fijando: fijar(고정하다)지만 이 관용 표현에 쓰지 않습니다 ✗","bajando: bajar(내리다)지만 이 관용 표현에 쓰지 않습니다 ✗","hincando: 'hincar los codos(열심히 공부하다)'로 정답입니다 ✓"]},{"id":"V569","q":"La empresa para la que trabajo va a incorporar a una decena de nuevos empleados a la ____.","o":["brigada","plantilla","banda","congregación"],"a":1,"k":"직장 어휘","t":"내가 일하는 회사는 직원 명단(인력)에 신입 직원 열 명 정도를 추가할 것이다.","e":"plantilla는 회사의 '전체 직원, 인력 구성'이라는 뜻입니다. 'incorporar a la plantilla'는 '직원으로 채용하다'입니다. plantilla는 '신발 깔창, 서식(템플릿)'이라는 뜻도 있습니다. decena는 '열 개(명) 정도'입니다.","x":["brigada: '(군대·소방) 부대, 반'이라는 뜻이라 회사 직원에는 쓰지 않습니다 ✗","plantilla: '(회사의) 전체 직원'으로 정답입니다 ✓","banda: '악단, 무리, 갱단'이라는 뜻이라 맞지 않습니다 ✗","congregación: '(종교적) 신도 집단'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V570","q":"Estas flores ____ un extraño olor.","o":["desprenden","lanzan","vierten","desatan"],"a":0,"k":"냄새 관련 동사","t":"이 꽃들은 이상한 냄새를 풍긴다.","e":"desprender는 '(냄새·열·빛 등을) 내뿜다, 발산하다'라는 뜻입니다. 'desprender un olor'는 '냄새를 풍기다'라는 자연스러운 조합입니다. 재귀형 desprenderse는 '떨어지다, 버리다'라는 뜻입니다.","x":["desprenden: '(냄새를) 풍기다'로 정답입니다 ✓","lanzan: lanzar(던지다)라서 냄새와 쓰지 않습니다 ✗","vierten: verter(붓다, 쏟다)라서 액체에 씁니다 ✗","desatan: desatar(풀다, 일으키다)라서 냄새와 맞지 않습니다 ✗"]},{"id":"V571","q":"Lo quiere todo para él, es muy ____.","o":["desinteresado","avaricioso","altruista","generoso"],"a":1,"k":"성격 형용사","t":"그는 모든 걸 자기 것으로 하려 한다, 아주 탐욕스럽다.","e":"avaricioso/a는 '탐욕스러운, 욕심 많은'이라는 뜻입니다. 'Lo quiere todo para él(모든 걸 자기 것으로 원한다)'는 설명과 맞습니다. 명사형은 avaricia(탐욕)이고, 비슷한 말로 codicioso(욕심 많은)가 있습니다.","x":["desinteresado: '사심 없는'이라는 뜻이라 반대 의미입니다 ✗","avaricioso: '탐욕스러운'으로 정답입니다 ✓","altruista: '이타적인'이라는 뜻이라 반대 의미입니다 ✗","generoso: '너그러운, 인심 좋은'이라는 뜻이라 반대 의미입니다 ✗"]},{"id":"V572","q":"Puedes ayudarme a cortar madera con esa ____ de allí.","o":["pala","paleta","taladradora","sierra"],"a":3,"k":"공구 어휘","t":"저기 있는 톱으로 나무 자르는 것 좀 도와줄래?","e":"sierra는 '톱'으로 나무를 자르는 도구입니다. 'cortar madera(나무를 자르다)'에 딱 맞습니다. sierra는 '산맥'이라는 뜻도 있습니다(예: Sierra Nevada).","x":["pala: '삽'이라서 흙을 파는 데 씁니다 ✗","paleta: '흙손, 팔레트'라서 나무를 자르지 못합니다 ✗","taladradora: '드릴'이라서 구멍을 뚫는 데 씁니다 ✗","sierra: '톱'으로 정답입니다 ✓"]},{"id":"V573","q":"Ese futbolista se pone ____ cuando no gana su equipo, es un mal perdedor.","o":["eufórico","exultante","alegre","furioso"],"a":3,"k":"감정 상태 형용사","t":"그 축구 선수는 자기 팀이 이기지 못하면 격분한다. 패배를 받아들일 줄 모르는 사람이다.","e":"furioso/a는 '격노한, 몹시 화난'이라는 뜻입니다. 'mal perdedor(지는 것을 못 참는 사람)'라는 설명과 연결됩니다. 'ponerse + 형용사'는 '(일시적으로) ~한 상태가 되다'라는 표현입니다.","x":["eufórico: '몹시 들뜬, 열광한'이라는 뜻이라 팀이 졌을 때와 맞지 않습니다 ✗","exultante: '기뻐 날뛰는'이라는 뜻이라 반대 의미입니다 ✗","alegre: '기쁜'이라는 뜻이라 반대 의미입니다 ✗","furioso: '격분한'으로 정답입니다 ✓"]},{"id":"V574","q":"Cuando ____ cuenta de que el perro había escapado, ya era demasiado tarde.","o":["me hice","tomé","me di","pedí"],"a":2,"k":"관용 표현","t":"개가 도망간 걸 알아챘을 때는 이미 너무 늦었다.","e":"'darse cuenta de algo'는 '~을 깨닫다, 알아차리다'라는 아주 중요한 표현입니다. 재귀 동사라서 me di처럼 재귀대명사(자기 자신을 가리키는 대명사)를 씁니다. 'tomar en cuenta'(고려하다)와 헷갈리지 마세요.","x":["me hice: hacerse는 이 표현에 쓰지 않습니다 ✗","tomé: 'tomar cuenta'는 '깨닫다'라는 뜻이 아닙니다 ✗","me di: 'darse cuenta(알아차리다)'로 정답입니다 ✓","pedí: 'pedir cuentas'는 '해명을 요구하다'라는 다른 뜻입니다 ✗"]},{"id":"V575","q":"He mandado más de cincuenta currículos, pero no me han llamado ni para ____ de trabajo.","o":["un debate","una tertulia","una conferencia","una entrevista"],"a":3,"k":"구직 어휘","t":"이력서를 50통 넘게 보냈지만 면접 보라는 연락조차 오지 않았다.","e":"'entrevista de trabajo'는 '취업 면접'입니다. 이력서를 보낸 후 기대하는 다음 단계이므로 정답입니다. 'ni para ~'는 '~하라고조차'라는 강조 표현입니다. currículos는 currículum(이력서)의 복수형입니다.","x":["un debate: '토론'이라서 구직 과정과 맞지 않습니다 ✗","una tertulia: '(모임의) 담소, 토크쇼'라서 맞지 않습니다 ✗","una conferencia: '강연, 회의'라서 맞지 않습니다 ✗","una entrevista: 'entrevista de trabajo(취업 면접)'로 정답입니다 ✓"]},{"id":"V576","q":"Mi ____, el padre de mi esposo, es un hombre muy divertido.","o":["cuñado","padrastro","suegro","sobrino"],"a":2,"k":"가족 어휘","t":"남편의 아버지인 우리 시아버지는 아주 재미있는 분이다.","e":"suegro는 배우자의 아버지, 즉 '시아버지/장인'입니다. 배우자의 어머니는 suegra(시어머니/장모)입니다. 'el padre de mi esposo(남편의 아버지)'라는 설명이 정의를 그대로 알려 줍니다.","x":["cuñado: '시아주버니·처남·매형 등(배우자의 형제나 형제자매의 배우자)'이라 맞지 않습니다 ✗","padrastro: '의붓아버지(새아버지)'라서 맞지 않습니다 ✗","suegro: '시아버지/장인'으로 정답입니다 ✓","sobrino: '조카'라서 맞지 않습니다 ✗"]},{"id":"V577","q":"Cuando nació mi hija ____ loco, fue un día muy especial.","o":["me volví","me vi","aparecí","me hice"],"a":0,"k":"변화 동사","t":"딸이 태어났을 때 나는 (기뻐서) 정신이 없었다. 정말 특별한 날이었다.","e":"'volverse loco'는 '미치다, 정신이 나갈 정도로 흥분하다'라는 표현입니다. volverse는 '(성격·상태가) ~로 변하다'라는 변화 동사입니다. 여기서는 너무 기뻐서 어쩔 줄 몰랐다는 긍정적 의미입니다. 예: Me volví loca de alegría.(기뻐서 미칠 것 같았다.)","x":["me volví: 'volverse loco(미칠 듯이 되다)'로 정답입니다 ✓","me vi: verse는 '~한 처지가 되다'라는 뜻으로 loco와 이 의미로 쓰지 않습니다 ✗","aparecí: '나타났다'라는 뜻이라 맞지 않습니다 ✗","me hice: hacerse는 노력으로 무언가가 되는 변화(직업 등)에 쓰고 loco와는 쓰지 않습니다 ✗"]},{"id":"V578","q":"El nuevo ____ de la universidad dio un discurso muy emotivo.","o":["rector","sacerdote","párroco","pastor"],"a":0,"k":"직위 어휘","t":"대학교의 새 총장이 매우 감동적인 연설을 했다.","e":"rector/a는 대학교의 '총장'입니다. 'rector de la universidad'는 고정 표현입니다. 나머지 보기는 모두 종교 관련 직책입니다.","x":["rector: '(대학) 총장'으로 정답입니다 ✓","sacerdote: '사제, 신부'라서 대학과 직접 관련이 없습니다 ✗","párroco: '본당 신부'라서 대학과 관련이 없습니다 ✗","pastor: '목사, 목동'이라서 대학과 관련이 없습니다 ✗"]},{"id":"V579","q":"¡Qué programa tan ____! Volveré a verlo.","o":["entretenido","pesado","molesto","aburrido"],"a":0,"k":"감상 형용사","t":"정말 재미있는 프로그램이야! 다시 볼 거야.","e":"entretenido/a는 '재미있는, 즐거운'이라는 뜻입니다. 'Volveré a verlo(다시 볼 거야)'라는 긍정적 반응의 이유가 됩니다. 동사 entretener는 '즐겁게 하다'입니다.","x":["entretenido: '재미있는'으로 정답입니다 ✓","pesado: '지루한, 짜증 나는'이라는 뜻이라 다시 볼 이유가 아닙니다 ✗","molesto: '성가신'이라는 뜻이라 반대 의미입니다 ✗","aburrido: '지루한'이라는 뜻이라 반대 의미입니다 ✗"]},{"id":"V580","q":"Admiro la obra de esta novelista por su estilo elegante y ____.","o":["pretencioso","grotesco","cuidado","corriente"],"a":2,"k":"문체 묘사 형용사","t":"나는 이 소설가의 우아하고 정성스러운(공들인) 문체 때문에 그녀의 작품을 존경한다.","e":"cuidado/a는 cuidar(돌보다)의 과거분사로 '공들인, 세심하게 다듬은'이라는 뜻입니다. 'estilo cuidado'는 '잘 다듬어진 문체'입니다. 존경한다(admiro)는 긍정적 평가와 elegante와 함께 어울립니다.","x":["pretencioso: '허세 부리는'이라는 뜻이라 부정적입니다 ✗","grotesco: '기괴한, 우스꽝스러운'이라는 뜻이라 부정적입니다 ✗","cuidado: '공들인, 세심한'으로 정답입니다 ✓","corriente: '평범한'이라는 뜻이라 존경할 이유가 되지 않습니다 ✗"]},{"id":"V581","q":"____ con la historia de Lucía, le pasan unas cosas increíbles.","o":["Me molesté","Me adormecí","Aluciné","Me calmé"],"a":2,"k":"놀람 표현 동사","t":"루시아 이야기를 듣고 정말 놀랐어. 그녀한테 믿기 힘든 일들이 일어나거든.","e":"alucinar는 원래 '환각을 보다'라는 뜻이지만, 스페인 구어에서는 '깜짝 놀라다, 어이가 없다'라는 뜻으로 많이 씁니다. 'alucinar con algo'는 '~에 깜짝 놀라다'입니다. 뒤의 'cosas increíbles(믿기 힘든 일들)'와 연결됩니다.","x":["Me molesté: '화가 났다, 기분이 상했다'라는 뜻으로 놀라운 이야기와 연결되지 않습니다 ✗","Me adormecí: '졸았다'라는 뜻이라 맞지 않습니다 ✗","Aluciné: '깜짝 놀랐다'로 정답입니다 ✓","Me calmé: '진정했다'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V582","q":"Me ____ pánico las alturas, por eso nunca viajo en avión.","o":["dan","toman","pasan","hacen"],"a":0,"k":"감정 표현 동사","t":"나는 높은 곳이 무서워서 절대 비행기를 타지 않는다.","e":"'dar miedo/pánico'는 '~이 무섭게 하다'라는 표현으로 gustar처럼 간접목적격 대명사(me)를 씁니다. 주어가 las alturas(높은 곳, 복수)이므로 동사도 dan(복수)입니다. 예: Me dan miedo las arañas.(나는 거미가 무섭다.)","x":["dan: 'dar pánico(공포를 주다)'로 정답입니다 ✓","toman: tomar는 이 표현에 쓰지 않습니다 ✗","pasan: pasar는 이 표현에 쓰지 않습니다 ✗","hacen: hacer는 이 표현에 쓰지 않습니다 ✗"]},{"id":"V583","q":"Frida Kahlo y Diego Rivera ____ matrimonio dos veces.","o":["crearon","contrajeron","hicieron","adquirieron"],"a":1,"k":"결혼 관련 연어","t":"프리다 칼로와 디에고 리베라는 두 번 결혼했다.","e":"'contraer matrimonio'는 '결혼하다'라는 격식 있는 표현입니다. contraer는 '(의무·질병 등을) 지다, 걸리다'라는 뜻으로, 'contraer una enfermedad(병에 걸리다)', 'contraer deudas(빚을 지다)'처럼도 씁니다. 실제로 두 화가는 1929년에 결혼해 이혼 후 1940년에 재혼했습니다.","x":["crearon: '만들었다'라는 뜻으로 matrimonio와 쓰지 않습니다 ✗","contrajeron: 'contraer matrimonio(결혼하다)'로 정답입니다 ✓","hicieron: 'hacer matrimonio'는 쓰지 않습니다 ✗","adquirieron: '획득했다'라는 뜻으로 matrimonio와 쓰지 않습니다 ✗"]},{"id":"V584","q":"Genaro se quedó ____ hace dos años. Su esposa falleció de cáncer.","o":["aislado","viudo","soltero","confinado"],"a":1,"k":"혼인 상태 어휘","t":"헤나로는 2년 전에 홀아비가 되었다. 그의 아내가 암으로 세상을 떠났다.","e":"viudo/a는 배우자를 잃은 사람, 즉 '홀아비/과부'입니다. 'quedarse viudo'는 '홀아비가 되다'라는 표현입니다. 아내가 사망했다는 뒷문장이 이유를 설명합니다.","x":["aislado: '고립된'이라는 뜻으로 혼인 상태를 나타내지 않습니다 ✗","viudo: '홀아비'로 정답입니다 ✓","soltero: '미혼의'라는 뜻으로 결혼했던 사람에게 쓰지 않습니다 ✗","confinado: '격리된, 갇힌'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V585","q":"Prefiero ver películas en ____ original, el doblaje me resulta muy artificial.","o":["descripción","versión","interpretación","traducción"],"a":1,"k":"영화 관련 어휘","t":"나는 원어(오리지널 버전)로 영화 보는 것을 더 좋아한다. 더빙은 너무 부자연스럽게 느껴진다.","e":"'versión original'은 '원어판(더빙하지 않은 원래 언어 버전)'입니다. 스페인 영화관에서는 'V.O.'라고 줄여 쓰고, 자막이 있으면 'V.O.S.(versión original subtitulada)'입니다. doblaje는 '더빙'입니다.","x":["descripción: '묘사, 설명'이라는 뜻이라 맞지 않습니다 ✗","versión: 'versión original(원어판)'로 정답입니다 ✓","interpretación: '연기, 해석, 통역'이라는 뜻이라 고정 표현이 아닙니다 ✗","traducción: '번역'이라는 뜻으로 'traducción original'은 모순된 표현입니다 ✗"]},{"id":"V586","q":"En mi escritorio hay un ordenador, un estuche, una libreta y ____.","o":["una lámpara de pie","una papelera","un flexo","un felpudo"],"a":2,"k":"사무용품 어휘","t":"내 책상 위에는 컴퓨터, 필통, 공책, 그리고 책상용 스탠드가 있다.","e":"flexo는 스페인에서 '(목이 구부러지는) 책상 스탠드'를 뜻합니다. 책상 위(en mi escritorio)에 놓는 물건이므로 정답입니다. 'lámpara de pie'는 바닥에 세우는 스탠드라서 책상 위에 둘 수 없습니다.","x":["una lámpara de pie: '플로어 스탠드'로 바닥에 세우는 것이라 책상 위에 놓지 않습니다 ✗","una papelera: '쓰레기통'으로 보통 책상 아래에 둡니다 ✗","un flexo: '책상 스탠드'로 정답입니다 ✓","un felpudo: '현관 매트'라서 책상과 관련이 없습니다 ✗"]},{"id":"V587","q":"El niño se cayó en el ____, de ahí que tenga la ropa mojada.","o":["pavimento","charco","suelo","andén"],"a":1,"k":"자연·거리 어휘","t":"아이가 물웅덩이에 빠져서 옷이 젖었다.","e":"charco는 '물웅덩이'입니다. 옷이 젖은(ropa mojada) 이유가 되므로 정답입니다. 'de ahí que + 접속법'은 '그래서 ~하다'라는 뜻입니다.","x":["pavimento: '포장도로'라서 옷이 젖는 이유가 되지 않습니다 ✗","charco: '물웅덩이'로 정답입니다 ✓","suelo: '바닥, 땅'이라서 옷이 젖는 이유가 되지 않습니다 ✗","andén: '(역) 플랫폼, 승강장'이라서 맞지 않습니다 ✗"]},{"id":"V588","q":"Deje que se caliente el aceite en la ____ antes de freír las patatas.","o":["cazuela","olla","sartén","cacerola"],"a":2,"k":"주방 기구 어휘","t":"감자를 튀기기 전에 프라이팬에 기름이 달궈지도록 두세요.","e":"sartén은 '프라이팬'으로 튀기거나 볶는 요리에 씁니다. freír(튀기다)와 가장 잘 어울리는 도구입니다. sartén은 스페인에서 여성 명사(la sartén)입니다.","x":["cazuela: '(얕은 질그릇) 냄비'로 주로 조림에 씁니다 ✗","olla: '(깊은) 냄비, 솥'으로 삶거나 끓이는 데 씁니다 ✗","sartén: '프라이팬'으로 정답입니다 ✓","cacerola: '냄비(손잡이 둘 달린)'로 끓이는 데 씁니다 ✗"]},{"id":"V589","q":"No deje ningún medicamento al ____ de los niños.","o":["alcance","dominio","nivel","mando"],"a":0,"k":"관용 표현","t":"어떤 약도 아이들 손이 닿는 곳에 두지 마세요.","e":"'al alcance de'는 '~의 손이 닿는 곳에'라는 표현입니다. 약 포장에 자주 쓰이는 'Manténgase fuera del alcance de los niños(어린이 손이 닿지 않는 곳에 보관하세요)'도 함께 기억하세요.","x":["alcance: 'al alcance de(~의 손이 닿는 곳에)'로 정답입니다 ✓","dominio: '지배, 영역'이라는 뜻으로 이 표현에 쓰지 않습니다 ✗","nivel: '수준, 높이'라는 뜻으로 'al nivel de'는 '~와 같은 높이에'라서 맞지 않습니다 ✗","mando: '지휘, 리모컨'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V590","q":"Es un tipo ____, por eso le tienen miedo.","o":["cauto","siniestro","reservado","afable"],"a":1,"k":"성격 형용사","t":"그는 음침한(불길한) 사람이라서 사람들이 그를 무서워한다.","e":"siniestro/a는 '불길한, 음험한, 섬뜩한'이라는 뜻입니다. 사람들이 무서워하는(le tienen miedo) 이유가 됩니다. 명사로 siniestro는 '(보험) 사고, 재해'라는 뜻도 있습니다.","x":["cauto: '신중한'이라는 뜻으로 무서워할 이유가 아닙니다 ✗","siniestro: '불길한, 섬뜩한'으로 정답입니다 ✓","reservado: '말수가 적은'이라는 뜻으로 무서워할 이유로는 약합니다 ✗","afable: '상냥한'이라는 뜻이라 반대 의미입니다 ✗"]},{"id":"V591","q":"¿En qué hospital ____ a luz a tus hijos?","o":["trajiste","diste","tuviste","pusiste"],"a":1,"k":"관용 표현","t":"너는 어느 병원에서 아이들을 낳았니?","e":"'dar a luz'는 '빛에 내주다', 즉 '출산하다'라는 표현입니다. 'dar a luz a un bebé(아기를 낳다)'처럼 씁니다. 여기서는 tú에 맞춘 단순과거 diste가 쓰였습니다.","x":["trajiste: traer는 이 관용 표현에 쓰지 않습니다 ✗","diste: 'dar a luz(출산하다)'로 정답입니다 ✓","tuviste: tener는 'tener un hijo(아이를 낳다)'로는 쓰지만 'a luz'와 쓰지 않습니다 ✗","pusiste: poner는 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"V592","q":"Cuando hago deporte prefiero usar ____, pues no me siento cómodo con las gafas.","o":["anteojos","lentes","prismáticos","lentillas"],"a":3,"k":"안경 관련 어휘","t":"운동할 때는 안경이 불편해서 콘택트렌즈를 쓰는 걸 더 좋아한다.","e":"lentilla는 스페인에서 '콘택트렌즈'입니다. 중남미에서는 'lentes de contacto' 또는 'pupilentes'(멕시코)라고 합니다. 안경(gafas)이 불편하다는 대안이므로 정답입니다.","x":["anteojos: '안경'(주로 중남미)이라 안경 대신 쓸 대안이 아닙니다 ✗","lentes: 중남미에서 '안경'을 뜻하는 경우가 많아 gafas와 같은 뜻이 됩니다 ✗","prismáticos: '쌍안경'이라 운동할 때 쓰지 않습니다 ✗","lentillas: '콘택트렌즈'로 정답입니다 ✓"]},{"id":"V593","q":"Cualquier comportamiento ____ debería ser denunciado.","o":["apropiado","justo","lógico","discriminatorio"],"a":3,"k":"사회 문제 형용사","t":"어떤 차별적인 행동이든 신고되어야 한다.","e":"discriminatorio/a는 '차별적인'이라는 뜻입니다. denunciar(고발하다, 신고하다)의 대상이 되려면 부정적인 행동이어야 하므로 정답입니다. 명사는 discriminación(차별)입니다.","x":["apropiado: '적절한'이라는 뜻이라 신고할 이유가 없습니다 ✗","justo: '공정한'이라는 뜻이라 신고할 이유가 없습니다 ✗","lógico: '논리적인'이라는 뜻이라 신고할 이유가 없습니다 ✗","discriminatorio: '차별적인'으로 정답입니다 ✓"]},{"id":"V594","q":"El líquido que circula por las plantas se llama ____.","o":["savia","sabía","sabia","savía"],"a":0,"k":"철자 구별","t":"식물 속을 흐르는 액체를 수액이라고 한다.","e":"savia(v로 씀)는 식물의 '수액'입니다. 발음이 같은 단어들과 철자를 구별해야 하는 문제입니다. sabia는 '현명한 여자', sabía는 saber의 불완료 과거형(알고 있었다)입니다.","x":["savia: '(식물의) 수액'으로 정답입니다 ✓","sabía: saber의 불완료 과거형 '알고 있었다'라서 맞지 않습니다 ✗","sabia: '현명한(여성형)/현자'라서 맞지 않습니다 ✗","savía: 악센트가 잘못된 존재하지 않는 형태입니다 ✗"]},{"id":"V595","q":"No tengo ningún ____ porque no creo en la magia.","o":["ídolo","talismán","objeto","adorno"],"a":1,"k":"미신 관련 어휘","t":"나는 마법을 믿지 않아서 부적이 하나도 없다.","e":"talismán은 행운이나 보호를 가져다준다고 믿는 '부적'입니다. 마법(magia)을 믿지 않는다는 이유와 연결됩니다. 비슷한 말: amuleto(부적).","x":["ídolo: '우상'이라는 뜻으로 마법과 직접 연결되지 않습니다 ✗","talismán: '부적'으로 정답입니다 ✓","objeto: '물건'이라는 일반적인 말이라 마법과 연결되지 않습니다 ✗","adorno: '장식품'이라 마법과 무관합니다 ✗"]},{"id":"V596","q":"Solicité una beca, pero desgraciadamente no me la ____.","o":["negaron","denegaron","concedieron","quitaron"],"a":2,"k":"승인 관련 동사","t":"장학금을 신청했지만 안타깝게도 받지 못했다(승인해 주지 않았다).","e":"conceder는 '(허가·장학금·상 등을) 주다, 승인하다'라는 뜻입니다. 'no me la concedieron'은 '나에게 그것을 주지 않았다'는 뜻으로 desgraciadamente(안타깝게도)와 맞습니다. me는 간접목적격, la는 직접목적격(la beca)입니다.","x":["negaron: 'no me la negaron'은 '거절하지 않았다'가 되어 안타깝다는 말과 모순됩니다 ✗","denegaron: 'no me la denegaron'은 '거부하지 않았다'가 되어 모순됩니다 ✗","concedieron: 'no me la concedieron(승인해 주지 않았다)'로 정답입니다 ✓","quitaron: 'no me la quitaron'은 '빼앗지 않았다'라서 문맥과 맞지 않습니다 ✗"]},{"id":"V597","q":"Entre Alba e Inés hay un ____ muy especial. Son amigas desde la primaria.","o":["enlace","vínculo","nudo","parentesco"],"a":1,"k":"인간관계 어휘","t":"알바와 이네스 사이에는 아주 특별한 유대감이 있다. 초등학교 때부터 친구다.","e":"vínculo는 '유대, 연결고리'라는 뜻으로 사람 사이의 정서적 관계를 말할 때 씁니다. 'un vínculo muy especial'은 '아주 특별한 유대'입니다. 친구 사이이므로 친척 관계(parentesco)가 아닌 vínculo가 맞습니다.","x":["enlace: '연결, 결혼식'이라는 뜻으로 우정을 표현하기에 어색합니다 ✗","vínculo: '유대'로 정답입니다 ✓","nudo: '매듭'이라는 뜻이라 맞지 않습니다 ✗","parentesco: '친척 관계'라서 친구 사이에 맞지 않습니다 ✗"]},{"id":"V598","q":"Martín está ____, por eso anda pidiéndole dinero a todo el mundo.","o":["endeudado","acomplejado","enfadado","irritado"],"a":0,"k":"금전 상태 형용사","t":"마르틴은 빚을 지고 있어서 모든 사람에게 돈을 빌리러 다닌다.","e":"endeudado/a는 deuda(빚)에서 나온 말로 '빚을 진'이라는 뜻입니다. 돈을 빌리러 다니는 이유가 됩니다. 'andar + 현재분사'는 '~하며 돌아다니다, 계속 ~하다'라는 표현입니다.","x":["endeudado: '빚을 진'으로 정답입니다 ✓","acomplejado: '열등감이 있는'이라는 뜻이라 돈과 무관합니다 ✗","enfadado: '화난'이라는 뜻이라 돈을 빌리는 이유가 되지 않습니다 ✗","irritado: '짜증 난'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V599","q":"____ al ver al pobre animal herido.","o":["Me fatigué","Me conformé","Me restablecí","Me estremecí"],"a":3,"k":"감정 반응 동사","t":"그 불쌍한 다친 동물을 보고 나는 몸서리쳤다(가슴이 떨렸다).","e":"estremecerse는 '(두려움·감동·슬픔으로) 몸을 떨다, 전율하다'라는 뜻입니다. 다친 동물을 보고 느끼는 강한 감정 반응에 맞습니다. 'al + 동사원형'은 '~할 때'라는 뜻입니다.","x":["Me fatigué: '피곤해졌다'라는 뜻으로 감정 반응이 아닙니다 ✗","Me conformé: '만족했다, 체념했다'라는 뜻이라 맞지 않습니다 ✗","Me restablecí: '회복했다'라는 뜻이라 맞지 않습니다 ✗","Me estremecí: '몸서리쳤다'로 정답입니다 ✓"]},{"id":"V600","q":"Es un placer escucharte hablar, te expresas con mucha ____.","o":["elocuencia","pedantería","frialdad","afectación"],"a":0,"k":"말하기 능력 어휘","t":"네가 말하는 걸 듣는 건 즐거워. 아주 유창하고 설득력 있게 말하거든.","e":"elocuencia는 '웅변, 유창하고 설득력 있는 말솜씨'입니다. 'Es un placer escucharte(네 말을 듣는 건 즐거움이다)'라는 칭찬과 맞습니다. 형용사형은 elocuente(말을 잘하는)입니다.","x":["elocuencia: '유창한 말솜씨'로 정답입니다 ✓","pedantería: '현학적 태도(아는 체)'라는 부정적 뜻이라 칭찬과 맞지 않습니다 ✗","frialdad: '냉담함'이라는 뜻이라 칭찬과 맞지 않습니다 ✗","afectación: '꾸밈, 가식'이라는 부정적 뜻이라 맞지 않습니다 ✗"]},{"id":"V601","q":"Le gusta la geografía, por eso tiene tantos mapas y ____ terráqueos.","o":["círculos","esféricos","balones","globos"],"a":3,"k":"globo terráqueo","t":"그는 지리를 좋아해서 지도와 지구본을 그렇게 많이 가지고 있다.","e":"'globo terráqueo'는 '지구본'을 뜻하는 고정 표현입니다. globo는 '공 모양의 것, 풍선, 구(球)'를 뜻하고 terráqueo는 '땅과 물로 이루어진'이라는 뜻의 형용사입니다. 복수형은 'globos terráqueos'가 됩니다. 예: Compré un globo terráqueo para mi hijo.(아들에게 지구본을 사 주었다.)","x":["círculos: '원, 동그라미'라는 뜻으로 평면 도형이라 지구본을 가리키지 않습니다 ✗","esféricos: '구형의'라는 형용사라 명사 자리에 맞지 않습니다 ✗","balones: '(축구공 같은) 공'이라는 뜻이라 지구본과 관계없습니다 ✗","globos: 'globos terráqueos(지구본)'를 이루는 단어 → 정답 ✓"]},{"id":"V602","q":"La ____ política es algo que no debería existir.","o":["colaboración","cooperación","contribución","corrupción"],"a":3,"k":"사회·정치 어휘","t":"정치 부패는 존재해서는 안 되는 것이다.","e":"'corrupción'은 '부패, 비리'라는 뜻으로 'corrupción política(정치 부패)'라는 표현으로 자주 쓰입니다. 문장 후반부의 '존재해서는 안 되는 것'이라는 부정적인 내용과 어울리는 단어는 부정적 의미를 가진 corrupción뿐입니다. 관련어: corrupto(부패한), sobornar(뇌물을 주다).","x":["colaboración: '협력, 협조'라는 긍정적 의미라 문맥과 맞지 않습니다 ✗","cooperación: '협력'이라는 뜻으로 존재하면 안 될 이유가 없습니다 ✗","contribución: '기여, 공헌, 세금'이라는 뜻이라 문맥에 어울리지 않습니다 ✗","corrupción: '부패'라는 부정적 의미로 문맥과 딱 맞음 → 정답 ✓"]},{"id":"V603","q":"Ahora tenemos una buena relación, antes nos llevábamos como el ____ y el gato.","o":["pájaro","perro","león","ratón"],"a":1,"k":"관용 표현","t":"지금은 사이가 좋지만, 예전에는 우리가 견원지간이었다.","e":"'llevarse como el perro y el gato'는 직역하면 '개와 고양이처럼 지내다'로, 서로 사이가 아주 나쁘다는 관용 표현입니다. 한국어의 '견원지간(개와 원숭이 사이)'과 비슷한 뜻입니다. llevarse bien/mal(사이가 좋다/나쁘다)과 함께 기억해 두세요.","x":["pájaro: '새'라는 뜻으로 이 관용 표현에 쓰이지 않습니다 ✗","perro: '개', 'como el perro y el gato(개와 고양이처럼)'라는 관용 표현 → 정답 ✓","león: '사자'라는 뜻으로 이 표현과 관계없습니다 ✗","ratón: '쥐'라는 뜻으로, 고양이와 쥐 표현은 'jugar al gato y al ratón(쫓고 쫓기다)'처럼 다른 의미입니다 ✗"]},{"id":"V604","q":"____ que no me llegue el dinero hasta el fin de mes.","o":["Pretendo","Procuro","Temo","Intento"],"a":2,"k":"temer + 접속법","t":"월말까지 돈이 버티지 못할까 봐 걱정이다.","e":"'Temo que...'는 '~할까 봐 두렵다/걱정이다'라는 뜻으로, 뒤에 접속법(바람·의심·감정을 나타낼 때 쓰는 동사 형태)이 옵니다. 여기서 'no me llegue el dinero'는 '돈이 (월말까지) 모자라다'라는 뜻입니다. 나머지 동사들은 '~하려고 노력하다/의도하다'라는 의미라 나쁜 일이 일어나지 않길 바라는 문맥에 어색합니다.","x":["Pretendo: '~하려고 의도하다'라는 뜻이라 돈이 모자라길 의도하는 셈이 되어 어색합니다 ✗","Procuro: '~하도록 애쓰다'라는 뜻으로 돈이 모자라도록 애쓴다는 이상한 의미가 됩니다 ✗","Temo: '~할까 봐 두렵다', 걱정을 나타내며 접속법과 함께 씀 → 정답 ✓","Intento: '~하려고 시도하다'라는 뜻으로 문맥상 맞지 않습니다 ✗"]},{"id":"V605","q":"Vamos a ____ a la casa nueva a finales de este mes.","o":["movernos","huir","mudarnos","emigrar"],"a":2,"k":"mudarse(이사하다)","t":"우리는 이번 달 말에 새 집으로 이사할 것이다.","e":"'mudarse'는 '이사하다, 거처를 옮기다'라는 뜻의 재귀동사(주어 자신에게 동작이 돌아가는 동사)입니다. 'mudarse a + 장소(~로 이사하다)' 형태로 씁니다. 명사형은 mudanza(이사)입니다. 참고로 영어 move를 떠올려 moverse를 쓰기 쉽지만, 스페인어에서 moverse는 '움직이다'일 뿐 '이사하다'의 뜻은 일반적이지 않습니다.","x":["movernos: '움직이다'라는 뜻으로 '이사하다' 의미로는 쓰지 않습니다 ✗","huir: '도망치다'라는 뜻이라 새 집으로 가는 문맥에 맞지 않습니다 ✗","mudarnos: '이사하다(mudarse)'의 nosotros 형태 → 정답 ✓","emigrar: '(다른 나라로) 이민 가다'라는 뜻이라 새 집으로의 이사에는 맞지 않습니다 ✗"]},{"id":"V606","q":"Se me ha roto la caña, así que hoy no podré ir de ____.","o":["viaje","copas","pesca","compras"],"a":2,"k":"ir de + 활동","t":"낚싯대가 부러져서 오늘은 낚시하러 갈 수 없을 것이다.","e":"'caña (de pescar)'는 '낚싯대'이므로 '낚시하러 가다'인 'ir de pesca'가 정답입니다. 'ir de + 명사'는 '~하러 가다'라는 활동 표현으로 자주 쓰입니다. 예: ir de compras(쇼핑하러 가다), ir de viaje(여행 가다). 참고로 스페인에서 caña는 '생맥주 한 잔'의 뜻도 있습니다.","x":["viaje: 'ir de viaje(여행 가다)'는 낚싯대와 관련이 없습니다 ✗","copas: 'ir de copas(술 마시러 가다)'는 낚싯대가 부러진 것과 관계없습니다 ✗","pesca: '낚시', 'ir de pesca(낚시하러 가다)' → 정답 ✓","compras: 'ir de compras(쇼핑하러 가다)'는 문맥과 맞지 않습니다 ✗"]},{"id":"V607","q":"Últimamente llevo una vida sedentaria, por eso ____.","o":["he crecido","he enflaquecido","he adelgazado","he engordado"],"a":3,"k":"체중 관련 동사","t":"요즘 앉아서만 지내는 생활을 해서 살이 쪘다.","e":"'vida sedentaria'는 '운동을 거의 하지 않고 앉아서 지내는 생활'을 뜻합니다. 그 결과로 자연스러운 것은 'engordar(살이 찌다)'입니다. 반대말은 adelgazar(살이 빠지다)이며, 'gordo(뚱뚱한)'에서 나온 동사라 기억하기 쉽습니다.","x":["he crecido: '자랐다, 성장했다'라는 뜻으로 운동 부족의 결과로 맞지 않습니다 ✗","he enflaquecido: '야위었다'라는 뜻으로 문맥과 반대입니다 ✗","he adelgazado: '살이 빠졌다'라는 뜻으로 문맥과 반대입니다 ✗","he engordado: '살이 쪘다', 운동 부족의 자연스러운 결과 → 정답 ✓"]},{"id":"V608","q":"La anorexia es un ____ de la alimentación.","o":["error","trastorno","equívoco","descuido"],"a":1,"k":"건강 어휘","t":"거식증은 섭식 장애이다.","e":"'trastorno'는 '(정신·신체의) 장애, 이상'을 뜻하는 의학 용어입니다. 'trastorno de la alimentación(섭식 장애)', 'trastorno del sueño(수면 장애)'처럼 씁니다. 나머지 보기는 '실수, 부주의'라는 일반적인 뜻이라 질병을 가리키지 않습니다.","x":["error: '실수, 오류'라는 뜻으로 질환을 나타내지 않습니다 ✗","trastorno: '장애, 질환', 'trastorno de la alimentación(섭식 장애)' → 정답 ✓","equívoco: '오해, 착오'라는 뜻으로 의학 용어가 아닙니다 ✗","descuido: '부주의, 소홀함'이라는 뜻이라 질병명에 쓰지 않습니다 ✗"]},{"id":"V609","q":"Manuel tiene un talento ____ para la música, desde pequeño se le daba muy bien.","o":["inexistente","adquirido","innato","aprendido"],"a":2,"k":"성격·능력 형용사","t":"마누엘은 음악에 타고난 재능이 있어서, 어릴 때부터 아주 잘했다.","e":"'innato'는 '타고난, 선천적인'이라는 뜻입니다. '어릴 때부터 잘했다'라는 내용이 재능이 배워서 생긴 것이 아니라 원래 가지고 있던 것임을 보여 줍니다. 'talento innato(타고난 재능)'는 자주 쓰는 짝꿍 표현입니다.","x":["inexistente: '존재하지 않는'이라는 뜻으로 '아주 잘했다'와 모순됩니다 ✗","adquirido: '후천적으로 얻은'이라는 뜻으로 '어릴 때부터'와 어울리지 않습니다 ✗","innato: '타고난, 선천적인' → 정답 ✓","aprendido: '배운'이라는 뜻으로 선천적 재능 문맥과 반대입니다 ✗"]},{"id":"V610","q":"La enfermera me pidió que ____ de cintura para arriba para la prueba.","o":["me calzara","me descalzara","me desnudara","me desabrigara"],"a":2,"k":"옷 관련 동사","t":"간호사는 검사를 위해 나에게 상반신을 벗으라고 했다.","e":"'desnudarse'는 '옷을 벗다'라는 뜻이며, 'de cintura para arriba(허리 위로)'와 함께 '상반신을 벗다'가 됩니다. pidió que 뒤에는 접속법 과거(me desnudara)가 왔습니다. 반대말은 vestirse(옷을 입다)입니다.","x":["me calzara: '신발을 신다(calzarse)'라는 뜻이라 상반신과 맞지 않습니다 ✗","me descalzara: '신발을 벗다'라는 뜻으로 허리 위와 관계없습니다 ✗","me desnudara: '옷을 벗다', 'de cintura para arriba'와 함께 상반신 탈의 → 정답 ✓","me desabrigara: '외투 등 따뜻한 옷을 벗다'라는 뜻으로 검사를 위한 탈의로는 부족합니다 ✗"]},{"id":"V611","q":"Los precios de algunos productos ____ en los últimos meses. ¿Así cómo puedo ahorrar?","o":["han bajado","han disminuido","se han disparado","se han reducido"],"a":2,"k":"가격 변동 표현","t":"몇몇 제품의 가격이 최근 몇 달 동안 치솟았다. 이래서야 어떻게 돈을 모을 수 있겠는가?","e":"'dispararse'는 원래 '발사되다'라는 뜻이지만 가격이나 수치가 '급등하다, 치솟다'라는 의미로 자주 쓰입니다. 뒤 문장 '어떻게 저축하겠어?'라는 불평이 가격 상승을 암시합니다. 예: Se ha disparado el precio de la gasolina.(휘발유 가격이 치솟았다.)","x":["han bajado: '내렸다'라는 뜻으로 저축 걱정과 맞지 않습니다 ✗","han disminuido: '감소했다'라는 뜻으로 문맥과 반대입니다 ✗","se han disparado: '치솟았다, 급등했다' → 정답 ✓","se han reducido: '줄었다'라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V612","q":"Los ____ decidirán con su papeleta el resultado de las elecciones.","o":["aficionados","simpatizantes","admiradores","votantes"],"a":3,"k":"선거 어휘","t":"유권자들이 투표용지로 선거 결과를 결정할 것이다.","e":"'votante'는 '투표하는 사람, 유권자'라는 뜻입니다. 'papeleta'는 '투표용지'를 가리키므로 선거에서 결과를 결정하는 사람은 votantes입니다. 관련어: votar(투표하다), voto(표), urna(투표함).","x":["aficionados: '(스포츠 등의) 팬, 애호가'라는 뜻으로 선거와 관련이 없습니다 ✗","simpatizantes: '지지자, 동조자'라는 뜻이지만 투표로 결과를 정하는 주체는 아닙니다 ✗","admiradores: '숭배자, 팬'이라는 뜻으로 문맥과 맞지 않습니다 ✗","votantes: '유권자, 투표자' → 정답 ✓"]},{"id":"V613","q":"Es normal que no vaya bien en los estudios si se va de ____ cada noche.","o":["juerga","compras","acampada","viaje"],"a":0,"k":"ir de juerga","t":"매일 밤 놀러 나가서 진탕 논다면 공부를 잘 못하는 게 당연하다.","e":"'ir(se) de juerga'는 '(밤에) 신나게 놀러 나가다, 흥청망청 놀다'라는 구어 표현입니다. 매일 밤 하는 행동이고 공부에 방해가 되는 것이므로 juerga가 가장 자연스럽습니다. 비슷한 표현: salir de fiesta(파티하러 나가다), ir de marcha(놀러 가다, 스페인).","x":["juerga: '흥청망청 놀기', 'irse de juerga(밤새 놀러 나가다)' → 정답 ✓","compras: 'ir de compras(쇼핑)'는 매일 밤 하는 일로 어색합니다 ✗","acampada: 'ir de acampada(캠핑 가다)'는 매일 밤 하는 일이 아닙니다 ✗","viaje: 'irse de viaje(여행 가다)'는 매일 밤 반복할 수 없습니다 ✗"]},{"id":"V614","q":"Para poder ____ a estas instalaciones necesitan una autorización.","o":["acceder","dirigirse","llegar","asomarse"],"a":0,"k":"acceder a","t":"이 시설에 출입하려면 허가가 필요합니다.","e":"'acceder a'는 '~에 접근하다, 들어가다'라는 뜻으로, 출입 허가(autorización)와 함께 자주 쓰입니다. 명사형은 acceso(접근, 출입)입니다. llegar(도착하다)는 허가와 상관없이 쓸 수 있는 일반 동사라 문맥상 acceder가 가장 정확합니다.","x":["acceder: '접근하다, 출입하다', 허가와 어울리는 동사 → 정답 ✓","dirigirse: '~로 향하다'라는 뜻으로 출입 허가와 어울리지 않습니다 ✗","llegar: '도착하다'라는 뜻으로 출입 허가의 문맥에는 덜 맞습니다 ✗","asomarse: '(창문 등으로) 내다보다, 얼굴을 내밀다'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"V615","q":"Alfonso es el vivo ____ de su padre, son idénticos.","o":["retrato","cuadro","marco","lienzo"],"a":0,"k":"관용 표현","t":"알폰소는 아버지를 쏙 빼닮았다. 둘이 똑같다.","e":"'ser el vivo retrato de alguien'은 직역하면 '누구의 살아 있는 초상화이다'로 '~를 쏙 빼닮다'라는 관용 표현입니다. retrato는 '초상화, 인물 사진'이라는 뜻입니다. 비슷한 표현: ser clavado a alguien(누구와 판박이다).","x":["retrato: '초상화', 'el vivo retrato de(~를 쏙 빼닮은 사람)' → 정답 ✓","cuadro: '그림, 액자 그림'이라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","marco: '액자 틀'이라는 뜻이라 맞지 않습니다 ✗","lienzo: '캔버스, 화폭'이라는 뜻으로 이 표현과 관계없습니다 ✗"]},{"id":"V616","q":"Estoy perdiendo mucho pelo últimamente, por eso estoy siguiendo un tratamiento ____.","o":["bucal","facial","fisioterapéutico","capilar"],"a":3,"k":"신체 관련 형용사","t":"요즘 머리카락이 많이 빠져서 두피·모발 치료를 받고 있다.","e":"'capilar'는 '머리카락의, 모발의'라는 뜻의 형용사입니다. 'tratamiento capilar(모발 치료)', 'loción capilar(헤어 로션)'처럼 씁니다. 라틴어 capillus(머리카락)에서 왔으며, 의학적으로는 '모세혈관의'라는 뜻도 있습니다.","x":["bucal: '입의, 구강의'라는 뜻이라 탈모와 관계없습니다 ✗","facial: '얼굴의'라는 뜻이라 머리카락 치료가 아닙니다 ✗","fisioterapéutico: '물리치료의'라는 뜻으로 탈모 치료와 맞지 않습니다 ✗","capilar: '모발의', 'tratamiento capilar(모발 치료)' → 정답 ✓"]},{"id":"V617","q":"Prefiero pagar el gimnasio una vez al año, por eso opto por la cuota ____.","o":["anual","mensual","semanal","quincenal"],"a":0,"k":"기간 형용사","t":"나는 헬스장 회비를 1년에 한 번 내는 게 더 좋아서 연간 회비를 선택한다.","e":"'anual'은 '1년의, 매년의'라는 뜻으로 año(해, 년)에서 나왔습니다. 'una vez al año(1년에 한 번)'라는 표현과 연결됩니다. 'cuota'는 '회비, 할당액'이라는 뜻입니다. 기간 형용사를 함께 정리해 두세요: semanal(주간), quincenal(2주마다), mensual(월간), anual(연간).","x":["anual: '연간의', 1년에 한 번 내는 회비 → 정답 ✓","mensual: '매달의'라는 뜻으로 1년에 한 번과 맞지 않습니다 ✗","semanal: '매주의'라는 뜻으로 문맥과 맞지 않습니다 ✗","quincenal: '보름마다의'라는 뜻으로 문맥과 맞지 않습니다 ✗"]},{"id":"V618","q":"Ahora estamos pasando una crisis financiera; en cambio, hace años aquí se vivía una época de ____.","o":["carencia","penuria","pobreza","prosperidad"],"a":3,"k":"반의어 대조","t":"지금 우리는 금융 위기를 겪고 있지만, 반대로 몇 년 전 이곳은 번영의 시기였다.","e":"'en cambio(반면에)'는 앞뒤 내용이 대조됨을 알려 줍니다. 앞에서 'crisis(위기)'를 말했으므로 뒤에는 반대 의미인 'prosperidad(번영, 번창)'가 와야 합니다. 형용사형은 próspero(번창하는)입니다.","x":["carencia: '결핍, 부족'이라는 뜻으로 위기와 대조되지 않습니다 ✗","penuria: '궁핍, 빈곤'이라는 뜻으로 대조가 되지 않습니다 ✗","pobreza: '가난'이라는 뜻이라 위기와 같은 방향입니다 ✗","prosperidad: '번영', 위기와 대조되는 의미 → 정답 ✓"]},{"id":"V619","q":"Marta se quedó ____ siendo tan solo una cría. Sus padres murieron en un accidente.","o":["acompañada","soltera","viuda","huérfana"],"a":3,"k":"가족 상태 어휘","t":"마르타는 아주 어린아이였을 때 고아가 되었다. 그녀의 부모님은 사고로 돌아가셨다.","e":"'huérfano/a'는 '고아'라는 뜻으로 부모를 잃은 아이를 가리킵니다. 'quedarse + 형용사'는 '~한 상태가 되다'라는 뜻입니다. 'cría'는 원래 '동물의 새끼'이지만 스페인 구어에서 '어린아이'를 뜻하기도 합니다. 배우자를 잃으면 viudo/a(홀아비/과부)입니다.","x":["acompañada: '동반된, 함께 있는'이라는 뜻으로 부모의 죽음과 맞지 않습니다 ✗","soltera: '미혼의'라는 뜻으로 어린아이와 부모의 죽음과 관계없습니다 ✗","viuda: '배우자를 잃은 여자'라는 뜻으로 부모를 잃은 경우가 아닙니다 ✗","huérfana: '고아(여)', 부모를 잃은 아이 → 정답 ✓"]},{"id":"V620","q":"No es nada ____, siempre ha luchado por conseguir sus objetivos.","o":["maniático","valiente","conformista","machista"],"a":2,"k":"성격 형용사","t":"그는 전혀 현실에 안주하는 사람이 아니다. 늘 목표를 이루기 위해 노력해 왔다.","e":"'conformista'는 '현실에 안주하는, 순응적인 (사람)'이라는 뜻입니다. 'No es nada ~(전혀 ~하지 않다)'와 뒤의 '항상 목표를 위해 싸워 왔다'가 자연스럽게 이어지려면, 노력과 반대되는 성격인 conformista가 와야 합니다. 동사 conformarse con(~에 만족하다)과 연결해 기억하세요.","x":["maniático: '괴벽스러운, 까다로운'이라는 뜻으로 노력과 대조되지 않습니다 ✗","valiente: '용감한'이라는 뜻이라 부정하면 뒤 문장과 어울리지 않습니다 ✗","conformista: '현실에 안주하는', 노력하는 모습과 대조 → 정답 ✓","machista: '남성 우월주의적인'이라는 뜻으로 문맥과 관계없습니다 ✗"]},{"id":"V621","q":"Para entender el texto detalladamente, lo ____ párrafo a párrafo.","o":["analizaremos","rectificaremos","combinaremos","compondremos"],"a":0,"k":"학습 관련 동사","t":"텍스트를 자세히 이해하기 위해 한 단락씩 분석할 것이다.","e":"'analizar'는 '분석하다'라는 뜻으로, 텍스트를 자세히 이해하는 목적과 잘 어울립니다. 'párrafo a párrafo(한 단락씩)'처럼 '명사 + a + 명사'는 '하나씩 차례로'라는 뜻입니다. 예: paso a paso(한 걸음씩).","x":["analizaremos: '분석할 것이다', 이해를 위한 행동 → 정답 ✓","rectificaremos: '수정할 것이다'라는 뜻으로 이해하는 목적과 맞지 않습니다 ✗","combinaremos: '조합할 것이다'라는 뜻으로 문맥과 맞지 않습니다 ✗","compondremos: '작성하다, 구성하다'라는 뜻으로 이미 있는 텍스트를 이해하는 것과 다릅니다 ✗"]},{"id":"V622","q":"En el cartón del zumo dice que hay que ____ antes de usarlo.","o":["moverlo","removerlo","agitarlo","sacudirlo"],"a":2,"k":"agitar(흔들다)","t":"주스 팩에 사용 전에 흔들어야 한다고 쓰여 있다.","e":"'agitar'는 '(액체 용기를) 흔들다'라는 뜻으로, 제품 설명서의 'Agítese antes de usar(사용 전에 흔드세요)'라는 표현에 자주 나옵니다. zumo는 스페인에서 '주스'이며 중남미에서는 jugo라고 합니다. sacudir는 먼지를 털 때처럼 세게 흔드는 동작에 주로 씁니다.","x":["moverlo: '움직이다'라는 일반적인 뜻으로 이 문맥에서는 부자연스럽습니다 ✗","removerlo: '(숟가락 등으로) 휘젓다'라는 뜻으로 팩 상태의 주스에는 맞지 않습니다 ✗","agitarlo: '흔들다', 용기 사용 설명에 쓰는 표준 표현 → 정답 ✓","sacudirlo: '털다, 세게 흔들다'라는 뜻으로 주로 먼지 터는 동작에 씁니다 ✗"]},{"id":"V623","q":"Cuando el calor aprieta es mejor llevar ropa ____.","o":["formal","de abrigo","ligera","oscura"],"a":2,"k":"의복 형용사","t":"더위가 심할 때는 가벼운 옷을 입는 것이 좋다.","e":"'ropa ligera'는 '가벼운 옷, 얇은 옷'이라는 뜻입니다. 'cuando el calor aprieta'는 '더위가 기승을 부릴 때'라는 표현으로, apretar는 원래 '조이다'이지만 날씨에 쓰면 '심해지다'라는 뜻이 됩니다. 반대 표현은 'ropa de abrigo(방한복)'입니다.","x":["formal: '격식 있는'이라는 뜻으로 더위와 관련이 없습니다 ✗","de abrigo: '방한용의'라는 뜻으로 더위와 반대입니다 ✗","ligera: '가벼운, 얇은', 더위에 알맞은 옷 → 정답 ✓","oscura: '어두운 색의'라는 뜻으로 오히려 열을 흡수해 덥습니다 ✗"]},{"id":"V624","q":"Necesitamos más papel para ____ los regalos de los niños.","o":["revolver","envolver","desenvolver","devolver"],"a":1,"k":"-volver 계열 동사","t":"아이들 선물을 포장하려면 종이가 더 필요하다.","e":"'envolver'는 '싸다, 포장하다'라는 뜻입니다. 'papel de regalo(포장지)'로 선물을 싸는 상황에 딱 맞습니다. -volver로 끝나는 동사들은 형태가 비슷해서 헷갈리기 쉬우니 함께 정리해 두세요.","x":["revolver: '휘젓다, 뒤섞다, 어지럽히다'라는 뜻으로 맞지 않습니다 ✗","envolver: '싸다, 포장하다' → 정답 ✓","desenvolver: '포장을 풀다'라는 뜻으로 반대 동작입니다 ✗","devolver: '돌려주다, 반납하다'라는 뜻으로 종이와 관계없습니다 ✗"]},{"id":"V625","q":"La nueva alumna ____ muy bien en su clase.","o":["se instaló","se integró","coincidió","se alojó"],"a":1,"k":"integrarse(적응하다)","t":"새로 온 여학생은 반에 아주 잘 적응했다.","e":"'integrarse (en)'은 '(집단에) 녹아들다, 잘 어울리다'라는 뜻입니다. 새 학생이 반 친구들과 잘 어울린다는 문맥에 가장 알맞습니다. 명사형은 integración(통합, 적응)입니다.","x":["se instaló: '자리 잡다, 정착하다(집·장소에)'라는 뜻으로 사람들과 어울리는 의미는 아닙니다 ✗","se integró: '잘 적응했다, 녹아들었다' → 정답 ✓","coincidió: '일치했다, 우연히 만났다'라는 뜻으로 'muy bien'과 어울리지 않습니다 ✗","se alojó: '묵었다, 숙박했다'라는 뜻으로 교실과 맞지 않습니다 ✗"]},{"id":"V626","q":"Este virus es muy ____, se transmite fácilmente de persona a persona.","o":["doloroso","visible","transferible","contagioso"],"a":3,"k":"질병 형용사","t":"이 바이러스는 전염성이 매우 강해서 사람 간에 쉽게 옮는다.","e":"'contagioso'는 '전염성의, 옮기 쉬운'이라는 뜻입니다. 뒤 문장 '사람에서 사람으로 쉽게 전파된다'는 설명이 그 정의와 같습니다. 관련어: contagiar(옮기다), contagio(전염).","x":["doloroso: '아픈, 고통스러운'이라는 뜻으로 전파 설명과 맞지 않습니다 ✗","visible: '눈에 보이는'이라는 뜻으로 문맥과 관계없습니다 ✗","transferible: '양도 가능한'이라는 뜻으로 주로 권리·티켓 등에 쓰고 질병에는 쓰지 않습니다 ✗","contagioso: '전염성의' → 정답 ✓"]},{"id":"V627","q":"Las moras y las ____ son frutos rojos.","o":["frambuesas","peras","papayas","piñas"],"a":0,"k":"과일 어휘","t":"블랙베리와 라즈베리는 베리류(붉은 과일)이다.","e":"'frambuesa'는 '라즈베리(산딸기)'입니다. 'frutos rojos'는 딸기·블루베리·라즈베리·블랙베리 같은 베리류를 묶어 부르는 말입니다. 'mora'는 '블랙베리, 오디'를 뜻합니다.","x":["frambuesas: '라즈베리', 대표적인 베리류 → 정답 ✓","peras: '배'라는 뜻으로 베리류가 아닙니다 ✗","papayas: '파파야'라는 뜻으로 열대 과일입니다 ✗","piñas: '파인애플'이라는 뜻으로 열대 과일입니다 ✗"]},{"id":"V628","q":"Las regiones ____ son las más visitadas en verano en los países mediterráneos.","o":["costeras","boscosas","montañosas","nevosas"],"a":0,"k":"지형 형용사","t":"지중해 국가에서는 여름에 해안 지역이 가장 많이 방문된다.","e":"'costero'는 '해안의'라는 뜻으로 costa(해안)에서 나왔습니다. 여름 휴가철에 사람들이 바다로 몰리므로 'regiones costeras(해안 지역)'가 정답입니다. 다른 지형 형용사: montañoso(산이 많은), boscoso(숲이 우거진).","x":["costeras: '해안의', 여름에 붐비는 바닷가 지역 → 정답 ✓","boscosas: '숲이 많은'이라는 뜻으로 여름 관광의 대표 지역은 아닙니다 ✗","montañosas: '산이 많은'이라는 뜻으로 지중해 여름 관광과 덜 맞습니다 ✗","nevosas: '눈이 많은'이라는 뜻으로 여름과 맞지 않습니다 ✗"]},{"id":"V629","q":"La sala está ____. ¿Dónde están todos?","o":["vacía","repleta","abarrotada","completa"],"a":0,"k":"상태 형용사","t":"홀이 텅 비어 있네. 다들 어디 있지?","e":"'vacío/a'는 '비어 있는'이라는 뜻입니다. '모두 어디 있지?'라는 질문은 사람이 아무도 없다는 뜻이므로 vacía가 맞습니다. 나머지 보기는 모두 '가득 찬'이라는 반대 의미입니다.","x":["vacía: '비어 있는', 아무도 없는 상황 → 정답 ✓","repleta: '가득 찬'이라는 뜻으로 문맥과 반대입니다 ✗","abarrotada: '꽉 들어찬, 붐비는'이라는 뜻으로 반대입니다 ✗","completa: '꽉 찬, 만석인'이라는 뜻으로 반대입니다 ✗"]},{"id":"V630","q":"Al público le gustó tanto la obra que no dejaba de ____.","o":["silbar","aplaudir","abuchear","patalear"],"a":1,"k":"공연 반응 동사","t":"관객들은 그 공연이 너무 마음에 들어서 박수를 멈추지 않았다.","e":"'aplaudir'는 '박수를 치다'라는 뜻으로 공연이 좋을 때 하는 반응입니다. 'no dejar de + 동사원형'은 '계속 ~하다, ~하기를 멈추지 않다'라는 표현입니다. 공연이 싫을 때는 abuchear(야유하다)를 씁니다.","x":["silbar: '휘파람을 불다'라는 뜻으로 스페인에서는 공연장에서 야유의 표현이기도 합니다 ✗","aplaudir: '박수를 치다', 마음에 들었을 때의 반응 → 정답 ✓","abuchear: '야유하다'라는 뜻으로 문맥과 반대입니다 ✗","patalear: '발을 구르다, 발버둥 치다'라는 뜻으로 주로 화내거나 떼쓸 때 씁니다 ✗"]},{"id":"V631","q":"Esta carne está ____, no la han cocinado el tiempo suficiente.","o":["quemada","jugosa","hecha","cruda"],"a":3,"k":"고기 익힘 정도","t":"이 고기는 덜 익었다. 충분히 오래 조리하지 않았다.","e":"'crudo/a'는 '날것의, 덜 익은'이라는 뜻입니다. 뒤 문장 '충분한 시간 동안 익히지 않았다'가 그 이유를 설명합니다. 고기 익힘 정도 표현: poco hecha(레어), en su punto(미디엄), muy hecha(웰던).","x":["quemada: '탄'이라는 뜻으로 너무 오래 익혔을 때 씁니다 ✗","jugosa: '육즙이 많은'이라는 뜻으로 덜 익었다는 설명과 맞지 않습니다 ✗","hecha: '익은'이라는 뜻으로 문맥과 반대입니다 ✗","cruda: '날것의, 덜 익은' → 정답 ✓"]},{"id":"V632","q":"Hoy voy a cenar comida ____ porque estoy demasiado cansado para cocinar.","o":["guisada","aderezada","horneada","precocinada"],"a":3,"k":"음식 조리 어휘","t":"오늘은 요리하기에 너무 피곤해서 즉석 조리 식품으로 저녁을 먹을 것이다.","e":"'precocinado/a'는 '미리 조리된, 데우기만 하면 되는'이라는 뜻입니다. 'comida precocinada'는 전자레인지 등으로 데워 먹는 즉석 식품을 가리킵니다. 요리할 기운이 없을 때 고르는 음식이므로 정답입니다.","x":["guisada: '스튜처럼 끓인'이라는 뜻으로 직접 요리해야 합니다 ✗","aderezada: '양념한, 드레싱을 뿌린'이라는 뜻으로 피곤함과 관계없습니다 ✗","horneada: '오븐에 구운'이라는 뜻으로 직접 조리가 필요합니다 ✗","precocinada: '미리 조리된', 데우기만 하면 되는 음식 → 정답 ✓"]},{"id":"V633","q":"Esta niña es una ____, no para de pedir cosas.","o":["soñadora","caprichosa","egocéntrica","idealista"],"a":1,"k":"성격 어휘","t":"이 여자아이는 변덕쟁이야. 계속 이것저것 사 달라고 해.","e":"'caprichoso/a'는 '변덕스러운, 제멋대로 원하는 것을 조르는'이라는 뜻입니다. capricho(변덕, 갖고 싶은 것)에서 나온 말로, 계속 무언가를 요구하는 아이를 묘사할 때 잘 어울립니다. 예: darse un capricho(자신에게 작은 사치를 부리다).","x":["soñadora: '몽상가'라는 뜻으로 물건을 조르는 것과 관계없습니다 ✗","caprichosa: '변덕쟁이, 이것저것 조르는 사람' → 정답 ✓","egocéntrica: '자기중심적인 사람'이라는 뜻이지만 계속 요구한다는 핵심과는 덜 맞습니다 ✗","idealista: '이상주의자'라는 뜻으로 문맥과 맞지 않습니다 ✗"]},{"id":"V634","q":"¿Podrías sujetar estos documentos con una ____?","o":["mochila","tiza","grapadora","regla"],"a":2,"k":"사무용품 어휘","t":"이 서류들을 스테이플러로 고정해 줄 수 있어?","e":"'grapadora'는 '스테이플러'로, grapa(스테이플러 심)에서 나온 말입니다. 'sujetar'는 '고정하다, 붙잡다'라는 뜻이므로 서류를 묶는 도구가 필요합니다. 중남미에서는 engrapadora, corchetera(칠레)라고도 합니다.","x":["mochila: '배낭'이라는 뜻으로 서류를 고정할 수 없습니다 ✗","tiza: '분필'이라는 뜻으로 고정하는 도구가 아닙니다 ✗","grapadora: '스테이플러', 서류를 고정하는 도구 → 정답 ✓","regla: '자'라는 뜻으로 고정 도구가 아닙니다 ✗"]},{"id":"V635","q":"Otra forma de llamar al paso de ____ es paso de cebra.","o":["peregrinos","peatones","viajeros","pasajeros"],"a":1,"k":"교통 어휘","t":"횡단보도를 부르는 다른 말은 '얼룩말 길(paso de cebra)'이다.","e":"'paso de peatones'는 '보행자 통로', 즉 '횡단보도'입니다. 'peatón'은 '보행자'라는 뜻입니다. 흰 줄무늬가 얼룩말(cebra)처럼 보여 'paso de cebra'라고도 부릅니다.","x":["peregrinos: '순례자'라는 뜻으로 횡단보도와 관계없습니다 ✗","peatones: '보행자', 'paso de peatones(횡단보도)' → 정답 ✓","viajeros: '여행자'라는 뜻으로 이 표현에 쓰지 않습니다 ✗","pasajeros: '승객'이라는 뜻으로 이 표현에 쓰지 않습니다 ✗"]},{"id":"V636","q":"No deberías acusar a nadie de un ____ sin tener ni una sola prueba.","o":["dato","detalle","delito","don"],"a":2,"k":"법률 어휘","t":"단 하나의 증거도 없이 누군가를 범죄로 고발해서는 안 된다.","e":"'delito'는 '범죄, 위법 행위'라는 뜻입니다. 'acusar a alguien de un delito(누군가를 범죄 혐의로 고발하다)'는 자주 쓰는 표현이며 'prueba(증거)'와도 잘 어울립니다. 관련어: delincuente(범죄자).","x":["dato: '자료, 데이터'라는 뜻으로 고발 대상이 될 수 없습니다 ✗","detalle: '세부 사항'이라는 뜻으로 문맥과 맞지 않습니다 ✗","delito: '범죄', acusar de와 함께 쓰는 단어 → 정답 ✓","don: '재능, 선물'이라는 뜻으로 고발과 관계없습니다 ✗"]},{"id":"V637","q":"El pan de muerto es propio de la ____ mexicana.","o":["música","gastronomía","danza","alfarería"],"a":1,"k":"문화 어휘","t":"'죽은 자의 빵'은 멕시코 음식 문화 특유의 것이다.","e":"'pan de muerto'는 멕시코 '망자의 날(Día de Muertos)'에 먹는 전통 빵입니다. 빵은 음식이므로 'gastronomía(요리, 음식 문화)'가 맞습니다. 'ser propio de'는 '~에 고유한, ~ 특유의'라는 뜻입니다.","x":["música: '음악'이라는 뜻으로 빵과 관련이 없습니다 ✗","gastronomía: '음식 문화, 미식', 빵은 음식이므로 → 정답 ✓","danza: '춤'이라는 뜻으로 빵과 관련이 없습니다 ✗","alfarería: '도자기 공예'라는 뜻으로 빵과 관련이 없습니다 ✗"]},{"id":"V638","q":"Los españoles suelen comer ____ en Navidad.","o":["paella","turrón","mole","gazpacho"],"a":1,"k":"스페인 음식 문화","t":"스페인 사람들은 크리스마스에 보통 투론을 먹는다.","e":"'turrón'은 아몬드, 꿀, 설탕 등으로 만든 스페인의 전통 과자로, 크리스마스 시즌의 대표 디저트입니다. 'soler + 동사원형'은 '보통 ~하다'라는 습관 표현입니다. 다른 보기들도 유명한 음식이지만 크리스마스와 연결되지는 않습니다.","x":["paella: '파에야(쌀 요리)'로 크리스마스 특정 음식은 아닙니다 ✗","turrón: '투론', 크리스마스 대표 과자 → 정답 ✓","mole: '몰레'는 멕시코 소스 요리로 스페인 음식이 아닙니다 ✗","gazpacho: '가스파초(차가운 토마토 수프)'로 여름 음식입니다 ✗"]},{"id":"V639","q":"La gente astuta te engaña porque eres demasiado ____.","o":["incrédula","suspicaz","precavida","confiada"],"a":3,"k":"성격 형용사","t":"교활한 사람들이 너를 속이는 건 네가 너무 남을 잘 믿기 때문이다.","e":"'confiado/a'는 '(남을) 쉽게 믿는, 경계심이 없는'이라는 뜻입니다. 속는 이유를 설명해야 하므로 잘 믿는 성격이 자연스럽습니다. 나머지 보기는 모두 '의심 많은, 조심스러운'이라는 반대 의미라 속지 않을 성격입니다.","x":["incrédula: '잘 믿지 않는'이라는 뜻으로 속는 이유가 될 수 없습니다 ✗","suspicaz: '의심 많은'이라는 뜻으로 문맥과 반대입니다 ✗","precavida: '조심성 있는'이라는 뜻으로 문맥과 반대입니다 ✗","confiada: '쉽게 믿는', 속는 이유 → 정답 ✓"]},{"id":"V640","q":"Mozart sigue siendo uno de los principales ____ de la historia musical.","o":["poetas","compositores","dramaturgos","literatos"],"a":1,"k":"예술 직업 어휘","t":"모차르트는 여전히 음악사에서 가장 중요한 작곡가 중 한 명이다.","e":"'compositor/a'는 '작곡가'로, componer(작곡하다, 구성하다)에서 나온 말입니다. 모차르트는 음악가이므로 compositores가 맞습니다. 'seguir + 현재분사'는 '여전히 ~하다'라는 뜻입니다.","x":["poetas: '시인'이라는 뜻으로 음악가가 아닙니다 ✗","compositores: '작곡가' → 정답 ✓","dramaturgos: '극작가'라는 뜻으로 음악가가 아닙니다 ✗","literatos: '문인, 작가'라는 뜻으로 음악가가 아닙니다 ✗"]},{"id":"V641","q":"Los fines de semana me gusta salir con mi ____. Me encanta estar con mis amigos.","o":["comunidad","pandilla","partido","agrupación"],"a":1,"k":"친구 집단 어휘","t":"주말마다 나는 친구 무리와 놀러 나가는 걸 좋아한다. 친구들과 함께 있는 게 정말 좋다.","e":"'pandilla'는 '(친구들의) 무리, 패거리'라는 뜻의 구어 표현입니다. 뒤 문장 '친구들과 있는 게 좋다'가 힌트입니다. 비슷한 말: grupo de amigos. 중남미에서는 'barra'(아르헨티나), 'parche'(콜롬비아) 등 지역어도 쓰입니다.","x":["comunidad: '공동체, 지역 사회'라는 뜻으로 친구 무리에 쓰기 어색합니다 ✗","pandilla: '친구 무리' → 정답 ✓","partido: '정당, 경기'라는 뜻으로 친구 모임이 아닙니다 ✗","agrupación: '단체, 협회'라는 공식적인 말이라 친구 모임에 맞지 않습니다 ✗"]},{"id":"V642","q":"¡Qué buena ____ tiene esta torta! ¿Me pones un trozo?","o":["presencia","pinta","cara","figura"],"a":1,"k":"tener buena pinta","t":"이 케이크 정말 맛있어 보이네! 한 조각 줄래?","e":"'tener buena pinta'는 '(음식 등이) 맛있어 보이다, 보기 좋다'라는 구어 표현입니다. pinta는 '겉모습, 외관'이라는 뜻입니다. 'torta'는 중남미에서 '케이크'를 뜻하는 경우가 많고(스페인은 보통 tarta), 멕시코에서는 샌드위치를 뜻하기도 합니다.","x":["presencia: '존재감, 풍채'라는 뜻으로 주로 사람의 외모에 씁니다 ✗","pinta: '겉모습', 'tener buena pinta(맛있어 보이다)' → 정답 ✓","cara: '얼굴'이라는 뜻으로 'tener buena cara'는 주로 사람의 안색에 씁니다 ✗","figura: '모양, 몸매'라는 뜻으로 음식이 맛있어 보인다는 표현이 아닙니다 ✗"]},{"id":"V643","q":"Los pueblos ____ no viven en un sitio fijo.","o":["asentados","sedentarios","nómadas","establecidos"],"a":2,"k":"생활 방식 형용사","t":"유목민들은 고정된 곳에 살지 않는다.","e":"'nómada'는 '유목의, 떠돌아다니는'이라는 뜻으로 남성·여성 형태가 같습니다. '고정된 장소에 살지 않는다'는 설명이 nómada의 정의입니다. 반대말은 sedentario(정착 생활을 하는)입니다.","x":["asentados: '정착한'이라는 뜻으로 문맥과 반대입니다 ✗","sedentarios: '정착 생활을 하는'이라는 뜻으로 반대입니다 ✗","nómadas: '유목의', 고정된 거처가 없는 → 정답 ✓","establecidos: '자리 잡은'이라는 뜻으로 반대입니다 ✗"]},{"id":"V644","q":"Este periódico es digital, no existe en ____ impreso.","o":["sistema","método","estilo","formato"],"a":3,"k":"미디어 어휘","t":"이 신문은 디지털 신문으로, 인쇄본 형태로는 존재하지 않는다.","e":"'formato'는 '형식, 판형, 포맷'이라는 뜻입니다. 'formato impreso(인쇄 형태)', 'formato digital(디지털 형태)'처럼 매체의 형태를 나타낼 때 씁니다. 'en papel(종이로)'이라고 말하기도 합니다.","x":["sistema: '체계, 시스템'이라는 뜻으로 인쇄 형태를 나타내지 않습니다 ✗","método: '방법'이라는 뜻으로 문맥과 맞지 않습니다 ✗","estilo: '스타일, 문체'라는 뜻으로 맞지 않습니다 ✗","formato: '형태', 'formato impreso(인쇄본)' → 정답 ✓"]},{"id":"V645","q":"Mi problema de salud es ____, lo tienen mi madre y mi abuela.","o":["insólito","hereditario","curioso","sorprendente"],"a":1,"k":"건강 형용사","t":"내 건강 문제는 유전성이다. 어머니와 할머니에게도 있다.","e":"'hereditario/a'는 '유전의, 물려받은'이라는 뜻으로 herencia(유산, 유전)에서 나왔습니다. 어머니와 할머니도 같은 문제가 있다는 설명은 유전을 암시합니다. 예: una enfermedad hereditaria(유전병).","x":["insólito: '보기 드문, 이례적인'이라는 뜻으로 가족력 설명과 맞지 않습니다 ✗","hereditario: '유전성의' → 정답 ✓","curioso: '신기한, 호기심 많은'이라는 뜻으로 맞지 않습니다 ✗","sorprendente: '놀라운'이라는 뜻으로 가족력의 이유가 되지 않습니다 ✗"]},{"id":"V646","q":"Los futbolistas más famosos ganan cantidades ____ de dinero.","o":["ínfimas","insignificantes","astronómicas","irrisorias"],"a":2,"k":"양을 강조하는 형용사","t":"가장 유명한 축구 선수들은 천문학적인 액수의 돈을 번다.","e":"'astronómico/a'는 원래 '천문학의'라는 뜻이지만 '엄청나게 큰'이라는 의미로도 쓰입니다. 'cantidades astronómicas(천문학적인 액수)'는 한국어와 똑같은 비유입니다. 나머지 보기는 모두 '아주 적은'이라는 뜻이라 유명 선수의 수입과 맞지 않습니다.","x":["ínfimas: '극히 적은'이라는 뜻으로 문맥과 반대입니다 ✗","insignificantes: '하찮은, 미미한'이라는 뜻으로 반대입니다 ✗","astronómicas: '천문학적인, 엄청난' → 정답 ✓","irrisorias: '웃음거리가 될 만큼 적은'이라는 뜻으로 반대입니다 ✗"]},{"id":"V647","q":"A casi los niños les gustan las ____, pero no son nada buenas para los dientes.","o":["legumbres","verduras","golosinas","especias"],"a":2,"k":"음식 어휘","t":"거의 모든 아이들은 사탕·과자를 좋아하지만, 이것은 치아에 전혀 좋지 않다.","e":"'golosinas'는 '사탕, 젤리 같은 단 군것질거리'를 뜻합니다. 치아에 나쁘고 아이들이 좋아하는 것이므로 정답입니다. 문장의 'A casi los niños'는 'A casi todos los niños(거의 모든 아이들에게)'에서 todos가 빠진 것으로 보입니다. 중남미에서는 dulces라고도 많이 합니다.","x":["legumbres: '콩류'라는 뜻으로 치아에 나쁘지 않습니다 ✗","verduras: '채소'라는 뜻으로 치아에 나쁘지 않습니다 ✗","golosinas: '단 군것질거리', 아이들이 좋아하고 이에 나쁨 → 정답 ✓","especias: '향신료'라는 뜻으로 아이들이 좋아하는 간식이 아닙니다 ✗"],"f":"문장에 todos 누락 오타 추정(A casi todos los niños)"},{"id":"V648","q":"Cuando esté hecha la sopa, déjela ____ unos minutos antes de servirla.","o":["reposar","descansar","dormir","yacer"],"a":0,"k":"요리 동사","t":"수프가 다 되면 내기 전에 몇 분 동안 그대로 두세요.","e":"'reposar'는 요리에서 '(음식을) 그대로 두어 뜸 들이다, 숙성시키다'라는 뜻입니다. 'dejar reposar'는 레시피에 자주 나오는 표현입니다. descansar(쉬다)는 사람에게 주로 쓰고 음식에는 일반적으로 reposar를 씁니다.","x":["reposar: '(음식을) 그대로 두다', 레시피 표현 'dejar reposar' → 정답 ✓","descansar: '쉬다'라는 뜻으로 주로 사람에게 씁니다 ✗","dormir: '자다'라는 뜻으로 음식에 쓰지 않습니다 ✗","yacer: '누워 있다, 묻혀 있다'라는 문어적 표현으로 맞지 않습니다 ✗"]},{"id":"V649","q":"La ____ digital es un problema que debe abordarse adecuadamente.","o":["grieta","equidad","igualdad","brecha"],"a":3,"k":"brecha digital","t":"디지털 격차는 적절히 다루어야 할 문제이다.","e":"'brecha digital'은 '디지털 격차(정보 기술 접근의 차이)'를 뜻하는 고정 표현입니다. brecha는 원래 '틈, 균열'이라는 뜻으로 '격차'의 의미로도 쓰입니다. 예: brecha salarial(임금 격차).","x":["grieta: '갈라진 틈'이라는 물리적 균열을 뜻해 이 표현에는 쓰지 않습니다 ✗","equidad: '공평'이라는 뜻으로 문제라고 할 수 없습니다 ✗","igualdad: '평등'이라는 뜻으로 문제라고 할 수 없습니다 ✗","brecha: '격차', 'brecha digital(디지털 격차)' → 정답 ✓"]},{"id":"V650","q":"El programa ____ que veo a diario empieza a las 9 de la mañana.","o":["del mediodía","nocturno","matinal","vespertino"],"a":2,"k":"시간대 형용사","t":"내가 매일 보는 아침 프로그램은 오전 9시에 시작한다.","e":"'matinal'은 '아침의'라는 뜻으로 mañana(아침)와 관련된 말입니다. 오전 9시에 시작하므로 아침 프로그램입니다. 시간대 형용사: matinal(아침), vespertino(오후·저녁), nocturno(밤).","x":["del mediodía: '정오의'라는 뜻으로 오전 9시와 맞지 않습니다 ✗","nocturno: '밤의'라는 뜻으로 맞지 않습니다 ✗","matinal: '아침의', 오전 9시 프로그램 → 정답 ✓","vespertino: '오후·저녁의'라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V651","q":"____ de precios que estamos viviendo es consecuencia de la inestabilidad económica.","o":["La regularidad","El equilibrio","La permanencia","El vaivén"],"a":3,"k":"변동 관련 명사","t":"우리가 겪고 있는 물가의 출렁임은 경제 불안정의 결과이다.","e":"'vaivén'은 '흔들림, 오르내림, 변동'이라는 뜻입니다. 'inestabilidad económica(경제 불안정)'의 결과로 가격이 오르락내리락하는 상황이므로 el vaivén이 맞습니다. 'ir y venir(오고 가다)'가 합쳐진 말로 기억하면 쉽습니다.","x":["La regularidad: '규칙성'이라는 뜻으로 불안정과 맞지 않습니다 ✗","El equilibrio: '균형'이라는 뜻으로 불안정의 결과와 반대입니다 ✗","La permanencia: '지속, 불변'이라는 뜻으로 맞지 않습니다 ✗","El vaivén: '변동, 오르내림', 불안정의 결과 → 정답 ✓"]},{"id":"V652","q":"No soy ____ a lo que está pasando, estoy tan informado como vos.","o":["reacio","indiferente","insensible","ajeno"],"a":3,"k":"ajeno a","t":"나는 지금 일어나고 있는 일과 동떨어져 있지 않아. 나도 너만큼 잘 알고 있어.","e":"'ser ajeno a algo'는 '~와 무관하다, ~을 모르다'라는 뜻입니다. 뒤 문장 '너만큼 잘 알고 있다'와 연결되려면 '모르는 상태가 아니다'라는 의미가 필요합니다. 'vos'는 아르헨티나·우루과이 등에서 쓰는 2인칭 tú에 해당하는 대명사이며, 'tan informado como vos'는 스페인식으로는 'como tú'입니다.","x":["reacio: '꺼리는, 마지못해 하는'이라는 뜻으로 보통 'reacio a + 동사원형'이며 정보와 맞지 않습니다 ✗","indiferente: '무관심한'이라는 뜻이지만 '잘 알고 있다'는 정보 여부와 직접 대비되지 않습니다 ✗","insensible: '무감각한'이라는 뜻으로 정보와 관련이 없습니다 ✗","ajeno: '무관한, 모르는', 'informado'와 대비 → 정답 ✓"]},{"id":"V653","q":"Para la pizarra digital voy a necesitar ____ especiales.","o":["lápices","plumas","rotuladores","bolígrafos"],"a":2,"k":"필기구 어휘","t":"디지털 칠판용으로 특수 마커가 필요할 것이다.","e":"'rotulador'는 '마커, 사인펜'이라는 뜻으로, 화이트보드나 전자 칠판에 쓰는 필기구입니다. 스페인에서는 rotulador라고 하지만 중남미에서는 marcador, plumón(페루·칠레 등)이라고 합니다.","x":["lápices: '연필'이라는 뜻으로 칠판에 쓰지 않습니다 ✗","plumas: '깃털, 만년필'이라는 뜻으로 칠판용이 아닙니다(멕시코에서는 볼펜) ✗","rotuladores: '마커', 칠판용 필기구 → 정답 ✓","bolígrafos: '볼펜'이라는 뜻으로 칠판용이 아닙니다 ✗"]},{"id":"V654","q":"Al morir el padre, los hermanos se pelearon por ____ familiar.","o":["el justificante","la adjudicación","la herencia","el contrato"],"a":2,"k":"herencia(유산)","t":"아버지가 돌아가시자 형제들은 집안 유산을 두고 싸웠다.","e":"'herencia'는 '유산, 상속 재산'이라는 뜻입니다. 아버지의 죽음 후 형제들이 다투는 대상으로 가장 자연스럽습니다. 관련어: heredar(상속받다), heredero(상속인).","x":["el justificante: '증빙 서류, 증명서'라는 뜻으로 맞지 않습니다 ✗","la adjudicación: '낙찰, 배정'이라는 뜻으로 행정·법률 절차를 뜻해 어색합니다 ✗","la herencia: '유산' → 정답 ✓","el contrato: '계약'이라는 뜻으로 문맥과 맞지 않습니다 ✗"]},{"id":"V655","q":"Carolina tuvo la ____ de casarse con un hombre que no era para ella.","o":["fortuna","suerte","desgracia","dicha"],"a":2,"k":"운·불운 어휘","t":"카롤리나는 불행하게도 자신과 맞지 않는 남자와 결혼했다.","e":"'tener la desgracia de + 동사원형'은 '불행하게도 ~하다'라는 뜻입니다. '자신에게 맞지 않는 남자와의 결혼'은 불행한 일이므로 desgracia가 맞습니다. 반대로 'tener la suerte de'는 '운 좋게 ~하다'입니다.","x":["fortuna: '행운, 재산'이라는 뜻으로 문맥과 반대입니다 ✗","suerte: '행운'이라는 뜻으로 문맥과 반대입니다 ✗","desgracia: '불행', 맞지 않는 결혼 → 정답 ✓","dicha: '행복, 행운'이라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V656","q":"Suspendí el examen porque me quedé completamente en ____.","o":["blanco","negro","rojo","gris"],"a":0,"k":"관용 표현","t":"머리가 완전히 하얘져서 시험에 떨어졌다.","e":"'quedarse en blanco'는 '머리가 하얘지다, 아무것도 생각나지 않다'라는 관용 표현입니다. 한국어와 비유가 같아 기억하기 쉽습니다. 'suspender(시험에 떨어지다)'는 스페인식이고, 중남미에서는 reprobar를 많이 씁니다.","x":["blanco: 'quedarse en blanco(머리가 하얘지다)' → 정답 ✓","negro: 이 표현에 쓰지 않으며, 'verlo todo negro'는 '모든 것을 비관적으로 보다'입니다 ✗","rojo: 'ponerse rojo(얼굴이 빨개지다)'처럼 다른 구조로 씁니다 ✗","gris: 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"V657","q":"No se le puede pedir peras al ____, debemos ser realistas.","o":["olmo","pino","naranjo","limonero"],"a":0,"k":"속담","t":"느릅나무에 배를 바랄 수는 없어. 우리는 현실적이어야 해.","e":"'pedir peras al olmo'는 '느릅나무에게 배를 달라고 하다', 즉 '불가능한 것을 바라다'라는 속담입니다. 느릅나무(olmo)는 열매를 맺지 않는 나무이기 때문입니다. 한국어의 '연목구어(나무에서 물고기를 구하다)'와 비슷합니다.","x":["olmo: '느릅나무', 'pedir peras al olmo(불가능한 것을 바라다)' → 정답 ✓","pino: '소나무'라는 뜻으로 이 속담에 쓰지 않습니다 ✗","naranjo: '오렌지 나무'라는 뜻으로 이 속담에 쓰지 않습니다 ✗","limonero: '레몬 나무'라는 뜻으로 이 속담에 쓰지 않습니다 ✗"]},{"id":"V658","q":"Algunos de estos libros antiguos tienen mucho ____, por eso no se pueden tocar.","o":["valor","significado","desinterés","sentido"],"a":0,"k":"valor(가치)","t":"이 고서들 중 몇 권은 가치가 매우 높아서 만질 수 없다.","e":"'tener mucho valor'는 '가치가 높다'라는 뜻입니다. 만지면 안 되는 이유는 책이 귀중하기 때문이므로 valor가 맞습니다. 'valor'는 '용기'라는 뜻도 있으니 문맥으로 구분하세요.","x":["valor: '가치', 귀중해서 만질 수 없음 → 정답 ✓","significado: '의미'라는 뜻으로 만지지 못하는 이유로 어색합니다 ✗","desinterés: '무관심'이라는 뜻으로 문맥과 반대입니다 ✗","sentido: '의미, 감각'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V659","q":"El personaje de Bernarda Alba ____ la autoridad y la intransigencia.","o":["encarna","copia","imita","reproduce"],"a":0,"k":"encarnar(구현하다)","t":"베르나르다 알바라는 인물은 권위와 완고함을 구현한다.","e":"'encarnar'는 '(추상적인 성질을) 구현하다, 상징하다, 체현하다'라는 뜻입니다. 로르카의 희곡 『베르나르다 알바의 집』의 주인공은 권위주의를 상징하는 인물입니다. 'carne(살, 육체)'에서 온 말로 '육체를 입히다'라는 이미지입니다.","x":["encarna: '구현하다, 상징하다' → 정답 ✓","copia: '베끼다'라는 뜻으로 인물이 성질을 나타내는 의미가 아닙니다 ✗","imita: '흉내 내다'라는 뜻으로 맞지 않습니다 ✗","reproduce: '재현하다, 복제하다'라는 뜻으로 성질을 상징한다는 의미가 아닙니다 ✗"]},{"id":"V660","q":"Hoy hace mucho frío, ____ bien, chicos.","o":["despertaos","maquillaos","abrigaos","peinaos"],"a":2,"k":"재귀동사 명령형","t":"오늘 정말 추워. 얘들아, 옷 따뜻하게 입어.","e":"'abrigarse'는 '옷을 따뜻하게 입다'라는 뜻의 재귀동사입니다. vosotros 긍정 명령형은 동사원형의 -r를 -d로 바꾸지만, 재귀 대명사 os가 붙으면 d가 빠져 'abrigaos'가 됩니다. vosotros는 스페인에서만 쓰며, 중남미에서는 'abríguense(ustedes)'라고 합니다.","x":["despertaos: '깨어나라'라는 뜻으로 추위와 관계없습니다 ✗","maquillaos: '화장해라'라는 뜻으로 추위와 관계없습니다 ✗","abrigaos: '따뜻하게 입어라', 추운 날 알맞은 조언 → 정답 ✓","peinaos: '머리 빗어라'라는 뜻으로 추위와 관계없습니다 ✗"]},{"id":"V661","q":"Ten cuidado con ese tipo, es un ____ de mucho cuidado.","o":["tigre","zorro","coyote","tigre"],"a":1,"k":"동물 비유 표현","t":"그 녀석 조심해. 아주 교활한 여우 같은 놈이야.","e":"'ser un zorro'는 '여우 같은 사람', 즉 '교활하고 꾀가 많은 사람'을 뜻합니다. 'de mucho cuidado'는 '매우 조심해야 할, 위험한'이라는 강조 표현입니다. 동물 비유는 한국어와 비슷한 경우가 많습니다.","x":["tigre: '호랑이'라는 뜻으로 교활함을 나타내는 비유로 쓰지 않습니다 ✗","zorro: '여우', 교활한 사람을 비유 → 정답 ✓","coyote: '코요테'로, 멕시코에서는 '불법 이민 브로커'를 뜻하기도 하지만 이 문맥의 일반적 표현은 아닙니다 ✗","tigre: '호랑이'라는 뜻으로 교활한 사람을 가리키는 표현이 아닙니다 ✗"],"f":"보기 A와 D가 모두 'tigre'로 중복됨(교재 오타 추정)"},{"id":"V662","q":"La ____ de la piel es una de las consecuencias del envejecimiento.","o":["suavidad","limpieza","tersura","flacidez"],"a":3,"k":"피부 상태 어휘","t":"피부 처짐은 노화의 결과 중 하나이다.","e":"'flacidez'는 '(피부·근육의) 처짐, 탄력 없음'이라는 뜻입니다. 노화(envejecimiento)의 결과로 자연스러운 것은 피부가 처지는 것입니다. 형용사형은 flácido(축 처진)입니다.","x":["suavidad: '부드러움'이라는 뜻으로 노화의 결과로 맞지 않습니다 ✗","limpieza: '깨끗함'이라는 뜻으로 노화와 관계없습니다 ✗","tersura: '매끄러움, 탱탱함'이라는 뜻으로 노화와 반대입니다 ✗","flacidez: '처짐, 탄력 저하', 노화의 결과 → 정답 ✓"]},{"id":"V663","q":"Le hablé de forma respetuosa, pero me respondió ____.","o":["cordialmente","amablemente","afectuosamente","bruscamente"],"a":3,"k":"태도 부사","t":"나는 그에게 공손하게 말했지만, 그는 퉁명스럽게 대답했다.","e":"'bruscamente'는 '퉁명스럽게, 무뚝뚝하게, 거칠게'라는 뜻입니다. 'pero(하지만)'가 앞뒤 대조를 나타내므로, 'respetuosa(공손한)'와 반대되는 태도가 와야 합니다. 형용사형은 brusco(무뚝뚝한, 갑작스러운)입니다.","x":["cordialmente: '다정하게, 정중하게'라는 뜻으로 대조가 되지 않습니다 ✗","amablemente: '친절하게'라는 뜻으로 대조가 되지 않습니다 ✗","afectuosamente: '애정 어리게'라는 뜻으로 대조가 되지 않습니다 ✗","bruscamente: '퉁명스럽게', 공손함과 대조 → 정답 ✓"]},{"id":"V664","q":"Si quieres tomar café frío, puedes echarlo en un vaso con algunos ____ de hielo.","o":["terrones","cubitos","fragmentos","pedazos"],"a":1,"k":"cubito de hielo","t":"차가운 커피를 마시고 싶으면 얼음 몇 조각을 넣은 컵에 부으면 된다.","e":"'cubito de hielo'는 '각얼음'이라는 고정 표현입니다. cubito는 cubo(정육면체)의 축소형입니다. 'terrón'은 'terrón de azúcar(각설탕)'처럼 설탕에 쓰는 말이니 구별하세요.","x":["terrones: '덩어리'라는 뜻으로 'terrón de azúcar(각설탕)'에 씁니다 ✗","cubitos: '각얼음', 'cubitos de hielo' → 정답 ✓","fragmentos: '파편, 조각'이라는 뜻으로 얼음을 넣는 일상 표현이 아닙니다 ✗","pedazos: '조각'이라는 뜻으로 가능은 하지만 각얼음의 고정 표현이 아닙니다 ✗"]},{"id":"V665","q":"Es el mejor estudiante de la clase, ha sacado ____ en todas las materias.","o":["relevante","suficiente","insuficiente","sobresaliente"],"a":3,"k":"성적 어휘","t":"그는 반에서 가장 우수한 학생이다. 모든 과목에서 '수(최우수)'를 받았다.","e":"스페인의 성적 체계에서 'sobresaliente'는 '최우수(보통 9~10점)'를 뜻합니다. 'sacar + 성적'은 '~ 점수를 받다'라는 표현입니다. 스페인 성적 순서: insuficiente(낙제) < suficiente(합격) < bien < notable < sobresaliente.","x":["relevante: '중요한, 관련 있는'이라는 뜻으로 성적 명칭이 아닙니다 ✗","suficiente: '합격(보통 5점)'이라는 뜻으로 최고 학생에게 맞지 않습니다 ✗","insuficiente: '낙제'라는 뜻으로 문맥과 반대입니다 ✗","sobresaliente: '최우수' 성적 → 정답 ✓"]},{"id":"V666","q":"Pensé que se me abriría un ____ de oportunidades laborales al mudarme a la capital, pero me equivoqué.","o":["repertorio","fajo","abanico","cúmulo"],"a":2,"k":"abanico de","t":"수도로 이사하면 다양한 취업 기회가 열릴 거라고 생각했지만, 내가 틀렸다.","e":"'un abanico de + 복수명사'는 '다양한 ~, 폭넓은 ~'이라는 뜻입니다. abanico는 원래 '부채'인데, 부채가 펼쳐지는 모습에서 '선택의 폭'이라는 의미가 생겼습니다. 'abrirse un abanico de oportunidades(다양한 기회가 열리다)'는 자주 쓰는 표현입니다.","x":["repertorio: '레퍼토리, 목록'이라는 뜻으로 기회가 '열린다'는 표현과 어울리지 않습니다 ✗","fajo: '(지폐 등의) 다발'이라는 뜻으로 기회에 쓰지 않습니다 ✗","abanico: '부채 → 다양한 범위', 'abanico de oportunidades' → 정답 ✓","cúmulo: '퇴적, 더미'라는 뜻으로 주로 부정적인 것이 쌓일 때 씁니다 ✗"]},{"id":"V667","q":"La alergia al polen me hace ____.","o":["respirar","sudar","suspirar","estornudar"],"a":3,"k":"신체 반응 동사","t":"꽃가루 알레르기 때문에 나는 재채기를 한다.","e":"'estornudar'는 '재채기하다'라는 뜻입니다. 꽃가루 알레르기의 대표 증상이 재채기이므로 정답입니다. 스페인어권에서는 누군가 재채기를 하면 '¡Salud!' 또는 '¡Jesús!'라고 말해 줍니다.","x":["respirar: '숨 쉬다'라는 뜻으로 알레르기 증상이 아닙니다 ✗","sudar: '땀 흘리다'라는 뜻으로 꽃가루 알레르기 증상이 아닙니다 ✗","suspirar: '한숨 쉬다'라는 뜻으로 알레르기와 관계없습니다 ✗","estornudar: '재채기하다', 알레르기 증상 → 정답 ✓"]},{"id":"V668","q":"Solo tengo un conocimiento ____ de ese acontecimiento, me gustaría saber más.","o":["completo","profundo","elemental","exhaustivo"],"a":2,"k":"지식 수준 형용사","t":"그 사건에 대해서는 기초적인 지식밖에 없어서 더 알고 싶다.","e":"'elemental'은 '기초적인, 초보적인'이라는 뜻입니다. 'Solo(~뿐)'와 '더 알고 싶다'는 표현이 지식이 부족하다는 것을 보여 주므로 elemental이 맞습니다. 비슷한 말: básico(기본적인).","x":["completo: '완전한'이라는 뜻으로 '더 알고 싶다'와 모순됩니다 ✗","profundo: '깊은'이라는 뜻으로 문맥과 반대입니다 ✗","elemental: '기초적인', 지식이 부족함을 나타냄 → 정답 ✓","exhaustivo: '철저한, 빠짐없는'이라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V669","q":"Nunca olvidaré aquel ____ terrorista. Fue horrible.","o":["atentado","altercado","tumulto","movimiento"],"a":0,"k":"사건·사고 어휘","t":"그 테러 공격은 절대 잊지 못할 것이다. 끔찍했다.","e":"'atentado'는 '(테러·암살 등의) 공격, 습격'이라는 뜻으로, 'atentado terrorista(테러 공격)'는 고정 표현입니다. 동사형 atentar contra는 '~을 해치려 하다'입니다.","x":["atentado: '공격, 습격', 'atentado terrorista(테러)' → 정답 ✓","altercado: '언쟁, 말다툼'이라는 뜻으로 테러와 어울리지 않습니다 ✗","tumulto: '소동, 혼란'이라는 뜻으로 'terrorista'와 어울리지 않습니다 ✗","movimiento: '운동, 움직임'이라는 뜻으로 '끔찍했던 사건'에 맞지 않습니다 ✗"]},{"id":"V670","q":"Estos estudiantes son muy ____, es un placer tenerlos en clase.","o":["irresponsables","aplicados","impuntuales","faltones"],"a":1,"k":"학생 묘사 형용사","t":"이 학생들은 아주 성실해서, 수업에 함께하는 것이 즐겁다.","e":"'aplicado/a'는 학생에게 쓸 때 '성실한, 열심히 공부하는'이라는 뜻입니다. '수업에 있어서 기쁘다'는 긍정적 평가이므로 긍정 형용사가 필요합니다. 나머지 보기는 모두 부정적인 뜻입니다.","x":["irresponsables: '무책임한'이라는 뜻으로 긍정 평가와 맞지 않습니다 ✗","aplicados: '성실한, 부지런한' → 정답 ✓","impuntuales: '시간을 안 지키는'이라는 뜻으로 부정적입니다 ✗","faltones: '자주 결석하는, 무례한'이라는 구어로 부정적입니다 ✗"]},{"id":"V671","q":"Tuvimos que esperar a que pasara ____ de ovejas para seguir nuestro camino.","o":["el enjambre","el rebaño","la manada","el banco"],"a":1,"k":"동물 집단 명사","t":"우리는 양 떼가 지나가길 기다렸다가 길을 계속 가야 했다.","e":"'rebaño'는 '(양·염소 등의) 떼'를 뜻합니다. 동물마다 무리를 부르는 말이 다르니 함께 외워 두세요: enjambre(벌 떼), manada(늑대·코끼리 등 무리), banco(물고기 떼), bandada(새 떼).","x":["el enjambre: '벌 떼'라는 뜻으로 양에 쓰지 않습니다 ✗","el rebaño: '양 떼', 양·염소 무리 → 정답 ✓","la manada: '(야생 동물의) 무리'로 양 떼에는 보통 rebaño를 씁니다 ✗","el banco: '물고기 떼(banco de peces)'라는 뜻으로 양에 쓰지 않습니다 ✗"]},{"id":"V672","q":"Desgraciadamente, estamos asistiendo a un ____ progresivo del desempleo.","o":["bajón","descenso","aumento","declive"],"a":2,"k":"증감 명사","t":"유감스럽게도 우리는 실업률이 점점 늘어나는 것을 목격하고 있다.","e":"'Desgraciadamente(불행히도)'는 나쁜 소식을 예고합니다. 실업(desempleo)이 나빠지는 것은 늘어나는 것이므로 'aumento(증가)'가 정답입니다. 'asistir a'는 여기서 '~을 목격하다, 지켜보다'라는 뜻입니다.","x":["bajón: '급락'이라는 구어로, 실업이 줄면 좋은 소식이라 '불행히도'와 맞지 않습니다 ✗","descenso: '감소'라는 뜻으로 실업 감소는 좋은 일이라 맞지 않습니다 ✗","aumento: '증가', 실업 증가는 나쁜 소식 → 정답 ✓","declive: '쇠퇴, 하락'이라는 뜻으로 실업 감소는 좋은 일이라 맞지 않습니다 ✗"]},{"id":"V673","q":"____ cuando vi por primera vez a mi nieto. Fue algo maravilloso.","o":["Me disgusté","Me enervé","Me emocioné","Me enojé"],"a":2,"k":"감정 동사","t":"손자를 처음 보았을 때 감격했다. 정말 경이로운 일이었다.","e":"'emocionarse'는 '감동하다, 감격하다'라는 뜻입니다. '정말 멋진 일이었다'라는 긍정적 내용과 어울립니다. 영어 emotion과 비슷해 보이지만, 'emocionarse'는 주로 '벅찬 감정을 느끼다'라는 의미입니다.","x":["Me disgusté: '불쾌했다, 언짢았다'라는 뜻으로 문맥과 반대입니다 ✗","Me enervé: '신경이 곤두섰다'라는 뜻으로 문맥과 반대입니다 ✗","Me emocioné: '감격했다' → 정답 ✓","Me enojé: '화가 났다'(주로 중남미)라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V674","q":"Cuando me voy de vacaciones, mi vecina se encarga de ____ mis plantas.","o":["mojar","esparcir","regar","duchar"],"a":2,"k":"regar(물 주다)","t":"내가 휴가를 떠나면, 이웃이 내 화분에 물 주는 것을 맡아 준다.","e":"'regar'는 '(식물·밭에) 물을 주다'라는 뜻입니다. 'encargarse de + 동사원형'은 '~하는 일을 맡다'라는 표현입니다. 관련어: regadera(물뿌리개), riego(관개, 물 주기).","x":["mojar: '적시다'라는 뜻으로 식물에 물 주는 표현으로 쓰지 않습니다 ✗","esparcir: '흩뿌리다'라는 뜻으로 씨앗 등에 씁니다 ✗","regar: '물을 주다' → 정답 ✓","duchar: '샤워시키다'라는 뜻으로 식물에 쓰지 않습니다 ✗"]},{"id":"V675","q":"Qué ____ está este bizcocho, tiene azúcar de más.","o":["amargo","empalagoso","agrio","dulce"],"a":1,"k":"맛 형용사","t":"이 카스텔라 너무 느끼하게 달다. 설탕이 너무 많이 들어갔어.","e":"'empalagoso/a'는 '지나치게 달아서 질리는, 느끼한'이라는 뜻입니다. 'azúcar de más(설탕이 지나치게 많음)'라는 부정적 평가와 어울립니다. dulce는 단순히 '단'이라는 중립적 표현이라 지나침을 나타내지 못합니다.","x":["amargo: '쓴'이라는 뜻으로 설탕 과다와 맞지 않습니다 ✗","empalagoso: '너무 달아 질리는' → 정답 ✓","agrio: '신, 시큼한'이라는 뜻으로 맞지 않습니다 ✗","dulce: '단'이라는 중립적 뜻이라 지나침을 표현하지 못합니다 ✗"]},{"id":"V676","q":"Está tan nervioso que cree que le va a ____ un infarto.","o":["llegar","venir","sobrevenir","dar"],"a":3,"k":"dar + 병·발작","t":"그는 너무 긴장해서 심장마비가 올 것 같다고 생각한다.","e":"'darle a alguien un infarto'는 '누구에게 심장마비가 오다'라는 표현입니다. 'dar'는 질병이나 갑작스러운 증상에 자주 쓰입니다. 예: Me dio un mareo.(현기증이 났다.) Me dio fiebre.(열이 났다.)","x":["llegar: '도착하다'라는 뜻으로 병이 오는 표현으로 쓰지 않습니다 ✗","venir: '오다'라는 뜻이지만 infarto와의 고정 표현이 아닙니다 ✗","sobrevenir: '(갑자기) 일어나다'라는 문어로 이 구어 문장에 어색합니다 ✗","dar: 'darle un infarto(심장마비가 오다)' → 정답 ✓"]},{"id":"V677","q":"Pese a ser multimillonario, es un hombre ____ y cordial.","o":["campechano","seco","estirado","distante"],"a":0,"k":"성격 형용사","t":"억만장자인데도 그는 소탈하고 다정한 사람이다.","e":"'campechano/a'는 '소탈한, 격식 없이 친근한'이라는 뜻입니다. 'Pese a(~에도 불구하고)'는 대조를 나타내므로 부자이지만 거만하지 않다는 의미가 필요합니다. 'cordial(다정한)'과 함께 쓰이므로 긍정적인 단어여야 합니다.","x":["campechano: '소탈한, 친근한' → 정답 ✓","seco: '무뚝뚝한'이라는 뜻으로 cordial과 어울리지 않습니다 ✗","estirado: '거만한, 뻣뻣한'이라는 뜻으로 대조 구조와 맞지 않습니다 ✗","distante: '거리를 두는, 냉담한'이라는 뜻으로 cordial과 어울리지 않습니다 ✗"]},{"id":"V678","q":"La indecisión de los votantes fue la principal causa de la alta ____ en las elecciones.","o":["satisfacción","represión","abstención","contención"],"a":2,"k":"선거 어휘","t":"유권자들의 우유부단함이 선거에서 높은 기권율의 주된 원인이었다.","e":"'abstención'은 '기권, (투표) 불참'이라는 뜻입니다. 'alta abstención(높은 기권율)'은 선거 관련 기사에 자주 나오는 표현입니다. 동사형은 abstenerse(기권하다, 삼가다)입니다.","x":["satisfacción: '만족'이라는 뜻으로 우유부단함의 결과로 맞지 않습니다 ✗","represión: '탄압, 억압'이라는 뜻으로 맞지 않습니다 ✗","abstención: '기권', 선거 어휘 → 정답 ✓","contención: '억제, 봉쇄'라는 뜻으로 선거와 관계없습니다 ✗"]},{"id":"V679","q":"Una de las formas más saludables de cocinar la verdura es prepararla ____.","o":["al dente","al vapor","al vacío","al aire"],"a":1,"k":"조리법 표현","t":"채소를 조리하는 가장 건강한 방법 중 하나는 찌는 것이다.","e":"'al vapor'는 '증기로, 찐'이라는 뜻입니다. 찜은 기름을 쓰지 않고 영양소 손실도 적어 건강한 조리법으로 꼽힙니다. 다른 조리 표현: a la plancha(철판에 구운), al horno(오븐에 구운), frito(튀긴).","x":["al dente: '(파스타가) 씹히는 맛이 있게'라는 익힘 정도로 조리 방식이 아닙니다 ✗","al vapor: '찜으로', 건강한 조리법 → 정답 ✓","al vacío: '진공 포장으로'라는 뜻으로 주로 보관 방식입니다 ✗","al aire: '공기 중에'라는 뜻으로 조리법 표현이 아닙니다 ✗"]},{"id":"V680","q":"Estoy a favor del ____, me encanta trabajar desde casa.","o":["televisor","telecontrol","telebanco","teletrabajo"],"a":3,"k":"tele- 합성어","t":"나는 재택근무에 찬성한다. 집에서 일하는 게 정말 좋다.","e":"'teletrabajo'는 '원격 근무, 재택근무'라는 뜻입니다. tele-는 '멀리서'라는 의미의 접두사이고 trabajo는 '일'이므로 '집에서 일하다'와 연결됩니다. 동사형은 teletrabajar입니다.","x":["televisor: 'TV 수상기'라는 뜻으로 일과 관계없습니다 ✗","telecontrol: '원격 제어'라는 뜻으로 근무 방식이 아닙니다 ✗","telebanco: '전화·온라인 뱅킹'이라는 뜻으로 맞지 않습니다 ✗","teletrabajo: '재택근무' → 정답 ✓"]},{"id":"V681","q":"A veces es mejor decir lo que uno piensa en vez de ____.","o":["opinar","expresarse","reprimirse","implicarse"],"a":2,"k":"감정 표현 동사","t":"때로는 참는 것보다 자기 생각을 말하는 것이 낫다.","e":"'reprimirse'는 '(감정·말을) 억누르다, 참다'라는 뜻입니다. 'en vez de(~하는 대신에)'는 대조를 나타내므로, '생각을 말하다'의 반대인 '참다'가 와야 합니다. 명사형은 represión(억압)입니다.","x":["opinar: '의견을 말하다'라는 뜻으로 앞 내용과 같은 방향이라 대조가 안 됩니다 ✗","expresarse: '자신을 표현하다'라는 뜻으로 대조가 안 됩니다 ✗","reprimirse: '참다, 억누르다', 말하기와 대조 → 정답 ✓","implicarse: '관여하다'라는 뜻으로 문맥과 맞지 않습니다 ✗"]},{"id":"V682","q":"No vamos a ____ a tus exigencias y punto.","o":["acceder","entrar","asistir","acudir"],"a":0,"k":"acceder a(응하다)","t":"우리는 너의 요구에 응하지 않을 거야, 이상 끝.","e":"'acceder a'는 '(요청·요구에) 응하다, 동의하다'라는 뜻도 있습니다. 'acceder a las exigencias(요구를 들어주다)'는 자주 쓰는 표현입니다. 'y punto'는 '더 이상 말할 것 없다, 끝'이라는 단호한 표현입니다.","x":["acceder: '(요구에) 응하다' → 정답 ✓","entrar: '들어가다'라는 뜻으로 요구에 쓰지 않습니다 ✗","asistir: '참석하다'라는 뜻으로 맞지 않습니다 ✗","acudir: '가다, 찾아가다, 도움을 청하다'라는 뜻으로 요구를 들어준다는 의미가 아닙니다 ✗"]},{"id":"V683","q":"De joven era muy ____, ahora pienso más antes de actuar.","o":["cautelosa","reflexiva","impulsiva","prudente"],"a":2,"k":"성격 형용사","t":"젊었을 때 나는 아주 충동적이었지만, 지금은 행동하기 전에 더 생각한다.","e":"'impulsivo/a'는 '충동적인'이라는 뜻입니다. '지금은 행동하기 전에 더 생각한다'와 대조되어야 하므로 생각 없이 행동하는 성격이 필요합니다. 나머지 보기는 모두 '신중한'이라는 뜻이라 대조가 안 됩니다.","x":["cautelosa: '조심스러운'이라는 뜻으로 대조가 안 됩니다 ✗","reflexiva: '사려 깊은'이라는 뜻으로 대조가 안 됩니다 ✗","impulsiva: '충동적인', 현재의 신중함과 대조 → 정답 ✓","prudente: '신중한'이라는 뜻으로 대조가 안 됩니다 ✗"]},{"id":"V684","q":"Anoche ____ tal lío en mi calle que hasta tuvo que venir la policía para poner orden.","o":["se implantó","se armó","se desmontó","se ató"],"a":1,"k":"armarse un lío","t":"어젯밤 우리 동네 길에서 큰 소동이 벌어져서 경찰까지 질서를 잡으러 와야 했다.","e":"'armarse un lío / un jaleo'는 '소동이 벌어지다, 난리가 나다'라는 구어 표현입니다. armar는 '조립하다, 일으키다'이며, 재귀형 armarse는 '(소란이) 일어나다'라는 뜻이 됩니다. 예: ¡Se armó la gorda!(큰 난리가 났다!)","x":["se implantó: '도입되었다, 이식되었다'라는 뜻으로 소동에 쓰지 않습니다 ✗","se armó: '(소동이) 벌어졌다' → 정답 ✓","se desmontó: '분해되었다'라는 뜻으로 맞지 않습니다 ✗","se ató: '묶였다'라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V685","q":"Es una chica muy ____, por eso siempre está leyendo o estudiando.","o":["fisgona","curiosa","entrometida","cotilla"],"a":1,"k":"curioso의 뜻","t":"그녀는 호기심이 아주 많은 아이라서 항상 책을 읽거나 공부하고 있다.","e":"'curioso/a'는 '호기심 많은, 알고 싶어 하는'이라는 긍정적 뜻으로 쓰일 수 있습니다. 항상 읽고 공부하는 모습은 지적 호기심을 나타냅니다. 나머지 보기는 모두 '남의 일을 캐는'이라는 부정적 의미입니다.","x":["fisgona: '남의 일을 엿보는 사람'이라는 부정적 뜻입니다 ✗","curiosa: '호기심 많은', 공부하는 모습과 연결 → 정답 ✓","entrometida: '참견하기 좋아하는'이라는 부정적 뜻입니다 ✗","cotilla: '남 얘기를 좋아하는 수다쟁이'(스페인 구어)라는 부정적 뜻입니다 ✗"]},{"id":"V686","q":"Trabajo en una ____ enseñando a conducir.","o":["academia","autoescuela","tasca","cantina"],"a":1,"k":"직장 장소 어휘","t":"나는 운전 학원에서 운전을 가르치며 일한다.","e":"'autoescuela'는 '운전 학원, 자동차 학원'입니다. auto(자동차)와 escuela(학교)가 합쳐진 말입니다. 스페인에서 주로 쓰고, 중남미에서는 'escuela de manejo'라고 많이 합니다.","x":["academia: '(일반) 학원'이라는 뜻으로 운전 교육 기관을 특정하지 않습니다 ✗","autoescuela: '운전 학원' → 정답 ✓","tasca: '선술집'이라는 뜻으로 운전과 관계없습니다 ✗","cantina: '구내식당, 술집'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V687","q":"No estoy contento con esta ____ telefónica, sólo me crean problemas.","o":["agrupación","asociación","entidad","compañía"],"a":3,"k":"compañía telefónica","t":"이 통신사에 만족하지 않는다. 나에게 문제만 일으킨다.","e":"'compañía telefónica'는 '전화 회사, 통신사'라는 고정 표현입니다. compañía는 '회사'라는 뜻이며, 'compañía aérea(항공사)', 'compañía de seguros(보험 회사)'처럼 씁니다. 'sólo'의 악센트는 현재 규범에서는 생략(solo)을 권장합니다.","x":["agrupación: '단체, 집단'이라는 뜻으로 회사를 가리키지 않습니다 ✗","asociación: '협회'라는 뜻으로 통신 회사에 쓰지 않습니다 ✗","entidad: '기관, 단체'라는 뜻으로 'entidad bancaria(은행)'처럼 쓰지만 telefónica와는 덜 어울립니다 ✗","compañía: '회사', 'compañía telefónica(통신사)' → 정답 ✓"]},{"id":"V688","q":"Para combatir la ____, deben prestar mucha atención a su alimentación y hacer ejercicio físico.","o":["conjuntivitis","faringitis","obesidad","migraña"],"a":2,"k":"질병 어휘","t":"비만을 이겨내려면 식습관에 많은 주의를 기울이고 운동을 해야 합니다.","e":"'obesidad'는 '비만'입니다. 식단 관리와 운동은 비만 치료의 대표적인 방법이므로 정답입니다. 형용사형은 obeso(비만인)입니다.","x":["conjuntivitis: '결막염'이라는 뜻으로 식단·운동과 관계없습니다 ✗","faringitis: '인두염'이라는 뜻으로 식단·운동과 관계없습니다 ✗","obesidad: '비만', 식단과 운동으로 관리 → 정답 ✓","migraña: '편두통'이라는 뜻으로 운동이 주요 해결책이 아닙니다 ✗"]},{"id":"V689","q":"Apenas tengo tiempo, por eso suelo leer únicamente los ____ de los periódicos.","o":["artículos","editoriales","reportajes","titulares"],"a":3,"k":"신문 어휘","t":"시간이 거의 없어서, 보통 신문의 헤드라인만 읽는다.","e":"'titular'는 명사로 '(신문 기사의) 제목, 헤드라인'이라는 뜻입니다. 시간이 없을 때 짧게 훑어보는 것은 헤드라인이므로 정답입니다. 'titular'는 형용사로 '정규의, 주전의'라는 뜻도 있습니다.","x":["artículos: '기사'라는 뜻으로 시간이 없을 때 읽기에는 깁니다 ✗","editoriales: '사설'이라는 뜻으로 짧지 않습니다 ✗","reportajes: '르포, 취재 기사'라는 뜻으로 깁니다 ✗","titulares: '헤드라인', 빠르게 훑어보는 부분 → 정답 ✓"]},{"id":"V690","q":"Tenga cuidado al manejar esa caja, su contenido es ____.","o":["férreo","frágil","consistente","sólido"],"a":1,"k":"물체 성질 형용사","t":"그 상자를 다룰 때 조심하세요, 내용물이 깨지기 쉽습니다.","e":"'frágil'은 '깨지기 쉬운, 연약한'이라는 뜻입니다. '조심하세요'라는 주의 문구와 어울립니다. 택배 상자에 쓰는 '취급 주의' 표시가 바로 'Frágil'입니다.","x":["férreo: '쇠처럼 단단한'이라는 뜻으로 조심할 이유가 되지 않습니다 ✗","frágil: '깨지기 쉬운' → 정답 ✓","consistente: '견고한, 일관된'이라는 뜻으로 맞지 않습니다 ✗","sólido: '단단한'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V691","q":"Puedes ponerte este ____ al salir de la ducha.","o":["suéter","albornoz","traje","chaleco"],"a":1,"k":"의복 어휘","t":"샤워하고 나와서 이 목욕 가운을 입으면 돼.","e":"'albornoz'는 '목욕 가운'입니다. 샤워 후에 입는 옷이므로 정답입니다. 아랍어에서 유래한 단어로, 중남미 일부 지역에서는 'bata de baño'라고도 합니다.","x":["suéter: '스웨터'라는 뜻으로 샤워 직후에 입는 옷이 아닙니다 ✗","albornoz: '목욕 가운' → 정답 ✓","traje: '정장, 양복'이라는 뜻으로 샤워 후 입는 옷이 아닙니다 ✗","chaleco: '조끼'라는 뜻으로 샤워 후 입는 옷이 아닙니다 ✗"]},{"id":"V692","q":"Me ____ con su mirada de galán y desde ese día somos inseparables.","o":["contradijo","rehuyó","sedujo","rechazó"],"a":2,"k":"seducir(매혹하다)","t":"그는 미남 배우 같은 눈빛으로 나를 사로잡았고, 그날부터 우리는 떼려야 뗄 수 없는 사이가 되었다.","e":"'seducir'는 '매혹하다, 유혹하다'라는 뜻으로, 불규칙 과거형은 'sedujo'입니다(-ducir 동사는 과거에서 -duj- 형태: conducir → condujo). 'galán'은 '미남, 멋쟁이 남자'를 뜻하며, 결과가 '떨어질 수 없는 사이'이므로 긍정적인 동사가 필요합니다.","x":["contradijo: '반박했다'라는 뜻으로 눈빛과 어울리지 않습니다 ✗","rehuyó: '피했다'라는 뜻으로 결과와 모순됩니다 ✗","sedujo: '매혹했다, 사로잡았다' → 정답 ✓","rechazó: '거절했다'라는 뜻으로 결과와 모순됩니다 ✗"]},{"id":"V693","q":"Ellos no tienen problemas económicos, pues tienen ____ de dinero.","o":["abundancia","exuberancia","escasez","carencia"],"a":0,"k":"양 관련 명사","t":"그들은 경제적 문제가 없다. 돈이 넘쳐나기 때문이다.","e":"'abundancia'는 '풍부함, 넉넉함'이라는 뜻입니다. 경제적 문제가 없는 이유를 설명하므로 돈이 많다는 의미가 필요합니다. 'en abundancia(풍부하게)'라는 표현도 자주 씁니다.","x":["abundancia: '풍부함', 돈이 많음 → 정답 ✓","exuberancia: '(식물 등의) 무성함, 넘치는 활기'라는 뜻으로 돈에는 잘 쓰지 않습니다 ✗","escasez: '부족'이라는 뜻으로 문맥과 반대입니다 ✗","carencia: '결핍'이라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V694","q":"Los menores no pueden pasar, tienen ____ el acceso a este local.","o":["permitido","restringido","autorizado","consentido"],"a":1,"k":"허가·제한 형용사","t":"미성년자는 들어갈 수 없습니다. 이 업소는 출입이 제한되어 있습니다.","e":"'restringido/a'는 '제한된'이라는 뜻입니다. '들어갈 수 없다'는 앞 문장과 이어지려면 출입이 제한되었다는 의미여야 합니다. 'acceso restringido(출입 제한)'는 표지판에서 자주 보는 표현입니다.","x":["permitido: '허용된'이라는 뜻으로 문맥과 반대입니다 ✗","restringido: '제한된', 'acceso restringido' → 정답 ✓","autorizado: '허가된'이라는 뜻으로 문맥과 반대입니다 ✗","consentido: '동의된, 응석받이의'라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V695","q":"Todo lo que se estropea en casa lo arregla mi hijo, es un ____.","o":["empollón","mandón","manitas","copión"],"a":2,"k":"사람 묘사 구어","t":"집에서 고장 나는 건 모두 내 아들이 고친다. 그 애는 손재주꾼이다.","e":"'manitas'는 '손재주가 좋은 사람, 뭐든 잘 고치는 사람'이라는 스페인 구어입니다. mano(손)의 축소형에서 나왔으며 단수·복수 형태가 같습니다(un manitas). 'ser un manitas'로 씁니다.","x":["empollón: '공부벌레'(스페인 구어, 약간 경멸적)라는 뜻으로 고치는 것과 관계없습니다 ✗","mandón: '이래라저래라 하는 사람'이라는 뜻으로 맞지 않습니다 ✗","manitas: '손재주꾼', 뭐든 잘 고치는 사람 → 정답 ✓","copión: '베끼는 사람, 커닝하는 사람'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V696","q":"Decidió ____ porque no se veía capaz de seguir ocupando un puesto de tanta responsabilidad.","o":["proseguir","resistir","continuar","dimitir"],"a":3,"k":"dimitir(사임하다)","t":"그는 그렇게 책임이 막중한 자리를 계속 맡을 자신이 없어서 사임하기로 결정했다.","e":"'dimitir'는 '(직책에서) 사임하다, 물러나다'라는 뜻입니다. '계속 자리를 맡을 수 없다고 느꼈다'는 이유와 어울립니다. 명사형은 dimisión(사임)입니다.","x":["proseguir: '계속하다'라는 뜻으로 문맥과 반대입니다 ✗","resistir: '버티다'라는 뜻으로 문맥과 반대입니다 ✗","continuar: '계속하다'라는 뜻으로 문맥과 반대입니다 ✗","dimitir: '사임하다' → 정답 ✓"]},{"id":"V697","q":"Ana no lo dijo claramente, pero sí ____ que el jefe no trataba por igual a todos los empleados.","o":["clarificó","aclaró","insinuó","evidenció"],"a":2,"k":"insinuar(넌지시 말하다)","t":"아나는 분명하게 말하지는 않았지만, 상사가 모든 직원을 똑같이 대하지 않는다는 것을 넌지시 내비쳤다.","e":"'insinuar'는 '넌지시 말하다, 암시하다'라는 뜻입니다. 'no lo dijo claramente(분명히 말하지 않았다)'와 'pero sí(하지만 ~는 했다)'의 대조로, 직접 말하지 않고 돌려서 표현했다는 의미가 됩니다. 명사형은 insinuación(암시)입니다.","x":["clarificó: '명확히 했다'라는 뜻으로 '분명히 말하지 않았다'와 모순됩니다 ✗","aclaró: '분명히 밝혔다'라는 뜻으로 모순됩니다 ✗","insinuó: '넌지시 내비쳤다' → 정답 ✓","evidenció: '명백히 드러냈다'라는 뜻으로 모순됩니다 ✗"]},{"id":"V698","q":"La cantante ____ al público con su increíble voz.","o":["enredó","engañó","encandiló","defraudó"],"a":2,"k":"encandilar(매료하다)","t":"그 가수는 놀라운 목소리로 관객을 매료시켰다.","e":"'encandilar'는 원래 '(강한 빛으로) 눈부시게 하다'라는 뜻이지만, '매료하다, 홀리다'라는 의미로도 쓰입니다. 놀라운 목소리의 결과로 긍정적인 반응이 필요하므로 정답입니다.","x":["enredó: '얽히게 했다, 꼬드겼다'라는 뜻으로 맞지 않습니다 ✗","engañó: '속였다'라는 뜻으로 부정적입니다 ✗","encandiló: '매료시켰다' → 정답 ✓","defraudó: '실망시켰다'라는 뜻으로 '놀라운 목소리'와 모순됩니다 ✗"]},{"id":"V699","q":"Los ____ piden medio millón de dólares a cambio de liberar a la víctima.","o":["estafadores","ladrones","secuestradores","falsificadores"],"a":2,"k":"범죄자 어휘","t":"납치범들은 피해자를 풀어 주는 대가로 50만 달러를 요구하고 있다.","e":"'secuestrador/a'는 '납치범, 유괴범'입니다. 'liberar a la víctima(피해자를 풀어 주다)'는 대가로 돈을 요구하는 것은 납치 상황입니다. 관련어: secuestrar(납치하다), secuestro(납치), rescate(몸값).","x":["estafadores: '사기꾼'이라는 뜻으로 피해자를 풀어 주는 상황이 아닙니다 ✗","ladrones: '도둑'이라는 뜻으로 몸값을 요구하지 않습니다 ✗","secuestradores: '납치범', 몸값을 요구 → 정답 ✓","falsificadores: '위조범'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V700","q":"____ es una bebida alcohólica que se obtiene fermentando zumo de manzana.","o":["La sidra","El ron","El mate","La ginebra"],"a":0,"k":"음료 어휘","t":"사이다(시드라)는 사과즙을 발효시켜 얻는 알코올음료이다.","e":"'sidra'는 사과를 발효해 만든 술(사과주)입니다. 스페인 아스투리아스 지방의 명물로 유명합니다. 한국의 '사이다(탄산음료)'와는 다르니 주의하세요.","x":["La sidra: '사과주', 사과즙을 발효한 술 → 정답 ✓","El ron: '럼주'로 사탕수수로 만듭니다 ✗","El mate: '마테차'로 알코올음료가 아닙니다(아르헨티나·우루과이 등) ✗","La ginebra: '진'으로 노간주나무 열매 향을 입힌 증류주입니다 ✗"]},{"id":"V701","q":"Los niños estaban ____ tras pasar tantos días perdidos en el bosque.","o":["repuestos","hiperactivos","desnutridos","recuperados"],"a":2,"k":"건강 상태 형용사","t":"아이들은 숲에서 그렇게 여러 날을 길을 잃고 지낸 뒤 영양실조 상태였다.","e":"'desnutrido/a'는 '영양실조의'라는 뜻입니다. 숲에서 여러 날 길을 잃었다면 제대로 먹지 못했을 것이므로 정답입니다. 명사형은 desnutrición(영양실조)입니다.","x":["repuestos: '회복된'이라는 뜻으로 길을 잃은 직후 상태와 맞지 않습니다 ✗","hiperactivos: '과잉 행동의'라는 뜻으로 맞지 않습니다 ✗","desnutridos: '영양실조의' → 정답 ✓","recuperados: '회복된'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V702","q":"¿Cuál es el primer diccionario del que se tiene ____?","o":["recuento","cuenta","balance","registro"],"a":3,"k":"tener registro de","t":"기록상 남아 있는 최초의 사전은 무엇인가?","e":"'tener registro de algo'는 '~에 대한 기록이 있다'라는 뜻입니다. 'el primer diccionario del que se tiene registro'는 '기록으로 확인되는 최초의 사전'이라는 의미입니다. 비슷한 표현: 'del que se tiene constancia'.","x":["recuento: '집계, 재검표'라는 뜻으로 이 표현에 쓰지 않습니다 ✗","cuenta: 'tener en cuenta(고려하다)'와 혼동하기 쉽지만 이 구조에서는 맞지 않습니다 ✗","balance: '결산, 평가'라는 뜻으로 맞지 않습니다 ✗","registro: '기록', 'tener registro de(기록이 있다)' → 정답 ✓"]},{"id":"V703","q":"No le digas tus ____ secretos a nadie para evitar problemas de seguridad.","o":["lemas","códigos","principios","valores"],"a":1,"k":"보안 어휘","t":"보안 문제를 피하려면 비밀번호(비밀 코드)를 아무에게도 말하지 마라.","e":"'código secreto'는 '비밀 코드, 비밀번호'라는 뜻입니다. 보안(seguridad) 문제를 언급하므로 코드가 정답입니다. 비밀번호는 contraseña라고도 하며, 카드 비밀번호는 'PIN'이라고도 합니다.","x":["lemas: '표어, 모토'라는 뜻으로 보안과 관계없습니다 ✗","códigos: '코드', 'códigos secretos(비밀번호)' → 정답 ✓","principios: '원칙'이라는 뜻으로 보안 문제와 관계없습니다 ✗","valores: '가치관'이라는 뜻으로 보안 문제와 관계없습니다 ✗"]},{"id":"V704","q":"La ____ joven es la más afectada por el paro en nuestro país.","o":["población","clase","vecindad","sociedad"],"a":0,"k":"사회 어휘","t":"우리나라에서 실업의 타격을 가장 많이 받는 것은 청년층이다.","e":"'población joven'은 '청년층, 젊은 인구'라는 뜻입니다. población은 '인구, 주민'이라는 뜻으로 통계나 사회 현상을 말할 때 자주 씁니다. 'paro'는 스페인에서 '실업'을 뜻하며, 중남미에서는 'desempleo'를 더 많이 씁니다(paro는 파업의 뜻도 있음).","x":["población: '인구층', 'población joven(청년층)' → 정답 ✓","clase: '계층'이라는 뜻이지만 'clase joven'이라는 표현은 쓰지 않습니다 ✗","vecindad: '이웃, 동네'라는 뜻으로 맞지 않습니다 ✗","sociedad: '사회'라는 뜻으로 'sociedad joven'은 연령층을 가리키지 않습니다 ✗"]},{"id":"V705","q":"En todas nuestras aulas hay ____ digital.","o":["un armario","una estantería","una pizarra","un pupitre"],"a":2,"k":"교실 어휘","t":"우리 모든 교실에는 전자 칠판이 있습니다.","e":"'pizarra digital'은 '전자 칠판'입니다. pizarra는 '칠판'이며, 중남미에서는 pizarrón 또는 tablero라고도 합니다. 'digital'과 자연스럽게 결합하는 교실 물품은 칠판입니다.","x":["un armario: '옷장, 수납장'이라는 뜻으로 digital과 어울리지 않습니다 ✗","una estantería: '책장, 선반'이라는 뜻으로 맞지 않습니다 ✗","una pizarra: '칠판', 'pizarra digital(전자 칠판)' → 정답 ✓","un pupitre: '학생용 책상'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V706","q":"Si todavía no está ____ a nuestro boletín, puede hacerlo mediante su correo electrónico.","o":["suscrito","inscrito","adscrito","escrito"],"a":0,"k":"-scrito 형태 구분","t":"아직 저희 소식지를 구독하지 않으셨다면, 이메일로 구독하실 수 있습니다.","e":"'suscribirse a'는 '(잡지·소식지 등을) 구독하다, 가입하다'라는 뜻이고 과거분사는 'suscrito'입니다. 'boletín'은 '소식지, 뉴스레터'입니다. inscribirse는 '(강좌·대회에) 등록하다'라는 뜻이라 구독과는 다릅니다.","x":["suscrito: '구독한', 소식지와 어울림 → 정답 ✓","inscrito: '등록한'이라는 뜻으로 강좌·행사 등록에 씁니다 ✗","adscrito: '소속된, 배속된'이라는 뜻으로 맞지 않습니다 ✗","escrito: '쓰인'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V707","q":"Es una playa tan ____ que apenas van allí a bañarse.","o":["accesible","bonita","rocosa","excepcional"],"a":2,"k":"지형 형용사","t":"그곳은 바위가 너무 많은 해변이라 수영하러 가는 사람이 거의 없다.","e":"'rocoso/a'는 '바위가 많은'이라는 뜻으로 roca(바위)에서 나왔습니다. 'tan ... que ...(너무 ~해서 …하다)' 구조에서 사람들이 거의 가지 않는 이유가 되려면 부정적인 특징이 필요합니다.","x":["accesible: '접근하기 쉬운'이라는 뜻으로 사람이 안 가는 이유가 아닙니다 ✗","bonita: '예쁜'이라는 뜻으로 사람이 안 가는 이유가 아닙니다 ✗","rocosa: '바위가 많은', 수영하기 불편한 이유 → 정답 ✓","excepcional: '특별히 뛰어난'이라는 뜻으로 사람이 안 가는 이유가 아닙니다 ✗"]},{"id":"V708","q":"Trabajando media ____ tengo más tiempo para mis hijos.","o":["fase","duración","etapa","jornada"],"a":3,"k":"media jornada","t":"파트타임(반일 근무)으로 일하니까 아이들을 위한 시간이 더 많다.","e":"'media jornada'는 '반일 근무, 파트타임'이라는 뜻입니다. jornada는 '(하루의) 근무 시간, 일과'를 뜻하며, 'jornada completa(전일 근무)'와 대비됩니다. 중남미에서는 'medio tiempo'라고도 합니다.","x":["fase: '단계'라는 뜻으로 근무 형태에 쓰지 않습니다 ✗","duración: '지속 기간'이라는 뜻으로 맞지 않습니다 ✗","etapa: '시기, 단계'라는 뜻으로 맞지 않습니다 ✗","jornada: '근무 시간', 'media jornada(반일 근무)' → 정답 ✓"]},{"id":"V709","q":"La termosfera es una de las ____ de la atmósfera.","o":["capas","ramas","secciones","áreas"],"a":0,"k":"과학 어휘","t":"열권은 대기의 층 중 하나이다.","e":"'capa'는 '층'이라는 뜻으로, 'capas de la atmósfera(대기의 층)'는 과학 시간에 쓰는 표현입니다. 대기층은 troposfera(대류권), estratosfera(성층권), mesosfera(중간권), termosfera(열권) 등으로 나뉩니다. 'capa de ozono(오존층)'도 함께 기억하세요.","x":["capas: '층', 대기의 층 → 정답 ✓","ramas: '가지, 분야'라는 뜻으로 대기 구조에 쓰지 않습니다 ✗","secciones: '부분, 부서'라는 뜻으로 맞지 않습니다 ✗","áreas: '지역, 영역'이라는 뜻으로 대기의 수직 구조를 표현하지 못합니다 ✗"]},{"id":"V710","q":"Hay mucho caos en el aeropuerto debido a la ____ de los controladores aéreos.","o":["labor","participación","huelga","actividad"],"a":2,"k":"노동 어휘","t":"항공 관제사들의 파업 때문에 공항이 큰 혼란에 빠져 있다.","e":"'huelga'는 '파업'이라는 뜻입니다. 공항 혼란(caos)의 원인으로 관제사들이 일을 하지 않는 상황이 가장 자연스럽습니다. 'estar en huelga(파업 중이다)', 'hacer huelga(파업하다)'처럼 씁니다. 중남미에서는 paro라고도 합니다.","x":["labor: '일, 노동'이라는 뜻으로 혼란의 원인이 되지 않습니다 ✗","participación: '참여'라는 뜻으로 맞지 않습니다 ✗","huelga: '파업', 혼란의 원인 → 정답 ✓","actividad: '활동'이라는 뜻으로 혼란의 원인으로 어색합니다 ✗"]},{"id":"V711","q":"La ____ acústica puede provocar alteraciones del sueño y otros problemas.","o":["emisión","transmisión","contaminación","difusión"],"a":2,"k":"환경 어휘","t":"소음 공해는 수면 장애와 다른 문제들을 일으킬 수 있다.","e":"'contaminación acústica'는 '소음 공해'라는 고정 표현입니다. contaminación은 '오염, 공해'이고 acústica는 '소리의'라는 뜻입니다. 비슷하게 'contaminación lumínica(빛 공해)', 'contaminación atmosférica(대기 오염)'도 있습니다.","x":["emisión: '배출, 방송'이라는 뜻으로 소음 공해의 고정 표현이 아닙니다 ✗","transmisión: '전송, 전달'이라는 뜻으로 맞지 않습니다 ✗","contaminación: '공해', 'contaminación acústica(소음 공해)' → 정답 ✓","difusión: '확산, 보급'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V712","q":"Quiero estudiar un ____ en la Universidad de Granada.","o":["expediente","temario","programa","grado"],"a":3,"k":"대학 어휘","t":"나는 그라나다 대학교에서 학사 과정을 공부하고 싶다.","e":"'grado'는 스페인에서 '학사 과정'을 뜻합니다(볼로냐 프로세스 이후 licenciatura 대신 사용). 'estudiar un grado en ...(~에서 학사 과정을 밟다)'처럼 씁니다. 그 이후 과정은 máster(석사), doctorado(박사)입니다. 중남미에서는 licenciatura나 carrera를 더 많이 씁니다.","x":["expediente: '성적 기록, 서류철'이라는 뜻으로 공부할 대상이 아닙니다 ✗","temario: '시험 범위, 주제 목록'이라는 뜻으로 대학 과정이 아닙니다 ✗","programa: '프로그램'이라는 뜻으로 일반적이지만 학위 과정을 가리키는 표준 표현이 아닙니다 ✗","grado: '학사 과정' → 정답 ✓"]},{"id":"V713","q":"¿Cómo puedo protegerme de ____ UVA?","o":["las rayas","los rayos","los emisores","las líneas"],"a":1,"k":"rayo(광선)","t":"자외선(UVA)으로부터 어떻게 나를 보호할 수 있을까?","e":"'rayos UVA'는 '자외선 A'를 뜻합니다. rayo는 '광선, 빛줄기, 번개'라는 뜻의 남성 명사입니다. 'raya'는 '줄, 선, 줄무늬'라는 뜻이라 혼동하지 마세요.","x":["las rayas: '줄무늬, 선'이라는 뜻으로 빛을 가리키지 않습니다 ✗","los rayos: '광선', 'rayos UVA(자외선)' → 정답 ✓","los emisores: '발신기, 방출원'이라는 뜻으로 맞지 않습니다 ✗","las líneas: '선'이라는 뜻으로 빛을 가리키지 않습니다 ✗"]},{"id":"V714","q":"No voy a ____ al examen, no he podido estudiar.","o":["llegar","asomarme","presentarme","acercarme"],"a":2,"k":"presentarse a","t":"공부를 못 했기 때문에 시험을 보러 가지 않을 거야.","e":"'presentarse a un examen'은 '시험에 응시하다, 시험을 치르러 가다'라는 고정 표현입니다. 비슷하게 'presentarse a unas elecciones(선거에 출마하다)'처럼도 씁니다. 다른 보기들은 장소로 이동한다는 의미라 '시험에 응시하다'의 뜻을 갖지 않습니다.","x":["llegar: '도착하다'라는 뜻으로 응시의 의미가 없습니다 ✗","asomarme: '얼굴을 내밀다, 내다보다'라는 뜻으로 맞지 않습니다 ✗","presentarme: '응시하다', 'presentarse a un examen' → 정답 ✓","acercarme: '다가가다'라는 뜻으로 응시의 의미가 없습니다 ✗"]},{"id":"V715","q":"¿Cómo voy a ____ si todo está cada vez más caro?","o":["recolectar","recaudar","ahorrar","coleccionar"],"a":2,"k":"ahorrar(저축하다)","t":"모든 게 점점 비싸지는데 내가 어떻게 저축을 하겠어?","e":"'ahorrar'는 '(돈을) 저축하다, 절약하다'라는 뜻입니다. 물가가 오르면 돈을 모으기 어렵다는 불평이므로 정답입니다. 명사형은 ahorro(저축)이고, 'cuenta de ahorro'는 '저축 예금 계좌'입니다.","x":["recolectar: '(농작물을) 수확하다, 수집하다'라는 뜻으로 맞지 않습니다 ✗","recaudar: '(세금·기금을) 거두다, 모금하다'라는 뜻으로 개인 저축이 아닙니다 ✗","ahorrar: '저축하다' → 정답 ✓","coleccionar: '(취미로) 수집하다'라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V716","q":"Tanto el aburrimiento como el sueño nos hacen ____.","o":["llorar","sollozar","bostezar","estornudar"],"a":2,"k":"신체 반응 동사","t":"지루함과 졸음 둘 다 우리를 하품하게 만든다.","e":"'bostezar'는 '하품하다'라는 뜻입니다. 지루함(aburrimiento)과 졸음(sueño)의 공통 반응은 하품입니다. 명사형은 bostezo(하품)입니다. 'Tanto A como B(A도 B도)' 구조도 함께 익혀 두세요.","x":["llorar: '울다'라는 뜻으로 지루함·졸음의 반응이 아닙니다 ✗","sollozar: '흐느끼다'라는 뜻으로 맞지 않습니다 ✗","bostezar: '하품하다' → 정답 ✓","estornudar: '재채기하다'라는 뜻으로 지루함과 관계없습니다 ✗"]},{"id":"V717","q":"En mi clase de español hay un grupo ____ de estudiantes, no es nada homogéneo.","o":["uniforme","variopinto","parecido","semejante"],"a":1,"k":"다양성 형용사","t":"내 스페인어 수업에는 각양각색의 학생들이 있어서 전혀 균일하지 않다.","e":"'variopinto/a'는 '각양각색의, 다채로운'이라는 뜻입니다. 'no es nada homogéneo(전혀 균일하지 않다)'는 다양함을 강조합니다. vario(여러 가지)와 pinto(얼룩진, 색이 섞인)가 합쳐진 말입니다.","x":["uniforme: '균일한'이라는 뜻으로 문맥과 반대입니다 ✗","variopinto: '각양각색의' → 정답 ✓","parecido: '비슷한'이라는 뜻으로 문맥과 반대입니다 ✗","semejante: '유사한'이라는 뜻으로 문맥과 반대입니다 ✗"]},{"id":"V718","q":"____ se usan para endulzar los alimentos.","o":["Las especias","Los conservantes","Los edulcorantes","Los colorantes"],"a":2,"k":"식품 첨가물 어휘","t":"감미료는 음식을 달게 하는 데 쓰인다.","e":"'edulcorante'는 '감미료'라는 뜻으로, endulzar(달게 하다)와 같은 어원(dulce, 단)에서 나왔습니다. 식품 라벨에서 자주 보는 단어입니다. 다른 첨가물: conservante(보존료), colorante(색소).","x":["Las especias: '향신료'로 맛과 향을 내지만 달게 하지는 않습니다 ✗","Los conservantes: '보존료'로 음식을 오래 보관하게 합니다 ✗","Los edulcorantes: '감미료', 음식을 달게 함 → 정답 ✓","Los colorantes: '색소'로 색을 냅니다 ✗"]},{"id":"V719","q":"Los niños deben tener una dieta ____ para estar sanos.","o":["nutritiva","insuficiente","restrictiva","pobre"],"a":0,"k":"식단 형용사","t":"아이들은 건강하려면 영양가 있는 식단을 먹어야 한다.","e":"'nutritivo/a'는 '영양가 있는'이라는 뜻입니다. 건강해지기 위한 식단이므로 긍정적인 형용사가 필요합니다. 관련어: nutrir(영양을 공급하다), nutriente(영양소).","x":["nutritiva: '영양가 있는' → 정답 ✓","insuficiente: '불충분한'이라는 뜻으로 건강에 좋지 않습니다 ✗","restrictiva: '제한적인'이라는 뜻으로 아이들 건강에 바람직하지 않습니다 ✗","pobre: '빈약한'이라는 뜻으로 건강에 좋지 않습니다 ✗"]},{"id":"V720","q":"La novela narra una historia ____ en la posguerra española.","o":["aclimatada","ambientada","afincada","instalada"],"a":1,"k":"ambientar(배경 설정)","t":"그 소설은 스페인 내전 이후 시기를 배경으로 한 이야기를 들려준다.","e":"'estar ambientado/a en'은 '(소설·영화가) ~을 배경으로 하다'라는 뜻입니다. 'posguerra española'는 스페인 내전(1936~1939) 이후 시기를 가리킵니다. 예: una película ambientada en los años 80(80년대를 배경으로 한 영화).","x":["aclimatada: '(기후·환경에) 적응한'이라는 뜻으로 작품 배경에 쓰지 않습니다 ✗","ambientada: '배경으로 한' → 정답 ✓","afincada: '정착한, 자리 잡은'이라는 뜻으로 사람에게 씁니다 ✗","instalada: '설치된, 자리 잡은'이라는 뜻으로 작품 배경에 쓰지 않습니다 ✗"]},{"id":"V721","q":"Pedro siempre tuvo ____ de profesor, nunca le interesó otra profesión.","o":["condición","intuición","vocación","naturaleza"],"a":2,"k":"vocación(천직)","t":"페드로는 늘 교사가 천직이라고 느꼈고, 다른 직업에는 전혀 관심이 없었다.","e":"'tener vocación de + 직업'은 '~이 되고 싶은 소명 의식이 있다, ~이 천직이다'라는 뜻입니다. '다른 직업에는 관심이 없었다'는 내용이 그 직업에 대한 강한 끌림을 보여 줍니다. 형용사형은 vocacional입니다.","x":["condición: '조건, 상태'라는 뜻으로 직업에 대한 끌림을 나타내지 않습니다 ✗","intuición: '직관'이라는 뜻으로 맞지 않습니다 ✗","vocación: '천직, 소명' → 정답 ✓","naturaleza: '본성, 자연'이라는 뜻으로 'tener naturaleza de profesor'라고 하지 않습니다 ✗"]},{"id":"V722","q":"A diferencia de las películas, los ____ no suelen durar más de treinta minutos.","o":["documentales","filmes","reportajes","cortometrajes"],"a":3,"k":"영상 장르 어휘","t":"장편 영화와 달리, 단편 영화는 보통 30분을 넘지 않는다.","e":"'cortometraje'는 '단편 영화'로, corto(짧은)와 metraje(필름 길이)가 합쳐진 말입니다. 구어로 'corto'라고 줄여 말하기도 합니다. 반대말은 largometraje(장편 영화)입니다.","x":["documentales: '다큐멘터리'로 길이가 짧다는 정의가 없습니다 ✗","filmes: '영화'라는 뜻으로 películas와 같은 의미라 대조가 안 됩니다 ✗","reportajes: '르포, 보도 기사'로 영화와 대비되는 장르가 아닙니다 ✗","cortometrajes: '단편 영화', 짧은 길이가 특징 → 정답 ✓"]},{"id":"V723","q":"Ese autobús siempre llega con ____, por eso prefiero ir a pie.","o":["rapidez","retraso","celeridad","premura"],"a":1,"k":"시간 관련 명사","t":"그 버스는 항상 늦게 와서 나는 걸어가는 것을 더 좋아한다.","e":"'llegar con retraso'는 '늦게 도착하다, 지연되다'라는 뜻입니다. 걸어가는 것을 선호하는 이유가 되려면 버스가 늦어야 합니다. 중남미에서는 retraso 대신 'atraso'나 'demora'도 많이 씁니다.","x":["rapidez: '신속함'이라는 뜻으로 걸어갈 이유가 되지 않습니다 ✗","retraso: '지연', 'llegar con retraso(늦게 도착하다)' → 정답 ✓","celeridad: '신속함'이라는 뜻으로 문맥과 반대입니다 ✗","premura: '긴급함, 서두름'이라는 뜻으로 문맥과 맞지 않습니다 ✗"]},{"id":"V724","q":"Fue un acto serio y ____, propio de una efemérides tan importante.","o":["informal","solemne","divertido","gracioso"],"a":1,"k":"행사 분위기 형용사","t":"그토록 중요한 기념일에 걸맞은, 진지하고 엄숙한 행사였다.","e":"'solemne'는 '엄숙한, 장중한'이라는 뜻입니다. 'serio(진지한)'와 함께 쓰이므로 비슷한 분위기의 단어가 필요합니다. 'efemérides'는 '(역사적) 기념일'이라는 뜻입니다.","x":["informal: '격식 없는'이라는 뜻으로 serio와 어울리지 않습니다 ✗","solemne: '엄숙한' → 정답 ✓","divertido: '재미있는'이라는 뜻으로 serio와 어울리지 않습니다 ✗","gracioso: '웃기는'이라는 뜻으로 serio와 어울리지 않습니다 ✗"]},{"id":"V725","q":"Tengo un dolor de espalda ____, no podré participar en la carrera.","o":["espantoso","prodigioso","costoso","escandaloso"],"a":0,"k":"강조 형용사","t":"허리가 끔찍하게 아파서 경주에 참가할 수 없을 것이다.","e":"'espantoso/a'는 '끔찍한, 지독한'이라는 뜻으로, 통증이나 날씨 등의 정도가 심함을 강조할 때 씁니다. 경주에 참가하지 못할 정도의 통증이므로 정답입니다. 비슷한 말: horrible, terrible.","x":["espantoso: '끔찍한', 심한 통증 → 정답 ✓","prodigioso: '경이로운'이라는 긍정적 뜻으로 통증에 쓰지 않습니다 ✗","costoso: '비용이 많이 드는'이라는 뜻으로 맞지 않습니다 ✗","escandaloso: '시끄러운, 수치스러운'이라는 뜻으로 통증에 쓰지 않습니다 ✗"]},{"id":"V726","q":"Intento no ____ el agua porque considero que es un recurso limitado.","o":["descuidar","obtener","desperdiciar","adquirir"],"a":2,"k":"desperdiciar(낭비하다)","t":"물은 한정된 자원이라고 생각하기 때문에 물을 낭비하지 않으려고 노력한다.","e":"'desperdiciar'는 '낭비하다, 허비하다'라는 뜻입니다. 물이 한정된 자원이라는 이유와 연결되어 '낭비하지 않으려 한다'가 자연스럽습니다. 비슷한 말: malgastar, derrochar.","x":["descuidar: '소홀히 하다'라는 뜻으로 물에 쓰기 어색합니다 ✗","obtener: '얻다'라는 뜻으로 문맥과 맞지 않습니다 ✗","desperdiciar: '낭비하다' → 정답 ✓","adquirir: '획득하다'라는 뜻으로 문맥과 맞지 않습니다 ✗"]},{"id":"V727","q":"Los Hernández son de clase ____, por eso viven en una mansión.","o":["alta","humilde","inferior","baja"],"a":0,"k":"사회 계층","t":"에르난데스 가족은 상류층이라서 대저택에 산다.","e":"'clase alta'는 '상류층'입니다. 'mansión(대저택)'에 사는 이유가 되므로 부유한 계층이어야 합니다. 계층 표현: clase alta(상류층), clase media(중산층), clase baja/humilde(하층·서민층).","x":["alta: '상류의', 대저택에 사는 이유 → 정답 ✓","humilde: '서민의'라는 뜻으로 대저택과 맞지 않습니다 ✗","inferior: '하위의'라는 뜻으로 계층을 말할 때 잘 쓰지 않고 문맥과도 맞지 않습니다 ✗","baja: '하층의'라는 뜻으로 대저택과 맞지 않습니다 ✗"]},{"id":"V728","q":"Los ____ trabajan bajo tierra.","o":["informáticos","funcionarios","mineros","reporteros"],"a":2,"k":"직업 어휘","t":"광부들은 땅속에서 일한다.","e":"'minero/a'는 '광부'로, mina(광산)에서 나온 말입니다. 'bajo tierra(땅속에서)' 일하는 직업이므로 정답입니다. 형용사로는 '광업의'라는 뜻도 있습니다.","x":["informáticos: 'IT 전문가'로 땅속에서 일하지 않습니다 ✗","funcionarios: '공무원'으로 땅속에서 일하지 않습니다 ✗","mineros: '광부', 땅속에서 일함 → 정답 ✓","reporteros: '기자'로 땅속에서 일하지 않습니다 ✗"]},{"id":"V729","q":"No tienes que tratarme de usted, me puedes ____.","o":["tutear","designar","avisar","nombrar"],"a":0,"k":"tutear(반말하다)","t":"저한테 존댓말 안 하셔도 돼요, 편하게 tú로 말하셔도 됩니다.","e":"'tutear'는 '상대를 tú로 부르다', 즉 '말을 놓다'라는 뜻입니다. 'tratar de usted'는 '상대를 usted로 부르다(존칭)'입니다. 참고로 아르헨티나 등 voseo 지역에서는 vos로 말하는 것을 'vosear'라고 합니다.","x":["tutear: 'tú로 말하다, 말을 놓다' → 정답 ✓","designar: '지명하다, 지정하다'라는 뜻으로 맞지 않습니다 ✗","avisar: '알리다'라는 뜻으로 맞지 않습니다 ✗","nombrar: '이름을 부르다, 임명하다'라는 뜻으로 호칭 방식을 나타내지 않습니다 ✗"]},{"id":"V730","q":"Mi abuelo nos ____ un cuento cuando nos íbamos a la cama.","o":["narraba","declaraba","exponía","reseñaba"],"a":0,"k":"narrar(이야기하다)","t":"할아버지는 우리가 잠자리에 들 때 옛날이야기를 들려주시곤 했다.","e":"'narrar un cuento'는 '이야기를 들려주다'라는 뜻입니다. 불완료 과거(narraba)는 과거에 반복된 습관을 나타냅니다. 일상 대화에서는 'contar un cuento'가 더 흔합니다.","x":["narraba: '들려주곤 했다', 이야기와 어울림 → 정답 ✓","declaraba: '선언했다, 진술했다'라는 뜻으로 동화에 쓰지 않습니다 ✗","exponía: '설명했다, 발표했다'라는 뜻으로 동화와 어울리지 않습니다 ✗","reseñaba: '서평·논평을 썼다'라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V731","q":"Marcelo es un hombre ____ y sin sentido del humor.","o":["chistoso","ingenioso","gruñón","ocurrente"],"a":2,"k":"성격 형용사","t":"마르셀로는 투덜대고 유머 감각이 없는 사람이다.","e":"'gruñón/a'는 '늘 투덜대는, 불평 많은'이라는 뜻으로 gruñir(으르렁거리다, 투덜대다)에서 나왔습니다. 'sin sentido del humor(유머 감각이 없는)'와 같은 부정적 성격과 어울립니다. 나머지 보기는 모두 '재치 있는, 웃긴'이라는 반대 의미입니다.","x":["chistoso: '웃기는'이라는 뜻으로 유머 감각이 없다는 것과 모순됩니다 ✗","ingenioso: '재치 있는'이라는 뜻으로 모순됩니다 ✗","gruñón: '투덜대는, 불평 많은' → 정답 ✓","ocurrente: '기발하고 재미있는'이라는 뜻으로 모순됩니다 ✗"]},{"id":"V732","q":"Puede pagarnos haciendo una ____ bancaria.","o":["transferencia","interferencia","conveniencia","conferencia"],"a":0,"k":"은행 어휘","t":"계좌 이체로 저희에게 결제하실 수 있습니다.","e":"'transferencia bancaria'는 '계좌 이체, 송금'입니다. 'hacer una transferencia(이체하다)'처럼 씁니다. -encia로 끝나는 비슷한 단어들이 함정이니 뜻을 정확히 구분하세요.","x":["transferencia: '이체', 'transferencia bancaria' → 정답 ✓","interferencia: '간섭, 전파 방해'라는 뜻으로 맞지 않습니다 ✗","conveniencia: '편의, 적절함'이라는 뜻으로 맞지 않습니다 ✗","conferencia: '강연, 회의'라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V733","q":"Come mucho, de ahí que esté como un ____.","o":["barril","botijo","cántaro","tonel"],"a":3,"k":"비유 표현","t":"그는 많이 먹는다. 그래서 술통처럼 뚱뚱하다.","e":"'estar como un tonel'은 '술통처럼 뚱뚱하다'라는 비유 표현입니다. tonel은 '큰 나무 술통'입니다. 'de ahí que(그래서 ~하다)' 뒤에는 접속법(esté)이 옵니다.","x":["barril: '통, 배럴'이라는 뜻이지만 이 비유의 고정 표현은 아닙니다 ✗","botijo: '(물을 담는) 토기 물병'이라는 뜻으로 이 표현에 쓰지 않습니다 ✗","cántaro: '항아리'라는 뜻으로 'llover a cántaros(비가 억수같이 오다)'에 씁니다 ✗","tonel: '술통', 'estar como un tonel(뚱뚱하다)' → 정답 ✓"]},{"id":"V734","q":"¡Mirad! En aquel campanario hay un ____ de cigüeñas.","o":["albergue","hogar","nido","hueco"],"a":2,"k":"동물 서식처","t":"봐! 저 종탑에 황새 둥지가 있어.","e":"'nido'는 '(새의) 둥지'입니다. 스페인에서는 성당 종탑(campanario) 위에 황새(cigüeña)가 둥지를 트는 모습을 흔히 볼 수 있습니다. 'Mirad'는 vosotros 명령형으로 스페인식이며, 중남미에서는 'Miren'이라고 합니다.","x":["albergue: '숙소, 대피소'라는 뜻으로 새에게 쓰지 않습니다 ✗","hogar: '가정, 집'이라는 뜻으로 새 둥지를 가리키지 않습니다 ✗","nido: '둥지' → 정답 ✓","hueco: '구멍, 빈 공간'이라는 뜻으로 둥지를 가리키지 않습니다 ✗"]},{"id":"V735","q":"La presidenta convocó una ____ de prensa para comunicar su decisión.","o":["agrupación","junta","rueda","congregación"],"a":2,"k":"rueda de prensa","t":"대통령은 자신의 결정을 알리기 위해 기자 회견을 열었다.","e":"'rueda de prensa'는 '기자 회견'이라는 고정 표현입니다. rueda는 원래 '바퀴, 둥근 모임'이라는 뜻입니다. 'conferencia de prensa'라고도 하며, 중남미에서는 이쪽을 더 많이 씁니다.","x":["agrupación: '단체'라는 뜻으로 이 표현에 쓰지 않습니다 ✗","junta: '회의, 위원회'라는 뜻으로 prensa와 결합하지 않습니다 ✗","rueda: 'rueda de prensa(기자 회견)' → 정답 ✓","congregación: '집회, 수도회'라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V736","q":"Esta es una crema corporal y esta otra es facial, es decir, para ____.","o":["el cabello","las manos","los pies","la cara"],"a":3,"k":"신체 부위 어휘","t":"이건 바디 크림이고 이건 얼굴용, 즉 얼굴에 바르는 크림이다.","e":"'facial'은 '얼굴의'라는 뜻으로 faz(얼굴)와 관련된 형용사입니다. 'es decir(즉)'는 앞말을 다시 풀어 설명하므로 facial을 풀어 쓴 'la cara(얼굴)'가 정답입니다.","x":["el cabello: '머리카락'으로 'capilar'에 해당합니다 ✗","las manos: '손'으로 facial의 뜻이 아닙니다 ✗","los pies: '발'로 facial의 뜻이 아닙니다 ✗","la cara: '얼굴', facial의 의미 → 정답 ✓"]},{"id":"V737","q":"De pequeño, mi hermano trabajaba como ____ de periódicos por la calle.","o":["transmisor","mediador","mensajero","repartidor"],"a":3,"k":"직업 어휘","t":"어렸을 때 우리 형은 거리에서 신문 배달원으로 일했다.","e":"'repartidor/a'는 '배달원'이라는 뜻으로 repartir(나누어 주다, 배달하다)에서 나왔습니다. 'repartidor de periódicos(신문 배달원)', 'repartidor de pizzas(피자 배달원)'처럼 씁니다.","x":["transmisor: '전달자, 송신기'라는 뜻으로 맞지 않습니다 ✗","mediador: '중재자'라는 뜻으로 맞지 않습니다 ✗","mensajero: '메신저, 심부름꾼'으로 편지·소포를 전달하지만 신문 배달에는 보통 쓰지 않습니다 ✗","repartidor: '배달원' → 정답 ✓"]},{"id":"V738","q":"Te invito a ____ chocolate con churros. ¿Qué dices?","o":["merendar","engullir","tragar","ingerir"],"a":0,"k":"merendar(간식 먹다)","t":"초콜릿과 추로스로 간식 먹으러 가자, 내가 살게. 어때?","e":"'merendar'는 '오후 간식(merienda)을 먹다'라는 뜻입니다. 스페인에서는 오후에 'chocolate con churros(진한 핫초콜릿과 추로스)'를 간식으로 즐깁니다. 'Te invito a'는 '내가 살게'라는 뜻입니다.","x":["merendar: '오후 간식을 먹다' → 정답 ✓","engullir: '게걸스럽게 삼키다'라는 뜻으로 초대에 어울리지 않습니다 ✗","tragar: '삼키다'라는 뜻으로 초대 표현에 어색합니다 ✗","ingerir: '섭취하다'라는 의학·격식 용어라 어색합니다 ✗"]},{"id":"V739","q":"Algunas personas confunden las abejas con las ____.","o":["moscas","avispas","mariquitas","hormigas"],"a":1,"k":"곤충 어휘","t":"어떤 사람들은 꿀벌과 말벌을 헷갈린다.","e":"'avispa'는 '말벌'입니다. 꿀벌(abeja)과 생김새가 비슷해 자주 혼동되므로 정답입니다. 'confundir A con B(A를 B와 혼동하다)' 구조도 함께 익혀 두세요.","x":["moscas: '파리'로 꿀벌과 크게 혼동되지 않습니다 ✗","avispas: '말벌', 꿀벌과 비슷해 혼동됨 → 정답 ✓","mariquitas: '무당벌레'로 꿀벌과 닮지 않았습니다 ✗","hormigas: '개미'로 꿀벌과 혼동되지 않습니다 ✗"]},{"id":"V740","q":"Muchas películas del Oeste ____ en Almería.","o":["se edificaron","se construyeron","se rodaron","se fabricaron"],"a":2,"k":"rodar(촬영하다)","t":"많은 서부 영화가 알메리아에서 촬영되었다.","e":"'rodar una película'는 '영화를 촬영하다'라는 뜻입니다. 여기서는 수동의 se(se rodaron, 촬영되었다)를 썼습니다. 스페인 알메리아의 타베르나스 사막은 1960~70년대 마카로니 웨스턴 영화의 촬영지로 유명합니다. 명사형은 rodaje(촬영)입니다.","x":["se edificaron: '건축되었다'라는 뜻으로 영화에 쓰지 않습니다 ✗","se construyeron: '건설되었다'라는 뜻으로 영화에 쓰지 않습니다 ✗","se rodaron: '촬영되었다' → 정답 ✓","se fabricaron: '제조되었다'라는 뜻으로 영화에 쓰지 않습니다 ✗"]},{"id":"V741","q":"Teníamos en ____ hacer un viaje a Madrid, pero hemos cambiado de idea e iremos a Bilbao.","o":["cabeza","pensamiento","mente","razón"],"a":2,"k":"tener en mente","t":"우리는 마드리드 여행을 계획하고 있었지만, 생각을 바꿔서 빌바오에 갈 것이다.","e":"'tener en mente'는 '~을 염두에 두다, 계획하고 있다'라는 고정 표현입니다. 뒤에 'cambiar de idea(생각을 바꾸다)'가 나와 원래 계획이 있었음을 보여 줍니다. 비슷한 표현: 'tener pensado + 동사원형'.","x":["cabeza: 'tener en la cabeza'는 관사가 필요하며 'en cabeza'는 '선두에'라는 뜻이라 어색합니다 ✗","pensamiento: '생각'이라는 뜻이지만 'tener en pensamiento'라고 하지 않습니다 ✗","mente: 'tener en mente(염두에 두다)' → 정답 ✓","razón: 'tener razón(옳다)'은 다른 의미이고 'tener en razón'은 쓰지 않습니다 ✗"]},{"id":"V742","q":"Cada socio recibirá ____ de las ganancias.","o":["una resta","un porcentaje","una multiplicación","una división"],"a":1,"k":"수학·경제 어휘","t":"각 동업자는 수익의 일정 비율을 받을 것이다.","e":"'porcentaje'는 '백분율, 비율'이라는 뜻입니다. 이익(ganancias)을 나눠 받을 때 '일정 비율'을 받는다고 표현합니다. 'socio'는 '동업자, 회원'이라는 뜻입니다.","x":["una resta: '뺄셈'이라는 뜻으로 받을 수 있는 것이 아닙니다 ✗","un porcentaje: '비율', 수익 배분 → 정답 ✓","una multiplicación: '곱셈'이라는 뜻으로 맞지 않습니다 ✗","una división: '나눗셈, 분할'이라는 뜻으로 '받는다'와 어울리지 않습니다 ✗"]},{"id":"V743","q":"Como profesor ____, trabajaré en este instituto durante unos meses, no más.","o":["exterior","externo","interino","interno"],"a":2,"k":"고용 형태 형용사","t":"기간제 교사로서 나는 이 학교에서 몇 달 동안만 일할 것이다.","e":"'interino/a'는 '임시의, 대행의, 기간제의'라는 뜻입니다. 'profesor interino'는 정규직 교사가 아닌 임시 교사를 가리키며, '몇 달만'이라는 기간 한정과 어울립니다. 'instituto'는 스페인에서 '중·고등학교'를 뜻합니다.","x":["exterior: '외부의'라는 뜻으로 고용 형태가 아닙니다 ✗","externo: '외부의, 통학생의'라는 뜻으로 임시 근무를 나타내지 않습니다 ✗","interino: '기간제의, 임시의' → 정답 ✓","interno: '내부의, 기숙의'라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V744","q":"No escuchaba su conversación porque estaban ____.","o":["gritando","vociferando","chillando","susurrando"],"a":3,"k":"말하는 방식 동사","t":"그들이 속삭이고 있어서 그들의 대화가 들리지 않았다.","e":"'susurrar'는 '속삭이다'라는 뜻입니다. 대화가 들리지 않았던 이유는 작게 말했기 때문이므로 정답입니다. 나머지 보기는 모두 '크게 소리치다'라는 반대 의미입니다.","x":["gritando: '소리 지르는'이라는 뜻으로 오히려 잘 들립니다 ✗","vociferando: '고래고래 외치는'이라는 뜻으로 잘 들립니다 ✗","chillando: '날카롭게 소리치는'이라는 뜻으로 잘 들립니다 ✗","susurrando: '속삭이는', 들리지 않는 이유 → 정답 ✓"]},{"id":"V745","q":"____ de nuestro bebé será en la misma iglesia donde nos casamos.","o":["El bautizo","El inicio","La comunión","El enlace"],"a":0,"k":"종교 의식 어휘","t":"우리 아기의 세례식은 우리가 결혼했던 같은 성당에서 할 것이다.","e":"'bautizo'는 '세례식'으로, 아기가 받는 가톨릭 의식입니다. 'comunión(첫영성체)'은 보통 8~10세 무렵에 받습니다. 'enlace'는 격식체로 '결혼식'을 뜻하기도 하지만 아기와는 맞지 않습니다.","x":["El bautizo: '세례식', 아기가 받는 의식 → 정답 ✓","El inicio: '시작'이라는 뜻으로 의식 이름이 아닙니다 ✗","La comunión: '첫영성체'로 아기보다 큰 아이가 받습니다 ✗","El enlace: '결혼식(격식체), 연결'이라는 뜻으로 아기와 맞지 않습니다 ✗"]},{"id":"V746","q":"¿Desde cuándo ____ usted a la Seguridad Social?","o":["recompensa","retribuye","abona","cotiza"],"a":3,"k":"cotizar(납부하다)","t":"언제부터 사회보장보험료를 납부하고 계십니까?","e":"'cotizar a la Seguridad Social'은 '사회보장보험료를 납부하다'라는 고정 표현입니다. cotizar는 '(분담금을) 내다'라는 뜻이며, 주식 시장에서는 '시세가 매겨지다'라는 뜻도 있습니다. 명사형은 cotización입니다.","x":["recompensa: '보상하다'라는 뜻으로 보험료 납부에 쓰지 않습니다 ✗","retribuye: '보수를 주다'라는 뜻으로 맞지 않습니다 ✗","abona: '지불하다'라는 뜻이지만 'abonar a la Seguridad Social'이라고는 하지 않습니다 ✗","cotiza: '(사회보험료를) 납부하다' → 정답 ✓"]},{"id":"V747","q":"Esta ____ es demasiado pequeña para una planta como esta.","o":["caja","jaula","maceta","taza"],"a":2,"k":"원예 어휘","t":"이 화분은 이런 식물에게는 너무 작다.","e":"'maceta'는 '화분'입니다. 식물을 심는 용기이므로 정답입니다. 중남미 일부 지역에서는 'matera'(콜롬비아)나 'macetero'라고도 합니다.","x":["caja: '상자'라는 뜻으로 식물을 심는 용기가 아닙니다 ✗","jaula: '새장, 우리'라는 뜻으로 동물용입니다 ✗","maceta: '화분' → 정답 ✓","taza: '(손잡이 달린) 컵'이라는 뜻으로 맞지 않습니다 ✗"]},{"id":"V748","q":"No hay ninguna ____ con respecto a ese asunto, todo sigue igual.","o":["sugerencia","innovación","advertencia","novedad"],"a":3,"k":"novedad(새 소식)","t":"그 일에 관해서는 아무런 새 소식이 없다. 모든 게 그대로다.","e":"'novedad'는 '새로운 일, 새 소식, 변화'라는 뜻입니다. '모든 것이 그대로다'라는 설명과 '변화가 없다'는 의미가 연결됩니다. 'Sin novedad'는 '이상 없음, 변동 없음'이라는 표현입니다.","x":["sugerencia: '제안'이라는 뜻으로 '모든 게 그대로'와 직접 연결되지 않습니다 ✗","innovación: '혁신'이라는 뜻으로 일상 상황에 어색합니다 ✗","advertencia: '경고'라는 뜻으로 맞지 않습니다 ✗","novedad: '새 소식, 변화', 변화 없음과 연결 → 정답 ✓"]},{"id":"V749","q":"Los ____ suelen traer tiempo despejado.","o":["ciclones","huracanes","anticiclones","tifones"],"a":2,"k":"기상 어휘","t":"고기압은 보통 맑은 날씨를 가져온다.","e":"'anticiclón'은 '고기압'으로, 보통 맑고 안정된 날씨를 가져옵니다. 'despejado'는 '구름 없이 맑은'이라는 뜻입니다. 나머지 보기는 모두 거센 폭풍을 가리키는 말입니다.","x":["ciclones: '사이클론, 저기압 폭풍'으로 궂은 날씨를 가져옵니다 ✗","huracanes: '허리케인'으로 맑은 날씨와 반대입니다 ✗","anticiclones: '고기압', 맑은 날씨를 가져옴 → 정답 ✓","tifones: '태풍'으로 맑은 날씨와 반대입니다 ✗"]},{"id":"V750","q":"Te recomiendo este libro, su lectura es muy ____.","o":["complicada","monótona","pesada","amena"],"a":3,"k":"독서 평가 형용사","t":"이 책을 추천해. 읽기가 아주 재미있어.","e":"'ameno/a'는 '즐거운, 재미있어서 술술 읽히는'이라는 뜻입니다. 책을 추천하는 이유이므로 긍정적인 형용사가 필요합니다. 나머지 보기는 모두 '어렵거나 지루한'이라는 부정적 의미입니다.","x":["complicada: '복잡한'이라는 뜻으로 추천 이유가 되지 않습니다 ✗","monótona: '단조로운'이라는 뜻으로 추천 이유가 되지 않습니다 ✗","pesada: '지루한, 읽기 버거운'이라는 뜻으로 추천 이유가 되지 않습니다 ✗","amena: '즐겁고 술술 읽히는' → 정답 ✓"]}];